window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家税务总局"] = {"yibanfanbishuiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范一般反避税管理，根据《中华人民共和国企业所得税法》（以下简称企业所得税法）及其实施条例、《中华人民共和国税收征收管理法》（以下简称税收征管法）及其实施细则，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于税务机关按照企业所得税法第四十七条、企业所得税法实施条例第一百二十条的规定，对企业实施的不具有合理商业目的而获取税收利益的避税安排，实施的特别纳税调整。 下列情况不适用本办法： （一）与跨境交易或者支付无关的安排； （二）涉嫌逃避缴纳税款、逃避追缴欠税、骗税、抗税以及虚开发票等税收违法行为。"},{"i":3,"n":"第三条","txt":"税收利益是指减少、免除或者推迟缴纳企业所得税应纳税额。"},{"i":4,"n":"第四条","txt":"避税安排具有以下特征： （一）以获取税收利益为唯一目的或者主要目的； （二）以形式符合税法规定、但与其经济实质不符的方式获取税收利益。"},{"i":5,"n":"第五条","txt":"税务机关应当以具有合理商业目的和经济实质的类似安排为基准，按照实质重于形式的原则实施特别纳税调整。调整方法包括： （一）对安排的全部或者部分交易重新定性； （二）在税收上否定交易方的存在，或者将该交易方与其他交易方视为同一实体； （三）对相关所得、扣除、税收优惠、境外税收抵免等重新定性或者在交易各方间重新分配； （四）其他合理方法。"},{"i":6,"n":"第六条","txt":"企业的安排属于转让定价、成本分摊、受控外国企业、资本弱化等其他特别纳税调整范围的，应当首先适用其他特别纳税调整相关规定。 企业的安排属于受益所有人、利益限制等税收协定执行范围的，应当首先适用税收协定执行的相关规定。"},{"i":7,"n":"第七条","txt":"各级税务机关应当结合工作实际，应用各种数据资源，如企业所得税汇算清缴、纳税评估、同期资料管理、对外支付税务管理、股权转让交易管理、税收协定执行等，及时发现一般反避税案源。"},{"i":8,"n":"第八条","txt":"主管税务机关发现企业存在避税嫌疑的，层报省、自治区、直辖市和计划单列市（以下简称省）税务机关复核同意后，报税务总局申请立案。"},{"i":9,"n":"第九条","txt":"省税务机关应当将税务总局形成的立案申请审核意见转发主管税务机关。税务总局同意立案的，主管税务机关实施一般反避税调查。"},{"i":10,"n":"第十条","txt":"主管税务机关实施一般反避税调查时，应当向被调查企业送达《税务检查通知书》。"},{"i":11,"n":"第十一条","txt":"被调查企业认为其安排不属于本办法所称避税安排的，应当自收到《税务检查通知书》之日起60日内提供下列资料： （一）安排的背景资料； （二）安排的商业目的等说明文件； （三）安排的内部决策和管理资料，如董事会决议、备忘录、电子邮件等； （四）安排涉及的详细交易资料，如合同、补充协议、收付款凭证等； （五）与其他交易方的沟通信息； （六）可以证明其安排不属于避税安排的其他资料； （七）税务机关认为有必要提供的其他资料。 企业因特殊情况不能按期提供的，可以向主管税务机关提交书面延期申请，经批准可以延期提供，但是最长不得超过30日。主管税务机关应当自收到企业延期申请之日起15日内书面回复。逾期未回复的，视同税务机关同意企业的延期申请。"},{"i":12,"n":"第十二条","txt":"企业拒绝提供资料的，主管税务机关可以按照税收征管法第三十五条的规定进行核定。"},{"i":13,"n":"第十三条","txt":"主管税务机关实施一般反避税调查时，可以要求为企业筹划安排的单位或者个人（以下简称筹划方）提供有关资料及证明材料。"},{"i":14,"n":"第十四条","txt":"一般反避税调查涉及向筹划方、关联方以及与关联业务调查有关的其他企业调查取证的，主管税务机关应当送达《税务事项通知书》。"},{"i":15,"n":"第十五条","txt":"主管税务机关审核企业、筹划方、关联方以及与关联业务调查有关的其他企业提供的资料，可以采用现场调查、发函协查和查阅公开信息等方式核实。需取得境外有关资料的，可以按有关规定启动税收情报交换程序，或者通过我驻外机构调查收集有关信息。涉及境外关联方相关资料的，主管税务机关也可以要求企业提供公证机构的证明。"},{"i":16,"n":"第十六条","txt":"主管税务机关根据调查过程中获得的相关资料，自税务总局同意立案之日起9个月内进行审核，综合判断企业是否存在避税安排，形成案件不予调整或者初步调整方案的意见和理由，层报省税务机关复核同意后，报税务总局申请结案。"},{"i":17,"n":"第十七条","txt":"主管税务机关应当根据税务总局形成的结案申请审核意见，分别以下情况进行处理： （一）同意不予调整的，向被调查企业下发《特别纳税调查结论通知书》； （二）同意初步调整方案的，向被调查企业下发《特别纳税调查初步调整通知书》； （三）税务总局有不同意见的，按照税务总局的意见修改后再次层报审核。 被调查企业在收到《特别纳税调查初步调整通知书》之日起7日内未提出异议的，主管税务机关应当下发《特别纳税调查调整通知书》。 被调查企业在收到《特别纳税调查初步调整通知书》之日起7日内提出异议，但是主管税务机关经审核后认为不应采纳的，应将被调查企业的异议及不应采纳的意见和理由层报省税务机关复核同意后，报税务总局再次申请结案。 被调查企业在收到《特别纳税调查初步调整通知书》之日起7日内提出异议，主管税务机关经审核后认为确需对调整方案进行修改的，应当将被调查企业的异议及修改后的调整方案层报省税务机关复核同意后，"},{"i":18,"n":"第十八条","txt":"主管税务机关应当根据税务总局考虑企业异议形成的结案申请审核意见，分别以下情况进行处理： （一）同意不应采纳企业所提异议的，向被调查企业下发《特别纳税调查调整通知书》； （二）同意修改后调整方案的，向被调查企业下发《特别纳税调查调整通知书》； （三）税务总局有不同意见的，按照税务总局的意见修改后再次层报审核。"},{"i":19,"n":"第十九条","txt":"被调查企业对主管税务机关作出的一般反避税调整决定不服的，可以按照有关法律法规的规定申请法律救济。"},{"i":20,"n":"第二十条","txt":"主管税务机关作出的一般反避税调整方案导致国内双重征税的，由税务总局统一组织协调解决。"},{"i":21,"n":"第二十一条","txt":"被调查企业认为我国税务机关作出的一般反避税调整，导致国际双重征税或者不符合税收协定规定征税的，可以按照税收协定及其相关规定申请启动相互协商程序。"},{"i":22,"n":"第二十二条","txt":"本办法自2015年2月1日起施行。2015年2月1日前税务机关尚未结案处理的避税安排适用本办法。"}],"gerensuodeshuizonghesuodehuisuanqingjiaoguanlibanf6e7164":[{"i":1,"n":"第二条","txt":"纳税人取得综合所得，按纳税年度合并计算个人所得税，并依法办理汇算清缴。"},{"i":2,"n":"第三条","txt":"本办法所称综合所得，是指纳税人取得的工资薪金所得、劳务报酬所得、稿酬所得和特许权使用费所得。 本办法所称汇算清缴，是指纳税人汇总一个纳税年度内取得的综合所得收入额，减除费用六万元以及专项扣除、专项附加扣除、依法确定的其他扣除和符合条件的公益慈善事业捐赠后，适用综合所得个人所得税税率并减去速算扣除数，减去减免税额后计算本年度实际应纳税额，再减去已预缴税额，确定该纳税年度应退或者应补税额，在法定期限内向税务机关办理纳税申报并结清税款的行为。具体计算公式如下： 应退或应补税额=[（综合所得收入额－60000元－“三险一金”等专项扣除－子女教育等专项附加扣除－依法确定的其他扣除－符合条件的公益慈善事业捐赠）×适用税率－速算扣除数]－减免税额－已预缴税额 纳税人取得境外所得，应当按照有关规定据实申报。"},{"i":3,"n":"第四条","txt":"纳税人按照实际取得综合所得的时间，确定综合所得所属纳税年度。 取得境外所得的境外纳税年度与公历年度不一致的，以境外纳税年度最后一日所在的公历年度，为境外所得对应的我国纳税年度。"},{"i":4,"n":"第五条","txt":"纳税人应当在取得综合所得的纳税年度的次年三月一日至六月三十日内办理汇算清缴。在中国境内无住所的纳税人在汇算清缴开始前离境的，可以在离境前办理。"},{"i":5,"n":"第六条","txt":"纳税人取得综合所得时已依法预缴个人所得税且符合下列情形之一的，无需办理汇算清缴： （一）汇算清缴需补税但综合所得收入全年不超过规定金额的； （二）汇算清缴需补税但不超过规定金额的； （三）已预缴税额与汇算清缴实际应纳税额一致的； （四）符合汇算清缴退税条件但不申请退税的。"},{"i":6,"n":"第七条","txt":"纳税人取得综合所得并且符合下列情形之一的，需要依法办理汇算清缴： （一）已预缴税额大于汇算清缴实际应纳税额且申请退税的； （二）已预缴税额小于汇算清缴实际应纳税额且不符合本办法第六条规定情形的； （三）因适用所得项目错误、扣缴义务人未依法履行扣缴义务、取得综合所得无扣缴义务人，造成纳税年度少申报或者未申报综合所得的。"},{"i":7,"n":"第八条","txt":"纳税人在汇算清缴前应确认填报的联系电话、银行账户等基础信息的有效性，并通过个人所得税APP（以下简称个税APP）、自然人电子税务局网站（以下简称网站）或者扣缴义务人查阅确认综合所得、相关扣除、已缴税额等信息。"},{"i":8,"n":"第九条","txt":"纳税人可以在汇算清缴时填报或补充下列扣除： （一）减除费用六万元； （二）符合条件的基本养老保险、基本医疗保险、失业保险等社会保险费和住房公积金等专项扣除； （三）符合条件的3岁以下婴幼儿照护、子女教育、继续教育、大病医疗、住房贷款利息或者住房租金、赡养老人等专项附加扣除； （四）符合条件的企业年金和职业年金、商业健康保险、个人养老金等其他扣除； （五）符合条件的公益慈善事业捐赠。 纳税人填报本条第二项至第五项扣除的，应当按照规定留存或者提供有关证据资料。"},{"i":9,"n":"第十条","txt":"同时取得综合所得和经营所得的纳税人，可在综合所得或者经营所得中申报减除费用六万元、专项扣除、专项附加扣除以及依法确定的其他扣除，但不得重复申报减除。"},{"i":10,"n":"第十一条","txt":"纳税人填报的专项附加扣除，应当符合个人所得税法及国家有关规定。 纳税人与其他填报人共同填报3岁以下婴幼儿照护、子女教育、大病医疗、住房贷款利息或者住房租金、赡养老人等专项附加扣除的，应当与其他填报人在允许扣除的标准内确认扣除金额。"},{"i":11,"n":"第十二条","txt":"纳税人享受相关减税或免税等税收优惠政策的，应当在填报前认真了解政策规定，确认符合条件。"},{"i":12,"n":"第十三条","txt":"纳税人对扣缴义务人申报的综合所得等信息有异议的，应当先行与扣缴义务人核实确认。确有错误且扣缴义务人拒不更正的，或者存在身份被冒用等情况无法与扣缴义务人取得联系的，纳税人可以通过个税APP、网站等向税务机关发起申诉。"},{"i":13,"n":"第十四条","txt":"纳税人可以选择下列方式办理汇算清缴： （一）自行办理； （二）通过任职受雇单位（含按累计预扣法预扣预缴其劳务报酬所得个人所得税的单位，以下统称单位）代为办理；纳税人提出要求的，单位应当代为办理或者培训、辅导纳税人完成申报和退（补）税；由单位代为办理的，纳税人应当与单位以书面或者电子等方式进行确认，纳税人未与单位确认的，单位不得代为办理； （三）委托涉税专业服务机构或者其他单位及个人办理。委托办理的，纳税人应当与受托人签订授权书。"},{"i":14,"n":"第十五条","txt":"纳税人优先通过个税APP、网站办理汇算清缴，也可以通过邮寄方式或到办税服务厅办理。选择邮寄方式办理的，纳税人应当将申报表寄送至主管税务机关所在省、自治区、直辖市和计划单列市税务局公告的地址。"},{"i":15,"n":"第十六条","txt":"纳税人办理汇算清缴，需确保填报信息真实、准确、完整。 通过单位代为办理或者委托受托人办理的，纳税人应当如实向单位或者受托人提供纳税年度的全部综合所得、相关扣除、享受税收优惠等信息资料。 纳税人、代为办理汇算清缴的单位，需将全部综合所得、相关扣除、享受税收优惠等信息资料自汇算清缴期结束之日起留存5年。"},{"i":16,"n":"第十七条","txt":"代为办理汇算清缴的单位或者受托人为纳税人办理汇算清缴后，应当及时将办理情况通知纳税人。纳税人发现汇算清缴存在错误的，可以要求单位或者受托人更正申报，也可以自行更正申报。"},{"i":17,"n":"第十八条","txt":"在汇算清缴期内纳税人自行办理或者委托受托人办理的，向纳税人任职受雇单位的主管税务机关申报；有两处及以上任职受雇单位的，可自主选择向其中一处主管税务机关申报。由单位代为办理汇算清缴的，向单位的主管税务机关申报。 纳税人没有任职受雇单位的，向其主要收入来源地、户籍所在地或者经常居住地的主管税务机关申报。主要收入来源地，是指纳税年度向纳税人累计发放劳务报酬、稿酬及特许权使用费金额最大的扣缴义务人所在地。 汇算清缴期结束后，税务部门为尚未办理汇算清缴的纳税人确定其主管税务机关。 除特殊规定外，纳税人一个纳税年度的汇算清缴主管税务机关一经确定不得变更。"},{"i":18,"n":"第十九条","txt":"税务机关依托个税APP、网站提供申报表项目预填服务，帮助纳税人便捷办理汇算清缴。 税务机关开展汇算清缴政策解读和操作辅导，通过个税APP、网站、12366等渠道提供涉税咨询。 独立完成汇算清缴存在困难的特殊人群提出申请，税务机关可以为其提供个性化便民服务。"},{"i":19,"n":"第二十条","txt":"税务机关在汇算清缴初期提供预约办理服务，有办理需求的纳税人可以通过个税APP预约。 税务机关、单位分批分期引导提醒纳税人在确定的时间段内办理汇算清缴。"},{"i":20,"n":"第二十一条","txt":"纳税人不能按期办理汇算清缴需要延期的，应当在汇算清缴期结束前向税务机关提出延期申请，经税务机关核准后，可以延期办理；但应在汇算清缴期内按照上一汇算清缴期实际缴纳的税额或者税务机关核定的税额预缴税款，并在核准的延期内完成汇算清缴。"},{"i":21,"n":"第二十二条","txt":"纳税人依法办理汇算清缴，实际应纳税额小于已预缴税额的，可以申请汇算清缴退税。 纳税人汇算清缴补税的，应当在汇算清缴期结束前缴纳税款。"},{"i":22,"n":"第二十三条","txt":"综合所得收入额不超过六万元且已预缴个人所得税的纳税人，在汇算清缴期内可以通过个税APP、网站选择简易申报方式办理汇算清缴退税。 对符合汇算清缴退税条件且生活负担较重的纳税人，税务机关提供优先退税服务。"},{"i":23,"n":"第二十四条","txt":"纳税人提交汇算清缴退税申请后，税务机关依法开展退税审核。 税务机关审核发现退税申请不符合规定，应当通知纳税人补充提供资料或更正汇算清缴申报，纳税人拒不提供资料或者拒不更正申报的，税务机关不予退税。"},{"i":24,"n":"第二十五条","txt":"申请汇算清缴退税及其他退税的纳税人，存在下列情形的，需在办理以前年度汇算清缴补税、更正申报或者提供资料后申请退税： （一）未依法办理以前年度汇算清缴补税的； （二）经税务机关通知以前年度汇算清缴存在疑点且未更正申报或提供资料的。"},{"i":25,"n":"第二十六条","txt":"纳税人申请汇算清缴退税，应当提供其在中国境内开设的符合条件的银行账户。税务机关按规定审核后办理税款退库。 纳税人未提供本人有效银行账户或者提供的账户信息有误的，按规定更正后申请退税。"},{"i":26,"n":"第二十七条","txt":"纳税人办理汇算清缴补税的，可以通过网上银行、办税服务厅、银行柜台、非银行支付机构等渠道缴纳税款。 选择邮寄方式办理汇算清缴补税的，纳税人应当通过个税APP、网站或者主管税务机关确认汇算清缴进度并及时缴纳税款。"},{"i":27,"n":"第二十八条","txt":"汇算清缴期结束后，对未申报补税或者未足额补税的纳税人，税务机关依法追缴其不缴或者少缴的税款、加收滞纳金，并在其个人所得税纳税记录中予以标注。纳税人纠正其未申报或未补税行为后，税务机关应当及时撤销标注。"},{"i":28,"n":"第二十九条","txt":"纳税人因申报信息填写错误造成汇算清缴多退或少缴税款，主动改正或经税务机关提醒后及时改正的，税务机关可以按照“首违不罚”原则免予处罚。"},{"i":29,"n":"第三十条","txt":"纳税人存在未按规定办理纳税申报、不缴或者少缴税款、进行虚假纳税申报、不配合税务检查、虚假承诺等行为，纳入信用信息系统，构成严重失信的，按照有关规定实施失信约束。"},{"i":30,"n":"第三十一条","txt":"单位未按照规定为纳税人代为办理汇算清缴，或者冒用纳税人身份办理扣缴申报、汇算清缴的，按照有关规定处理，并纳入企业纳税信用评价。 企业法定代表人、合伙企业自然人合伙人、个人独资企业投资者等未依法办理汇算清缴的，关联纳入企业纳税信用评价。"},{"i":31,"n":"第三十二条","txt":"受托人协助纳税人虚假申报、骗取退税或者实施其他与汇算清缴相关的税收违法行为，按照税收征管法及涉税专业服务管理等规定处理，并纳入涉税专业服务信用评价管理。"},{"i":32,"n":"第三十三条","txt":"汇算清缴期结束后，对未申报补税或者未足额补税的纳税人，税务机关依法责令其限期改正并送达相关文书，逾期仍不改正的，税务机关可依据税收征管法规定处理处罚。情节严重的，予以公开曝光。"},{"i":33,"n":"第三十四条","txt":"税务机关、代为办理单位、受托人应当依法为纳税人涉税信息保密。"},{"i":34,"n":"第三十五条","txt":"税务机关及其工作人员违反法律法规等规定，侵犯纳税人合法权益的，纳税人可以依法投诉、举报或者申请行政复议、提起行政诉讼。"},{"i":35,"n":"第三十六条","txt":"纳税人取得财产租赁等分类所得，以及按规定不并入综合所得计算纳税的所得，不适用本办法。 非居民个人取得工资薪金所得、劳务报酬所得、稿酬所得、特许权使用费所得，不适用本办法。"},{"i":36,"n":"第三十七条","txt":"本办法自公布之日起施行。"}],"getigongshanghugerensuodeshuijishuibanfa":[{"i":1,"n":"第一条","txt":"为了规范和加强个体工商户个人所得税征收管理，根据个人所得税法等有关税收法律、法规和政策规定，制定本办法。"},{"i":2,"n":"第二条","txt":"实行查账征收的个体工商户应当按照本办法的规定，计算并申报缴纳个人所得税。"},{"i":3,"n":"第三条","txt":"本办法所称个体工商户包括： （一）依法取得个体工商户营业执照，从事生产经营的个体工商户； （二）经政府有关部门批准，从事办学、医疗、咨询等有偿服务活动的个人； （三）其他从事个体生产、经营的个人。"},{"i":4,"n":"第四条","txt":"个体工商户以业主为个人所得税纳税义务人。"},{"i":5,"n":"第五条","txt":"个体工商户应纳税所得额的计算，以权责发生制为原则，属于当期的收入和费用，不论款项是否收付，均作为当期的收入和费用；不属于当期的收入和费用，即使款项已经在当期收付，均不作为当期收入和费用。本办法和财政部、国家税务总局另有规定的除外。"},{"i":6,"n":"第六条","txt":"在计算应纳税所得额时，个体工商户会计处理办法与本办法和财政部、国家税务总局相关规定不一致的，应当依照本办法和财政部、国家税务总局的相关规定计算。"},{"i":7,"n":"第七条","txt":"个体工商户的生产、经营所得，以每一纳税年度的收入总额，减除成本、费用、税金、损失、其他支出以及允许弥补的以前年度亏损后的余额，为应纳税所得额。"},{"i":8,"n":"第八条","txt":"个体工商户从事生产经营以及与生产经营有关的活动（以下简称生产经营）取得的货币形式和非货币形式的各项收入，为收入总额。包括：销售货物收入、提供劳务收入、转让财产收入、利息收入、租金收入、接受捐赠收入、其他收入。 前款所称其他收入包括个体工商户资产溢余收入、逾期一年以上的未退包装物押金收入、确实无法偿付的应付款项、已作坏账损失处理后又收回的应收款项、债务重组收入、补贴收入、违约金收入、汇兑收益等。"},{"i":9,"n":"第九条","txt":"成本是指个体工商户在生产经营活动中发生的销售成本、销货成本、业务支出以及其他耗费。"},{"i":10,"n":"第十条","txt":"费用是指个体工商户在生产经营活动中发生的销售费用、管理费用和财务费用，已经计入成本的有关费用除外。"},{"i":11,"n":"第十一条","txt":"税金是指个体工商户在生产经营活动中发生的除个人所得税和允许抵扣的增值税以外的各项税金及其附加。"},{"i":12,"n":"第十二条","txt":"损失是指个体工商户在生产经营活动中发生的固定资产和存货的盘亏、毁损、报废损失，转让财产损失，坏账损失，自然灾害等不可抗力因素造成的损失以及其他损失。 个体工商户发生的损失，减除责任人赔偿和保险赔款后的余额，参照财政部、国家税务总局有关企业资产损失税前扣除的规定扣除。 个体工商户已经作为损失处理的资产，在以后纳税年度又全部收回或者部分收回时，应当计入收回当期的收入。"},{"i":13,"n":"第十三条","txt":"其他支出是指除成本、费用、税金、损失外，个体工商户在生产经营活动中发生的与生产经营活动有关的、合理的支出。"},{"i":14,"n":"第十四条","txt":"个体工商户发生的支出应当区分收益性支出和资本性支出。收益性支出在发生当期直接扣除；资本性支出应当分期扣除或者计入有关资产成本，不得在发生当期直接扣除。 前款所称支出，是指与取得收入直接相关的支出。 除税收法律法规另有规定外，个体工商户实际发生的成本、费用、税金、损失和其他支出，不得重复扣除。"},{"i":15,"n":"第十五条","txt":"个体工商户下列支出不得扣除： （一）个人所得税税款； （二）税收滞纳金； （三）罚金、罚款和被没收财物的损失； （四）不符合扣除规定的捐赠支出； （五）赞助支出； （六）用于个人和家庭的支出； （七）与取得生产经营收入无关的其他支出； （八）国家税务总局规定不准扣除的支出。"},{"i":16,"n":"第十六条","txt":"个体工商户生产经营活动中，应当分别核算生产经营费用和个人、家庭费用。对于生产经营与个人、家庭生活混用难以分清的费用，其40%视为与生产经营有关费用，准予扣除。"},{"i":17,"n":"第十七条","txt":"个体工商户纳税年度发生的亏损，准予向以后年度结转，用以后年度的生产经营所得弥补，但结转年限最长不得超过五年。"},{"i":18,"n":"第十八条","txt":"个体工商户使用或者销售存货，按照规定计算的存货成本，准予在计算应纳税所得额时扣除。"},{"i":19,"n":"第十九条","txt":"个体工商户转让资产，该项资产的净值，准予在计算应纳税所得额时扣除。"},{"i":20,"n":"第二十条","txt":"本办法所称亏损，是指个体工商户依照本办法规定计算的应纳税所得额小于零的数额。"},{"i":21,"n":"第二十一条","txt":"个体工商户实际支付给从业人员的、合理的工资薪金支出，准予扣除。 个体工商户业主的费用扣除标准，依照相关法律、法规和政策规定执行。 个体工商户业主的工资薪金支出不得税前扣除。"},{"i":22,"n":"第二十二条","txt":"个体工商户按照国务院有关主管部门或者省级人民政府规定的范围和标准为其业主和从业人员缴纳的基本养老保险费、基本医疗保险费、失业保险费、生育保险费、工伤保险费和住房公积金，准予扣除。 个体工商户为从业人员缴纳的补充养老保险费、补充医疗保险费，分别在不超过从业人员工资总额5%标准内的部分据实扣除；超过部分，不得扣除。 个体工商户业主本人缴纳的补充养老保险费、补充医疗保险费，以当地（地级市）上年度社会平均工资的3倍为计算基数，分别在不超过该计算基数5%标准内的部分据实扣除；超过部分，不得扣除。"},{"i":23,"n":"第二十三条","txt":"除个体工商户依照国家有关规定为特殊工种从业人员支付的人身安全保险费和财政部、国家税务总局规定可以扣除的其他商业保险费外，个体工商户业主本人或者为从业人员支付的商业保险费，不得扣除。"},{"i":24,"n":"第二十四条","txt":"个体工商户在生产经营活动中发生的合理的不需要资本化的借款费用，准予扣除。 个体工商户为购置、建造固定资产、无形资产和经过12个月以上的建造才能达到预定可销售状态的存货发生借款的，在有关资产购置、建造期间发生的合理的借款费用，应当作为资本性支出计入有关资产的成本，并依照本办法的规定扣除。"},{"i":25,"n":"第二十五条","txt":"个体工商户在生产经营活动中发生的下列利息支出，准予扣除： （一）向金融企业借款的利息支出； （二）向非金融企业和个人借款的利息支出，不超过按照金融企业同期同类贷款利率计算的数额的部分。"},{"i":26,"n":"第二十六条","txt":"个体工商户在货币交易中，以及纳税年度终了时将人民币以外的货币性资产、负债按照期末即期人民币汇率中间价折算为人民币时产生的汇兑损失，除已经计入有关资产成本部分外，准予扣除。"},{"i":27,"n":"第二十七条","txt":"个体工商户向当地工会组织拨缴的工会经费、实际发生的职工福利费支出、职工教育经费支出分别在工资薪金总额的2%、14%、2.5%的标准内据实扣除。 工资薪金总额是指允许在当期税前扣除的工资薪金支出数额。 职工教育经费的实际发生数额超出规定比例当期不能扣除的数额，准予在以后纳税年度结转扣除。 个体工商户业主本人向当地工会组织缴纳的工会经费、实际发生的职工福利费支出、职工教育经费支出，以当地（地级市）上年度社会平均工资的3倍为计算基数，在本条第一款规定比例内据实扣除。"},{"i":28,"n":"第二十八条","txt":"个体工商户发生的与生产经营活动有关的业务招待费，按照实际发生额的60%扣除，但最高不得超过当年销售（营业）收入的5‰。 业主自申请营业执照之日起至开始生产经营之日止所发生的业务招待费，按照实际发生额的60%计入个体工商户的开办费。"},{"i":29,"n":"第二十九条","txt":"个体工商户每一纳税年度发生的与其生产经营活动直接相关的广告费和业务宣传费不超过当年销售（营业）收入15%的部分，可以据实扣除；超过部分，准予在以后纳税年度结转扣除。"},{"i":30,"n":"第三十条","txt":"个体工商户代其从业人员或者他人负担的税款，不得税前扣除。"},{"i":31,"n":"第三十一条","txt":"个体工商户按照规定缴纳的摊位费、行政性收费、协会会费等，按实际发生数额扣除。"},{"i":32,"n":"第三十二条","txt":"个体工商户根据生产经营活动的需要租入固定资产支付的租赁费，按照以下方法扣除： （一）以经营租赁方式租入固定资产发生的租赁费支出，按照租赁期限均匀扣除； （二）以融资租赁方式租入固定资产发生的租赁费支出，按照规定构成融资租入固定资产价值的部分应当提取折旧费用，分期扣除。"},{"i":33,"n":"第三十三条","txt":"个体工商户参加财产保险，按照规定缴纳的保险费，准予扣除。"},{"i":34,"n":"第三十四条","txt":"个体工商户发生的合理的劳动保护支出，准予扣除。"},{"i":35,"n":"第三十五条","txt":"个体工商户自申请营业执照之日起至开始生产经营之日止所发生符合本办法规定的费用，除为取得固定资产、无形资产的支出，以及应计入资产价值的汇兑损益、利息支出外，作为开办费，个体工商户可以选择在开始生产经营的当年一次性扣除，也可自生产经营月份起在不短于3年期限内摊销扣除，但一经选定，不得改变。 开始生产经营之日为个体工商户取得第一笔销售（营业）收入的日期。"},{"i":36,"n":"第三十六条","txt":"个体工商户通过公益性社会团体或者县级以上人民政府及其部门，用于《中华人民共和国公益事业捐赠法》规定的公益事业的捐赠，捐赠额不超过其应纳税所得额30％的部分可以据实扣除。 财政部、国家税务总局规定可以全额在税前扣除的捐赠支出项目，按有关规定执行。 个体工商户直接对受益人的捐赠不得扣除。 公益性社会团体的认定，按照财政部、国家税务总局、民政部有关规定执行。"},{"i":37,"n":"第三十七条","txt":"本办法所称赞助支出，是指个体工商户发生的与生产经营活动无关的各种非广告性质支出。"},{"i":38,"n":"第三十八条","txt":"个体工商户研究开发新产品、新技术、新工艺所发生的开发费用，以及研究开发新产品、新技术而购置单台价值在10万元以下的测试仪器和试验性装置的购置费准予直接扣除；单台价值在10万元以上（含10万元）的测试仪器和试验性装置，按固定资产管理，不得在当期直接扣除。"},{"i":39,"n":"第三十九条","txt":"个体工商户资产的税务处理，参照企业所得税相关法律、法规和政策规定执行。"},{"i":40,"n":"第四十条","txt":"个体工商户有两处或两处以上经营机构的，选择并固定向其中一处经营机构所在地主管税务机关申报缴纳个人所得税。"},{"i":41,"n":"第四十一条","txt":"个体工商户终止生产经营的，应当在注销工商登记或者向政府有关部门办理注销前向主管税务机关结清有关纳税事宜。"},{"i":42,"n":"第四十二条","txt":"各省、自治区、直辖市和计划单列市税务局可以结合本地实际,制定具体实施办法。"},{"i":43,"n":"第四十三条","txt":"本办法自2015年1月1日起施行。国家税务总局1997年3月26日发布的《国家税务总局关于印发〈个体工商户个人所得税计税办法（试行）〉的通知》（国税发〔1997〕43号）同时废止。"}],"getigongshanghujianzhangguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了规范和加强个体工商户税收征收管理，促进个体工商户加强经济核算，根据《中华人民共和国税收征收管理法》(以下简称税收征管法)及其实施细则和《国务院关于批转国家税务总局加强个体私营经济税收征管强化查账征收工作意见的通知》，制定本办法。"},{"i":2,"n":"第二条","txt":"凡从事生产、经营并有固定生产、经营场所的个体工商户，都应当按照法律、行政法规和本办法的规定设置、使用和保管账簿及凭证，并根据合法、有效凭证记账核算。 税务机关应同时采取有效措施，巩固已有建账成果，积极引导个体工商户建立健全账簿，正确进行核算，如实申报纳税。"},{"i":3,"n":"第三条","txt":"符合下列情形之一的个体工商户，应当设置复式账： (一)注册资金在20万元以上的。 (二)销售增值税应税劳务的纳税人或营业税纳税人月销售(营业)额在40000元以上；从事货物生产的增值税纳税人月销售额在60000元以上；从事货物批发或零售的增值税纳税人月销售额在80000元以上的。 (三)省税务机关确定应设置复式账的其他情形。"},{"i":4,"n":"第四条","txt":"符合下列情形之一的个体工商户，应当设置简易账，并积极创造条件设置复式账： (一)注册资金在10万元以上20万元以下的。 (二)销售增值税应税劳务的纳税人或营业税纳税人月销售(营业)额在15000元至40000元；从事货物生产的增值税纳税人月销售额在30000元至60000元；从事货物批发或零售的增值税纳税人月销售额在40000元至80000元的。 (三)省税务机关确定应当设置简易账的其他情形。"},{"i":5,"n":"第五条","txt":"上述所称纳税人月销售额或月营业额，是指个体工商户上一个纳税年度月平均销售额或营业额；新办的个体工商户为业户预估的当年度经营期月平均销售额或营业额。"},{"i":6,"n":"第六条","txt":"达不到上述建账标准的个体工商户，经县以上税务机关批准，可按照税收征管法的规定，建立收支凭证粘贴簿、进货销货登记簿或者使用税控装置。"},{"i":7,"n":"第七条","txt":"达到建账标准的个体工商户，应当根据自身生产、经营情况和本办法规定的设置账簿条件，对照选择设置复式账或简易账，并报主管税务机关备案。账簿方式一经确定，在一个纳税年度内不得进行变更。"},{"i":8,"n":"第八条","txt":"达到建账标准的个体工商户，应当自领取营业执照或者发生纳税义务之日起15日内，按照法律、行政法规和本办法的有关规定设置账簿并办理账务，不得伪造、变造或者擅自损毁账簿、记账凭证、完税凭证和其他有关资料。"},{"i":9,"n":"第九条","txt":"设置复式账的个体工商户应按《个体工商户会计制度(试行)》的规定设置总分类账、明细分类账、日记账等，进行财务会计核算，如实记载财务收支情况。成本、费用列支和其他财务核算规定按照《个体工商户个人所得税计税办法(试行)》执行。 设置简易账的个体工商户应当设置经营收入账、经营费用账、商品(材料)购进账、库存商品(材料)盘点表和利润表，以收支方式记录、反映生产、经营情况并进行简易会计核算。"},{"i":10,"n":"第十条","txt":"复式账簿中现金日记账，银行存款日记账和总分类账必须使用订本式，其他账簿可以根据业务的实际发生情况选用活页账簿。简易账簿均应采用订本式。 账簿和凭证应当按照发生的时间顺序填写，装订或者粘贴。 建账户对各种账簿、记账凭证、报表、完税凭证和其他有关涉税资料应当保存10年。"},{"i":11,"n":"第十一条","txt":"设置复式账的个体工商户在办理纳税申报时，应当按照规定向当地主管税务机关报送财务会计报表和有关纳税资料。月度会计报表应当于月份终了后10日内报出，年度会计报表应当在年度终了后30日内报出。"},{"i":12,"n":"第十二条","txt":"个体工商户可以聘请经批准从事会计代理记账业务的专业机构或者具备资质的财会人员代为建账和办理账务。"},{"i":13,"n":"第十三条","txt":"按照税务机关规定的要求使用税控收款机的个体工商户，其税控收款机输出的完整的书面记录，可以视同经营收入账。"},{"i":14,"n":"第十四条","txt":"税务机关对建账户采用查账征收方式征收税款。建账初期，也可以采用查账征收与定期定额征收相结合的方式征收税款。"},{"i":15,"n":"第十五条","txt":"依照本办法规定应当设置账簿的个体工商户，具有税收征管法第三十五条第一款第二项至第六项情形之一的，税务机关有权根据税收征管法实施细则第四十七条规定的方法核定其应纳税额。"},{"i":16,"n":"第十六条","txt":"依照本办法规定应当设置账簿的个体工商户违反有关法律、行政法规和本办法关于账簿设置、使用和保管规定的，由税务机关按照税收征管法的有关规定进行处理。"},{"i":17,"n":"第十七条","txt":"个体工商户建账工作中所涉及的有关账簿、凭证、表格，按照有关规定办理。"},{"i":18,"n":"第十八条","txt":"本办法所称“以上”均含本数。"},{"i":19,"n":"第十九条","txt":"各省、自治区、直辖市和计划单列市税务局可根据本办法制定具体实施办法，并报国家税务总局备案。"},{"i":20,"n":"第二十条","txt":"本办法自2007年1月1日起施行。1997年6月19日国家税务总局发布的《个体工商户建账管理暂行办法》同时废止。"}],"getigongshanghushuishoudingqidingezhengshouguanliba77054":[{"i":1,"n":"第一条","txt":"为规范和加强个体工商户税收定期定额征收（以下简称定期定额征收）管理，公平税负，保护个体工商户合法权益，促进个体经济的健康发展，根据《中华人民共和国税收征收管理法》及其实施细则，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称个体工商户税收定期定额征收，是指税务机关依照法律、行政法规及本办法的规定，对个体工商户在一定经营地点、一定经营时期、一定经营范围内的应纳税经营额（包括经营数量）或所得额（以下简称定额）进行核定，并以此为计税依据，确定其应纳税额的一种征收方式。"},{"i":3,"n":"第三条","txt":"本办法适用于经主管税务机关认定和县以上税务机关（含县级，下同）批准的生产、经营规模小，达不到《个体工商户建账管理暂行办法》规定设置账簿标准的个体工商户（以下简称定期定额户）的税收征收管理。"},{"i":4,"n":"第四条","txt":"主管税务机关应当将定期定额户进行分类，在年度内按行业、区域选择一定数量并具有代表性的定期定额户，对其经营、所得情况进行典型调查，做出调查分析，填制有关表格。 典型调查户数应当占该行业、区域总户数的5%以上。具体比例由省税务机关确定。"},{"i":5,"n":"第五条","txt":"定额执行期的具体期限由省税务机关确定，但最长不得超过一年。 定额执行期是指税务机关核定后执行的第一个纳税期至最后一个纳税期。"},{"i":6,"n":"第六条","txt":"税务机关应当根据定期定额户的经营规模、经营区域、经营内容、行业特点、管理水平等因素核定定额，可以采用下列一种或两种以上的方法核定： （一）按照耗用的原材料、燃料、动力等推算或者测算核定； （二）按照成本加合理的费用和利润的方法核定； （三）按照盘点库存情况推算或者测算核定； （四）按照发票和相关凭据核定； （五）按照银行经营账户资金往来情况测算核定； （六）参照同类行业或类似行业中同规模、同区域纳税人的生产、经营情况核定； （七）按照其他合理方法核定。 税务机关应当运用现代信息技术手段核定定额，增强核定工作的规范性和合理性。"},{"i":7,"n":"第七条","txt":"税务机关核定定额程序： （一）自行申报。定期定额户要按照税务机关规定的申报期限、申报内容向主管税务机关申报，填写有关申报文书。申报内容应包括经营行业、营业面积、雇佣人数和每月经营额、所得额以及税务机关需要的其他申报项目。 本项所称经营额、所得额为预估数。 （二）核定定额。主管税务机关根据定期定额户自行申报情况，参考典型调查结果，采取本办法第六条规定的核定方法核定定额，并计算应纳税额。 （三）定额公示。主管税务机关应当将核定定额的初步结果进行公示，公示期限为五个工作日。 公示地点、范围、形式应当按照便于定期定额户及社会各界了解、监督的原则，由主管税务机关确定。 （四）上级核准。主管税务机关根据公示意见结果修改定额，并将核定情况报经县以上税务机关审核批准后，填制《核定定额通知书》。 （五）下达定额。将《核定定额通知书》送达定期定额户执行。 （六）公布定额。主管税务机关将最终确定的定额和应纳"},{"i":8,"n":"第八条","txt":"定期定额户应当建立收支凭证粘贴簿、进销货登记簿，完整保存有关纳税资料，并接受税务机关的检查。"},{"i":9,"n":"第九条","txt":"依照法律、行政法规的规定，定期定额户负有纳税申报义务。 实行简易申报的定期定额户，应当在税务机关规定的期限内按照法律、行政法规规定缴清应纳税款，当期（指纳税期，下同）可以不办理申报手续。"},{"i":10,"n":"第十条","txt":"采用数据电文申报、邮寄申报、简易申报等方式的，经税务机关认可后方可执行。经确定的纳税申报方式在定额执行期内不予更改。"},{"i":11,"n":"第十一条","txt":"定期定额户可以委托经税务机关认定的银行或其他金融机构办理税款划缴。 凡委托银行或其他金融机构办理税款划缴的定期定额户，应当向税务机关书面报告开户银行及账号。其账户内存款应当足以按期缴纳当期税款。其存款余额低于当期应纳税款，致使当期税款不能按期入库的，税务机关按逾期缴纳税款处理；对实行简易申报的，按逾期办理纳税申报和逾期缴纳税款处理。"},{"i":12,"n":"第十二条","txt":"定期定额户发生下列情形，应当向税务机关办理相关纳税事宜： （一）定额与发票开具金额或税控收款机记录数据比对后，超过定额的经营额、所得额所应缴纳的税款； （二）在税务机关核定定额的经营地点以外从事经营活动所应缴纳的税款。"},{"i":13,"n":"第十三条","txt":"税务机关可以根据保证国家税款及时足额入库、方便纳税人、降低税收成本的原则，采用简化的税款征收方式，具体方式由省税务机关确定。"},{"i":14,"n":"第十四条","txt":"县以上税务机关可以根据当地实际情况，依法委托有关单位代征税款。税务机关与代征单位必须签订委托代征协议，明确双方的权利、义务和应当承担的责任，并向代征单位颁发委托代征证书。"},{"i":15,"n":"第十五条","txt":"定期定额户经营地点偏远、缴纳税款数额较小，或者税务机关征收税款有困难的，税务机关可以按照法律、行政法规的规定简并征期。但简并征期最长不得超过一个定额执行期。 简并征期的税款征收时间为最后一个纳税期。"},{"i":16,"n":"第十六条","txt":"通过银行或其他金融机构划缴税款的，其完税凭证可以到税务机关领取，或到税务机关委托的银行或其他金融机构领取；税务机关也可以根据当地实际情况采取邮寄送达，或委托有关单位送达。"},{"i":17,"n":"第十七条","txt":"定期定额户在定额执行期结束后，应当以该期每月实际发生的经营额、所得额向税务机关申报，申报额超过定额的，按申报额缴纳税款；申报额低于定额的，按定额缴纳税款。具体申报期限由省税务机关确定。 定期定额户当期发生的经营额、所得额超过定额一定幅度的，应当在法律、行政法规规定的申报期限内向税务机关进行申报并缴清税款。具体幅度由省税务机关确定。"},{"i":18,"n":"第十八条","txt":"定期定额户的经营额、所得额连续纳税期超过或低于税务机关核定的定额，应当提请税务机关重新核定定额，税务机关应当根据本办法规定的核定方法和程序重新核定定额。具体期限由省税务机关确定。"},{"i":19,"n":"第十九条","txt":"经税务机关检查发现定期定额户在以前定额执行期发生的经营额、所得额超过定额，或者当期发生的经营额、所得额超过定额一定幅度而未向税务机关进行纳税申报及结清应纳税款的，税务机关应当追缴税款、加收滞纳金，并按照法律、行政法规规定予以处理。其经营额、所得额连续纳税期超过定额，税务机关应当按照本办法第十八条的规定重新核定其定额。"},{"i":20,"n":"第二十条","txt":"定期定额户发生停业的，应当在停业前向税务机关书面提出停业报告；提前恢复经营的，应当在恢复经营前向税务机关书面提出复业报告；需延长停业时间的，应当在停业期满前向税务机关提出书面的延长停业报告。"},{"i":21,"n":"第二十一条","txt":"税务机关停止定期定额户实行定期定额征收方式，应当书面通知定期定额户。"},{"i":22,"n":"第二十二条","txt":"定期定额户对税务机关核定的定额有争议的，可以在接到《核定定额通知书》之日起30日内向主管税务机关提出重新核定定额申请，并提供足以说明其生产、经营真实情况的证据，主管税务机关应当自接到申请之日起30日内书面答复。 定期定额户也可以按照法律、行政法规的规定直接向上一级税务机关申请行政复议；对行政复议决定不服的，可以依法向人民法院提起行政诉讼。 定期定额户在未接到重新核定定额通知、行政复议决定书或人民法院判决书前，仍按原定额缴纳税款。"},{"i":23,"n":"第二十三条","txt":"税务机关应当严格执行核定定额程序，遵守回避制度。税务人员个人不得擅自确定或更改定额。 税务人员徇私舞弊或者玩忽职守，致使国家税收遭受重大损失，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":24,"n":"第二十四条","txt":"对违反本办法规定的行为，按照《中华人民共和国税收征收管理法》及其实施细则有关规定处理。"},{"i":25,"n":"第二十五条","txt":"个人独资企业的税款征收管理比照本办法执行。"},{"i":26,"n":"第二十六条","txt":"各省、自治区、直辖市税务局根据本办法制定具体实施办法，并报国家税务总局备案。"},{"i":27,"n":"第二十七条","txt":"本办法自2007年1月1日起施行。1997年6月19日国家税务总局发布的《个体工商户定期定额管理暂行办法》同时废止。"}],"fapiaoguanlibanfashishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国发票管理办法》(以下简称《办法》)规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"在全国范围内统一式样的发票，由国家税务总局确定。 在省、自治区、直辖市范围内统一式样的发票，由省、自治区、直辖市税务局（以下简称省税务局）确定。"},{"i":3,"n":"第三条","txt":"《办法》第三条所称电子发票是指在购销商品、提供或者接受服务以及从事其他经营活动中，按照税务机关发票管理规定以数据电文形式开具、收取的收付款凭证。 电子发票与纸质发票的法律效力相同，任何单位和个人不得拒收。"},{"i":4,"n":"第四条","txt":"税务机关建设电子发票服务平台，为用票单位和个人提供数字化等形态电子发票开具、交付、查验等服务。"},{"i":5,"n":"第五条","txt":"税务机关应当按照法律、行政法规的规定，建立健全发票数据安全管理制度，保障发票数据安全。 单位和个人按照国家税务总局有关规定开展发票数据处理活动，依法承担发票数据安全保护义务，不得超过规定的数量存储发票数据，不得违反规定使用、非法出售或非法向他人提供发票数据。"},{"i":6,"n":"第六条","txt":"纸质发票的基本联次包括存根联、发票联、记账联。存根联由收款方或开票方留存备查；发票联由付款方或受票方作为付款原始凭证；记账联由收款方或开票方作为记账原始凭证。 省以上税务机关可根据纸质发票管理情况以及纳税人经营业务需要，增减除发票联以外的其他联次，并确定其用途。"},{"i":7,"n":"第七条","txt":"发票的基本内容包括:发票的名称、发票代码和号码、联次及用途、客户名称、开户银行及账号、商品名称或经营项目、计量单位、数量、单价、大小写金额、税率（征收率）、税额、开票人、开票日期、开票单位（个人）名称（章）等。 省以上税务机关可根据经济活动以及发票管理需要，确定发票的具体内容。"},{"i":8,"n":"第八条","txt":"领用发票单位可以书面向税务机关要求使用印有本单位名称的发票，税务机关依据《办法》第十五条的规定，确认印有该单位名称发票的种类和数量。"},{"i":9,"n":"第九条","txt":"税务机关根据政府采购合同和发票防伪用品管理要求对印制发票企业实施监督管理。"},{"i":10,"n":"第十条","txt":"全国统一的纸质发票防伪措施由国家税务总局确定，省税务局可以根据需要增加本地区的纸质发票防伪措施,并向国家税务总局备案。 纸质发票防伪专用品应当按照规定专库保管，不得丢失。次品、废品应当在税务机关监督下集中销毁。"},{"i":11,"n":"第十一条","txt":"全国统一发票监制章是税务机关管理发票的法定标志，其形状、规格、内容、印色由国家税务总局规定。"},{"i":12,"n":"第十二条","txt":"全国范围内发票换版由国家税务总局确定；省、自治区、直辖市范围内发票换版由省税务局确定。 发票换版时，应当进行公告。"},{"i":13,"n":"第十三条","txt":"监制发票的税务机关根据需要下达发票印制通知书，印制企业必须按照要求印制。 发票印制通知书应当载明印制发票企业名称、用票单位名称、发票名称、发票代码、种类、联次、规格、印色、印制数量、起止号码、交货时间、地点等内容。"},{"i":14,"n":"第十四条","txt":"印制发票企业印制完毕的成品应当按照规定验收后专库保管，不得丢失。废品应当及时销毁。"},{"i":15,"n":"第十五条","txt":"《办法》第十五条所称经办人身份证明是指经办人的居民身份证、护照或者其他能证明经办人身份的证件。"},{"i":16,"n":"第十六条","txt":"《办法》第十五条所称发票专用章是指领用发票单位和个人在其开具纸质发票时加盖的有其名称、统一社会信用代码或者纳税人识别号、发票专用章字样的印章。 发票专用章式样由国家税务总局确定。"},{"i":17,"n":"第十七条","txt":"税务机关对领用纸质发票单位和个人提供的发票专用章的印模应当留存备查。"},{"i":18,"n":"第十八条","txt":"《办法》第十五条所称领用方式是指批量供应、交旧领新、验旧领新、额度确定等方式。 税务机关根据单位和个人的税收风险程度、纳税信用级别、实际经营情况确定或调整其领用发票的种类、数量、额度以及领用方式。"},{"i":19,"n":"第十九条","txt":"《办法》第十五条所称发票使用情况是指发票领用存情况及相关开票数据。"},{"i":20,"n":"第二十条","txt":"《办法》第十六条所称书面证明是指有关业务合同、协议或者税务机关认可的其他资料。"},{"i":21,"n":"第二十一条","txt":"税务机关应当与受托代开发票的单位签订协议，明确代开发票的种类、对象、内容和相关责任等内容。"},{"i":22,"n":"第二十二条","txt":"《办法》第十八条所称特殊情况下，由付款方向收款方开具发票，是指下列情况： （一）收购单位和扣缴义务人支付个人款项时； （二）国家税务总局认为其他需要由付款方向收款方开具发票的。"},{"i":23,"n":"第二十三条","txt":"向消费者个人零售小额商品或者提供零星服务的，是否可免予逐笔开具发票，由省税务局确定。"},{"i":24,"n":"第二十四条","txt":"填开发票的单位和个人必须在发生经营业务确认营业收入时开具发票。未发生经营业务一律不准开具发票。"},{"i":25,"n":"第二十五条","txt":"《办法》第十九条规定的不得变更金额，包括不得变更涉及金额计算的单价和数量。"},{"i":26,"n":"第二十六条","txt":"开具纸质发票后，如发生销售退回、开票有误、应税服务中止等情形，需要作废发票的，应当收回原发票全部联次并注明“作废”字样后作废发票。 开具纸质发票后，如发生销售退回、开票有误、应税服务中止、销售折让等情形，需要开具红字发票的，应当收回原发票全部联次并注明“红冲”字样后开具红字发票。无法收回原发票全部联次的，应当取得对方有效证明后开具红字发票。"},{"i":27,"n":"第二十七条","txt":"开具电子发票后，如发生销售退回、开票有误、应税服务中止、销售折让等情形的，应当按照规定开具红字发票。"},{"i":28,"n":"第二十八条","txt":"单位和个人在开具发票时，应当填写项目齐全，内容真实。 开具纸质发票应当按照发票号码顺序填开，字迹清楚，全部联次一次打印，内容完全一致，并在发票联和抵扣联加盖发票专用章。"},{"i":29,"n":"第二十九条","txt":"《办法》第二十一条所称与实际经营业务情况不符是指具有下列行为之一的： （一）未购销商品、未提供或者接受服务、未从事其他经营活动，而开具或取得发票； （二）有购销商品、提供或者接受服务、从事其他经营活动，但开具或取得的发票载明的购买方、销售方、商品名称或经营项目、金额等与实际情况不符。"},{"i":30,"n":"第三十条","txt":"开具发票应当使用中文。民族自治地方可以同时使用当地通用的一种民族文字。"},{"i":31,"n":"第三十一条","txt":"单位和个人向委托人提供发票领用、开具等服务，应当接受税务机关监管，所存储发票数据的最大数量应当符合税务机关的规定。"},{"i":32,"n":"第三十二条","txt":"开发电子发票信息系统为他人提供发票数据查询、下载、存储、使用等涉税服务的，应当符合税务机关的数据标准和管理规定，并与委托人签订协议，不得超越授权范围使用发票数据。"},{"i":33,"n":"第三十三条","txt":"《办法》第二十五条所称规定的使用区域是指国家税务总局和省税务局规定的区域。"},{"i":34,"n":"第三十四条","txt":"《办法》第二十六条所称身份验证是指单位和个人在领用、开具、代开发票时，其经办人应当实名办税。"},{"i":35,"n":"第三十五条","txt":"使用纸质发票的单位和个人应当妥善保管发票。发生发票丢失情形时，应当于发现丢失当日书面报告税务机关。"},{"i":36,"n":"第三十六条","txt":"税务机关在发票检查中，可以对发票数据进行提取、调出、查阅、复制。"},{"i":37,"n":"第三十七条","txt":"《办法》第三十一条所称发票换票证仅限于在本县(市)范围内使用。需要调出外县（市）的发票查验时，应当提请该县（市）税务机关调取发票。"},{"i":38,"n":"第三十八条","txt":"用票单位和个人有权申请税务机关对发票的真伪进行鉴别。收到申请的税务机关应当受理并负责鉴别发票的真伪；鉴别有困难的，可以提请发票监制税务机关协助鉴别。 在伪造、变造现场以及买卖地、存放地查获的发票，由当地税务机关鉴别。"},{"i":39,"n":"第三十九条","txt":"税务机关对违反发票管理法规的行为依法进行处罚的，由县以上税务机关决定；罚款额在2000元以下的，可由税务所决定。"},{"i":40,"n":"第四十条","txt":"《办法》第三十三条第六项规定以其他凭证代替发票使用的，包括： （一）应当开具发票而未开具发票，以其他凭证代替发票使用； （二）应当取得发票而未取得发票，以发票外的其他凭证或者自制凭证用于抵扣税款、出口退税、税前扣除和财务报销； （三）取得不符合规定的发票，用于抵扣税款、出口退税、税前扣除和财务报销。 构成逃避缴纳税款、骗取出口退税、虚开发票的，按照《中华人民共和国税收征收管理法》《办法》相关规定执行。"},{"i":41,"n":"第四十一条","txt":"《办法》第三十八条所称的公告是指，税务机关应当在办税场所或者广播、电视、报纸、期刊、网络等新闻媒体上公告纳税人发票违法的情况。公告内容包括：纳税人名称、统一社会信用代码或者纳税人识别号、经营地点、违反发票管理法规的具体情况。"},{"i":42,"n":"第四十二条","txt":"对违反发票管理法规情节严重构成犯罪的，税务机关应当依法移送司法机关处理。"},{"i":43,"n":"第四十三条","txt":"计划单列市税务局参照《办法》中省、自治区、直辖市税务局的职责做好发票管理工作。"},{"i":44,"n":"第四十四条","txt":"本实施细则自2011年2月1日起施行。"}],"chuxucunkuanlixisuodegerensuodeshuizhengshouguanliea9af9":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国个人所得税法》、《中华人民共和国税收征收管理法》和国务院关于《对个人储蓄存款利息所得征收个人所得税的实施办法》（以下简称《实施办法》）的有关规定，特制定本办法。"},{"i":2,"n":"第二条","txt":"储蓄存款利息所得个人所得税以取得储蓄存款利息所得的个人为纳税义务人，以办理结付个人储蓄存款利息的储蓄机构为扣缴义务人。扣缴义务人区分不同情况具体规定如下： 一、内资商业银行以支行或相当于支行的储蓄机构为扣缴义务人。经各省、自治区、直辖市和计划单列市国家税务局批准，扣缴义务人所扣税款或由其上一级机构汇总向其所在地主管税务机关申报缴纳。 二、城市信用社和农村信用社以独立核算的单位为扣缴义务人。 三、外资银行以设在中国境内的分行为扣缴义务人。 四、邮政储蓄机构以县级邮政局为扣缴义务人。 根据上述规定难以认定扣缴义务人的，由省、自治区、直辖市和计划单列市国家税务局依据便于扣缴义务人操作和税务机关征收管理、有利于明确扣缴义务人法律责任的原则进行认定。"},{"i":3,"n":"第三条","txt":"凡办理个人储蓄业务的储蓄机构，在向个人结付储蓄存款利息时，应依法代扣代缴其应缴纳的个人所得税税款。 前款所称结付储蓄存款利息，是指向个人储户支付利息、结息日和办理存款自动转存业务时结息。"},{"i":4,"n":"第四条","txt":"扣缴义务人应指定财务会计部门或其他有关部门的专门人员，具体负责扣缴税款的纳税申报及有关事宜。人员发生变动时，应将名单及时报告主管税务机关。 第五条扣缴义务人在代扣税款时，应当在给储户的利息清单上注明已扣税款的数额。注明已扣税款的利息清单视同完税证明，除另有规定者外，不再开具代扣代收税款凭证。"},{"i":5,"n":"第六条","txt":"扣缴义务人应扣未扣税款的，由扣缴义务人缴纳应扣未扣税款以及相应的滞纳金。其应纳税款按下列公式计算： 应纳税所得额=结付的利息额÷（1-税率） 应纳税额=应纳税所得额×适用税率"},{"i":6,"n":"第七条","txt":"扣缴义务人每月所扣的税款，应当在次月7日内缴入中央金库，并向主管税务机关报送《储蓄存款利息所得扣缴个人所得税报告表》和主管税务机关要求报送的其他有关资料；所扣税款为外币的，应当按照缴款上一月最后一日中国人民银行公布的人民币基准汇价折算成人民币，以人民币缴入国库。"},{"i":7,"n":"第八条","txt":"现有储蓄机构，符合本办法第二条规定的，应于《实施办法》公布后至11月1日前到当地主管税务机关办理扣缴税款登记；11月1日后成立的储蓄机构，凡符合本办法第二条规定的，应自中国人民银行批准开业之日起30日内，到当地主管税务机关办理扣缴税款登记。"},{"i":8,"n":"第九条","txt":"税务机关应依法对扣缴义务人的代扣代缴税款情况进行检查，扣缴义务人必须如实反映有关情况，提供有关资料，不得拒绝或隐瞒。 税务机关在依法检查中了解的情况，应依照《中华人民共和国商业银行法》的有关规定，为储户保密。"},{"i":9,"n":"第十条","txt":"主管税务机关应对扣缴义务人登记建档，建立收入统计台账，及时对征收情况进行总结、分析和预测。"},{"i":10,"n":"第十一条","txt":"其他征管事项，依照《中华人民共和国个人所得税》及其实施条例、《中华人民共和国税收征收管理法》及其实施细则和《个人所得税代扣代缴暂行办法》的有关规定执行。"},{"i":11,"n":"第十二条","txt":"各省、自治区、直辖市国家税务局可以根据本办法规定的原则，结合本地实际，制定具体实施办法，并报国家税务总局备案。"},{"i":12,"n":"第十三条","txt":"本办法由国家税务总局负责解释。"},{"i":13,"n":"第十四条","txt":"本办法自发布之日起执行。 附件：储蓄存款利息所得扣缴个人所得税报告表"}],"juanyanxiaofeishuijishuijiagexinxicaijihehedingguab81bf1":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国税收征收管理法》、《中华人民共和国消费税暂行条例》和《中华人民共和国消费税暂行条例实施细则》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"卷烟价格信息采集范围为在中华人民共和国境内销售的所有牌号、规格的卷烟。 卷烟消费税最低计税价格（以下简称计税价格）核定范围为卷烟生产企业在生产环节销售的所有牌号、规格的卷烟。"},{"i":3,"n":"第三条","txt":"卷烟价格信息采集的内容包括：卷烟牌号规格、卷烟类别、卷烟条包装商品条码、销售数量、销售价格和销售额及其他相关信息。"},{"i":4,"n":"第四条","txt":"卷烟批发企业所在地主管税务机关负责卷烟价格信息采集和审核工作。"},{"i":5,"n":"第五条","txt":"《卷烟批发企业月份销售明细清单》（以下简称《清单》，见附件），为卷烟批发企业申报缴纳消费税（以下简称申报纳税）的附报资料，由卷烟批发企业按月填写，于每月申报纳税时一并向主管税务机关报送。"},{"i":6,"n":"第六条","txt":"《卷烟生产企业年度销售明细表》（以下简称《明细表》，见附件），由卷烟生产企业于次年的1月份填写，于填报当月申报纳税时一并向主管税务机关报送。"},{"i":7,"n":"第七条","txt":"《清单》和《明细表》由主管税务机关审核后，于申报期结束后10个工作日内逐级上报至省（自治区、直辖市和计划单列市）税务局（以下简称省税务局）。省税务局应于次月15日前，上报国家税务总局。"},{"i":8,"n":"第八条","txt":"新牌号、新规格卷烟信息，由国家烟草专卖局于批准生产企业新牌号、新规格卷烟执行销售价格的当月，将卷烟牌号规格、类别、卷烟条包装商品条码、调拨价格、批发价格及建议计税价格等信息送国家税务总局。 卷烟生产企业应于新牌号、新规格卷烟实际销售的当月将上述信息报送主管税务机关。"},{"i":9,"n":"第九条","txt":"本办法第三条所称卷烟条包装商品条码按以下标准采集： （一）标准条（200支/条）包装的卷烟，为条包装卷烟的商品标识代码； （二）非标准条包装的卷烟，为卷烟实际外包装商品标识代码。"},{"i":10,"n":"第十条","txt":"计税价格由国家税务总局按照卷烟批发环节销售价格扣除卷烟批发环节批发毛利核定并发布。计税价格的核定公式为： 某牌号、规格卷烟计税价格=批发环节销售价格×（1-适用批发毛利率）"},{"i":11,"n":"第十一条","txt":"卷烟批发环节销售价格，按照税务机关采集的所有卷烟批发企业在价格采集期内销售的该牌号、规格卷烟的数量、销售额进行加权平均计算。计算公式为： 批发环节销售价格="},{"i":12,"n":"第十二条","txt":"卷烟批发毛利率具体标准为： （一）调拨价格满146.15元的一类烟34%； （二）其他一类烟29%； （三）二类烟25%； （四）三类烟25%； （五）四类烟20%； （六）五类烟15%。 调整后的卷烟批发毛利率，由国家税务总局另行发布。"},{"i":13,"n":"第十三条","txt":"已经核定计税价格的卷烟，发生下列情况，国家税务总局将重新核定计税价格： （一）卷烟价格调整的； （二）卷烟批发毛利率调整的； （三）通过《清单》采集的卷烟批发环节销售价格扣除卷烟批发毛利后，卷烟平均销售价格连续6个月高于国家税务总局已核定计税价格10%，且无正当理由的。"},{"i":14,"n":"第十四条","txt":"计税价格核定时限分别为： （一）新牌号、新规格的卷烟，国家税务总局于收到国家烟草专卖局相关信息满8个月或信息采集期满6个月后的次月核定并发布。 （二）已经核定计税价格的卷烟： 1.全行业卷烟价格或毛利率调整的，由国家烟草专卖局向国家税务总局提请重新调整计税价格。国家税务总局于收到申请调整计税价格文件后1个月内核定并发布； 2.个别牌号、规格卷烟价格调整的，由卷烟生产企业向主管税务机关提出重新核定计税价格的申请，主管税务机关逐级上报至国家税务总局。国家税务总局于收到申请调整计税价格文件后1个月内核定并发布； 3.连续6个月高于计税价格的，经相关省税务局核实后，且无正当理由的，国家税务总局于收到省税务局核实文件后1个月内核定并发布。"},{"i":15,"n":"第十五条","txt":"未经国家税务总局核定计税价格的新牌号、新规格卷烟，生产企业应按卷烟调拨价格申报纳税。 已经国家税务总局核定计税价格的卷烟，生产企业实际销售价格高于计税价格的，按实际销售价格确定适用税率，计算应纳税款并申报纳税；实际销售价格低于计税价格的，按计税价格确定适用税率，计算应纳税款并申报纳税。"},{"i":16,"n":"第十六条","txt":"对于在6个月内未按规定向国家税务总局报送信息资料的新牌号、新规格卷烟，国家税务总局将按照《清单》采集的实际销售价格适用最低档批发毛利率核定计税价格。"},{"i":17,"n":"第十七条","txt":"卷烟批发企业编制虚假批发环节实际销售价格信息的，由主管税务机关按照《中华人民共和国税收征收管理法》有关规定处理。"},{"i":18,"n":"第十八条","txt":"卷烟生产企业套用其他牌号、规格卷烟已核定计税价格，造成企业少缴消费税税款的，由主管税务机关自新牌号、新规格卷烟投放市场之日起调整卷烟生产企业应纳税收入，追缴少缴消费税税款，并按照《中华人民共和国税收征收管理法》有关规定处理。"},{"i":19,"n":"第十九条","txt":"国家税务总局依据国家烟草专卖局备案信息及《清单》，建立全国统一的卷烟信息库，记录各牌号规格卷烟核价的相关信息。"},{"i":20,"n":"第二十条","txt":"本办法下列用语的含义： “卷烟牌号规格”，是指经国家烟草专卖局批准生产的卷烟商标牌号规格。 “卷烟类别”，是指国家烟草专卖局划分的卷烟类别，即一类卷烟、二类卷烟、三类卷烟、四类卷烟和五类卷烟。 一类卷烟：是指每标准条（200支，下同）调拨价格满100元的卷烟。 二类卷烟：是指每标准条调拨价格满70元不满100元的卷烟。 三类卷烟：是指每标准条调拨价格满30元不满70元的卷烟。 四类卷烟：是指每标准条调拨价格满16.5元不满30元的卷烟。 五类卷烟：是指每标准条调拨价格不满16.5元的卷烟。 “卷烟条包装商品条码”，是指经国家烟草专卖局批准并下发的，符合国家标准规定的13位条包装卷烟的商品标识代码和非标准包装（如听、扁盒等）卷烟的外包装商品标识代码。 “新牌号卷烟”，是指在国家工商行政管理总局商标局新注册商标牌号，且未经国家税务总局核定计税价格的卷烟。 “新规格卷烟”，是指2009年5月"},{"i":21,"n":"第二十一条","txt":"本办法自2012年1月1日起施行。2003年1月23日国家税务总局公布的《卷烟消费税计税价格信息采集和核定管理办法》（国家税务总局令第5号）同时废止。 附件: 表1.卷烟批发企业月份销售明细清单及填表说明 表2.卷烟批发企业月份销售明细汇总表及填表说明 表3.卷烟生产企业年度销售明细表及填表说明 表4.卷烟生产企业年度销售明细汇总表及填表说明"}],"zengzhishuiyibannashuirendengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了做好增值税一般纳税人（以下简称“一般纳税人”）登记管理，根据《中华人民共和国增值税暂行条例》及其实施细则有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"增值税纳税人（以下简称“纳税人”），年应税销售额超过财政部、国家税务总局规定的小规模纳税人标准（以下简称“规定标准”）的，除本办法第四条规定外，应当向主管税务机关办理一般纳税人登记。 本办法所称年应税销售额，是指纳税人在连续不超过12个月或四个季度的经营期内累计应征增值税销售额，包括纳税申报销售额、稽查查补销售额、纳税评估调整销售额。 销售服务、无形资产或者不动产（以下简称“应税行为”）有扣除项目的纳税人，其应税行为年应税销售额按未扣除之前的销售额计算。纳税人偶然发生的销售无形资产、转让不动产的销售额，不计入应税行为年应税销售额。"},{"i":3,"n":"第三条","txt":"年应税销售额未超过规定标准的纳税人，会计核算健全，能够提供准确税务资料的，可以向主管税务机关办理一般纳税人登记。 本办法所称会计核算健全，是指能够按照国家统一的会计制度规定设置账簿，根据合法、有效凭证进行核算。"},{"i":4,"n":"第四条","txt":"下列纳税人不办理一般纳税人登记： （一）按照政策规定，选择按照小规模纳税人纳税的； （二）年应税销售额超过规定标准的其他个人。"},{"i":5,"n":"第五条","txt":"纳税人应当向其机构所在地主管税务机关办理一般纳税人登记手续。"},{"i":6,"n":"第六条","txt":"纳税人办理一般纳税人登记的程序如下： （一）纳税人向主管税务机关填报《增值税一般纳税人登记表》（附件1），如实填写固定生产经营场所等信息，并提供税务登记证件； （二）纳税人填报内容与税务登记信息一致的，主管税务机关当场登记； （三）纳税人填报内容与税务登记信息不一致，或者不符合填列要求的，税务机关应当场告知纳税人需要补正的内容。"},{"i":7,"n":"第七条","txt":"年应税销售额超过规定标准的纳税人符合本办法第四条第一项规定的，应当向主管税务机关提交书面说明（附件2）。"},{"i":8,"n":"第八条","txt":"纳税人在年应税销售额超过规定标准的月份（或季度）的所属申报期结束后15日内按照本办法第六条或者第七条的规定办理相关手续；未按规定时限办理的，主管税务机关应当在规定时限结束后5日内制作《税务事项通知书》，告知纳税人应当在5日内向主管税务机关办理相关手续；逾期仍不办理的，次月起按销售额依照增值税税率计算应纳税额，不得抵扣进项税额，直至纳税人办理相关手续为止。"},{"i":9,"n":"第九条","txt":"纳税人自一般纳税人生效之日起，按照增值税一般计税方法计算应纳税额，并可以按照规定领用增值税专用发票，财政部、国家税务总局另有规定的除外。 本办法所称的生效之日，是指纳税人办理登记的当月1日或者次月1日，由纳税人在办理登记手续时自行选择。"},{"i":10,"n":"第十条","txt":"纳税人登记为一般纳税人后，不得转为小规模纳税人，国家税务总局另有规定的除外。"},{"i":11,"n":"第十一条","txt":"主管税务机关应当加强对税收风险的管理。对税收遵从度低的一般纳税人，主管税务机关可以实行纳税辅导期管理，具体办法由国家税务总局另行制定。"},{"i":12,"n":"第十二条","txt":"本办法自2018年2月1日起施行,《增值税一般纳税人资格认定管理办法》（国家税务总局令第22号公布）同时废止。 附件： 1.增值税一般纳税人登记表 2.选择按小规模纳税人纳税的情况说明"}],"zengzhishuirichangjichabanfa":[{"i":1,"n":"第一条","txt":"为了规范增值税日常稽查的内容和程序，加强增值税日常稽查管理，防范和查处偷骗增值税行为，提高纳税人依法纳税自觉性，根据《中华人民共和国税收征收管理法》、《中华人民共和国增值税暂行条例》制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于税务机关对增值税一般纳税人（以下简称纳税人）实施的增值税日常稽查。小规模纳税人增值税日常稽查办法另行制定。"},{"i":3,"n":"第三条","txt":"增值税日常稽查是税务机关依照税收法律、法规和规章，对纳税人履行纳税义务情况实施常规稽核和检查的总称，包括稽核、检查及一般性违法问题的处理。"},{"i":4,"n":"第四条","txt":"增值税稽核是税务机关监审纳税人增值税纳税申报情况及相关资料，筛选检查对象的过程，分为一级稽核和二级稽核。 一级稽核的工作内容和步骤： （一）监控纳税人的申报情况。对超过纳税申报期限未办理纳税申报者，在本纳税申报期结束后5日内，向其发出催报通知。对连续两个月逾期未申报的，列印《未申报纳税人清单》送交检查。 （二）审核纳税人的申报数据。依据纳税申报表内各指标之间的逻辑关系，对所申报的应纳税额进行逻辑审核。对申报有误的，应及时向纳税人发出《申报错误更正通知》。 （三）按季计算分析纳税人销售额变动率和税负率，计算公式如下： 1.销售额变动率＝（本年累计应税销售额-上年同期应税销售额）÷上年同期应税销售额×100% 2.税负率＝（本年累计应纳税额÷本年累计应税销售额）×100% 将销售额变动率和税负率与相应的正常峰值进行比较，对存在下列问题的纳税人，列印《纳税申报异常纳税人清单》送交二级稽核。"},{"i":5,"n":"第五条","txt":"将稽核发现的问题和疑点，分别不同情况作如下处理： （一）对纳税人申报异常提出质询，并逐一记录质询情况，质询记录内容包括：纳税人名称、纳税人识别号、申报异常所属时期、销售额变动率及税负率、答复人姓名以及答复情况等。 （二）对申报异常且无正当理由的纳税人应填写《增值税待查对象通知》，送交检查；申报异常现象特别严重或有较大偷骗税嫌疑的，填写《增值税待查对象特急通知》送交专案检查。 （三）质询记录、待查对象通知和检查情况所报资料要随时复核，定期统计并报主管领导审阅。"},{"i":6,"n":"第六条","txt":"对稽核阶段未被列入检查对象的纳税人，应定期随机抽取一定数量的待查对象送交检查。对该类纳税人的检查间隔（即实施两次检查之间的时间）最长不得超过3年。"},{"i":7,"n":"第七条","txt":"增值税检查是税务机关对纳税人会计核算资料及有关生产经营情况进行实地检查的过程。"},{"i":8,"n":"第八条","txt":"增值税检查的对象为稽核环节送达的未申报清单和待查对象通知所列的纳税人以及根据本办法第六条确定的纳税人。"},{"i":9,"n":"第九条","txt":"增值税检查应按计划组织实施，对未申报待查对象的检查应自通知送达之日起1个月内实施，对申报异常的待查对象的检查应自通知送达之日起2个月内实施。"},{"i":10,"n":"第十条","txt":"增值税检查方法根据待查对象的具体情况确定： （一）无申报异常现象的，可采取抽查的方法，如有问题再全面检查。 （二）有申报异常现象的，应以销项或进项的某一方面问题核实为主，实施销项税额与进项税额的全面检查。 1.销售额变动率高于正常峰值及税负率低于正常峰值或销售额变动率正常，而税负率低于正常峰值的，以进项税额为检查重点，查证有无扩大进项抵扣范围、骗抵进项税额、不按规定申报抵扣等问题，对应核实销项税额计算的正确性； 2.销售额变动率低于正常峰值及税负率变动低于正常峰值的，销项税额和进项税额均应作为检查重点。 对销项税额的检查，应侧重查证有无帐外经营、瞒报、迟报计税销售额、混淆增值税与营业税征税范围、错用税率等问题。 检查基本方法见附件1."},{"i":11,"n":"第十一条","txt":"经稽核、检查核实的一般性偷骗税问题应按《中华人民共和国税收征收管理法》有关条款及现行有关管理规定进行处理；同时责成纳税人进行相关的帐务调整（具体调帐方法见附件2）。对偷骗税数额较大、情节较严重、涉及地域范围较广的偷骗税案件应及时移送专案稽查。"},{"i":12,"n":"第十二条","txt":"经增值税检查查实的问题及处理情况应按国家税务总局统一规定的文书形式反馈给二级稽核。"},{"i":13,"n":"第十三条","txt":"《未申报纳税人清单》、《申报错误更正通知》、《纳税申报异常纳税人清单》、《增值税待查对象通知》、《增值税待查对象特急通知》的样式及内容由各省级税务机关确定。"},{"i":14,"n":"第十四条","txt":"本办法自1998年1月1日起执行。"}],"zengzhishuiruoganjutiwentideguiding":[],"zengzhishuifangweishuikongxitongguanlibanfa":[{"i":1,"n":"第一条","txt":"为保证增值税防伪税控系统（以下简称防伪税控系统）的顺利推行和正常运转，防范利用增值税专用发票（以下简称专用发票）偷骗税的不法行为，进一步加强增值税征收管理，特制定本办法。"},{"i":2,"n":"第二条","txt":"防伪税控系统的推广应用由国家税务总局（以下简称总局）统一领导，省级以下税务机关逐级组织实施。"},{"i":3,"n":"第三条","txt":"各级税务机关增值税业务管理部门（以下简称业务部门）负责防伪税控系统推行应用的组织及日常管理工作，计算机技术管理部门（以下简称技术部门）提供技术支持。"},{"i":4,"n":"第四条","txt":"主管税务机关根据防伪税控系统推行计划确定纳入防伪税控系统管理的企业（以下简称防伪税控企业），下达《增值税防伪税控系统使用通知书》（附件1）。"},{"i":5,"n":"第五条","txt":"防伪税控企业认定登记事项发生变化，应到主管税务机关办理变更认定登记手续。"},{"i":6,"n":"第六条","txt":"防伪税控企业发生下列情形，应到主管税务机关办理注销认定登记，同时由主管税务机关收缴金税卡和IC卡（以下简称两卡）。 （一）依法注销税务登记，终止纳税义务； （二）被取消一般纳税人资格； （三）减少分开票机。"},{"i":7,"n":"第七条","txt":"防伪税控系统发行实行分级管理。 总局负责发行省级税务发行子系统以及省局直属征收分局认证报税子系统、企业发行子系统和发票发售子系统； 省级税务机关负责发行地级税务发行子系统以及地级直属征收分局认证报税子系统、企业发行子系统和发票发售子系统； 地级税务机关负责发行县级认证报税子系统、企业发行子系统和发票发售子系统； 地级税务机关经省级税务机关批准，可发行县级所属征收单位认证报税子系统、企业发行子系统和发票发售子系统。"},{"i":8,"n":"第八条","txt":"防伪税控企业办理认定登记后，由主管税务机关负责向其发行开票子系统。"},{"i":9,"n":"第九条","txt":"防伪税控企业发生本办法第七条情形的，应同时办理变更发行。"},{"i":10,"n":"第十条","txt":"防伪税控系统专用设备（以下简称专用设备）包括：金税卡、IC卡、读卡器、延伸板及相关软件等。防伪税控系统税务专用设备由总局统一配备并逐级发放；企业专用设备由防伪税控系统技术服务单位（以下简称服务单位）实施发售管理。"},{"i":11,"n":"第十一条","txt":"主管税务机关需要增配专用设备的，应填制《防伪税控系统专用设备需求表》（附件2）报上级税务机关核发。"},{"i":12,"n":"第十二条","txt":"地级以上税务机关接收和发放专用设备，应严格交接制度，分别填写《防伪税控系统专用设备入库单》（附件3）和《防伪税控系统专用设备出库单》（附件4），及时登记《防伪税控系统（专用设备）收、发、存台账》（附件5）。 各级税务机关对库存专用设备实行按月盘存制度，登记《增值税防伪税控专用设备盘存表》（附件6）。"},{"i":13,"n":"第十三条","txt":"服务单位凭主管税务机关下达的《增值税防伪税控系统使用通知书》向防伪税控企业发售专用设备。"},{"i":14,"n":"第十四条","txt":"服务单位应参照本办法第十二条的规定，加强企业专业设备的仓储发售管理，认真记录收发存情况。对库存专用设备实行按月盘点制度，登记《增值税防伪税控专用设备盘存表》（同附件6），并报同级税务机关备案。"},{"i":15,"n":"第十五条","txt":"防伪税控企业凭税控IC卡向主管税务机关领购电脑版专用发票。主管税务机关核对企业出示的相关资料与税控IC卡记录内容，确认无误后，按照专用发票发售管理规定，通过企业发票发售子系统发售专用发票，并将专用发票的起始号码及发售时间登录在税控IC卡内。"},{"i":16,"n":"第十六条","txt":"新纳入防伪税控系统的企业，在系统启用后十日内将启用前尚未使用完的专用发票（包括误填作废的专用发票）报主管税务机关缴销。"},{"i":17,"n":"第十七条","txt":"防伪税控企业必须使用防伪税控系统开具专用发票，不得以其他方式开具手工版或电脑版专用发票。"},{"i":18,"n":"第十八条","txt":"防伪税控企业应按照《增值税专用发票使用规定》开具专用发票，打印压线或错格的，应作废重开。"},{"i":19,"n":"第十九条","txt":"防伪税控企业应在纳税申报期限内将抄有申报所属月份纳税信息的IC卡和备份数据软盘向主管税务机关报税。"},{"i":20,"n":"第二十条","txt":"防伪税控企业和未纳入防伪税控系统管理的企业取得的防伪税控系统开具的专用发票抵扣联，应据增值税有关扣税规定核算当期进项税额，如期申报纳税，属于扣税范围的，应于纳税申报时或纳税申报前报主管税务机关认证。"},{"i":21,"n":"第二十一条","txt":"主管税务机关应在企业申报月份内完成企业申报所属月份的防伪税控专用发票抵扣联的认证。对因褶皱、揉搓等无法认证的加盖“无法认证”戳记，认证不符的加盖“认证不符”戳记，属于利用丢失被盗金税卡开具的加盖“丢失被盗”戳记。认证完毕后，应将认证相符和无法认证的专用发票抵扣联退还企业，并同时向企业下达《认证结果通知书》（附件7）。对认证不符和确认为丢失、被盗金税卡开具的专用发票应及时组织查处。 认证戳记式样由各省级税务机关统一制定。"},{"i":22,"n":"第二十二条","txt":"防伪税控企业应将税务机关认证相符的专用发票抵扣联连同《认证结果通知书》和认证清单一起按月装订成册备查。"},{"i":23,"n":"第二十三条","txt":"经税务机关认证确定为“无法认证”、“认证不符”以及“丢失被盗”的专用发票，防伪税控企业如已申报扣税的，应调减当月进项税额。"},{"i":24,"n":"第二十四条","txt":"报税子系统采集的专用发票存根联数据和认证子系统采集的专用发票抵扣联数据应按规定传递到增值税计算机稽核系统。"},{"i":25,"n":"第二十五条","txt":"防伪税控企业金税卡需要维修或更换时，其存储的数据，必须通过磁盘保存并列印出清单。税务机关应核查金税卡内尚未申报的数据和软盘中专用发票开具的明细信息，生成专用发票存根联数据传递到增值税计算机稽核系统；企业计算机主机损坏不能抄录开票明细信息的，税务机关应对企业开具的专用发票存根联通过防伪税控认证子系统进行认证，产生专用发票存根联数据传递到增值税计算机稽核系统。"},{"i":26,"n":"第二十六条","txt":"防伪税控系统研制生产单位应按照总局制定的推行计划组织专用设备的生产，确保产品质量。严格保密、交接等各项制度。两卡等关键设备在出厂时要进行统一编号，标贴国家密码管理委员会办公室核发的“商密产品认证标识”。"},{"i":27,"n":"第二十七条","txt":"各地税务机关技术部门应做好税务机关内部防伪税控系统的技术支持和日常维护工作。"},{"i":28,"n":"第二十八条","txt":"系统研制生产单位应在各地建立服务单位，负责防伪税控系统的安装调试、操作培训、维护服务和企业用防伪税控系统专用设备的销售。"},{"i":29,"n":"第二十九条","txt":"税务机关应与当地服务单位签订协议，明确工作程序、业务规范和双方的权利义务等事项。"},{"i":30,"n":"第三十条","txt":"服务单位在向防伪税控企业发售专用设备时，应和企业签订系统维护合同，按照税务机关的有关要求明确服务标准和违约责任等事项，并报当地税务机关备案。"},{"i":31,"n":"第三十一条","txt":"防伪税控系统使用过程中出现的技术问题，税务机关、服务单位应填制《防伪税控系统故障登记表》（附件8），分别逐级上报总局和系统研制生产单位，重大问题及时上报。"},{"i":32,"n":"第三十二条","txt":"税务机关用两卡应由专人使用保管，使用或保管场所应有安全保障措施。发生丢失、被盗的，应立即报公安机关侦破追缴，并报上级税务机关进行系统处理。"},{"i":33,"n":"第三十三条","txt":"按照密码安全性的要求，总局适时统一布置更换系统密钥，部分地区由于两卡丢失被盗等原因需要更换密钥的，由上一级税务机关决定。"},{"i":34,"n":"第三十四条","txt":"有关防伪税控系统管理的表、账、册及税务文书等资料保存期为五年。"},{"i":35,"n":"第三十五条","txt":"防伪税控企业应采取有效措施保障开票设备的安全，对税控IC卡和专用发票应分开专柜保管。"},{"i":36,"n":"第三十六条","txt":"任何单位和个人未经总局批准不得擅自改动防伪税控系统软、硬件。"},{"i":37,"n":"第三十七条","txt":"服务单位和防伪税控企业专用设备发生丢失被盗的，应迅速报告公安机关和主管税务机关。各级税务机关按月汇总上报《丢失、被盗金税卡情况表》（附件9）。总局建立丢失被盗金税卡数据库下发各地录入认证子系统。"},{"i":38,"n":"第三十八条","txt":"税务机关或企业损坏的两卡以及按本办法第六条规定收缴的两卡，由省级税务机关统一登记造册并集中销毁。"},{"i":39,"n":"第三十九条","txt":"税务机关应定期检查服务单位的两卡收发存和技术服务情况。督促服务单位严格两卡发售工作程序，落实安全措施。严格履行服务协议，不断改进服务工作。"},{"i":40,"n":"第四十条","txt":"防伪税控企业逾期未报税，经催报仍不报的，主管税务机关应立即进行实地查处。"},{"i":41,"n":"第四十一条","txt":"防伪税控企业未按规定使用保管专用设备，发生下列情形之一的，视同未按规定使用和保管专用发票处罚： （一）因保管不善或擅自拆装专用设备造成系统不能正常运行； （二）携带系统外出开具专用发票。"},{"i":42,"n":"第四十二条","txt":"各级税务机关应定期检查系统发行情况，地级以上税务机关对下一级税务机关的检查按年进行，地级对县级税务机关的检查按季进行。"},{"i":43,"n":"第四十三条","txt":"本办法由国家税务总局负责解释。各地可根据本办法制定具体实施细则。"},{"i":44,"n":"第四十四条","txt":"本办法自2000年1月1日起施行。 附件： 1.增值税防伪税控系统使用通知书 2.防伪税控系统专用设备需求表 3.防伪税控系统专用设备入库单 4.防伪税控系统专用设备出库单 5.防伪税控系统（专用设备）收、发、存台账 6.增值税防伪税控专用设备盘存表 7.认证结果通知书 8.防伪税控系统故障登记表 9.丢失、被盗金税卡情况表"}],"guanggaoshichanggerensuodeshuizhengshouguanlizanxieb470e":[{"i":1,"n":"第一条","txt":"为了进一步加强对广告市场个人所得税的征收管理，依据《中华人民共和国个人所得税法》及其实施条例和《中华人民共和国税收征收管理法》及其实施细则，制定本办法。"},{"i":2,"n":"第二条","txt":"凡在广告中提供名义、形象或在广告设计、制作、发布过程中提供劳务并取得所得的个人以及广告主、广告经营者或受托从事广告制作的单位和广告发布者，均应当依照本办法的规定办理个人所得税有关事宜。 本办法所称广告主，是指为推销商品或者提供服务，自行或者委托他人设计、制作、发布广告的法人、其他经济组织或者个人。 本办法所称广告经营者，是指受委托提供广告设计、制作、代理服务的法人、其他经济组织或者个人。 本办法所称受托从事广告制作的单位，是指受广告主或广告经营者委托而从事广告设计、制作的法人、其他经济组织或者个人。 本办法所称广告发布者，是指为广告主、或者广告主委托的广告经营者发布广告的法人及其他经济组织。"},{"i":3,"n":"第三条","txt":"在广告设计、制作、发布过程中提供名义、形象及劳务并取得所得的个人为个人所得税的纳税义务人（以下简称纳税人）；直接向上述个人支付所得的广告主、广告经营者、受托从事广告制作的单位和广告发布者为个人所得税的扣缴义务人（以下简称扣缴人）。"},{"i":4,"n":"第四条","txt":"扣缴人应当在每项广告制作前向所在地主管税务机关报告广告中名义、形象及劳务提供者的姓名、身份证号码（护照号码及国籍）、工作单位（户籍所在地）、电话号码以及支付报酬的标准和支付形式等情况。双方订立书面合同（协议）的，应同时将合同（协议）副本报送上述税务机关。 广告发布者应当定期向所在地主管税务机关报送当期发布广告的数量及其广告主、广告经营者的名单。"},{"i":5,"n":"第五条","txt":"纳税人在广告设计、制作、发布过程中提供名义、形象而取得的所得，应按劳务报酬所得项目计算纳税。 纳税人在广告设计、制作、发布过程中提供其他劳务取得的所得，视其情况分别按照税法规定的劳务报酬所得、稿酬所得、特许权使用费所得等应税项目计算纳税。 扣缴人的本单位人员在广告设计、制作、发布过程中取得的由本单位支付的所得，按工资、薪金所得项目计算纳税。"},{"i":6,"n":"第六条","txt":"纳税人以现金、实物和有价证券以外的其他形式取得所得，税务机关可以根据其所得的形式和价值，核定其应纳税所得额，据以征税。 对于不能准确提供或划分个人在广告设计、制作、发布过程中提供名义、形象及劳务而取得的所得的纳税人，主管税务机关可以根据支付总额等实际情况，参照同类广告活动名义、形象及其他劳务提供者的所得标准，核定其应纳税所得额，据以征税。"},{"i":7,"n":"第七条","txt":"劳务报酬所得以纳税人每参与一项广告的设计、制作、发布所取得的所得为一次；稿酬所得以在图书、报刊上发布一项广告时使用其作品而取得的所得为一次；特许权使用费所得以提供一项特许权在一项广告的设计、制作、发布过程中使用而取得的所得为一次。上述所得，采取分笔支付的，应合并为一次所得计算纳税。"},{"i":8,"n":"第八条","txt":"分笔取得一次所得和扣缴人应扣未扣或少扣税款以及没有扣缴人的纳税人，应当于取得所得的月度终了后七日内，向扣缴人所在地主管税务机关自行申报纳税。"},{"i":9,"n":"第九条","txt":"扣缴人和纳税人必须接受税务机关依法进行的税务检查，如实反映情况，提供有关资料，不得拒绝、隐瞒。"},{"i":10,"n":"第十条","txt":"本办法未尽事宜，按照有关税收法律、行政法规的规定执行。"},{"i":11,"n":"第十一条","txt":"各省、自治区、直辖市税务局可以根据本办法规定的原则，结合本地实际，制定具体实施办法，并报国家税务总局备案。"},{"i":12,"n":"第十二条","txt":"本办法由国家税务总局负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自1996年9月1日起执行。"}],"jianzhuanzhuangyegerensuodeshuizhengshouguanlizanxf75c55":[{"i":1,"n":"第一条","txt":"为了加强对建筑安装业个人所得税的征收管理，根据《中华人民共和国个人所得税法》及其实施条例、《中华人民共和国税收征收管理法》及其实施细则和其他有关法律、行政法规的规定制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称建筑安装业，包括建筑、安装、修缮、装饰及其他工程作业。从事建筑安装业的工程承包人、个体户及其他个人为个人所得税的纳税义务人。其从事建筑安装业取得的所得，应依法缴纳个人所得税。"},{"i":3,"n":"第三条","txt":"承包建筑安装业各项工程作业的承包人取得的所得，应区别不同情况计征个人所得税：经营成果归承包人个人所有的所得，或按照承包合同（协议）规定，将一部分经营成果留归承包人个人的所得，按对企事业单位的承包经营、承租经营所得项目征税；以其他分配方式取得的所得，按工资、薪金所得项目征税。 从事建筑安装业的个体工商户和未领取营业执照承揽建筑安装业工程作业的建筑安装队和个人，以及建筑安装企业实行个人承包后工商登记改变为个体经济性质的，其从事建筑安装业取得的收入应依照个体工商户的生产、经营所得项目计征个人所得税。 从事建筑安装业工程作业的其他人员取得的所得，分别按照工资、薪金所得项目和劳务报酬所得项目计征个人所得税。"},{"i":4,"n":"第四条","txt":"从事建筑安装业的单位和个人，应依法办理税务登记。在异地从事建筑安装业的单位和个人，必须自工程开工之日前三日内，持营业执照、外出经营活动税收管理证明、城建部门批准开工的文件和工程承包合同（协议）、开户银行账号以及主管税务机关要求提供的其他资料向主管税务机关办理有关登记手续。"},{"i":5,"n":"第五条","txt":"对未领取营业执照承揽建筑安装业工程作业的单位和个人，主管税务机关可以根据其工程规模，责令其缴纳一定数额的纳税保证金。在规定的期限内结清税款后，退还纳税保证金；逾期未结清税款的，以纳税保证金抵缴应纳税款和滞纳金。"},{"i":6,"n":"第六条","txt":"从事建筑安装业的单位和个人应设置会计账簿，健全财务制度，准确、完整地进行会计核算。对未设立会计账簿，或者不能准确、完整地进行会计核算的单位和个人，主管税务机关可根据其工程规模、工程承包合同（协议）价款和工程完工进度等情况，核定其应纳税所得额或应纳税额，据以征税。具体核定办法由县以上（含县级）税务机关制定。"},{"i":7,"n":"第七条","txt":"从事建筑安装业工程作业的单位和个人应按照主管税务机关的规定，购领、填开和保管建筑安装业专用发票或许可使用的其他发票。"},{"i":8,"n":"第八条","txt":"建筑安装业的个人所得税，由扣缴义务人代扣代缴和纳税人自行申报缴纳。"},{"i":9,"n":"第九条","txt":"承揽建筑安装业工程作业的单位和个人是个人所得税的代扣代缴义务人，应在向个人支付收入时依法代扣代缴其应纳的个人所得税。"},{"i":10,"n":"第十条","txt":"没有扣缴义务人的和扣缴义务人未按规定代扣代缴税款的，纳税人应自行向主管税务机关申报纳税。"},{"i":11,"n":"第十一条","txt":"本办法第三条第一款、第二款涉及的纳税人和扣缴义务人应按每月工程完工量预缴、预扣个人所得税，按年结算。一项工程跨年度作业的，应按各年所得预缴、预扣和结算个人所得税。难以划分各年所得的，可以按月预缴、预扣税款，并在工程完工后按各年度工程完工量分摊所得并结算税款。"},{"i":12,"n":"第十二条","txt":"扣缴义务人每月所扣的税款，自行申报纳税人每月应纳的税款，应当在次月七日内缴入国库，并向主管税务机关报送扣缴个人所得税报告表或纳税申报表以及税务机关要求报送的其他资料。"},{"i":13,"n":"第十三条","txt":"对扣缴义务人按照所扣缴的税款，付给2%的手续费。"},{"i":14,"n":"第十四条","txt":"建筑安装业单位所在地税务机关和工程作业所在地税务机关双方可以协商有关个人所得税代扣代缴和征收的具体操作办法，都有权对建筑安装业单位和个人依法进行税收检查，并有权依法处理其违反税收规定的行为。但一方已经处理的，另一方不得重复处理。"},{"i":15,"n":"第十五条","txt":"本办法所称主管税务机关，是指建筑安装业工程作业所在地税务局（分局、所）。"},{"i":16,"n":"第十六条","txt":"各省、自治区、直辖市税务局可根据本办法规定的原则，结合本地实际制定具体的征管办法，并报国家税务总局备案。"},{"i":17,"n":"第十七条","txt":"本办法未尽事宜，按照《中华人民共和国个人所得税法》及其实施条例、《中华人民共和国税收征收管理法》及其实施细则以及其他有关的法律、行政法规的规定执行。"},{"i":18,"n":"第十八条","txt":"本办法由国家税务总局负责解释。"},{"i":19,"n":"第十九条","txt":"本办法从1996年1月1日起执行。"}],"zhengshougerensuodeshuiruoganwentideguiding":[],"chengpinyoulingshoujiayouzhanzengzhishuizhengshouga6ffa7":[{"i":1,"n":"第一条","txt":"为加强成品油零售加油站的增值税征收管理，堵塞税收管理漏洞，根据《中华人民共和国税收征收管理法》、《中华人民共和国增值税暂行条例》及有关税收政策规定，制定本办法。"},{"i":2,"n":"第二条","txt":"凡经经贸委批准从事成品油零售业务，并已办理工商、税务登记，有固定经营场所，使用加油机自动计量销售成品油的单位和个体经营者（以下简称加油站），适用本办法。"},{"i":3,"n":"第三条","txt":"本办法第一条所称加油站，一律按照《国家税务总局关于加油站一律按照增值税一般纳税人征税的通知》（国税函〔2001〕882号）认定为增值税一般纳税人；并根据《中华人民共和国增值税暂行条例》有关规定进行征收管理。"},{"i":4,"n":"第四条","txt":"采取统一配送成品油方式设立的非独立核算的加油站，在同一县市的，由总机构汇总缴纳增值税。在同一省内跨县市经营的，是否汇总缴纳增值税，由省级税务机关确定。跨省经营的，是否汇总缴纳增值税，由国家税务总局确定。 对统一核算，且经税务机关批准汇总缴纳增值税的成品油销售单位跨县市调配成品油的，不征收增值税。"},{"i":5,"n":"第五条","txt":"加油站无论以何种结算方式（如收取现金、支票、汇票、加油凭证（簿）、加油卡等）收取售油款，均应征收增值税。加油站销售成品油必须按不同品种分别核算，准确计算应税销售额。加油站以收取加油凭证（簿）、加油卡方式销售成品油，不得向用户开具增值税专用发票。"},{"i":6,"n":"第六条","txt":"加油站应税销售额包括当月成品油应税销售额和其他应税货物及劳务的销售额。其中成品油应税销售额的计算公式为： 成品油应税销售额=（当月全部成品油销售数量-允许扣除的成品油数量）×油品单价"},{"i":7,"n":"第七条","txt":"加油站必须按规定建立《加油站日销售油品台账》（附表1，以下简称台账）登记制度。加油站应按日登记台账，按日或交接班次填写，完整、详细地记录当日或本班次的加油情况，月终汇总登记《加油站月销售油品汇总表》（附表2）。台账须按月装订成册，按会计原始账证的期限保管，以备主管税务机关检查。"},{"i":8,"n":"第八条","txt":"加油站除按月向主管税务机关报送增值税一般纳税人纳税申报办法规定的申报资料外，还应报送以下资料： （一）《加油站______月份加油信息明细表》（附表3）或加油IC卡； （二）《加油站月销售油品汇总表》； （三）《成品油购销存数量明细表》（附表4）。"},{"i":9,"n":"第九条","txt":"加油站通过加油机加注成品油属于以下情形的，允许在当月成品油销售数量中扣除： （一）经主管税务机关确定的加油站自有车辆自用油。 （二）外单位购买的，利用加油站的油库存放的代储油。 加油站发生代储油业务时，应凭委托代储协议及委托方购油发票复印件向主管税务机关申报备案。 （三）加油站本身倒库油。 加油站发生成品油倒库业务时，须提前向主管税务机关报告说明，由主管税务机关派专人实地审核监控。 （四）加油站检测用油（回罐油）。 上述允许扣除的成品油数量，加油站月终应根据《加油站月销售油品汇总表》统计的数量向主管税务机关申报。"},{"i":10,"n":"第十条","txt":"成品油生产、批发单位所在地税务机关应按月将其销售成品油信息通过金税工程网络传递到购油企业所在地主管税务机关。"},{"i":11,"n":"第十一条","txt":"对财务核算不健全的加油站，如已全部安装税控加油机，应按照税控加油机所记录的数据确定计税销售额征收增值税。对未全部安装税控加油机（包括未安装）或税控加油机运行不正常的加油站，主管税务机关应要求其严格执行台账制度，并按月报送《成品油购销存数量明细表》。按月对其成品油库存数量进行盘点，定期联合有关执法部门对其进行检查。 主管税务机关应将财务核算不健全的加油站全部纳入增值税纳税评估范围，结合通过金税工程网络所掌握的企业购油信息以及本地区同行业的税负水平等相关信息，按照《国家税务总局关于加强商贸企业增值税纳税评估工作的通知》（国税发〔2001〕140号）的有关规定进行增值税纳税评估。对纳税评估有异常的，应立即移送稽查部门进行税务稽查。 主管税务机关对财务核算不健全的加油站可以根据所掌握的企业实际经营状况，核定征收增值税。 财务核算不健全的加油站，主管税务机关应根据其实际经营情况和专用发票使用管理"},{"i":12,"n":"第十二条","txt":"发售加油卡、加油凭证销售成品油的纳税人（以下简称“预售单位”）在售卖加油卡、加油凭证时，应按预收账款方法作相关账务处理，不征收增值税。 预售单位在发售加油卡或加油凭证时可开具普通发票，如购油单位要求开具增值税专用发票，待用户凭卡或加油凭证加油后，根据加油卡或加油凭证回笼记录，向购油单位开具增值税专用发票。接受加油卡或加油凭证销售成品油的单位与预售单位结算油款时，接受加油卡或加油凭证销售成品油的单位根据实际结算的油款向预售单位开具增值税专用发票。"},{"i":13,"n":"第十三条","txt":"主管税务机关每季度应对所辖加油站运用稽查卡进行1次加油数据读取，并将读出的数据与该加油站的《增值税纳税申报表》、《加油站日销售油品台账》、《加油站月销售油品汇总表》等资料进行核对，同时应对加油站的应扣除油量的确定、成品油购销存等情况进行全面纳税检查。"},{"i":14,"n":"第十四条","txt":"本办法自2002年5月1日起执行。 附表：1.加油站日销售成品油台账 　　　2.加油站月销售油品汇总表 　　　3.加油站_________月份加油信息明细表 　　　4.成品油购销存数量明细表"}],"dishuicaiwupaimaibianmaishixingbanfa":[{"i":1,"n":"第一条","txt":"为规范税收强制执行中抵税财物的拍卖、变卖行为，保障国家税收收入，保护纳税人合法权益，根据《中华人民共和国税收征收管理法》及其实施细则和有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"税务机关拍卖、变卖抵税财物，以拍卖、变卖所得抵缴税款、滞纳金的行为，适用本办法。 拍卖是指税务机关将抵税财物依法委托拍卖机构，以公开竞价的形式，将特定财物转让给最高应价者的买卖方式。 变卖是指税务机关将抵税财物委托商业企业代为销售、责令纳税人限期处理或由税务机关变价处理的买卖方式。 抵税财物，是指被税务机关依法实施税收强制执行而扣押、查封或者按照规定应强制执行的已设置纳税担保物权的商品、货物、其他财产或者财产权利。 被执行人是指从事生产经营的纳税人、扣缴义务人或者纳税担保人等税务行政相对人。"},{"i":3,"n":"第三条","txt":"拍卖或者变卖抵税财物应依法进行，并遵循公开、公正、公平、效率的原则。"},{"i":4,"n":"第四条","txt":"有下列情形之一的，税务机关依法进行拍卖、变卖： （一）采取税收保全措施后，限期期满仍未缴纳税款的； （二）设置纳税担保后，限期期满仍未缴纳所担保的税款的； （三）逾期不按规定履行税务处理决定的； （四）逾期不按规定履行复议决定的； （五）逾期不按规定履行税务行政处罚决定的； （六）其他经责令限期缴纳，逾期仍未缴纳税款的。 对前款（三）至（六）项情形进行强制执行时，在拍卖、变卖之前（或同时）进行扣押、查封，办理扣押、查封手续。"},{"i":5,"n":"第五条","txt":"税务机关按照拍卖优先的原则确定抵税财物拍卖、变卖的顺序： （一）委托依法成立的拍卖机构拍卖； （二）无法委托拍卖或者不适于拍卖的，可以委托当地商业企业代为销售，或者责令被执行人限期处理； （三）无法委托商业企业销售，被执行人也无法处理的，由税务机关变价处理。 国家禁止自由买卖的商品、货物、其他财产，应当交由有关单位按照国家规定的价格收购。"},{"i":6,"n":"第六条","txt":"税务机关拍卖变卖抵税财物时按下列程序进行： （一）制作拍卖（变卖）抵税财物决定书，经县以上税务局（分局）局长批准后，对被执行人下达拍卖（变卖）抵税财物决定书。 依照法律法规规定需要经过审批才能转让的物品或财产权利，在拍卖、变卖前，应当依法办理审批手续。 （二）查实需要拍卖或者变卖的商品、货物或者其他财产。在拍卖或者变卖前，应当审查所扣押商品、货物、财产专用收据和所查封商品、货物、财产清单，查实被执行人与抵税财物的权利关系，核对盘点需要拍卖或者变卖的商品、货物或者其他财产是否与收据或清单一致。 （三）按照本办法规定的顺序和程序，委托拍卖、变卖，填写拍卖（变卖）财产清单，与拍卖机构签订委托拍卖合同，与受委托的商业企业签订委托变卖合同，对被执行人下达税务事项通知书，并按规定结算价款。 （四）以拍卖、变卖所得支付应由被执行人依法承担的扣押、查封、保管以及拍卖、变卖过程中的费用。 （五）拍卖、变"},{"i":7,"n":"第七条","txt":"拍卖、变卖抵税财物，由县以上税务局（分局）组织进行。变卖鲜活、易腐烂变质或者易失效的商品、货物时，经县以上税务局（分局）局长批准，可由县以下税务机关进行。"},{"i":8,"n":"第八条","txt":"拍卖、变卖抵税财物进行时，应当通知被执行人到场；被执行人未到场的，不影响执行。"},{"i":9,"n":"第九条","txt":"税务机关及其工作人员不得参与被拍卖或者变卖商品、货物或者其他财产的竞买或收购，也不得委托他人为其竞买或收购。"},{"i":10,"n":"第十条","txt":"拍卖由财产所在地的省、自治区、直辖市的人民政府和设区的市的人民政府指定的拍卖机构进行拍卖。"},{"i":11,"n":"第十一条","txt":"抵税财物除有市场价或其价格依照通常方法可以确定的外，应当委托依法设立并具有相应资质的评估鉴定机构进行质量鉴定和价格评估，并将鉴定、评估结果通知被执行人。 拍卖抵税财物应当确定保留价，由税务机关与被执行人协商确定，协商不成的，由税务机关参照市场价、出厂价或者评估价确定。"},{"i":12,"n":"第十二条","txt":"委托拍卖的文物，在拍卖前，应当经文物行政管理部门依法鉴定、许可。"},{"i":13,"n":"第十三条","txt":"被执行人应当向税务机关说明商品、货物或其他财产的瑕疵，税务机关应当向拍卖机构说明拍卖标的的来源和了解到的瑕疵。"},{"i":14,"n":"第十四条","txt":"拍卖机构接受委托后，未经委托拍卖的税务机关同意，不得委托其他拍卖机构拍卖。"},{"i":15,"n":"第十五条","txt":"税务机关应当在作出拍卖决定后10日内委托拍卖。"},{"i":16,"n":"第十六条","txt":"税务机关应当向拍卖机构提供下列材料： （一）税务机关单位证明及委托拍卖的授权委托书； （二）拍卖（变卖）抵税财物决定书； （三）拍卖（变卖）财产清单； （四）抵税财物质量鉴定与价格评估结果； （五）与拍卖活动有关的其他资料。"},{"i":17,"n":"第十七条","txt":"税务机关应当与拍卖机构签订书面委托拍卖合同。委托拍卖合同应载明以下内容： （一）税务机关及拍卖机构的名称、住所、法定代表人姓名； （二）拍卖标的的名称、规格、数量、质量、存放地或者坐落地、新旧程度或者使用年限等； （三）拍卖的时间、地点，拍卖标的交付或转移的时间、方式，拍卖公告的方式及其费用的承担； （四）拍卖价款结算方式及价款给付期限； （五）佣金标准及其支付的方式、期限； （六）违约责任； （七）双方约定的其他事项。"},{"i":18,"n":"第十八条","txt":"拍卖一次流拍后，税务机关经与被执行人协商同意，可以将抵税财物进行变卖；被执行人不同意变卖的，应当进行第二次拍卖。不动产和文物应当进行第二次拍卖。 第二次拍卖仍然流拍的，税务机关应当将抵税财物进行变卖，以抵缴税款、滞纳金或罚款。 经过流拍再次拍卖的，保留价应当不低于前次拍卖保留价的2/3。"},{"i":19,"n":"第十九条","txt":"税务机关可以自行办理委托拍卖手续，也可以由其上级税务机关代为办理拍卖手续。"},{"i":20,"n":"第二十条","txt":"下列抵税财物为无法委托拍卖或者不适于拍卖，可以交由当地商业企业代为销售或责令被执行人限期处理，进行变卖： （一）鲜活、易腐烂变质或者易失效的商品、货物； （二）经拍卖程序一次或二次流拍的抵税财物； （三）拍卖机构不接受拍卖的抵税财物。"},{"i":21,"n":"第二十一条","txt":"变卖抵税财物的价格，应当参照同类商品的市场价、出厂价遵循公平、合理、合法的原则确定。税务机关应当与被执行人协商是否需要请评估机构进行价格评估，被执行人认为需要的，税务机关应当委托评估机构进行评估，按照评估价确定变卖价格。 对有政府定价的商品、货物或者其他财产，由政府价格主管部门，按照定价权限和范围确定价格。对实行政府指导价的商品、货物或者其他财产，按照定价权限和范围规定的基准价及其浮动幅度确定。 经拍卖流拍的抵税财物，其变卖价格应当不低于最后一次拍卖保留价的2/3。"},{"i":22,"n":"第二十二条","txt":"委托商业企业变卖的，受委托的商业企业要经县以上税务机关确认，并与商业企业签订委托变卖合同，按本办法第二十一条规定的核价方式约定变卖价格。委托变卖合同应载明下列内容： （一）税务机关及商业企业的名称、地址、法定代表人姓名； （二）变卖商品、货物或其他财产的名称、规格、数量、质量、存放地或坐落地、新旧程度或使用年限等； （三）变卖商品、货物或其他财产的时间、地点及其费用的承担； （四）变卖价款结算方式及价款给付期限； （五）违约责任； （六）双方约定的其他事项。"},{"i":23,"n":"第二十三条","txt":"抵税财物委托商业企业代为销售15日后，无法实现销售的，税务机关应当第二次核定价格，由商业企业继续销售，第二次核定的价格应当不低于首次核定价格的2/3。"},{"i":24,"n":"第二十四条","txt":"无法委托商业企业销售，被执行人也无法处理的，税务机关应当进行变价处理。 有下列情形之一的，属于无法委托商业企业代为销售： （一）税务机关与两家（含两家）以上商业企业联系协商，不能达成委托销售的； （二）经税务机关在新闻媒体上征求代售单位，自征求公告发出之日起10日内无应征单位或个人，或应征之后未达成代售协议的； （三）已达成代售协议的商业企业在经第二次核定价格15日内仍无法售出税务机关委托代售的商品、货物或其他财产的。 被执行人无法处理，包括拒绝处理、逾期不处理等情形。"},{"i":25,"n":"第二十五条","txt":"税务机关变价处理时，按照本办法第二十一条规定的原则以不低于前两种变卖方式定价的2/3确定价格。 税务机关实施变卖前，应当在办税服务厅、税务机关网站或当地新闻媒体上公告，说明变卖财物的名称、规格、数量、质量、新旧程度或使用年限、变卖价格、变卖时间等事项；登出公告10日后实施变卖。 税务机关实施变卖10日后仍没有实现变卖的，税务机关可以重新核定价格，再次发布变卖公告，组织变卖。再次核定的价格不得低于首次定价的2/3。 经过二次定价变卖仍未实现变卖的，以市场可接受的价格进行变卖。"},{"i":26,"n":"第二十六条","txt":"以拍卖、变卖收入抵缴未缴的税款、滞纳金和支付相关费用时按照下列顺序进行： （一）拍卖、变卖费用。由被执行人承担拍卖变卖所发生的费用，包括扣押、查封活动中和拍卖或者变卖活动中发生的依法应由被执行人承担的费用，具体为：保管费、仓储费、运杂费、评估费、鉴定费、拍卖公告费、支付给变卖企业的手续费以及其他依法应由被执行人承担的费用。 拍卖物品的买受人未按照约定领受拍卖物品的，由买受人支付自应领受拍卖财物之日起的保管费用。 （二）未缴的税款、滞纳金。 （三）罚款。下列情况可以用拍卖、变卖收入抵缴罚款： 1.被执行人主动用拍卖、变卖收入抵缴罚款的； 2.对价值超过应纳税额且不可分割的商品、货物或者其他财产进行整体扣押、查封、拍卖，以拍卖收入抵缴未缴的税款、滞纳金时，连同罚款一并抵缴； 3.从事生产经营的被执行人对税务机关的处罚决定逾期不申请行政复议也不向人民法院起诉、又不履行的，作出处罚决定的税务机"},{"i":27,"n":"第二十七条","txt":"拍卖或者变卖实现后，税务机关在结算并收取价款后3个工作日内，办理税款、滞纳金或者罚款的入库手续。"},{"i":28,"n":"第二十八条","txt":"拍卖或者变卖收入抵缴税款、滞纳金、罚款后有余额的，税务机关应当自办理入库手续之日起3个工作日内退还被执行人，并通知被执行人将拍卖、变卖全部收入记入当期销售收入额并在当期申报缴纳各种税款。"},{"i":29,"n":"第二十九条","txt":"拍卖变卖结束后，税务机关制作拍卖、变卖结果通知书，拍卖、变卖扣押、查封的商品、货物、财产清单一式两份，一份税务机关留存，一份交被执行人。"},{"i":30,"n":"第三十条","txt":"被执行人在拍卖、变卖成交前缴清了税款、滞纳金的，税务机关应当终止拍卖或者变卖活动，税务机关将商品、货物或其他财产退还被执行人，扣押、查封、保管以及拍卖或者变卖已经产生的费用由被执行人承担。 被执行人拒不承担上述相关费用的，继续进行拍卖或者变卖，以拍卖、变卖收入扣除被执行人应承担的扣押、查封、保管、拍卖或者变卖费用后，剩余部分税务机关在3个工作日内返还被执行人。"},{"i":31,"n":"第三十一条","txt":"对抵税财物经鉴定、评估为不能或不适于进行拍卖、变卖的，税务机关应当终止拍卖、变卖，并将抵税财物返还被执行人。 对抵税财物经拍卖、变卖程序而无法完成拍卖、变卖实现变价抵税的，税务机关应当将抵税财物返还被执行人。 抵税财物无法或不能返还被执行人的，税务机关应当经专门鉴定机构或公证部门鉴定或公证，报废抵税财物。 被执行人应缴纳的税款、滞纳金和应支付的费用，由税务机关采取其他措施继续追缴。"},{"i":32,"n":"第三十二条","txt":"拍卖、变卖过程中，严禁向被执行人摊派、索取任何不合法费用。税务人员在拍卖、变卖过程中，向被执行人摊派、索取不合法费用的，依法给予行政处分；税务机关及其工作人员参与被拍卖或者变卖商品、货物或者其他财产的竞买或收购，或者委托他人竞买或收购，依法给予行政处分。"},{"i":33,"n":"第三十三条","txt":"税务人员有不依法对抵税财物进行拍卖或者变卖，或者擅自将应该拍卖的改为变卖的，在变卖过程中擅自将应该委托商业企业变卖、责令被执行人自行处理的由税务机关直接变价处理的行为，依法给予行政处分；给被执行人造成损失的，由批准拍卖或者变卖的税务机关赔偿其直接损失。 税务机关可向直接责任人追偿部分或全部直接损失。对有故意或重大过失的责任人员依法给予行政处分。"},{"i":34,"n":"第三十四条","txt":"因税务机关违法对扣押、查封的商品、货物或者其他财产造成损失的，由造成损失的税务机关负责赔偿直接损失，并可向直接责任人追偿部分或全部直接损失。"},{"i":35,"n":"第三十五条","txt":"受税务机关委托的拍卖机构或商业企业违反拍卖合同或变卖合同的约定进行拍卖或变卖的，依照合同的约定承担违约责任；合同无约定的，依照法律的规定承担违约责任；其行为构成违法的，依法承担法律责任。"},{"i":36,"n":"第三十六条","txt":"抵税财物在被查封、扣押前，已经设置担保物权而被执行人隐瞒的，或者有瑕疵、质量问题而被执行人隐瞒的，由被执行人承担扣押、查封、拍卖、变卖活动产生的费用，并依法承担法律责任。"},{"i":37,"n":"第三十七条","txt":"税务机关追缴从事生产经营的纳税人骗取国家出口退税的，适用本办法规定。"},{"i":38,"n":"第三十八条","txt":"税收强制执行拍卖、变卖文书由国家税务总局统一制定。"},{"i":39,"n":"第三十九条","txt":"本办法自2005年7月1日起施行。 附件：1.拍卖/变卖抵税财物决定书 　　 2.拍卖/变卖结果通知书 　　 3.拍卖/变卖商品、货物或者其他财产清单 　　 4.返还商品、货物或者其他财产通知书 　　 5.返还商品、货物或者其他财产清单"}],"jidongchuzuchejiashiyuangerensuodeshuizhengshougua169b14":[{"i":1,"n":"第一条","txt":"为了加强对机动出租车驾驶员（包括大、中、小客货运机动出租车驾驶员，下同）个人所得税的征收管理，根据《中华人民共和国个人所得税法》及其实施条例、《中华人民共和国税收征收管理法》（以下简称征管法）及有关行政法规的规定制定本办法。"},{"i":2,"n":"第二条","txt":"各种机动出租车驾驶员为个人所得税的纳税义务人，其从事出租车运营取得的收入，应依法缴纳个人所得税。"},{"i":3,"n":"第三条","txt":"税务机关可以委托出租汽车经营单位、交通管理部门和运输服务站或者其他有关部门（单位）代收代缴出租车驾驶员应纳的个人所得税。被委托的单位为扣缴义务人，应按期代收代缴出租车驾驶员应纳的个人所得税。"},{"i":4,"n":"第四条","txt":"没有扣缴义务人或扣缴义务人未按规定扣缴税款的，出租车驾驶员应自行向单位所在地或准运证发放地的主管税务机关申报纳税。"},{"i":5,"n":"第五条","txt":"出租车驾驶员办理了个体出租车营业执照的，应在领取营业执照后30日内到当地主管税务机关办理税务登记。"},{"i":6,"n":"第六条","txt":"出租车驾驶员从事出租车运营取得的收入，适用的个人所得税项目为： （一）出租汽车经营单位对出租车驾驶员采取单车承包或承租方式运营，出租车驾驶员从事客货运营取得的收入，按工资、薪金所得项目征税。 （二）从事个体出租车运营的出租车驾驶员取得的收入，按个体工商户的生产、经营所得项目缴纳个人所得税。 （三）出租车属个人所有，但挂靠出租汽车经营单位或企事业单位，驾驶员向挂靠单位缴纳管理费的，或出租汽车经营单位将出租车所有权转移给驾驶员的，出租车驾驶员从事客货运营取得的收入，比照个体工商户的生产、经营所得项目征税。"},{"i":7,"n":"第七条","txt":"县级以上（含县级）税务机关可以根据出租车的不同经营方式、不同车型、收费标准、缴纳的承包承租费等情况，核定出租车驾驶员的营业额并确定征收率或征收额，按月征收出租车驾驶员应纳的个人所得税。"},{"i":8,"n":"第八条","txt":"出租车驾驶员能够提供有效停运证明的，税务机关应根据其停运期长短，相应核减其停运期间应缴纳的个人所得税。"},{"i":9,"n":"第九条","txt":"纳税义务人和扣缴义务人未按规定缴纳、扣缴个人所得税的，主管税务机关应按《征管法》及有关法律、行政法规的规定予以处罚，触犯刑律的移送司法机关处理。"},{"i":10,"n":"第十条","txt":"扣缴义务人每月所扣的税款、自行申报纳税人每月应纳的税款，应当在次月7日内缴入国库，并向主管税务机关报送扣缴个人所得税报告表或纳税申报表以及税务机关要求报送的其他资料。"},{"i":11,"n":"第十一条","txt":"对扣缴义务人按照所扣缴或代收代缴的税款，付给2%的手续费。"},{"i":12,"n":"第十二条","txt":"各省、自治区、直辖市税务局可根据本办法规定的原则，结合当地实际制定有关具体办法，并报国家税务总局备案。"},{"i":13,"n":"第十三条","txt":"本办法由国家税务总局负责解释。"},{"i":14,"n":"第十四条","txt":"本办法从1995年4月1日起执行。"}],"jianjunashuirenshuishouweifaxingweijianglizanxingb85d562":[{"i":1,"n":"第一条","txt":"为了鼓励检举税收违法行为，根据《中华人民共和国税收征收管理法》及其实施细则有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称税收违法行为，是指纳税人、扣缴义务人的税收违法行为以及本办法列举的其他税收违法行为。 检举税收违法行为是单位和个人的自愿行为。"},{"i":3,"n":"第三条","txt":"对单位和个人实名向税务机关检举税收违法行为并经查实的，税务机关根据其贡献大小依照本办法给予奖励。但有下列情形之一的，不予奖励： （一）匿名检举税收违法行为，或者检举人无法证实其真实身份的； （二）检举人不能提供税收违法行为线索，或者采取盗窃、欺诈或者法律、行政法规禁止的其他手段获取税收违法行为证据的； （三）检举内容含糊不清、缺乏事实根据的； （四）检举人提供的线索与税务机关查处的税收违法行为无关的； （五）检举的税收违法行为税务机关已经发现或者正在查处的； （六）有税收违法行为的单位和个人在被检举前已经向税务机关报告其税收违法行为的； （七）国家机关工作人员利用工作便利获取信息用以检举税收违法行为的； （八）检举人从国家机关或者国家机关工作人员处获取税收违法行为信息检举的； （九）国家税务总局规定不予奖励的其他情形。"},{"i":4,"n":"第四条","txt":"国家税务局系统检举奖励资金从财政部向国家税务总局拨付的税务稽查办案专项经费中据实列支，地方税务局系统检举奖励资金从省、自治区、直辖市和计划单列市财政厅（局）向同级地方税务局拨付的税务稽查办案专项经费中据实列支。 检举奖励资金的拨付，按照财政国库管理制度的有关规定执行。"},{"i":5,"n":"第五条","txt":"检举奖励资金由稽查局、主管税务局财务部门共同负责管理，稽查局使用，主管税务局财务部门负责支付和监督。 省、自治区、直辖市和计划单列市国家税务局、地方税务局应当对检举奖励资金使用情况编写年度报告，于次年3月底前报告国家税务总局。地方税务局检举奖励资金使用情况同时通报同级财政厅（局）。"},{"i":6,"n":"第六条","txt":"检举的税收违法行为经税务机关立案查实处理并依法将税款收缴入库后，根据本案检举时效、检举材料中提供的线索和证据详实程度、检举内容与查实内容相符程度以及收缴入库的税款数额，按照以下标准对本案检举人计发奖金： （一）收缴入库税款数额在1亿元以上的，给予10万元以下的奖金； （二）收缴入库税款数额在5000万元以上不足1亿元的，给予6万元以下的奖金； （三）收缴入库税款数额在1000万元以上不足5000万元的，给予4万元以下的奖金； （四）收缴入库税款数额在500万元以上不足1000万元的，给予2万元以下的奖金； （五）收缴入库税款数额在100万元以上不足500万元的，给予1万元以下的奖金； （六）收缴入库税款数额在100万元以下的，给予5000元以下的奖金。"},{"i":7,"n":"第七条","txt":"被检举人以增值税留抵税额或者多缴、应退的其他税款抵缴被查处的应纳税款，视同税款已经收缴入库。 检举的税收违法行为经查实处理后没有应纳税款的，按照收缴入库罚款数额依照本办法第六条规定的标准计发奖金。 因被检举人破产或者存有符合法律、行政法规规定终止执行的条件，致使无法将税款或者罚款全额收缴入库的，按已经收缴入库税款或者罚款数额依照本办法规定的标准计发奖金。"},{"i":8,"n":"第八条","txt":"检举虚开增值税专用发票以及其他可用于骗取出口退税、抵扣税款发票行为的，根据立案查实虚开发票填开的税额按照本办法第六条规定的标准计发奖金。"},{"i":9,"n":"第九条","txt":"检举伪造、变造、倒卖、盗窃、骗取增值税专用发票以及可用于骗取出口退税、抵扣税款的其他发票行为的，按照以下标准对检举人计发奖金： （一）查获伪造、变造、倒卖、盗窃、骗取上述发票10000份以上的，给予10万元以下的奖金； （二）查获伪造、变造、倒卖、盗窃、骗取上述发票6000份以上不足10000份的，给予6万元以下的奖金； （三）查获伪造、变造、倒卖、盗窃、骗取上述发票3000份以上不足6000份的，给予4万元以下的奖金； （四）查获伪造、变造、倒卖、盗窃、骗取上述发票1000份以上不足3000份的，给予2万元以下的奖金； （五）查获伪造、变造、倒卖、盗窃、骗取上述发票100份以上不足1000份的，给予1万元以下的奖金； （六）查获伪造、变造、倒卖、盗窃、骗取上述发票不足100份的，给予5000元以下的奖金； 查获伪造、变造、倒卖、盗窃、骗取前款所述以外其他发票的，最高给予5万元以下的奖"},{"i":10,"n":"第十条","txt":"检举非法印制、转借、倒卖、变造或者伪造完税凭证行为的，按照以下标准对检举人计发奖金： （一）查获非法印制、转借、倒卖、变造或者伪造完税凭证100份以上或者票面填开税款金额50万元以上的，给予1万元以下的奖金； （二）查获非法印制、转借、倒卖、变造或者伪造完税凭证50份以上不足100份或者票面填开税款金额20万元以上不足50万元的，给予5000元以下的奖金； （三）查获非法印制、转借、倒卖、变造或者伪造完税凭证不足50份或者票面填开税款金额20万元以下的，给予2000元以下的奖金。"},{"i":11,"n":"第十一条","txt":"被检举人的税收违法行为被国家税务局、地方税务局查处的，合计国家税务局、地方税务局收缴入库的税款数额，按照本办法第六条规定的标准计算检举奖金总额，由国家税务局、地方税务局根据各自收缴入库的税款数额比例分担奖金数额，分别兑付；国家税务局、地方税务局计发的检举奖金合计数额不得超过10万元。"},{"i":12,"n":"第十二条","txt":"同一案件具有适用本办法第六条、第七条、第八条、第九条、第十条规定的两种或者两种以上奖励标准情形的，分别计算检举奖金数额，但检举奖金合计数额不得超过10万元。"},{"i":13,"n":"第十三条","txt":"同一税收违法行为被两个或者两个以上检举人分别检举的，奖励符合本办法规定的最先检举人。检举次序以负责查处的税务机关受理检举的登记时间为准。 最先检举人以外的其他检举人提供的证据对查明税收违法行为有直接作用的，可以酌情给予奖励。 对前两款规定的检举人计发的奖金合计数额不得超过10万元。"},{"i":14,"n":"第十四条","txt":"检举税收违法行为的检举人，可以向税务机关申请检举奖金。 检举奖金由负责查处税收违法行为的税务机关支付。"},{"i":15,"n":"第十五条","txt":"税务机关对检举的税收违法行为经立案查实处理并依法将税款或者罚款收缴入库后，由税收违法案件举报中心根据检举人书面申请及其贡献大小，制作《检举纳税人税收违法行为奖励审批表》，提出奖励对象和奖励金额建议，按照规定权限和程序审批后，向检举人发出《检举纳税人税收违法行为领奖通知书》，通知检举人到指定地点办理领奖手续。《检举纳税人税收违法行为奖励审批表》由税收违法案件举报中心作为密件存档。 税收违法案件举报中心填写《检举纳税人税收违法行为奖金领款财务凭证》，向财务机构领取检举奖金。财务凭证只注明案件编号、案件名称、被检举人名称、检举奖金数额及审批人、领款人的签名，不填写检举内容和检举人身份、名称。"},{"i":16,"n":"第十六条","txt":"检举人应当在接到领奖通知书之日起90日内，持本人身份证或者其他有效证件，到指定地点领取奖金。检举人逾期不领取奖金，视同放弃奖金。 联名检举同一税收违法行为的，奖金由第一署名人领取，并与其他署名人协商分配。"},{"i":17,"n":"第十七条","txt":"检举人或者联名检举的第一署名人不能亲自到税务机关指定的地点领取奖金的，可以委托他人代行领取；代领人应当持委托人的授权委托书、身份证或者其他有效证件以及代领人的身份证或者其他有效证件，办理领取奖金手续。 检举人是单位的，可以委托本单位工作人员代行领取奖金，代领人应当持委托人的授权委托书和代领人的身份证、工作证到税务机关指定的地点办理领取奖金手续。"},{"i":18,"n":"第十八条","txt":"检举人或者代领人领取奖金时，应当在《检举纳税人税收违法行为奖金付款专用凭证》上签名，并注明身份证或者其他有效证件的号码及填发单位。 《检举纳税人税收违法行为奖金付款专用凭证》和委托人的授权委托书由税收违法案件举报中心作为密件存档。"},{"i":19,"n":"第十九条","txt":"税收违法案件举报中心发放检举奖金时，可应检举人的要求，简要告知其所检举的税收违法行为的查处情况，但不得告知其检举线索以外的税收违法行为查处情况，不得提供税务处理（处罚）决定书及有关案情材料。 检举的税收违法行为查结前，税务机关不得将具体查处情况告知检举人。"},{"i":20,"n":"第二十条","txt":"税务机关支付检举奖金时应当严格审核。对玩忽职守、徇私舞弊致使奖金被骗取的，除追缴奖金外，依法追究有关人员责任。"},{"i":21,"n":"第二十一条","txt":"对有特别突出贡献的检举人，税务机关除给予物质奖励外，可以给予相应的精神奖励，但公开表彰宣传应当事先征得检举人的书面同意。"},{"i":22,"n":"第二十二条","txt":"各省、自治区、直辖市和计划单列市国家税务局根据本办法制定具体规定。 各省、自治区、直辖市和计划单列市地方税务局会同同级财政厅（局）根据本办法制定具体规定。"},{"i":23,"n":"第二十三条","txt":"《检举纳税人税收违法行为奖励审批表》、《检举纳税人税收违法行为领奖通知书》、《检举纳税人税收违法行为奖金领款财务凭证》、《检举纳税人税收违法行为奖金付款专用凭证》的格式，由国家税务总局制定。"},{"i":24,"n":"第二十四条","txt":"本办法所称“以上”、“以下”均含本数。"},{"i":25,"n":"第二十五条","txt":"本办法由国家税务总局和财政部负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2007年3月1日起施行。国家税务总局1998年12月15日印发的《税务违法案件举报奖励办法》同时废止。"}],"qianshuigonggaobanfa":[{"i":1,"n":"第一条","txt":"为了规范税务机关的欠税公告行为，保护纳税人的合法权益，督促纳税人自觉缴纳欠税，防止新的欠税的发生，保证国家税款及时足额入库，根据《中华人民共和国税收征收管理法》（以下简称税收征管法）及其实施细则的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称欠税是指纳税人超过税收法律、行政法规规定的期限或者纳税人超过税务机关依照税收法律、行政法规规定确定的纳税期限（以下简称税款缴纳期限）未缴纳的税款（含教育费附加、地方教育附加，下同），包括： （一）办理纳税申报后，纳税人未在税款缴纳期限内缴纳的税款； （二）经批准延期缴纳的税款期限已满，纳税人未在税款缴纳期限内缴纳的税款； （三）税务检查已查定纳税人的应补税额，纳税人未在税款缴纳期限内缴纳的税款； （四）税务机关核定纳税人的应纳税额，纳税人未在税款缴纳期限内缴纳的税款； （五）纳税人的其他未在税款缴纳期限内缴纳的税款。 已缴纳欠税对应形成的欠缴税款滞纳金一并公告。 税务机关对本条规定的欠税及税款滞纳金数额应当及时核实。"},{"i":3,"n":"第三条","txt":"本办法所称公告机关为欠税所属的县级以上税务局（分局）。"},{"i":4,"n":"第四条","txt":"公告机关应当按月在行政执法信息公示平台公告纳税人的欠税情况。根据需要，可以在电子税务局、办税场所、新闻媒体等渠道公告纳税人的欠税情况。 视情节轻重，省级以上税务机关可以对部分纳税人欠税情况予以曝光。 各省（自治区、直辖市、计划单列市）税务机关在官方网站提供其管辖范围内的欠税公告查询服务。"},{"i":5,"n":"第五条","txt":"欠税公告内容如下： （一）企业或者单位欠税的，公告企业或者单位的名称、纳税人识别号、法定代表人或者负责人姓名、证件类型、证件号码、经营地点、欠缴税费种、欠税所属期、欠税金额、已缴纳欠税对应形成的欠缴税款滞纳金金额、欠缴日期、公告机关； （二）个体工商户欠税的，公告个体工商户名称、经营者姓名、纳税人识别号、证件类型、证件号码、经营地点、欠缴税费种、欠税所属期、欠税金额、已缴纳欠税对应形成的欠缴税款滞纳金金额、欠缴日期、公告机关； （三）个人（不含个体工商户）欠税的，公告其姓名、证件类型、证件号码、欠缴税费种、欠税所属期、欠税金额、已缴纳欠税对应形成的欠缴税款滞纳金金额、欠缴日期、公告机关。"},{"i":6,"n":"第六条","txt":"公告机关应当在公告前将拟公告内容推送至纳税人进行确认，纳税人应当在3个工作日内予以确认。 纳税人认为拟公告内容存在信息录入、计算错误的，可以在3个工作日内向公告机关提出异议处理，并提供有关证明材料。公告机关自收到异议之日起3个工作日内，对欠税公告内容与税务信息系统载明的数据进行核实，并将核实结果反馈纳税人；异议成立的，公告机关及时更正欠税公告内容。 纳税人在期限内确认、逾期未确认或者异议处理完成的，公告机关按规定予以公告。"},{"i":7,"n":"第七条","txt":"欠税公告应当经公告机关负责人批准后，向社会公告。 欠税情况存在下列情形之一的，税务机关可不公告： （一）破产程序中税务机关依法受偿但尚未入库的税款、税款滞纳金； （二）已宣告破产、解散或者依法被吊销营业执照、责令关闭、被撤销的，经法定清算后，被依法注销其法人资格企业的税款、税款滞纳金； （三）破产重整、和解程序中，税务机关在依法受偿后，依据重整计划或者和解协议未获清偿的税款、税款滞纳金。 欠税情况涉及国家秘密等其他不宜公告的情形，经省级税务机关批准，不予公告。"},{"i":8,"n":"第八条","txt":"纳税人已缴清公告所列税款、税款滞纳金，或者因登记信息变更等导致欠税公告内容发生变化的，公告机关于次月发布欠税公告时更新相关内容。 欠税公告发布后，纳税人认为欠税公告内容与其实际情况不符，或者欠税公告程序违法的，可以书面向公告机关提出异议，并提供有关证明材料。公告机关自收到异议之日起5个工作日内,对欠税数据来源、公告流程等进行核实，并将核实结果反馈纳税人；异议成立的，公告机关及时更正欠税公告内容。"},{"i":9,"n":"第九条","txt":"公告机关公告纳税人欠税情况不得超出本办法规定的范围，并应当依照税收征管法及其实施细则的规定对纳税人的有关情况进行保密。"},{"i":10,"n":"第十条","txt":"税务机关应当加强欠税管理。欠税发生后，除依照本办法公告外，应当依法催缴并严格按日计算加收税款滞纳金，直至实施强制措施、强制执行清缴欠税。任何单位和个人不得以欠税公告代替强制措施、强制执行等法定措施的实施，干扰清缴欠税。公告机关应当指定部门负责欠税公告工作，并明确其他有关职能部门的相关责任。 税务机关将欠税公告与纳税缴费信用联动管理，积极参与社会信用体系建设。"},{"i":11,"n":"第十一条","txt":"公告机关应公告不公告，给国家税款造成损失的，上级税务机关除责令其改正外，应当按《中华人民共和国公务员法》、《中华人民共和国公职人员政务处分法》等规定，对相关责任人员予以处理处分。"},{"i":12,"n":"第十二条","txt":"与欠税公告相关的资料应当列为税收征管资料档案，妥善保存。"},{"i":13,"n":"第十三条","txt":"扣缴义务人、纳税担保人的欠税公告参照本办法的规定执行。"},{"i":14,"n":"第十四条","txt":"本办法自2026年3月1日起施行。《欠税公告办法（试行）》（国家税务总局令第9号公布、第44号修改）同时废止。"}],"qianshuigonggaobanfa-2":[{"i":1,"n":"第一条","txt":"为了规范税务机关的欠税公告行为，督促纳税人自觉缴纳欠税，防止新的欠税的发生，保证国家税款的及时足额入库，根据《中华人民共和国税收征收管理法》（以下简称《税收征管法》）及其实施细则的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称公告机关为县以上（含县）税务局。"},{"i":3,"n":"第三条","txt":"本办法所称欠税是指纳税人超过税收法律、行政法规规定的期限或者纳税人超过税务机关依照税收法律、行政法规规定确定的纳税期限（以下简称税款缴纳期限）未缴纳的税款，包括： （一）办理纳税申报后，纳税人未在税款缴纳期限内缴纳的税款； （二）经批准延期缴纳的税款期限已满，纳税人未在税款缴纳期限内缴纳的税款； （三）税务检查已查定纳税人的应补税额，纳税人未在税款缴纳期限内缴纳的税款； （四）税务机关根据《税收征管法》第二十七条、第三十五条核定纳税人的应纳税额，纳税人未在税款缴纳期限内缴纳的税款； （五）纳税人的其他未在税款缴纳期限内缴纳的税款。 税务机关对前款规定的欠税数额应当及时核实。 本办法公告的欠税不包括滞纳金和罚款。"},{"i":4,"n":"第四条","txt":"公告机关应当按期在办税场所或者广播、电视、报纸、期刊、网络等新闻媒体上公告纳税人的欠缴税款情况。 （一）企业或单位欠税的，每季公告一次； （二）个体工商户和其他个人欠税的，每半年公告一次； （三）走逃、失踪的纳税户以及其他经税务机关查无下落的非正常户欠税的，随时公告。"},{"i":5,"n":"第五条","txt":"欠税公告内容如下： （一）企业或单位欠税的，公告企业或单位的名称、纳税人识别号、法定代表人或负责人姓名、居民身份证或其他有效身份证件号码、经营地点、欠税税种、欠税余额和当期新发生的欠税金额； （二）个体工商户欠税的，公告业户名称、业主姓名、纳税人识别号、居民身份证或其他有效身份证件号码、经营地点、欠税税种、欠税余额和当期新发生的欠税金额； （三）个人（不含个体工商户）欠税的，公告其姓名、居民身份证或其他有效身份证件号码、欠税税种、欠税余额和当期新发生的欠税金额。"},{"i":6,"n":"第六条","txt":"企业、单位纳税人欠缴税款200万元以下（不含200万元），个体工商户和其他个人欠缴税款10万元以下（不含10万元）的，由县级税务局（分局）在办税服务厅公告。 企业、单位纳税人欠缴税款200万元以上（含200万元），个体工商户和其他个人欠缴税款10万元以上（含10万元）的，由地（市）级税务局（分局）公告。 对走逃、失踪的纳税户以及其他经税务机关查无下落的纳税人欠税的，由各省、自治区、直辖市和计划单列市税务局公告。"},{"i":7,"n":"第七条","txt":"对按本办法规定需要由上级公告机关公告的纳税人欠税信息，下级公告机关应及时上报。具体的时间和要求由各省、自治区、直辖市和计划单列市税务局确定。"},{"i":8,"n":"第八条","txt":"公告机关在欠税公告前，应当深入细致地对纳税人欠税情况进行确认，重点要就欠税统计清单数据与纳税人分户台账记载数据、账簿记载书面数据与信息系统记录电子数据逐一进行核对，确保公告数据的真实、准确。"},{"i":9,"n":"第九条","txt":"欠税一经确定，公告机关应当以正式文书的形式签发公告决定，向社会公告。 欠税公告的数额实行欠税余额和新增欠税相结合的办法，对纳税人的以下欠税，税务机关可不公告： （一）已宣告破产，经法定清算后，依法注销其法人资格的企业欠税； （二）被责令撤销、关闭，经法定清算后，被依法注销或吊销其法人资格的企业欠税； （三）已经连续停止生产经营一年（按日历日期计算）以上的企业欠税； （四）失踪两年以上的纳税人的欠税。 公告决定应当列为税收征管资料档案，妥善保存。"},{"i":10,"n":"第十条","txt":"公告机关公告纳税人欠税情况不得超出本办法规定的范围，并应依照《税收征管法》及其实施细则的规定对纳税人的有关情况进行保密。"},{"i":11,"n":"第十一条","txt":"欠税发生后，除依照本办法公告外，税务机关应当依法催缴并严格按日计算加收滞纳金，直至采取税收保全、税收强制执行措施清缴欠税。任何单位和个人不得以欠税公告代替税收保全、税收强制执行等法定措施的实施，干扰清缴欠税。各级公告机关应指定部门负责欠税公告工作，并明确其他有关职能部门的相关责任，加强欠税管理。"},{"i":12,"n":"第十二条","txt":"公告机关应公告不公告或者应上报不上报，给国家税款造成损失的，上级税务机关除责令其改正外，应按《中华人民共和国公务员法》规定，对直接责任人员予以处理。"},{"i":13,"n":"第十三条","txt":"扣缴义务人、纳税担保人的欠税公告参照本办法的规定执行。"},{"i":14,"n":"第十四条","txt":"各省、自治区、直辖市和计划单列市税务局可以根据本办法制定具体实施细则。"},{"i":15,"n":"第十五条","txt":"本办法由国家税务总局负责解释。"},{"i":16,"n":"第十六条","txt":"本办法自2005年1月1日起施行。"}],"xiaofeishuiruoganjutiwentideguiding":[],"sheshuizhuanyefuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范涉税专业服务行为，保护纳税人合法权益，维护国家税收秩序，促进市场公平竞争，进一步优化营商环境，根据《中华人民共和国税收征收管理法》及其实施细则、《优化营商环境条例》等法律法规和国务院有关决定，制定本办法。"},{"i":2,"n":"第二条","txt":"涉税专业服务机构及涉税服务人员在中华人民共和国境内提供涉税专业服务，适用本办法。 涉税专业服务是指接受委托，利用专业知识和技能，就涉税事项向委托人提供的税务代理等服务。 涉税专业服务机构是指税务师事务所和提供涉税专业服务的会计师事务所、律师事务所、代理记账机构、税务代理公司、财税类咨询公司以及其他提供涉税专业服务的机构。 涉税服务人员是指在涉税专业服务机构任职或者受雇提供涉税专业服务的人员，以及依照法律法规、部门规章规定提供涉税专业服务的其他人员。"},{"i":3,"n":"第三条","txt":"税务机关应当建立健全以实名制为基础的涉税专业服务信用管理与风险管理机制，坚持管理与服务并重，规范和支持涉税专业服务行业按市场化原则为纳税人提供个性化服务。"},{"i":4,"n":"第四条","txt":"涉税专业服务机构及涉税服务人员提供涉税专业服务，应当坚持独立、客观、公正、规范的原则，遵守法律法规及相关规定，遵循涉税专业服务业务规范，恪守职业道德。"},{"i":5,"n":"第五条","txt":"税务机关应当严格规范税务人员与涉税专业服务机构及涉税服务人员的交往行为。 税务机关及其税务工作人员不得参与或者违规干预涉税专业服务机构经营活动。 税务机关及其税务工作人员对在涉税专业服务管理过程中知悉的商业秘密或者个人隐私，应当依法予以保密。"},{"i":6,"n":"第六条","txt":"税务机关应当严格落实监督管理职责，积极发挥行业协会自律监督和社会监督作用，加强对税务师行业党的建设的指导。"},{"i":7,"n":"第七条","txt":"涉税专业服务包括以下内容： （一）纳税申报代办； （二）一般税务咨询； （三）专业税务顾问； （四）税务合规计划； （五）涉税鉴证； （六）纳税情况审查； （七）其他税务事项代办； （八）其他税务代理。"},{"i":8,"n":"第八条","txt":"税务机关对涉税专业服务实行分类管理。涉税专业服务包括一般涉税专业服务和特定涉税专业服务。 本办法第七条第一项、第二项、第七项、第八项为一般涉税专业服务，第七条第三项至第六项为特定涉税专业服务。"},{"i":9,"n":"第九条","txt":"从事涉税专业服务应当具有相应的税收专业知识和技能。"},{"i":10,"n":"第十条","txt":"税务机关对税务师事务所实施行政登记管理。"},{"i":11,"n":"第十一条","txt":"税务机关应当建立健全涉税专业服务管理工作机制，对涉税专业服务机构及涉税服务人员实行涉税业务的集中管理与服务。 税务机关应当加强涉税专业服务管理信息化建设，提高管理与服务的智能化、数字化水平，实现涉税专业服务数据集成、智能分析、风险提示、实时监控、信息推送等功能。"},{"i":12,"n":"第十二条","txt":"税务机关应当加强对涉税专业服务机构及涉税服务人员的实名制管理，涉税专业服务机构及涉税服务人员应当以真实身份提供涉税专业服务。 涉税专业服务机构应当于首次提供涉税专业服务前，如实向税务机关报送机构及其涉税服务人员的基本信息，并根据实际情况及时更新相关信息。 依照法律法规、部门规章规定提供涉税专业服务的其他人员，应当于首次提供服务前，向户籍所在地、经常居住地或者提供服务所在地的主管税务机关如实报送本人的基本信息。 涉税专业服务机构及涉税服务人员应当如实签署申报表等涉税文书。"},{"i":13,"n":"第十三条","txt":"税务机关应当运用信息技术对涉税专业服务机构及涉税服务人员赋予信用码。 信用码采用二维码形式，经扫码可展示持有者的基本信息及其信用情况。 涉税专业服务机构报送基本信息并作出信用承诺，取得涉税专业服务机构信用码。 涉税服务人员应当通过电子税务局等渠道经实名认证，取得涉税服务人员信用码。"},{"i":14,"n":"第十四条","txt":"涉税专业服务机构及涉税服务人员为委托人提供业务委托协议约定的涉税专业服务，应当如实向税务机关报送业务委托协议要素信息。其中，提供本办法第七条第一项和第七项涉税专业服务的，应当于提供服务前报送，并根据实际情况及时更新相关信息；提供本办法第七条第二项至第六项、第八项涉税专业服务的，应当于业务委托协议签订或者变更、终止之日起30日内报送。 纳税人、扣缴义务人委托涉税专业服务机构及涉税服务人员代为办理税务事项时，应当向税务机关表明委托代理关系及相关授权事项，明确双方权利义务。 税务机关应当对纳税人、扣缴义务人授权的代理办税人员进行实名验证。对在多户纳税人、扣缴义务人担任办税人员的，应当由纳税人、扣缴义务人与办税人员在税务信息系统中确认任职受雇或者委托代理关系。 税务机关应当依托税务信息系统对代理办税人员在办税环节进行验证，确保其在委托人授权的范围内办理涉税事项。"},{"i":15,"n":"第十五条","txt":"税务机关建立涉税专业服务业务信息采集制度，利用现有的信息化平台分类采集业务信息，提高分析利用水平。 提供第七条第三项至第六项涉税专业服务的，应当向税务机关报送相关业务要素信息。"},{"i":16,"n":"第十六条","txt":"涉税专业服务机构应当加强合规建设，按照涉税专业服务业务规范的要求，完善内部控制制度，建立质量管理制度、风险控制机制，规范承揽和开展业务。 涉税专业服务机构及涉税服务人员在业务实施过程中，应当加强对委托人的税法宣传辅导，促进提高税法遵从度。 涉税专业服务机构应当建立业务记录制度，记录执业过程并形成工作底稿，需要出具涉税报告和文书的，应当由承办业务的涉税服务人员签字并加盖涉税专业服务机构印章后交付委托人，由双方留存备查。法律、法规及国家税务总局规定报送的，应当向税务机关报送。 涉税专业服务机构应当支持涉税服务人员参加继续教育、业务培训，保持其专业胜任能力。"},{"i":17,"n":"第十七条","txt":"涉税专业服务机构及涉税服务人员为委托人提供涉税专业服务，应当如实准确按照涉税专业服务类别对应的商品和服务税收分类编码开具发票。"},{"i":18,"n":"第十八条","txt":"税务机关应当建立涉税专业服务信用评价管理制度，涉税专业服务机构信用（英文名称为Tax Service Credit，缩写为TSC）按照从高到低顺序分为五级，分别是TSC5级、TSC4级、TSC3级、TSC2级和TSC1级。 税务机关对涉税服务人员采取信用积分和执业负面记录相结合的方式进行信用记录，建立累积信用积分激励机制，并为其提供自身信用记录的查询及下载服务。 税务机关根据涉税专业服务机构及涉税服务人员信用情况采取激励和约束措施。"},{"i":19,"n":"第十九条","txt":"税务机关应当在门户网站、电子税务局和办税服务场所公示涉税专业服务机构名单及其信用情况，同时公示未经行政登记的税务师事务所名单、重点监管对象名单、涉税服务失信主体。 税务机关应当建立涉税专业服务机构信息公告制度，提供涉税专业服务机构信用等级及排名等查询服务，便于纳税人、扣缴义务人自主比较选择涉税专业服务机构。"},{"i":20,"n":"第二十条","txt":"税务机关所需的涉税专业服务，应当严格执行政府购买服务相关规定。"},{"i":21,"n":"第二十一条","txt":"税务机关应当为涉税专业服务机构及涉税服务人员提供便利化服务，不断优化税务信息系统的代理办税功能。 税务机关可以在涉税专业服务机构较为集中的区域，设立涉税专业服务机构办税服务专窗或者专区。"},{"i":22,"n":"第二十二条","txt":"税务机关通过信息系统智能归集涉税专业服务机构相关数据，简化信息报送，定期生成涉税专业服务机构的年度服务总体情况，为其加强内部管理、防范执业风险、提升涉税专业服务信用等级提供参考。"},{"i":23,"n":"第二十三条","txt":"税务机关应当加强对涉税专业服务机构及涉税服务人员的宣传辅导及业务培训，建立健全与涉税专业服务机构及其行业协会、纳税人之间的沟通机制。"},{"i":24,"n":"第二十四条","txt":"税务机关应当加强对税务师行业协会的监督指导，发挥税务师行业在涉税专业服务行业中的示范和引领作用，与注册会计师、律师、代理记账等其他相关行业协会建立工作联系制度，强化行业自律监督，引导合规诚信经营，促进涉税专业服务行业高质量发展。 税务机关可以委托行业协会对涉税专业服务机构提供涉税专业服务的执业质量进行评价。 全国税务师行业协会负责拟制涉税专业服务业务规范，报国家税务总局批准后施行。"},{"i":25,"n":"第二十五条","txt":"税务机关应当对涉税专业服务机构及涉税服务人员实行风险管理，对其逃避涉税专业服务管理、不依法纳税、执业违规等风险事项进行监督检查。 税务机关应当加强对涉税专业服务机构及涉税服务人员发布涉税违法违规信息问题的监测及处置。"},{"i":26,"n":"第二十六条","txt":"税务机关负责对涉税专业服务执业情况进行检查，包括以下检查内容： （一）涉税专业服务机构内部制度建设情况； （二）涉税专业服务机构报送的基本信息； （三）涉税专业服务机构的执业资质； （四）涉税专业服务机构报送的业务信息； （五）涉税专业服务机构执行涉税专业服务业务规范情况； （六）涉税报告和文书留存备查情况； （七）其他监督检查事项。"},{"i":27,"n":"第二十七条","txt":"税务机关应当根据涉税专业服务机构的信用和风险等日常管理情况制定检查计划，明确检查的依据、频次、方式、内容和程序，抽取被检查对象；也可以根据举报投诉、涉税违法违规信息监测进行检查。"},{"i":28,"n":"第二十八条","txt":"税务机关可以采取实地检查、调取业务档案、询问、查询、异地协查等方法，对涉税专业服务机构实施检查，对与检查相关的情况和资料，可以记录、录音、录像、照相和复制。"},{"i":29,"n":"第二十九条","txt":"税务机关在检查完成后，应当形成检查报告。 对检查发现涉税专业服务机构及涉税服务人员存在违反本办法规定情形的，由主管税务机关进行处理。 对检查发现涉税专业服务机构及涉税服务人员存在其他涉税问题的，由税务机关按照规定进行处理；属于其他部门职责的，由主管税务机关移送有权处理部门。 对检查发现税务人员存在与涉税专业服务机构及涉税服务人员不当交往，或者涉嫌滥用职权、玩忽职守、徇私舞弊等行为的，由税务机关根据干部管理权限移送纪检监察机构处理，涉嫌违法犯罪的移送司法机关。"},{"i":30,"n":"第三十条","txt":"税务机关应当加强与财政、司法行政、市场监管、网信等相关部门的协同管理。"},{"i":31,"n":"第三十一条","txt":"违反本办法，有下列情形之一的，由主管税务机关提示提醒、责令限期改正或者予以约谈，扣减信用积分或者纳入负面信用记录（第一、二项情形除外）；情节较重或者逾期不改正的，由主管税务机关列为重点监管对象，扣减信用积分、降低信用等级或者纳入负面信用记录（第一、二项情形除外），向委托人及委托人所在地主管税务机关进行风险提示；情节严重的，由主管税务机关列为涉税服务失信主体予以公告，向委托人及委托人所在地主管税务机关进行风险提示，所代理的涉税业务应当由其与委托人共同到税务机关现场办理： （一）使用税务师事务所名称未办理行政登记的； （二）提供涉税专业服务但未按规定报送涉税专业服务机构及涉税服务人员基本信息的； （三）未按规定报送涉税专业服务业务委托协议、业务信息的； （四）报送的基本信息、业务委托协议及业务信息与实际不符的； （五）妨害税务机关依照本办法履行职责的； （六）未以涉税服务人员身份，而以委托"},{"i":32,"n":"第三十二条","txt":"涉税专业服务机构及涉税服务人员有下列情形之一的，由主管税务机关列为重点监管对象，扣减信用积分、降低信用等级或者纳入负面信用记录，向委托人及委托人所在地主管税务机关进行风险提示；情节较重的，由主管税务机关列为涉税服务失信主体予以公告，向委托人及委托人所在地主管税务机关进行风险提示，所代理的涉税业务应当由其与委托人共同到税务机关现场办理；情节严重的，由设区的市、自治州税务机关列为涉税服务严重失信主体予以公告，向委托人及委托人所在地主管税务机关进行风险提示，所代理的涉税业务应当由其与委托人共同到税务机关现场办理，将信息通报相关部门实施监管和联合惩戒，对税务师事务所由其行政登记的税务机关宣布《税务师事务所行政登记证书》无效，提请市场监管部门吊销其营业执照，提请全国税务师行业协会取消税务师职业资格证书登记、收回其职业资格证书并向社会公告，对会计师事务所、律师事务所、代理记账机构等其他涉税专业服务"},{"i":33,"n":"第三十三条","txt":"存在第三十一条第一款所列情形的，情节较重或者逾期不改正的，对机构处以一千元以下、对人员处以五百元以下罚款；情节严重的，对机构处以二千元以下、对人员处以一千元以下罚款。 违反税收法律、行政法规，造成委托人未缴少缴税款或者骗取税收优惠的，对涉税专业服务机构及涉税服务人员按照《中华人民共和国税收征收管理法》及其实施细则相关规定予以处罚；涉税专业服务机构已被依法处罚、所属涉税服务人员未被依法处罚的，对负有直接责任的涉税服务人员，处以一千元以下罚款；情节较重的，处以二千元以下罚款；情节严重的，处以五千元以下罚款。 存在第三十二条第二项至第九项情形，未按照相关法律法规被处罚的，对涉税专业服务机构处以二千元以下、对涉税服务人员处以一千元以下罚款；情节较重的，对涉税专业服务机构处以五千元以下、对涉税服务人员处以二千元以下罚款；情节严重的，对涉税专业服务机构处以一万元以下、对涉税服务人员处以五千元以下罚"},{"i":34,"n":"第三十四条","txt":"涉税专业服务机构有证据证明涉税服务人员的违法违规行为属与本机构无关的个人行为的，可以免予对涉税专业服务机构的处理处罚。"},{"i":35,"n":"第三十五条","txt":"税务机关及其税务工作人员违反本办法规定的，对直接责任人和相关责任人依规依纪依法处理。"},{"i":36,"n":"第三十六条","txt":"各省级税务机关可以依据本办法，结合本地实际，制定具体实施办法并报国家税务总局备案。"},{"i":37,"n":"第三十七条","txt":"本办法所称“以下”包含本数。"},{"i":38,"n":"第三十八条","txt":"本办法自2025年5月1日起施行。 本办法施行之前的涉税专业服务有关管理规定与本办法不一致的，以本办法为准。"},{"i":39,"n":"第三十九条","txt":"本办法由国家税务总局解释。"}],"yanchushichanggerensuodeshuizhengshouguanlizanxing4eb128":[{"i":1,"n":"第一条","txt":"为加强演出市场个人所得税的征收管理，根据《中华人民共和国个人所得税法》及其实施条例和《国务院办公厅转发文化部关于加强演出市场管理报告的通知》（国办发〔1991〕112号）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"凡参加演出（包括舞台演出、录音、录像、拍摄影视等，下同）而取得报酬的演职员，是个人所得税的纳税义务人；所取得的所得，为个人所得税的应纳税项目。"},{"i":3,"n":"第三条","txt":"向演职员支付报酬的单位或个人，是个人所得税的扣缴义务人。扣缴义务人必须在支付演职员报酬的同时，按税收法律、行政法规及税务机关依照法律、行政法规作出的规定扣缴或预扣个人所得税。 预扣办法由各省、自治区、直辖市税务局根据有利控管的原则自行确定。"},{"i":4,"n":"第四条","txt":"演出经纪机构领取《演出经营许可证》、《临时营业演出许可证》或变更以上证件内容的，必须在领证后或变更登记后的三十日内到机构所在地主管税务机关办理税务登记或变更税务登记。文化行政部门向演出经纪机构或个人发放《演出经营许可证》和《临时营业演出许可证》时，应将演出经纪机构的名称、住所、法人代表等情况抄送当地主管税务机关备案。"},{"i":5,"n":"第五条","txt":"演出活动主办单位应在每次演出前两日内，将文化行政部门的演出活动批准件和演出合同、演出计划（时间、地点、场次）、报酬分配方案等有关材料报送演出所在地主管税务机关。演出合同和演出计划的内容如有变化，应按规定程序重新向文化行政部门申报审批并向主管税务机关报送新的有关材料。"},{"i":6,"n":"第六条","txt":"演职员参加非任职单位组织的演出取得的报酬为劳务报酬所得，按次缴纳个人所得税。演职员参加任职单位组织的演出取得的报酬为工资、薪金所得，按月缴纳个人所得税。 上述报酬包括现金、实物和有价证券。"},{"i":7,"n":"第七条","txt":"参加组台（团）演出的演职员取得的报酬，由主办单位或承办单位通过银行转账支付给演职员所在单位或发放演职员演出许可证的文化行政部门或其授权单位的，经演出所在地主管税务机关确认后，由演职员所在单位或者发放演职员许可证的文化行政部门或其授权单位，按实际支付给演职员个人的报酬代扣个人所得税，并在原单位所在地缴入金库。"},{"i":8,"n":"第八条","txt":"组台（团）演出，不按第七条所述方式支付演职员报酬，或者虽按上述方式支付但未经演出所在地主管税务机关确认的，由向演职员支付报酬的演出经纪机构或者主办、承办单位扣缴个人所得税，税款在演出所在地缴纳。申报的演职员报酬明显偏低又无正当理由的，主管税务机关可以在查账核实的基础 上，依据演出报酬总额、演职员分工、演员演出通常收费额等情况核定演职员的应纳税所得，扣缴义务人据此扣缴税款。"},{"i":9,"n":"第九条","txt":"税务机关有根据认为从事演出的纳税义务人有逃避纳税义务行为的，可以在规定的纳税期之前，责令其限期缴纳应纳税款；在限期内发现纳税义务人有明显的转移、隐匿演出收入迹象的，税务机关可以责成纳税义务人提供纳税担保。如果纳税义务人不能提供纳税担保，经县以上（含县级）税务局（分局）局长批准，税务机关可以采取税收保全措施。"},{"i":10,"n":"第十条","txt":"参与录音、录像、拍摄影视和在歌厅、舞厅、卡拉OK厅、夜总会、娱乐城等娱乐场所演出的演职员取得的报酬，由向演职员支付报酬的单位或业主扣缴个人所得税。"},{"i":11,"n":"第十一条","txt":"演职员取得的报酬为不含税收入的，扣缴义务人支付的税款应按以下公式计算： （一）应纳税所得额= （二）应纳税额=应纳税所得额×适用税率-速算扣除数"},{"i":12,"n":"第十二条","txt":"扣缴义务人扣缴的税款，应在次月七日内缴入国库，同时向主管税务机关报送扣缴个人所得税报告表、支付报酬明细表以及税务机关要求报送的其他资料。"},{"i":13,"n":"第十三条","txt":"有下列情形的，演职员应在取得报酬的次月七日内自行到演出所在地或者单位所在地主管税务机关申报纳税： （一）在两处或者两处以上取得工资、薪金性质所得的，应将各处取得的工资、薪金性质的所得合并计算纳税； （二）分笔取得属于一次报酬的； （三）扣缴义务人没有依法扣缴税款的； （四）主管税务机关要求其申报纳税的。"},{"i":14,"n":"第十四条","txt":"为了强化征收管理，主管税务机关可以根据当地实际情况，自行确定对在歌厅、舞厅、卡拉OK厅、夜总会、娱乐城等娱乐场所演出的演职员的个人所得税征收管理方式。"},{"i":15,"n":"第十五条","txt":"组台（团）演出，应当建立健全财务会计制度，正确反映演出收支和向演职员支付报酬情况，并接受主管税务机关的监督检查。没有建立财务会计制度，或者未提供完整、准确的纳税资料，主管税务机关可以核定其应纳税所得额，据以征税。"},{"i":16,"n":"第十六条","txt":"扣缴义务人和纳税义务人违反本办法有关规定，主管税务机关可以依照《中华人民共和国税收征收管理法》及其他有关法律和行政法规的有关规定给以处罚。"},{"i":17,"n":"第十七条","txt":"演职员偷税情节恶劣，或者被第三次查出偷税的，除税务机关对其依法惩处外，文化行政部门可据情节轻重停止其演出活动半年至一年。"},{"i":18,"n":"第十八条","txt":"各省、自治区、直辖市税务局和文化行政部门可依据本办法规定的原则，制定具体实施细则。"},{"i":19,"n":"第十九条","txt":"本办法由国家税务总局、文化和旅游部共同负责解释。"},{"i":20,"n":"第二十条","txt":"本办法自文到之日起施行。以前规定凡与本办法不符的，按本办法执行。"}],"dianlichanpinzengzhishuizhengshouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强电力产品增值税的征收管理，根据《中华人民共和国税收征收管理法》、《中华人民共和国增值税暂行条例》、《中华人民共和国增值税暂行条例实施细则》及其有关规定，结合电力体制改革以及电力产品生产、销售特点，制定本办法。"},{"i":2,"n":"第二条","txt":"生产、销售电力产品的单位和个人为电力产品增值税纳税人，并按本办法规定缴纳增值税。"},{"i":3,"n":"第三条","txt":"电力产品增值税的计税销售额为纳税人销售电力产品向购买方收取的全部价款和价外费用，但不包括收取的销项税额。价外费用是指纳税人销售电力产品在目录电价或上网电价之外向购买方收取的各种性质的费用。 供电企业收取的电费保证金，凡逾期（超过合同约定时间）未退还的，一律并入价外费用缴纳增值税。"},{"i":4,"n":"第四条","txt":"电力产品增值税的征收，区分不同情况，分别采取以下征税办法： （一）发电企业（电厂、电站、机组，下同）生产销售的电力产品，按照以下规定计算缴纳增值税： 1.独立核算的发电企业生产销售电力产品，按照现行增值税有关规定向其机构所在地主管税务机关申报纳税；具有一般纳税人资格或具备一般纳税人核算条件的非独立核算的发电企业生产销售电力产品，按照增值税一般纳税人的计算方法计算增值税，并向其机构所在地主管税务机关申报纳税。 2.不具有一般纳税人资格且不具有一般纳税人核算条件的非独立核算的发电企业生产销售的电力产品，由发电企业按上网电量，依核定的定额税率计算发电环节的预缴增值税，且不得抵扣进项税额，向发电企业所在地主管税务机关申报纳税。计算公式为： 预征税额=上网电量×核定的定额税率 （二）供电企业销售电力产品，实行在供电环节预征、由独立核算的供电企业统一结算的办法缴纳增值税，具体办法如下： 1.独立核"},{"i":5,"n":"第五条","txt":"实行预缴方式缴纳增值税的发、供电企业生产销售电力产品以外的其他货物和应税劳务，如果能准确核算销售额的，在发、供电企业所在地依适用税率计算缴纳增值税。不能准确核算销售额的，按其隶属关系由独立核算的发、供电企业统一计算缴纳增值税。"},{"i":6,"n":"第六条","txt":"发、供电企业销售电力产品的纳税义务发生时间的具体规定如下： （一）发电企业和其他企事业单位销售电力产品的纳税义务发生时间为电力上网并开具确认单据的当天。 （二）供电企业采取直接收取电费结算方式的，销售对象属于企事业单位，为开具发票的当天；属于居民个人，为开具电费缴纳凭证的当天。 （三）供电企业采取预收电费结算方式的，为发行电量的当天。 （四）发、供电企业将电力产品用于非应税项目、集体福利、个人消费，为发出电量的当天。 （五）发、供电企业之间互供电力，为双方核对计数量，开具抄表确认单据的当天。 （六）发、供电企业销售电力产品以外其他货物，其纳税义务发生时间按《中华人民共和国增值税暂行条例》及其实施细则的有关规定执行。"},{"i":7,"n":"第七条","txt":"发、供电企业应按现行增值税的有关规定办理税务登记，进行增值税纳税申报。 实行预缴方式缴纳增值税的发、供电企业应按以下规定办理： （一）实行预缴方式缴纳增值税的发、供电企业在办理税务开业、变更、注销登记时，应将税务登记证正本复印件按隶属关系逐级上报其独立核算的发、供电企业所在地主管税务机关留存。 独立核算的发、供电企业也应将税务登记证正本复印件报其所属的采用预缴方式缴纳增值税的发、供电企业所在地主管税务机关留存。 （二）采用预缴方式缴纳增值税的发、供电企业在申报纳税的同时，应将增值税进项税额和上网电量、电力产品销售额、其他产品销售额、价外费用、预征税额和查补税款分别归集汇总，填写《电力企业增值税销项税额和进项税额传递单》（样式附后，以下简称《传递单》）报送主管税务机关签章确认后，按隶属关系逐级汇总上报给独立核算发、供电企业；预征地主管税务机关也必须将确认后的《传递单》于收到当月传递给结算"},{"i":8,"n":"第八条","txt":"发、供电企业销售电力产品，应按《中华人民共和国发票管理办法》和增值税专用发票使用管理规定领购、使用和管理发票。"},{"i":9,"n":"第九条","txt":"电力产品增值税的其他征税事项，按《中华人民共和国税收征收管理法》、《中华人民共和国税收征收管理法实施细则》、《中华人民共和国增值税暂行条例》和《中华人民共和国增值税暂行条例实施细则》及其他有关规定执行。"},{"i":10,"n":"第十条","txt":"本办法由国家税务总局负责解释。"},{"i":11,"n":"第十一条","txt":"本办法自2005年2月1日起施行。 电力增值税销项税额和进项税额传递单.pdf 发、供电企业税收检查情况通报单.pdf"}],"shuiwurenyuanshuishouyewuweifaxingweichufenguiding":[{"i":1,"n":"第一条","txt":"为了规范对税务人员税收业务有关违法行为的处分，促进税务机关、税务人员依法履职，维护国家税收秩序和税收安全，根据《中华人民共和国公务员法》、《中华人民共和国公职人员政务处分法》、《中华人民共和国税收征收管理法》及其实施细则等相关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称税务人员是指税务机关公务员、参照《中华人民共和国公务员法》管理的人员。 本规定所称税收业务违法行为（以下简称违法行为）是指第三章所列违反税收法律、行政法规的行为。 税务机关对有违法行为的税务人员给予处分，适用《中华人民共和国公职人员政务处分法》第二章、第三章的规定和本规定。"},{"i":3,"n":"第三条","txt":"税务人员违法行为处分工作，坚持中国共产党的领导，坚持党管干部原则，加强税务干部队伍建设，高质量推进中国式现代化税务实践。"},{"i":4,"n":"第四条","txt":"税务机关应当加强对税务人员的教育、管理、监督。给予税务人员处分，应当坚持公平公正，集体讨论决定；坚持宽严相济，惩戒与教育相结合；坚持法治原则，以事实为根据，以法律为准绳，依法保障税务人员及相关人员的合法权益。"},{"i":5,"n":"第五条","txt":"给予税务人员处分，应当事实清楚、证据确凿、定性准确、处理恰当、程序合法、手续完备，与其违法行为的性质、情节、危害程度相适应。"},{"i":6,"n":"第六条","txt":"处分的种类为： （一）警告； （二）记过； （三）记大过； （四）降级； （五）撤职； （六）开除。"},{"i":7,"n":"第七条","txt":"处分的期间为： （一）警告，六个月； （二）记过，十二个月； （三）记大过，十八个月； （四）降级、撤职，二十四个月。 处分决定自作出之日起生效，处分期自处分决定生效之日起计算。"},{"i":8,"n":"第八条","txt":"税务机关集体作出的决定违法或者实施违法行为的，对负有责任的领导人员和直接责任人员依法给予处分。 税务机关集体作出的决定违法，持保留意见或者不同意见的税务人员可以免予或者不予处分。 税务人员二人以上共同违法，根据各自在违法行为中所起的作用和应当承担的责任，分别依法给予处分。"},{"i":9,"n":"第九条","txt":"税务人员有下列情形之一，可以从轻或者减轻给予处分： （一）主动交代本人应当受到处分的违法行为的； （二）配合调查，如实说明本人违法事实的； （三）检举他人违纪违法行为，经查证属实的； （四）主动采取措施，有效避免、挽回损失或者消除不良影响的； （五）在共同违法行为中起次要或者辅助作用的； （六）主动上交或者退赔违法所得的； （七）法律、法规规定其他从轻或者减轻情节的。"},{"i":10,"n":"第十条","txt":"税务人员违法行为情节轻微，且具有本规定第九条规定情形之一的，可以对其进行谈话提醒、批评教育、责令检查或者予以诫勉，免予或者不予处分。 税务人员因不明真相被裹挟或者被胁迫参与违法活动，经批评教育后确有悔改表现的，可以减轻、免予或者不予处分。"},{"i":11,"n":"第十一条","txt":"税务人员有下列情形之一，应当从重给予处分： （一）在处分期内再次故意违法，应当受到处分的； （二）阻止他人检举、提供证据的； （三）串供或者伪造、隐匿、毁灭证据的； （四）包庇同案人员的； （五）胁迫、唆使他人实施违法行为的； （六）拒不上交或者退赔违法所得的； （七）法律、法规规定其他从重情节的。"},{"i":12,"n":"第十二条","txt":"税务人员在处分期内，不得晋升职务、职级和级别；其中，被记过、记大过、降级、撤职的，不得晋升工资档次。被撤职的，按照规定降低职务、职级和级别，同时降低工资和待遇。"},{"i":13,"n":"第十三条","txt":"违反规定擅自改变税收征收管理范围和税款入库预算级次的，予以降级或者撤职。"},{"i":14,"n":"第十四条","txt":"有下列行为之一，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除： （一）违反法律、行政法规的规定提前征收、延缓征收或者摊派税款的； （二）违反规定采取虚收空转等手段虚增税收收入的； （三）违反规定配合地方政府统计造假等行为的。"},{"i":15,"n":"第十五条","txt":"违反法律、行政法规的规定，擅自作出税收的开征、停征或者减税、免税、退税、补税以及其他同税收法律、行政法规相抵触的决定，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":16,"n":"第十六条","txt":"对地方政府违规招商引资涉税问题知情不报，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职。 参与配合地方政府违规招商引资、为地方政府违规招商引资出谋划策，在发票数量、额度调整，委托代征，代开发票，出口税收管理等工作中违反规定，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":17,"n":"第十七条","txt":"有下列行为之一，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除： （一）违反规定要求纳税人、扣缴义务人委托税务代理，或者为其指定涉税专业服务机构，谋取不正当利益的； （二）税务人员的近亲属违反有关规定在本人任职单位管辖的业务范围内从事涉税中介经营活动，本人拒不按照有关要求整改的。"},{"i":18,"n":"第十八条","txt":"有下列行为之一，造成不良后果或影响，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职；情节特别严重的，予以开除： （一）查封、扣押纳税人个人及其所扶养家属维持生活必需的住房和用品的； （二）其他违反规定采取税收保全、强制执行措施的。"},{"i":19,"n":"第十九条","txt":"私分扣押、查封的商品、货物或者其他财产，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":20,"n":"第二十条","txt":"有下列行为之一，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除： （一）隐匿、毁损、伪造、变造税收违法案件证据的； （二）提供虚假税务协查函件的（含出口税收调查函）。"},{"i":21,"n":"第二十一条","txt":"在征收税款或者查处税收违法案件时，违反规定应当回避而不回避，影响公正执行公务，造成不良后果或者影响，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职。"},{"i":22,"n":"第二十二条","txt":"有下列行为之一，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除： （一）未依法为纳税人、扣缴义务人、税务代理人、检举人保密，泄露涉税数据、资料的； （二）盗用他人账号或者违反规定将税收业务系统用户账号提供给他人使用的。"},{"i":23,"n":"第二十三条","txt":"有下列行为之一，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除： （一）利用职务职权上的便利，收受或者索取纳税人、扣缴义务人等管理服务对象财物或者谋取其他不正当利益的； （二）截留、挪用税款的。"},{"i":24,"n":"第二十四条","txt":"故意刁难纳税人、扣缴义务人，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职；情节特别严重的，予以开除。 滥用职权，侵害纳税人、扣缴义务人合法权益，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":25,"n":"第二十五条","txt":"对依法批评、申诉、控告、检举税收违纪违法行为的纳税人、扣缴义务人以及其他检举人进行压制或者打击报复的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":26,"n":"第二十六条","txt":"有下列行为之一，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除： （一）勾结、唆使或者协助纳税人、扣缴义务人逃避缴纳税款、抗税、逃避追缴欠税、骗取出口退税的； （二）勾结、唆使或者协助纳税人、扣缴义务人虚开发票，非法代开发票，私自印制、伪造、变造发票以及窃取、截留、篡改、出售、泄露发票数据等违反发票管理法律、行政法规的； （三）违反规定办理发票限额调整、全面数字化电子发票额度调整的。"},{"i":27,"n":"第二十七条","txt":"对涉嫌犯罪的纳税人、扣缴义务人依法应当移交司法机关追究刑事责任的不移交，造成不良后果或者影响的，予以记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":28,"n":"第二十八条","txt":"不履行或者不正确履行职责，玩忽职守，不征或者少征应征税款，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。"},{"i":29,"n":"第二十九条","txt":"税务人员有其他违反税收法律、行政法规行为，影响税务人员形象，损害国家和纳税人、扣缴义务人利益的，可以根据情节轻重给予相应处分。"},{"i":30,"n":"第三十条","txt":"税务人员涉嫌有违法行为的，按照干部管理权限，经税务机关负责人同意，由税务机关有关部门对需要调查处理的事项进行初步调查；税务机关有关部门经初步调查认为税务人员涉嫌违法需要进一步查证的，报税务机关负责人批准后立案，由有权处理单位调查，并按规定处理。"},{"i":31,"n":"第三十一条","txt":"对涉嫌违法税务人员的调查，应当由二名以上工作人员进行。"},{"i":32,"n":"第三十二条","txt":"作出处分决定前，有权处理单位应当将调查认定的违法事实及拟给予处分的依据告知被调查人，听取被调查人的陈述和申辩，并对其陈述的事实、理由和证据进行核实，记录在案。被调查人提出的事实、理由和证据成立的，应予采纳。不得因被调查人的申辩而加重处分。"},{"i":33,"n":"第三十三条","txt":"决定给予处分的，应当制作处分决定书。 处分决定书应当载明下列事项： （一）受处分税务人员的姓名、工作单位和职务（职级）； （二）违法事实和证据； （三）处分的种类和依据； （四）不服处分决定，申请复核、申诉的途径和期限； （五）作出处分决定的机关、单位名称和日期。 处分决定书应当盖有作出决定的机关、单位的印章，并存入受处分税务人员本人档案。"},{"i":34,"n":"第三十四条","txt":"参与税务人员违法案件调查、处理的人员有下列情形之一，应当自行回避，被调查人及其他涉案人员也有权要求其回避： （一）是被调查人或者涉案人员的近亲属的； （二）担任过本案的证人的； （三）本人或者其近亲属与调查的案件有利害关系的； （四）可能影响案件公正调查、处理的其他情形。"},{"i":35,"n":"第三十五条","txt":"税务机关负责人的回避，由上级税务机关决定；其他参与案件调查、处理人员的回避，由本级税务机关决定。 税务机关或者上级税务机关发现参与违法案件调查、处理人员有应当回避情形的，可以直接决定该人员回避。"},{"i":36,"n":"第三十六条","txt":"在调查中发现税务人员受到不实检举、控告或者诬告陷害，造成不良影响的，应当按照规定及时澄清事实，恢复名誉，消除不良影响。"},{"i":37,"n":"第三十七条","txt":"对税务人员违法行为情节轻微，可以从轻、减轻、免予或者不予处分的，应当列明从轻、减轻、免予或者不予处分的原因，并按规定履行报批手续。"},{"i":38,"n":"第三十八条","txt":"按本规定受到处分的税务人员对处分决定不服的，可以依照《中华人民共和国公务员法》等有关规定申请复核或者提出申诉。"},{"i":39,"n":"第三十九条","txt":"税务人员有违法行为，按照规定应当给予党纪处分的，移送相应纪检机构按规定处理。涉嫌违法犯罪的，移送有关机关依法处理。"},{"i":40,"n":"第四十条","txt":"本规定所称造成不良后果或者影响的情形，包括： （一）导致国家税收损失且数额较大的； （二）形成涉税负面舆情造成恶劣社会影响的； （三）导致税务机关承担国家赔偿责任的； （四）其他应当认定为造成不良后果或者影响的。"},{"i":41,"n":"第四十一条","txt":"本规定施行前，已经结案的案件如果需要复核、申诉，适用当时的规定。尚未结案的案件，如果行为发生时的规定不认为是违法的，适用当时的规定；如果行为发生时的规定认为是违法的，依照当时的规定处理，但是如果本规定不认为是违法或者根据本规定处理较轻的，适用本规定。"},{"i":42,"n":"第四十二条","txt":"事业单位工作人员有本规定第三章违法行为的，按照《事业单位工作人员处分规定》给予处分；机关工勤人员有本规定第三章违法行为的，参照《事业单位工作人员处分规定》执行。 税务机关编外人员有本规定第三章违法行为的，由税务机关依照相关规定处理或者向其任职、受雇单位提出处理建议。"},{"i":43,"n":"第四十三条","txt":"税务人员在征收社会保险费、非税收入过程中，有违法违规行为的，有关处分事宜参照本规定执行。"},{"i":44,"n":"第四十四条","txt":"法律、行政法规、国务院决定和国家公务员管理部门制定的处分规定对违法行为的处分另有规定的，从其规定。"},{"i":45,"n":"第四十五条","txt":"本规定自2026年1月1日起施行。《税收违法违纪行为处分规定》（监察部 人力资源和社会保障部 国家税务总局令第26号）同时废止。"}],"shuiwudengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范税务登记管理，加强税源监控，根据《中华人民共和国税收征收管理法》（以下简称《税收征管法》）以及《中华人民共和国税收征收管理法实施细则》（以下简称《实施细则》）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"企业，企业在外地设立的分支机构和从事生产、经营的场所，个体工商户和从事生产、经营的事业单位，均应当按照《税收征管法》及《实施细则》和本办法的规定办理税务登记。 前款规定以外的纳税人，除国家机关、个人和无固定生产、经营场所的流动性农村小商贩外，也应当按照《税收征管法》及《实施细则》和本办法的规定办理税务登记。 根据税收法律、行政法规的规定负有扣缴税款义务的扣缴义务人（国家机关除外），应当按照《税收征管法》及《实施细则》和本办法的规定办理扣缴税款登记。"},{"i":3,"n":"第三条","txt":"县以上（含本级，下同）税务局（分局）是税务登记的主管税务机关，负责税务登记的设立登记、变更登记、注销登记和税务登记证验证、换证以及非正常户处理、报验登记等有关事项。"},{"i":4,"n":"第四条","txt":"税务登记证件包括税务登记证及其副本、临时税务登记证及其副本。 扣缴税款登记证件包括扣缴税款登记证及其副本。"},{"i":5,"n":"第五条","txt":"县以上税务局（分局）按照国务院规定的税收征收管理范围，实施属地管理。有条件的城市，可以按照“各区分散受理、全市集中处理”的原则办理税务登记。"},{"i":6,"n":"第六条","txt":"税务局（分局）执行统一纳税人识别号。纳税人识别号由省、自治区、直辖市和计划单列市税务局按照纳税人识别号代码行业标准联合编制，统一下发各地执行。 已领取组织机构代码的纳税人，其纳税人识别号共15位，由纳税人登记所在地6位行政区划码+9位组织机构代码组成。以业主身份证件为有效身份证明的组织，即未取得组织机构代码证书的个体工商户以及持回乡证、通行证、护照办理税务登记的纳税人，其纳税人识别号由身份证件号码+2位顺序码组成。 纳税人识别号具有唯一性。"},{"i":7,"n":"第七条","txt":"纳税人办理下列事项时，必须提供税务登记证件： （一）开立银行账户； （二）领购发票。 纳税人办理其他税务事项时，应当出示税务登记证件，经税务机关核准相关信息后办理手续。"},{"i":8,"n":"第八条","txt":"企业，企业在外地设立的分支机构和从事生产、经营的场所，个体工商户和从事生产、经营的事业单位（以下统称从事生产、经营的纳税人），向生产、经营所在地税务机关申报办理税务登记： （一）从事生产、经营的纳税人领取工商营业执照的，应当自领取工商营业执照之日起30日内申报办理税务登记，税务机关发放税务登记证及副本； （二）从事生产、经营的纳税人未办理工商营业执照但经有关部门批准设立的，应当自有关部门批准设立之日起30日内申报办理税务登记，税务机关发放税务登记证及副本； （三）从事生产、经营的纳税人未办理工商营业执照也未经有关部门批准设立的，应当自纳税义务发生之日起30日内申报办理税务登记，税务机关发放临时税务登记证及副本； （四）有独立的生产经营权、在财务上独立核算并定期向发包人或者出租人上交承包费或租金的承包承租人，应当自承包承租合同签订之日起30日内，向其承包承租业务发生地税务机关申报办理税务"},{"i":9,"n":"第九条","txt":"本办法第八条规定以外的其他纳税人，除国家机关、个人和无固定生产、经营场所的流动性农村小商贩外，均应当自纳税义务发生之日起30日内，向纳税义务发生地税务机关申报办理税务登记，税务机关发放税务登记证及副本。"},{"i":10,"n":"第十条","txt":"税务机关对纳税人税务登记地点发生争议的，由其共同的上级税务机关指定管辖。"},{"i":11,"n":"第十一条","txt":"纳税人在申报办理税务登记时，应当根据不同情况向税务机关如实提供以下证件和资料： （一）工商营业执照或其他核准执业证件； （二）有关合同、章程、协议书； （三）组织机构统一代码证书； （四）法定代表人或负责人或业主的居民身份证、护照或者其他合法证件。 其他需要提供的有关证件、资料，由省、自治区、直辖市税务机关确定。"},{"i":12,"n":"第十二条","txt":"纳税人在申报办理税务登记时，应当如实填写税务登记表。 税务登记表的主要内容包括： （一）单位名称、法定代表人或者业主姓名及其居民身份证、护照或者其他合法证件的号码； （二）住所、经营地点； （三）登记类型； （四）核算方式； （五）生产经营方式； （六）生产经营范围； （七）注册资金（资本）、投资总额； （八）生产经营期限； （九）财务负责人、联系电话； （十）国家税务总局确定的其他有关事项。"},{"i":13,"n":"第十三条","txt":"纳税人提交的证件和资料齐全且税务登记表的填写内容符合规定的，税务机关应当日办理并发放税务登记证件。纳税人提交的证件和资料不齐全或税务登记表的填写内容不符合规定的，税务机关应当场通知其补正或重新填报。"},{"i":14,"n":"第十四条","txt":"税务登记证件的主要内容包括：纳税人名称、税务登记代码、法定代表人或负责人、生产经营地址、登记类型、核算方式、生产经营范围（主营、兼营）、发证日期、证件有效期等。"},{"i":15,"n":"第十五条","txt":"已办理税务登记的扣缴义务人应当自扣缴义务发生之日起30日内，向税务登记地税务机关申报办理扣缴税款登记。税务机关在其税务登记证件上登记扣缴税款事项，税务机关不再发放扣缴税款登记证件。 根据税收法律、行政法规的规定可不办理税务登记的扣缴义务人，应当自扣缴义务发生之日起30日内，向机构所在地税务机关申报办理扣缴税款登记。税务机关发放扣缴税款登记证件。"},{"i":16,"n":"第十六条","txt":"纳税人税务登记内容发生变化的，应当向原税务登记机关申报办理变更税务登记。"},{"i":17,"n":"第十七条","txt":"纳税人已在工商行政管理机关办理变更登记的，应当自工商行政管理机关变更登记之日起30日内，向原税务登记机关如实提供下列证件、资料，申报办理变更税务登记： （一）工商登记变更表； （二）纳税人变更登记内容的有关证明文件； （三）税务机关发放的原税务登记证件（登记证正、副本和登记表等）； （四）其他有关资料。"},{"i":18,"n":"第十八条","txt":"纳税人按照规定不需要在工商行政管理机关办理变更登记，或者其变更登记的内容与工商登记内容无关的，应当自税务登记内容实际发生变化之日起30日内，或者自有关机关批准或者宣布变更之日起30日内，持下列证件到原税务登记机关申报办理变更税务登记： （一）纳税人变更登记内容的有关证明文件； （二）税务机关发放的原税务登记证件（登记证正、副本和税务登记表等）； （三）其他有关资料。"},{"i":19,"n":"第十九条","txt":"纳税人提交的有关变更登记的证件、资料齐全的，应如实填写税务登记变更表，符合规定的，税务机关应当日办理；不符合规定的，税务机关应通知其补正。"},{"i":20,"n":"第二十条","txt":"税务机关应当于受理当日办理变更税务登记。纳税人税务登记表和税务登记证中的内容都发生变更的，税务机关按变更后的内容重新发放税务登记证件；纳税人税务登记表的内容发生变更而税务登记证中的内容未发生变更的，税务机关不重新发放税务登记证件。"},{"i":21,"n":"第二十一条","txt":"实行定期定额征收方式的个体工商户需要停业的，应当在停业前向税务机关申报办理停业登记。纳税人的停业期限不得超过一年。"},{"i":22,"n":"第二十二条","txt":"纳税人在申报办理停业登记时，应如实填写停业复业报告书，说明停业理由、停业期限、停业前的纳税情况和发票的领、用、存情况，并结清应纳税款、滞纳金、罚款。税务机关应收存其税务登记证件及副本、发票领购簿、未使用完的发票和其他税务证件。"},{"i":23,"n":"第二十三条","txt":"纳税人在停业期间发生纳税义务的，应当按照税收法律、行政法规的规定申报缴纳税款。"},{"i":24,"n":"第二十四条","txt":"纳税人应当于恢复生产经营之前，向税务机关申报办理复业登记，如实填写《停业复业报告书》，领回并启用税务登记证件、发票领购簿及其停业前领购的发票。"},{"i":25,"n":"第二十五条","txt":"纳税人停业期满不能及时恢复生产经营的，应当在停业期满前到税务机关办理延长停业登记，并如实填写《停业复业报告书》。"},{"i":26,"n":"第二十六条","txt":"纳税人发生解散、破产、撤销以及其他情形，依法终止纳税义务的，应当在向工商行政管理机关或者其他机关办理注销登记前，持有关证件和资料向原税务登记机关申报办理注销税务登记；按规定不需要在工商行政管理机关或者其他机关办理注册登记的，应当自有关机关批准或者宣告终止之日起15日内，持有关证件和资料向原税务登记机关申报办理注销税务登记。 纳税人被工商行政管理机关吊销营业执照或者被其他机关予以撤销登记的，应当自营业执照被吊销或者被撤销登记之日起15日内，向原税务登记机关申报办理注销税务登记。"},{"i":27,"n":"第二十七条","txt":"纳税人因住所、经营地点变动，涉及改变税务登记机关的，应当在向工商行政管理机关或者其他机关申请办理变更、注销登记前，或者住所、经营地点变动前，持有关证件和资料，向原税务登记机关申报办理注销税务登记，并自注销税务登记之日起30日内向迁达地税务机关申报办理税务登记。"},{"i":28,"n":"第二十八条","txt":"境外企业在中国境内承包建筑、安装、装配、勘探工程和提供劳务的，应当在项目完工、离开中国前15日内，持有关证件和资料，向原税务登记机关申报办理注销税务登记。"},{"i":29,"n":"第二十九条","txt":"纳税人办理注销税务登记前，应当向税务机关提交相关证明文件和资料，结清应纳税款、多退（免）税款、滞纳金和罚款，缴销发票、税务登记证件和其他税务证件，经税务机关核准后，办理注销税务登记手续。"},{"i":30,"n":"第三十条","txt":"纳税人到外县（市）临时从事生产经营活动的，应当在外出生产经营以前，持税务登记证到主管税务机关开具《外出经营活动税收管理证明》（以下简称《外管证》）。"},{"i":31,"n":"第三十一条","txt":"税务机关按照一地一证的原则，发放《外管证》，《外管证》的有效期限一般为30日，最长不得超过180天。"},{"i":32,"n":"第三十二条","txt":"纳税人应当在《外管证》注明地进行生产经营前向当地税务机关报验登记，并提交下列证件、资料： （一）税务登记证件副本； （二）《外管证》。 纳税人在《外管证》注明地销售货物的，除提交以上证件、资料外，应如实填写《外出经营货物报验单》，申报查验货物。"},{"i":33,"n":"第三十三条","txt":"纳税人外出经营活动结束，应当向经营地税务机关填报《外出经营活动情况申报表》，并结清税款、缴销发票。"},{"i":34,"n":"第三十四条","txt":"纳税人应当在《外管证》有效期届满后10日内，持《外管证》回原税务登记地税务机关办理《外管证》缴销手续。"},{"i":35,"n":"第三十五条","txt":"税务机关应当加强税务登记证件的管理，采取实地调查、上门验证等方法进行税务登记证件的管理。"},{"i":36,"n":"第三十六条","txt":"税务登记证式样改变，需统一换发税务登记证的，由国家税务总局确定。"},{"i":37,"n":"第三十七条","txt":"纳税人、扣缴义务人遗失税务登记证件的，应当自遗失税务登记证件之日起15日内，书面报告主管税务机关，如实填写《税务登记证件遗失报告表》，并将纳税人的名称、税务登记证件名称、税务登记证件号码、税务登记证件有效期、发证机关名称在税务机关认可的报刊上作遗失声明，凭报刊上刊登的遗失声明到主管税务机关补办税务登记证件。"},{"i":38,"n":"第三十八条","txt":"已办理税务登记的纳税人未按照规定的期限申报纳税，在税务机关责令其限期改正后，逾期不改正的，税务机关应当派员实地检查，查无下落并且无法强制其履行纳税义务的，由检查人员制作非正常户认定书，存入纳税人档案，税务机关暂停其税务登记证件、发票领购簿和发票的使用。"},{"i":39,"n":"第三十九条","txt":"纳税人被列入非正常户超过三个月的，税务机关可以宣布其税务登记证件失效，其应纳税款的追征仍按《税收征管法》及其《实施细则》的规定执行。"},{"i":40,"n":"第四十条","txt":"纳税人不办理税务登记的，税务机关应当自发现之日起3日内责令其限期改正；逾期不改正的，依照《税收征管法》第六十条第一款的规定处罚。"},{"i":41,"n":"第四十一条","txt":"纳税人通过提供虚假的证明资料等手段，骗取税务登记证的，处2000元以下的罚款；情节严重的，处2000元以上10000元以下的罚款。纳税人涉嫌其他违法行为的，按有关法律、行政法规的规定处理。"},{"i":42,"n":"第四十二条","txt":"扣缴义务人未按照规定办理扣缴税款登记的，税务机关应当自发现之日起3日内责令其限期改正，并可处以1000元以下的罚款。"},{"i":43,"n":"第四十三条","txt":"纳税人、扣缴义务人违反本办法规定，拒不接受税务机关处理的，税务机关可以收缴其发票或者停止向其发售发票。"},{"i":44,"n":"第四十四条","txt":"税务人员徇私舞弊或者玩忽职守，违反本办法规定为纳税人办理税务登记相关手续，或者滥用职权，故意刁难纳税人、扣缴义务人的，调离工作岗位，并依法给予行政处分。"},{"i":45,"n":"第四十五条","txt":"本办法涉及的标识、戳记和文书式样，由国家税务总局确定。"},{"i":46,"n":"第四十六条","txt":"本办法由国家税务总局负责解释。各省、自治区、直辖市和计划单列市税务局可根据本办法制定具体的实施办法。"},{"i":47,"n":"第四十七条","txt":"本办法自2004年2月1日起施行。"}],"shuiwujichaanjianbanlichengxuguiding":[{"i":1,"n":"第一条","txt":"为了贯彻落实中共中央办公厅、国务院办公厅印发的《关于进一步深化税收征管改革的意见》，保障税收法律、行政法规的贯彻实施，规范税务稽查案件办理程序，强化监督制约机制，保护纳税人、扣缴义务人和其他涉税当事人合法权益，根据《中华人民共和国税收征收管理法》（以下简称税收征管法）、《中华人民共和国税收征收管理法实施细则》（以下简称税收征管法实施细则）等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"稽查局办理税务稽查案件适用本规定。"},{"i":3,"n":"第三条","txt":"办理税务稽查案件应当以事实为根据，以法律为准绳，坚持公平、公正、公开、效率的原则。"},{"i":4,"n":"第四条","txt":"税务稽查由稽查局依法实施。稽查局主要职责是依法对纳税人、扣缴义务人和其他涉税当事人履行纳税义务、扣缴义务情况及涉税事项进行检查处理，以及围绕检查处理开展的其他相关工作。稽查局具体职责由国家税务总局依照税收征管法、税收征管法实施细则和国家有关规定确定。"},{"i":5,"n":"第五条","txt":"稽查局办理税务稽查案件时，实行选案、检查、审理、执行分工制约原则。"},{"i":6,"n":"第六条","txt":"稽查局应当在税务局向社会公告的范围内实施税务稽查。上级税务机关可以根据案件办理的需要指定管辖。 税收法律、行政法规和国家税务总局规章对税务稽查管辖另有规定的，从其规定。"},{"i":7,"n":"第七条","txt":"税务稽查管辖有争议的，由争议各方本着有利于案件办理的原则逐级协商解决；不能协商一致的，报请共同的上级税务机关决定。"},{"i":8,"n":"第八条","txt":"税务稽查人员具有税收征管法实施细则规定回避情形的，应当回避。 被查对象申请税务稽查人员回避或者税务稽查人员自行申请回避的，由稽查局局长依法决定是否回避。稽查局局长发现税务稽查人员具有规定回避情形的，应当要求其回避。稽查局局长的回避，由税务局局长依法审查决定。"},{"i":9,"n":"第九条","txt":"税务稽查人员对实施税务稽查过程中知悉的国家秘密、商业秘密或者个人隐私、个人信息，应当依法予以保密。 纳税人、扣缴义务人和其他涉税当事人的税收违法行为不属于保密范围。"},{"i":10,"n":"第十条","txt":"税务稽查人员应当遵守工作纪律，恪守职业道德，不得有下列行为： （一）违反法定程序、超越权限行使职权； （二）利用职权为自己或者他人牟取利益； （三）玩忽职守，不履行法定义务； （四）泄露国家秘密、工作秘密，向被查对象通风报信、泄露案情； （五）弄虚作假，故意夸大或者隐瞒案情； （六）接受被查对象的请客送礼等影响公正执行公务的行为； （七）其他违法违纪行为。 税务稽查人员在执法办案中滥用职权、玩忽职守、徇私舞弊的，依照有关规定严肃处理；涉嫌犯罪的，依法移送司法机关处理。"},{"i":11,"n":"第十一条","txt":"税务稽查案件办理应当通过文字、音像等形式，对案件办理的启动、调查取证、审核、决定、送达、执行等进行全过程记录。"},{"i":12,"n":"第十二条","txt":"稽查局应当加强稽查案源管理，全面收集整理案源信息，合理、准确地选择待查对象。案源管理依照国家税务总局有关规定执行。"},{"i":13,"n":"第十三条","txt":"待查对象确定后，经稽查局局长批准实施立案检查。 必要时，依照法律法规的规定，稽查局可以在立案前进行检查。"},{"i":14,"n":"第十四条","txt":"稽查局应当统筹安排检查工作，严格控制对纳税人、扣缴义务人的检查次数。"},{"i":15,"n":"第十五条","txt":"检查前，稽查局应当告知被查对象检查时间、需要准备的资料等，但预先通知有碍检查的除外。 检查应当由两名以上具有执法资格的检查人员共同实施，并向被查对象出示税务检查证件、出示或者送达税务检查通知书，告知其权利和义务。"},{"i":16,"n":"第十六条","txt":"检查应当依照法定权限和程序，采取实地检查、调取账簿资料、询问、查询存款账户或者储蓄存款、异地协查等方法。 对采用电子信息系统进行管理和核算的被查对象，检查人员可以要求其打开该电子信息系统，或者提供与原始电子数据、电子信息系统技术资料一致的复制件。被查对象拒不打开或者拒不提供的，经稽查局局长批准，可以采用适当的技术手段对该电子信息系统进行直接检查，或者提取、复制电子数据进行检查，但所采用的技术手段不得破坏该电子信息系统原始电子数据，或者影响该电子信息系统正常运行。"},{"i":17,"n":"第十七条","txt":"检查应当依照法定权限和程序收集证据材料。收集的证据必须经查证属实，并与证明事项相关联。 不得以下列方式收集、获取证据材料： （一）严重违反法定程序收集； （二）以违反法律强制性规定的手段获取且侵害他人合法权益； （三）以利诱、欺诈、胁迫、暴力等手段获取。"},{"i":18,"n":"第十八条","txt":"调取账簿、记账凭证、报表和其他有关资料时，应当向被查对象出具调取账簿资料通知书，并填写调取账簿资料清单交其核对后签章确认。 调取纳税人、扣缴义务人以前会计年度的账簿、记账凭证、报表和其他有关资料的，应当经县以上税务局局长批准，并在3个月内完整退还；调取纳税人、扣缴义务人当年的账簿、记账凭证、报表和其他有关资料的，应当经设区的市、自治州以上税务局局长批准，并在30日内退还。 退还账簿资料时，应当由被查对象核对调取账簿资料清单，并签章确认。"},{"i":19,"n":"第十九条","txt":"需要提取证据材料原件的，应当向当事人出具提取证据专用收据，由当事人核对后签章确认。对需要退还的证据材料原件，检查结束后应当及时退还，并履行相关签收手续。需要将已开具的纸质发票调出查验时，应当向被查验的单位或者个人开具发票换票证；需要将空白纸质发票调出查验时，应当向被查验的单位或者个人开具调验空白发票收据。经查无问题的，应当及时退还，并履行相关签收手续。 提取证据材料复制件的，应当由当事人或者原件保存单位（个人）在复制件上注明“与原件核对无误”及原件存放地点，并签章。"},{"i":20,"n":"第二十条","txt":"询问应当由两名以上检查人员实施。除在被查对象生产、经营、办公场所询问外，应当向被询问人送达询问通知书。 询问时应当告知被询问人有关权利义务。询问笔录应当交被询问人核对或者向其宣读；询问笔录有修改的，应当由被询问人在改动处捺指印；核对无误后，由被询问人在尾页结束处写明“以上笔录我看过（或者向我宣读过），与我说的相符”，并逐页签章、捺指印。被询问人拒绝在询问笔录上签章、捺指印的，检查人员应当在笔录上注明。"},{"i":21,"n":"第二十一条","txt":"当事人、证人可以采取书面或者口头方式陈述或者提供证言。当事人、证人口头陈述或者提供证言的，检查人员应当以笔录、录音、录像等形式进行记录。笔录可以手写或者使用计算机记录并打印，由当事人或者证人逐页签章、捺指印。 当事人、证人口头提出变更陈述或者证言的，检查人员应当就变更部分重新制作笔录，注明原因，由当事人或者证人逐页签章、捺指印。当事人、证人变更书面陈述或者证言的，变更前的笔录不予退回。"},{"i":22,"n":"第二十二条","txt":"制作录音、录像等视听资料的，应当注明制作方法、制作时间、制作人和证明对象等内容。 调取视听资料时，应当调取有关资料的原始载体；难以调取原始载体的，可以调取复制件，但应当说明复制方法、人员、时间和原件存放处等事项。 对声音资料，应当附有该声音内容的文字记录；对图像资料，应当附有必要的文字说明。"},{"i":23,"n":"第二十三条","txt":"以电子数据的内容证明案件事实的，检查人员可以要求当事人将电子数据打印成纸质资料，在纸质资料上注明数据出处、打印场所、打印时间或者提供时间，注明“与电子数据核对无误”，并由当事人签章。 需要以有形载体形式固定电子数据的，检查人员应当与提供电子数据的个人、单位的法定代表人或者财务负责人或者经单位授权的其他人员一起将电子数据复制到存储介质上并封存，同时在封存包装物上注明制作方法、制作时间、制作人、文件格式及大小等，注明“与原始载体记载的电子数据核对无误”，并由电子数据提供人签章。 收集、提取电子数据，检查人员应当制作现场笔录，注明电子数据的来源、事由、证明目的或者对象，提取时间、地点、方法、过程，原始存储介质的存放地点以及对电子数据存储介质的签封情况等。进行数据压缩的，应当在笔录中注明压缩方法和完整性校验值。"},{"i":24,"n":"第二十四条","txt":"检查人员实地调查取证时，可以制作现场笔录、勘验笔录，对实地调查取证情况予以记录。 制作现场笔录、勘验笔录，应当载明时间、地点和事件等内容，并由检查人员签名和当事人签章。 当事人经通知不到场或者拒绝在现场笔录、勘验笔录上签章的，检查人员应当在笔录上注明原因；如有其他人员在场，可以由其签章证明。"},{"i":25,"n":"第二十五条","txt":"检查人员异地调查取证的，当地税务机关应当予以协助；发函委托相关稽查局调查取证的，必要时可以派人参与受托地稽查局的调查取证，受托地稽查局应当根据协查请求，依照法定权限和程序调查。 需要取得境外资料的，稽查局可以提请国际税收管理部门依照有关规定程序获取。"},{"i":26,"n":"第二十六条","txt":"查询从事生产、经营的纳税人、扣缴义务人存款账户，应当经县以上税务局局长批准，凭检查存款账户许可证明向相关银行或者其他金融机构查询。 查询案件涉嫌人员储蓄存款的，应当经设区的市、自治州以上税务局局长批准，凭检查存款账户许可证明向相关银行或者其他金融机构查询。"},{"i":27,"n":"第二十七条","txt":"被查对象有下列情形之一的，依照税收征管法和税收征管法实施细则有关逃避、拒绝或者以其他方式阻挠税务检查的规定处理： （一）提供虚假资料，不如实反映情况，或者拒绝提供有关资料的； （二）拒绝或者阻止税务机关记录、录音、录像、照相和复制与案件有关的情况和资料的； （三）在检查期间转移、隐匿、销毁有关资料的； （四）有不依法接受税务检查的其他情形的。"},{"i":28,"n":"第二十八条","txt":"税务机关有根据认为从事生产、经营的纳税人有逃避纳税义务行为，可以在规定的纳税期之前，责令限期缴纳应纳税款；在限期内发现纳税人有明显的转移、隐匿其应纳税的商品、货物以及其他财产或者应纳税收入迹象的，可以责成纳税人提供纳税担保。如果纳税人不能提供纳税担保，经县以上税务局局长批准，可以依法采取税收强制措施。 检查从事生产、经营的纳税人以前纳税期的纳税情况时，发现纳税人有逃避纳税义务行为，并有明显的转移、隐匿其应纳税的商品、货物以及其他财产或者应纳税收入迹象的，经县以上税务局局长批准，可以依法采取税收强制措施。"},{"i":29,"n":"第二十九条","txt":"稽查局采取税收强制措施时，应当向纳税人、扣缴义务人、纳税担保人交付税收强制措施决定书，告知其采取税收强制措施的内容、理由、依据以及依法享有的权利、救济途径，并履行法律、法规规定的其他程序。 采取冻结纳税人在开户银行或者其他金融机构的存款措施时，应当向纳税人开户银行或者其他金融机构交付冻结存款通知书，冻结其相当于应纳税款的存款；并于作出冻结决定之日起3个工作日内，向纳税人交付冻结决定书。 采取查封、扣押商品、货物或者其他财产措施时，应当向纳税人、扣缴义务人、纳税担保人当场交付查封、扣押决定书，填写查封商品、货物或者其他财产清单或者出具扣押商品、货物或者其他财产专用收据，由当事人核对后签章。查封清单、扣押收据一式二份，由当事人和稽查局分别保存。 采取查封、扣押有产权证件的动产或者不动产措施时，应当依法向有关单位送达税务协助执行通知书，通知其在查封、扣押期间不再办理该动产或者不动产的过户手续"},{"i":30,"n":"第三十条","txt":"按照本规定第二十八条第二款采取查封、扣押措施的，期限一般不得超过６个月；重大案件有下列情形之一，需要延长期限的，应当报国家税务总局批准： （一）案情复杂，在查封、扣押期限内确实难以查明案件事实的； （二）被查对象转移、隐匿、销毁账簿、记账凭证或者其他证据材料的； （三）被查对象拒不提供相关情况或者以其他方式拒绝、阻挠检查的； （四）解除查封、扣押措施可能使纳税人转移、隐匿、损毁或者违法处置财产，从而导致税款无法追缴的。 除前款规定情形外采取查封、扣押、冻结措施的，期限不得超过30日；情况复杂的，经县以上税务局局长批准，可以延长，但是延长期限不得超过30日。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，应当依法及时解除税收强制措施： （一）纳税人已按履行期限缴纳税款、扣缴义务人已按履行期限解缴税款、纳税担保人已按履行期限缴纳所担保税款的； （二）税收强制措施被复议机关决定撤销的； （三）税收强制措施被人民法院判决撤销的； （四）其他法定应当解除税收强制措施的。"},{"i":32,"n":"第三十二条","txt":"解除税收强制措施时，应当向纳税人、扣缴义务人、纳税担保人送达解除税收强制措施决定书，告知其解除税收强制措施的时间、内容和依据，并通知其在规定时间内办理解除税收强制措施的有关事宜： （一）采取冻结存款措施的，应当向冻结存款的纳税人开户银行或者其他金融机构送达解除冻结存款通知书，解除冻结； （二）采取查封商品、货物或者其他财产措施的，应当解除查封并收回查封商品、货物或者其他财产清单； （三）采取扣押商品、货物或者其他财产措施的，应当予以返还并收回扣押商品、货物或者其他财产专用收据。 税收强制措施涉及协助执行单位的，应当向协助执行单位送达税务协助执行通知书，通知解除税收强制措施相关事项。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一，致使检查暂时无法进行的，经稽查局局长批准后，中止检查： （一）当事人被有关机关依法限制人身自由的； （二）账簿、记账凭证及有关资料被其他国家机关依法调取且尚未归还的； （三）与税收违法行为直接相关的事实需要人民法院或者其他国家机关确认的； （四）法律、行政法规或者国家税务总局规定的其他可以中止检查的。 中止检查的情形消失，经稽查局局长批准后，恢复检查。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一，致使检查确实无法进行的，经稽查局局长批准后，终结检查： （一）被查对象死亡或者被依法宣告死亡或者依法注销，且有证据表明无财产可抵缴税款或者无法定税收义务承担主体的； （二）被查对象税收违法行为均已超过法定追究期限的； （三）法律、行政法规或者国家税务总局规定的其他可以终结检查的。"},{"i":35,"n":"第三十五条","txt":"检查结束前，检查人员可以将发现的税收违法事实和依据告知被查对象。 被查对象对违法事实和依据有异议的，应当在限期内提供说明及证据材料。被查对象口头说明的，检查人员应当制作笔录，由当事人签章。"},{"i":36,"n":"第三十六条","txt":"检查结束后，稽查局应当对案件进行审理。符合重大税务案件标准的，稽查局审理后提请税务局重大税务案件审理委员会审理。 重大税务案件审理依照国家税务总局有关规定执行。"},{"i":37,"n":"第三十七条","txt":"案件审理应当着重审核以下内容： （一）执法主体是否正确； （二）被查对象是否准确； （三）税收违法事实是否清楚，证据是否充分，数据是否准确，资料是否齐全； （四）适用法律、行政法规、规章及其他规范性文件是否适当，定性是否正确； （五）是否符合法定程序； （六）是否超越或者滥用职权； （七）税务处理、处罚建议是否适当； （八）其他应当审核确认的事项或者问题。"},{"i":38,"n":"第三十八条","txt":"有下列情形之一的，应当补正或者补充调查： （一）被查对象认定错误的； （二）税收违法事实不清、证据不足的； （三）不符合法定程序的； （四）税务文书不规范、不完整的； （五）其他需要补正或者补充调查的。"},{"i":39,"n":"第三十九条","txt":"拟对被查对象或者其他涉税当事人作出税务行政处罚的，应当向其送达税务行政处罚事项告知书，告知其依法享有陈述、申辩及要求听证的权利。税务行政处罚事项告知书应当包括以下内容： （一）被查对象或者其他涉税当事人姓名或者名称、有效身份证件号码或者统一社会信用代码、地址。没有统一社会信用代码的，以税务机关赋予的纳税人识别号代替； （二）认定的税收违法事实和性质； （三）适用的法律、行政法规、规章及其他规范性文件； （四）拟作出的税务行政处罚； （五）当事人依法享有的权利； （六）告知书的文号、制作日期、税务机关名称及印章； （七）其他相关事项。"},{"i":40,"n":"第四十条","txt":"被查对象或者其他涉税当事人可以书面或者口头提出陈述、申辩意见。对当事人口头提出陈述、申辩意见，应当制作陈述申辩笔录，如实记录，由陈述人、申辩人签章。 应当充分听取当事人的陈述、申辩意见；经复核，当事人提出的事实、理由或者证据成立的，应当采纳。"},{"i":41,"n":"第四十一条","txt":"被查对象或者其他涉税当事人按照法律、法规、规章要求听证的，应当依法组织听证。 听证依照国家税务总局有关规定执行。"},{"i":42,"n":"第四十二条","txt":"经审理，区分下列情形分别作出处理： （一）有税收违法行为，应当作出税务处理决定的，制作税务处理决定书； （二）有税收违法行为，应当作出税务行政处罚决定的，制作税务行政处罚决定书； （三）税收违法行为轻微，依法可以不予税务行政处罚的，制作不予税务行政处罚决定书； （四）没有税收违法行为的，制作税务稽查结论。 税务处理决定书、税务行政处罚决定书、不予税务行政处罚决定书、税务稽查结论引用的法律、行政法规、规章及其他规范性文件，应当注明文件全称、文号和有关条款。"},{"i":43,"n":"第四十三条","txt":"税务处理决定书应当包括以下主要内容： （一）被查对象姓名或者名称、有效身份证件号码或者统一社会信用代码、地址。没有统一社会信用代码的，以税务机关赋予的纳税人识别号代替； （二）检查范围和内容； （三）税收违法事实及所属期间； （四）处理决定及依据； （五）税款金额、缴纳期限及地点； （六）税款滞纳时间、滞纳金计算方法、缴纳期限及地点； （七）被查对象不按期履行处理决定应当承担的责任； （八）申请行政复议或者提起行政诉讼的途径和期限； （九）处理决定书的文号、制作日期、税务机关名称及印章。"},{"i":44,"n":"第四十四条","txt":"税务行政处罚决定书应当包括以下主要内容： （一）被查对象或者其他涉税当事人姓名或者名称、有效身份证件号码或者统一社会信用代码、地址。没有统一社会信用代码的，以税务机关赋予的纳税人识别号代替； （二）检查范围和内容； （三）税收违法事实、证据及所属期间； （四）行政处罚种类和依据； （五）行政处罚履行方式、期限和地点； （六）当事人不按期履行行政处罚决定应当承担的责任； （七）申请行政复议或者提起行政诉讼的途径和期限； （八）行政处罚决定书的文号、制作日期、税务机关名称及印章。 税务行政处罚决定应当依法公开。公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，应当在3个工作日内撤回原行政处罚决定信息并公开说明理由。"},{"i":45,"n":"第四十五条","txt":"不予税务行政处罚决定书应当包括以下主要内容： （一）被查对象或者其他涉税当事人姓名或者名称、有效身份证件号码或者统一社会信用代码、地址。没有统一社会信用代码的，以税务机关赋予的纳税人识别号代替； （二）检查范围和内容； （三）税收违法事实及所属期间； （四）不予税务行政处罚的理由及依据； （五）申请行政复议或者提起行政诉讼的途径和期限； （六）不予行政处罚决定书的文号、制作日期、税务机关名称及印章。"},{"i":46,"n":"第四十六条","txt":"税务稽查结论应当包括以下主要内容： （一）被查对象姓名或者名称、有效身份证件号码或者统一社会信用代码、地址。没有统一社会信用代码的，以税务机关赋予的纳税人识别号代替； （二）检查范围和内容； （三）检查时间和检查所属期间； （四）检查结论； （五）结论的文号、制作日期、税务机关名称及印章。"},{"i":47,"n":"第四十七条","txt":"稽查局应当自立案之日起90日内作出行政处理、处罚决定或者无税收违法行为结论。案情复杂需要延期的，经税务局局长批准，可以延长不超过90日；特殊情况或者发生不可抗力需要继续延期的，应当经上一级税务局分管副局长批准，并确定合理的延长期限。但下列时间不计算在内： （一）中止检查的时间； （二）请示上级机关或者征求有权机关意见的时间； （三）提请重大税务案件审理的时间； （四）因其他方式无法送达，公告送达文书的时间； （五）组织听证的时间； （六）纳税人、扣缴义务人超期提供资料的时间； （七）移送司法机关后，税务机关需根据司法文书决定是否处罚的案件，从司法机关接受移送到司法文书生效的时间。"},{"i":48,"n":"第四十八条","txt":"税收违法行为涉嫌犯罪的，填制涉嫌犯罪案件移送书，经税务局局长批准后，依法移送公安机关，并附送以下资料： （一）涉嫌犯罪案件情况的调查报告； （二）涉嫌犯罪的主要证据材料复制件； （三）其他有关涉嫌犯罪的材料。"},{"i":49,"n":"第四十九条","txt":"稽查局应当依法及时送达税务处理决定书、税务行政处罚决定书、不予税务行政处罚决定书、税务稽查结论等税务文书。"},{"i":50,"n":"第五十条","txt":"具有下列情形之一的，经县以上税务局局长批准，稽查局可以依法强制执行，或者依法申请人民法院强制执行： （一）纳税人、扣缴义务人未按照规定的期限缴纳或者解缴税款、滞纳金，责令限期缴纳逾期仍未缴纳的； （二）经稽查局确认的纳税担保人未按照规定的期限缴纳所担保的税款、滞纳金，责令限期缴纳逾期仍未缴纳的； （三）当事人对处罚决定逾期不申请行政复议也不向人民法院起诉、又不履行的； （四）其他可以依法强制执行的。"},{"i":51,"n":"第五十一条","txt":"当事人确有经济困难，需要延期或者分期缴纳罚款的，可向稽查局提出申请，经税务局局长批准后，可以暂缓或者分期缴纳。"},{"i":52,"n":"第五十二条","txt":"作出强制执行决定前，应当制作并送达催告文书，催告当事人履行义务，听取当事人陈述、申辩意见。经催告，当事人逾期仍不履行行政决定，且无正当理由的，经县以上税务局局长批准，实施强制执行。 实施强制执行时，应当向被执行人送达强制执行决定书，告知其实施强制执行的内容、理由及依据，并告知其享有依法申请行政复议或者提起行政诉讼的权利。 催告期间，对有证据证明有转移或者隐匿财物迹象的，可以作出立即强制执行决定。"},{"i":53,"n":"第五十三条","txt":"稽查局采取从被执行人开户银行或者其他金融机构的存款中扣缴税款、滞纳金、罚款措施时，应当向被执行人开户银行或者其他金融机构送达扣缴税收款项通知书，依法扣缴税款、滞纳金、罚款，并及时将有关凭证送达被执行人。"},{"i":54,"n":"第五十四条","txt":"拍卖、变卖被执行人商品、货物或者其他财产，以拍卖、变卖所得抵缴税款、滞纳金、罚款的，在拍卖、变卖前应当依法进行查封、扣押。 稽查局拍卖、变卖被执行人商品、货物或者其他财产前，应当制作拍卖/变卖抵税财物决定书，经县以上税务局局长批准后送达被执行人，予以拍卖或者变卖。 拍卖或者变卖实现后，应当在结算并收取价款后3个工作日内，办理税款、滞纳金、罚款的入库手续，并制作拍卖/变卖结果通知书，附拍卖/变卖查封、扣押的商品、货物或者其他财产清单，经稽查局局长审核后，送达被执行人。 以拍卖或者变卖所得抵缴税款、滞纳金、罚款和拍卖、变卖等费用后，尚有剩余的财产或者无法进行拍卖、变卖的财产的，应当制作返还商品、货物或者其他财产通知书，附返还商品、货物或者其他财产清单，送达被执行人，并自办理税款、滞纳金、罚款入库手续之日起3个工作日内退还被执行人。"},{"i":55,"n":"第五十五条","txt":"执行过程中发现涉嫌犯罪的，依照本规定第四十八条处理。"},{"i":56,"n":"第五十六条","txt":"执行过程中发现有下列情形之一的，经稽查局局长批准后，中止执行： （一）当事人死亡或者被依法宣告死亡，尚未确定可执行财产的； （二）当事人进入破产清算程序尚未终结的； （三）可执行财产被司法机关或者其他国家机关依法查封、扣押、冻结，致使执行暂时无法进行的； （四）可供执行的标的物需要人民法院或者仲裁机构确定权属的； （五）法律、行政法规和国家税务总局规定其他可以中止执行的。 中止执行情形消失后，经稽查局局长批准，恢复执行。"},{"i":57,"n":"第五十七条","txt":"当事人确无财产可供抵缴税款、滞纳金、罚款或者依照破产清算程序确实无法清缴税款、滞纳金、罚款，或者有其他法定终结执行情形的，经税务局局长批准后，终结执行。"},{"i":58,"n":"第五十八条","txt":"税务处理决定书、税务行政处罚决定书等决定性文书送达后，有下列情形之一的，稽查局可以依法重新作出： （一）决定性文书被人民法院判决撤销的； （二）决定性文书被行政复议机关决定撤销的； （三）税务机关认为需要变更或者撤销原决定性文书的； （四）其他依法需要变更或者撤销原决定性文书的。"},{"i":59,"n":"第五十九条","txt":"本规定相关税务文书的式样，由国家税务总局规定。"},{"i":60,"n":"第六十条","txt":"本规定所称签章，区分以下情况确定： （一）属于法人或者其他组织的，由相关人员签名，加盖单位印章并注明日期； （二）属于个人的，由个人签名并注明日期。 本规定所称“以上”“日内”，均含本数。"},{"i":61,"n":"第六十一条","txt":"本规定自2021年8月11日起施行。《税务稽查工作规程》（国税发〔2009〕157号印发，国家税务总局公告2018年第31号修改）同时废止。"}],"shuiwuxingzhengfuyiguize":[{"i":1,"n":"第一条","txt":"为了进一步发挥行政复议解决税务行政争议的作用，保护公民、法人和其他组织的合法权益，监督和保障税务机关依法行使职权，根据《中华人民共和国行政复议法》（以下简称行政复议法）、《中华人民共和国税收征收管理法》和《中华人民共和国行政复议法实施条例》（以下简称行政复议法实施条例），结合税收工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"公民、法人和其他组织（以下简称申请人）认为税务机关的具体行政行为侵犯其合法权益，向税务行政复议机关申请行政复议，税务行政复议机关办理行政复议事项，适用本规则。"},{"i":3,"n":"第三条","txt":"本规则所称税务行政复议机关（以下简称行政复议机关），指依法受理行政复议申请、对具体行政行为进行审查并作出行政复议决定的税务机关。"},{"i":4,"n":"第四条","txt":"行政复议应当遵循合法、公正、公开、及时和便民的原则。 行政复议机关应当树立依法行政观念，强化责任意识和服务意识，认真履行行政复议职责，坚持有错必纠，确保法律正确实施。"},{"i":5,"n":"第五条","txt":"行政复议机关在申请人的行政复议请求范围内，不得作出对申请人更为不利的行政复议决定。"},{"i":6,"n":"第六条","txt":"申请人对行政复议决定不服的，可以依法向人民法院提起行政诉讼。"},{"i":7,"n":"第七条","txt":"行政复议机关受理行政复议申请，不得向申请人收取任何费用。"},{"i":8,"n":"第八条","txt":"各级税务机关行政首长是行政复议工作第一责任人，应当切实履行职责，加强对行政复议工作的组织领导。"},{"i":9,"n":"第九条","txt":"行政复议机关应当为申请人、第三人查阅案卷资料、接受询问、调解、听证等提供专门场所和其他必要条件。"},{"i":10,"n":"第十条","txt":"各级税务机关应当加大对行政复议工作的基础投入，推进行政复议工作信息化建设，配备调查取证所需的照相、录音、录像和办案所需的电脑、扫描、投影、传真、复印等设备，保障办案交通工具和相应经费。"},{"i":11,"n":"第十一条","txt":"各级行政复议机关负责法制工作的机构（以下简称行政复议机构）依法办理行政复议事项，履行下列职责： （一）受理行政复议申请。 （二）向有关组织和人员调查取证，查阅文件和资料。 （三）审查申请行政复议的具体行政行为是否合法和适当，起草行政复议决定。 （四）处理或者转送对本规则第十五条所列有关规定的审查申请。 （五）对被申请人违反行政复议法及其实施条例和本规则规定的行为，依照规定的权限和程序向相关部门提出处理建议。 （六）研究行政复议工作中发现的问题，及时向有关机关或者部门提出改进建议，重大问题及时向行政复议机关报告。 （七）指导和监督下级税务机关的行政复议工作。 （八）办理或者组织办理行政诉讼案件应诉事项。 （九）办理行政复议案件的赔偿事项。 （十）办理行政复议、诉讼、赔偿等案件的统计、报告、归档工作和重大行政复议决定备案事项。 （十一）其他与行政复议工作有关的事项。"},{"i":12,"n":"第十二条","txt":"各级行政复议机关可以成立行政复议委员会，研究重大、疑难案件，提出处理建议。 行政复议委员会可以邀请本机关以外的具有相关专业知识的人员参加。"},{"i":13,"n":"第十三条","txt":"行政复议工作人员应当具备与履行行政复议职责相适应的品行、专业知识和业务能力。 税务机关中初次从事行政复议的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":14,"n":"第十四条","txt":"行政复议机关受理申请人对税务机关下列具体行政行为不服提出的行政复议申请： （一）征税行为，包括确认纳税主体、征税对象、征税范围、减税、免税、退税、抵扣税款、适用税率、计税依据、纳税环节、纳税期限、纳税地点和税款征收方式等具体行政行为，征收税款、加收滞纳金，扣缴义务人、受税务机关委托的单位和个人作出的代扣代缴、代收代缴、代征行为等。 （二）行政许可、行政审批行为。 （三）发票管理行为，包括发售、收缴、代开发票等。 （四）税收保全措施、强制执行措施。 （五）行政处罚行为： 1.罚款； 2.没收财物和违法所得； 3.停止出口退税权。 （六）不依法履行下列职责的行为： 1.颁发税务登记； 2.开具、出具完税凭证、外出经营活动税收管理证明； 3.行政赔偿； 4.行政奖励； 5.其他不依法履行职责的行为。 （七）资格认定行为。 （八）不依法确认纳税担保行为。 （九）政府信息公开工作中的具体行政行为"},{"i":15,"n":"第十五条","txt":"申请人认为税务机关的具体行政行为所依据的下列规定不合法，对具体行政行为申请行政复议时，可以一并向行政复议机关提出对有关规定的审查申请；申请人对具体行政行为提出行政复议申请时不知道该具体行政行为所依据的规定的，可以在行政复议机关作出行政复议决定以前提出对该规定的审查申请： （一）国家税务总局和国务院其他部门的规定。 （二）其他各级税务机关的规定。 （三）地方各级人民政府的规定。 （四）地方人民政府工作部门的规定。 前款中的规定不包括规章。"},{"i":16,"n":"第十六条","txt":"对各级税务局的具体行政行为不服的，向其上一级税务局申请行政复议。 对计划单列市税务局的具体行政行为不服的，向国家税务总局申请行政复议。"},{"i":17,"n":"第十七条","txt":"对税务所（分局）、各级税务局的稽查局的具体行政行为不服的，向其所属税务局申请行政复议。"},{"i":18,"n":"第十八条","txt":"对国家税务总局的具体行政行为不服的，向国家税务总局申请行政复议。对行政复议决定不服，申请人可以向人民法院提起行政诉讼，也可以向国务院申请裁决。国务院的裁决为最终裁决。"},{"i":19,"n":"第十九条","txt":"对下列税务机关的具体行政行为不服的，按照下列规定申请行政复议： （一）对两个以上税务机关以共同的名义作出的具体行政行为不服的，向共同上一级税务机关申请行政复议；对税务机关与其他行政机关以共同的名义作出的具体行政行为不服的，向其共同上一级行政机关申请行政复议。 （二）对被撤销的税务机关在撤销以前所作出的具体行政行为不服的，向继续行使其职权的税务机关的上一级税务机关申请行政复议。 （三）对税务机关作出逾期不缴纳罚款加处罚款的决定不服的，向作出行政处罚决定的税务机关申请行政复议。但是对已处罚款和加处罚款都不服的，一并向作出行政处罚决定的税务机关的上一级税务机关申请行政复议。 申请人向具体行政行为发生地的县级地方人民政府提交行政复议申请的，由接受申请的县级地方人民政府依照行政复议法第十五条、第十八条的规定予以转送。"},{"i":20,"n":"第二十条","txt":"合伙企业申请行政复议的，应当以核准登记的企业为申请人，由执行合伙事务的合伙人代表该企业参加行政复议；其他合伙组织申请行政复议的，由合伙人共同申请行政复议。 前款规定以外的不具备法人资格的其他组织申请行政复议的，由该组织的主要负责人代表该组织参加行政复议；没有主要负责人的，由共同推选的其他成员代表该组织参加行政复议。"},{"i":21,"n":"第二十一条","txt":"股份制企业的股东大会、股东代表大会、董事会认为税务具体行政行为侵犯企业合法权益的，可以以企业的名义申请行政复议。"},{"i":22,"n":"第二十二条","txt":"有权申请行政复议的公民死亡的，其近亲属可以申请行政复议；有权申请行政复议的公民为无行为能力人或者限制行为能力人，其法定代理人可以代理申请行政复议。 有权申请行政复议的法人或者其他组织发生合并、分立或终止的，承受其权利义务的法人或者其他组织可以申请行政复议。"},{"i":23,"n":"第二十三条","txt":"行政复议期间，行政复议机关认为申请人以外的公民、法人或者其他组织与被审查的具体行政行为有利害关系的，可以通知其作为第三人参加行政复议。 行政复议期间，申请人以外的公民、法人或者其他组织与被审查的税务具体行政行为有利害关系的，可以向行政复议机关申请作为第三人参加行政复议。 第三人不参加行政复议，不影响行政复议案件的审理。"},{"i":24,"n":"第二十四条","txt":"非具体行政行为的行政管理相对人，但其权利直接被该具体行政行为所剥夺、限制或者被赋予义务的公民、法人或其他组织，在行政管理相对人没有申请行政复议时，可以单独申请行政复议。"},{"i":25,"n":"第二十五条","txt":"同一行政复议案件申请人超过5人的，应当推选1至5名代表参加行政复议。"},{"i":26,"n":"第二十六条","txt":"申请人对具体行政行为不服申请行政复议的，作出该具体行政行为的税务机关为被申请人。"},{"i":27,"n":"第二十七条","txt":"申请人对扣缴义务人的扣缴税款行为不服的，主管该扣缴义务人的税务机关为被申请人；对税务机关委托的单位和个人的代征行为不服的，委托税务机关为被申请人。"},{"i":28,"n":"第二十八条","txt":"税务机关与法律、法规授权的组织以共同的名义作出具体行政行为的，税务机关和法律、法规授权的组织为共同被申请人。 税务机关与其他组织以共同名义作出具体行政行为的，税务机关为被申请人。"},{"i":29,"n":"第二十九条","txt":"税务机关依照法律、法规和规章规定，经上级税务机关批准作出具体行政行为的，批准机关为被申请人。 申请人对经重大税务案件审理程序作出的决定不服的，审理委员会所在税务机关为被申请人。"},{"i":30,"n":"第三十条","txt":"税务机关设立的派出机构、内设机构或者其他组织，未经法律、法规授权，以自己名义对外作出具体行政行为的，税务机关为被申请人。"},{"i":31,"n":"第三十一条","txt":"申请人、第三人可以委托1至2名代理人参加行政复议。申请人、第三人委托代理人的，应当向行政复议机构提交授权委托书。授权委托书应当载明委托事项、权限和期限。公民在特殊情况下无法书面委托的，可以口头委托。口头委托的，行政复议机构应当核实并记录在卷。申请人、第三人解除或者变更委托的，应当书面告知行政复议机构。 被申请人不得委托本机关以外人员参加行政复议。"},{"i":32,"n":"第三十二条","txt":"申请人可以在知道税务机关作出具体行政行为之日起60日内提出行政复议申请。 因不可抗力或者被申请人设置障碍等原因耽误法定申请期限的，申请期限的计算应当扣除被耽误时间。"},{"i":33,"n":"第三十三条","txt":"申请人对本规则第十四条第（一）项规定的行为不服的，应当先向行政复议机关申请行政复议；对行政复议决定不服的，可以向人民法院提起行政诉讼。 申请人按照前款规定申请行政复议的，必须依照税务机关根据法律、法规确定的税额、期限，先行缴纳或者解缴税款和滞纳金，或者提供相应的担保，才可以在缴清税款和滞纳金以后或者所提供的担保得到作出具体行政行为的税务机关确认之日起60日内提出行政复议申请。 申请人提供担保的方式包括保证、抵押和质押。作出具体行政行为的税务机关应当对保证人的资格、资信进行审查，对不具备法律规定资格或者没有能力保证的，有权拒绝。作出具体行政行为的税务机关应当对抵押人、出质人提供的抵押担保、质押担保进行审查，对不符合法律规定的抵押担保、质押担保，不予确认。"},{"i":34,"n":"第三十四条","txt":"申请人对本规则第十四条第（一）项规定以外的其他具体行政行为不服，可以申请行政复议，也可以直接向人民法院提起行政诉讼。 申请人对税务机关作出逾期不缴纳罚款加处罚款的决定不服的，应当先缴纳罚款和加处罚款，再申请行政复议。"},{"i":35,"n":"第三十五条","txt":"本规则第三十二条第一款规定的行政复议申请期限的计算，依照下列规定办理： （一）当场作出具体行政行为的，自具体行政行为作出之日起计算。 （二）载明具体行政行为的法律文书直接送达的，自受送达人签收之日起计算。 （三）载明具体行政行为的法律文书邮寄送达的，自受送达人在邮件签收单上签收之日起计算；没有邮件签收单的，自受送达人在送达回执上签名之日起计算。 （四）具体行政行为依法通过公告形式告知受送达人的，自公告规定的期限届满之日起计算。 （五）税务机关作出具体行政行为时未告知申请人，事后补充告知的，自该申请人收到税务机关补充告知的通知之日起计算。 （六）被申请人能够证明申请人知道具体行政行为的，自证据材料证明其知道具体行政行为之日起计算。 税务机关作出具体行政行为,依法应当向申请人送达法律文书而未送达的，视为该申请人不知道该具体行政行为。"},{"i":36,"n":"第三十六条","txt":"申请人依照行政复议法第六条第（八）项、第（九）项、第（十）项的规定申请税务机关履行法定职责，税务机关未履行的，行政复议申请期限依照下列规定计算： （一）有履行期限规定的，自履行期限届满之日起计算。 （二）没有履行期限规定的，自税务机关收到申请满60日起计算。"},{"i":37,"n":"第三十七条","txt":"税务机关作出的具体行政行为对申请人的权利、义务可能产生不利影响的，应当告知其申请行政复议的权利、行政复议机关和行政复议申请期限。"},{"i":38,"n":"第三十八条","txt":"申请人书面申请行政复议的，可以采取当面递交、邮寄或者传真等方式提出行政复议申请。 有条件的行政复议机关可以接受以电子邮件形式提出的行政复议申请。 对以传真、电子邮件形式提出行政复议申请的，行政复议机关应当审核确认申请人的身份、复议事项。"},{"i":39,"n":"第三十九条","txt":"申请人书面申请行政复议的，应当在行政复议申请书中载明下列事项： （一）申请人的基本情况，包括公民的姓名、性别、出生年月、身份证件号码、工作单位、住所、邮政编码、联系电话；法人或者其他组织的名称、住所、邮政编码、联系电话和法定代表人或者主要负责人的姓名、职务。 （二）被申请人的名称。 （三）行政复议请求、申请行政复议的主要事实和理由。 （四）申请人的签名或者盖章。 （五）申请行政复议的日期。"},{"i":40,"n":"第四十条","txt":"申请人口头申请行政复议的，行政复议机构应当依照本规则第三十九条规定的事项，当场制作行政复议申请笔录，交申请人核对或者向申请人宣读，并由申请人确认。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，申请人应当提供证明材料： （一）认为被申请人不履行法定职责的，提供要求被申请人履行法定职责而被申请人未履行的证明材料。 （二）申请行政复议时一并提出行政赔偿请求的，提供受具体行政行为侵害而造成损害的证明材料。 （三）法律、法规规定需要申请人提供证据材料的其他情形。"},{"i":42,"n":"第四十二条","txt":"申请人提出行政复议申请时错列被申请人的，行政复议机关应当告知申请人变更被申请人。申请人不变更被申请人的，行政复议机关不予受理，或者驳回行政复议申请。"},{"i":43,"n":"第四十三条","txt":"申请人向行政复议机关申请行政复议，行政复议机关已经受理的，在法定行政复议期限内申请人不得向人民法院提起行政诉讼；申请人向人民法院提起行政诉讼，人民法院已经依法受理的，不得申请行政复议。"},{"i":44,"n":"第四十四条","txt":"行政复议申请符合下列规定的，行政复议机关应当受理： （一）属于本规则规定的行政复议范围。 （二）在法定申请期限内提出。 （三）有明确的申请人和符合规定的被申请人。 （四）申请人与具体行政行为有利害关系。 （五）有具体的行政复议请求和理由。 （六）符合本规则第三十三条和第三十四条规定的条件。 （七）属于收到行政复议申请的行政复议机关的职责范围。 （八）其他行政复议机关尚未受理同一行政复议申请，人民法院尚未受理同一主体就同一事实提起的行政诉讼。"},{"i":45,"n":"第四十五条","txt":"行政复议机关收到行政复议申请以后，应当在5日内审查，决定是否受理。对不符合本规则规定的行政复议申请，决定不予受理，并书面告知申请人。 对不属于本机关受理的行政复议申请，应当告知申请人向有关行政复议机关提出。 行政复议机关收到行政复议申请以后未按照前款规定期限审查并作出不予受理决定的，视为受理。"},{"i":46,"n":"第四十六条","txt":"对符合规定的行政复议申请，自行政复议机构收到之日起即为受理；受理行政复议申请，应当书面告知申请人。"},{"i":47,"n":"第四十七条","txt":"行政复议申请材料不齐全、表述不清楚的，行政复议机构可以自收到该行政复议申请之日起5日内书面通知申请人补正。补正通知应当载明需要补正的事项和合理的补正期限。无正当理由逾期不补正的，视为申请人放弃行政复议申请。 补正申请材料所用时间不计入行政复议审理期限。"},{"i":48,"n":"第四十八条","txt":"上级税务机关认为行政复议机关不予受理行政复议申请的理由不成立的，可以督促其受理；经督促仍然不受理的，责令其限期受理。 上级税务机关认为行政复议申请不符合法定受理条件的，应当告知申请人。"},{"i":49,"n":"第四十九条","txt":"上级税务机关认为有必要的，可以直接受理或者提审由下级税务机关管辖的行政复议案件。"},{"i":50,"n":"第五十条","txt":"对应当先向行政复议机关申请行政复议，对行政复议决定不服再向人民法院提起行政诉讼的具体行政行为，行政复议机关决定不予受理或者受理以后超过行政复议期限不作答复的，申请人可以自收到不予受理决定书之日起或者行政复议期满之日起15日内，依法向人民法院提起行政诉讼。 依照本规则第八十三条规定延长行政复议期限的，以延长以后的时间为行政复议期满时间。"},{"i":51,"n":"第五十一条","txt":"行政复议期间具体行政行为不停止执行；但是有下列情形之一的，可以停止执行： （一）被申请人认为需要停止执行的。 （二）行政复议机关认为需要停止执行的。 （三）申请人申请停止执行，行政复议机关认为其要求合理，决定停止执行的。 （四）法律规定停止执行的。"},{"i":52,"n":"第五十二条","txt":"行政复议证据包括以下类别： （一）书证； （二）物证； （三）视听资料； （四）电子数据； （五）证人证言； （六）当事人的陈述； （七）鉴定意见； （八）勘验笔录、现场笔录。"},{"i":53,"n":"第五十三条","txt":"在行政复议中，被申请人对其作出的具体行政行为负有举证责任。"},{"i":54,"n":"第五十四条","txt":"行政复议机关应当依法全面审查相关证据。行政复议机关审查行政复议案件，应当以证据证明的案件事实为依据。定案证据应当具有合法性、真实性和关联性。"},{"i":55,"n":"第五十五条","txt":"行政复议机关应当根据案件的具体情况，从以下方面审查证据的合法性： （一）证据是否符合法定形式。 （二）证据的取得是否符合法律、法规、规章和司法解释的规定。 （三）是否有影响证据效力的其他违法情形。"},{"i":56,"n":"第五十六条","txt":"行政复议机关应当根据案件的具体情况，从以下方面审查证据的真实性： （一）证据形成的原因。 （二）发现证据时的环境。 （三）证据是否为原件、原物，复制件、复制品与原件、原物是否相符。 （四）提供证据的人或者证人与行政复议参加人是否具有利害关系。 （五）影响证据真实性的其他因素。"},{"i":57,"n":"第五十七条","txt":"行政复议机关应当根据案件的具体情况，从以下方面审查证据的关联性： （一）证据与待证事实是否具有证明关系。 （二）证据与待证事实的关联程度。 （三）影响证据关联性的其他因素。"},{"i":58,"n":"第五十八条","txt":"下列证据材料不得作为定案依据： （一）违反法定程序收集的证据材料。 （二）以偷拍、偷录和窃听等手段获取侵害他人合法权益的证据材料。 （三）以利诱、欺诈、胁迫和暴力等不正当手段获取的证据材料。 （四）无正当事由超出举证期限提供的证据材料。 （五）无正当理由拒不提供原件、原物，又无其他证据印证，且对方不予认可的证据的复制件、复制品。 （六）无法辨明真伪的证据材料。 （七）不能正确表达意志的证人提供的证言。 （八）不具备合法性、真实性的其他证据材料。 行政复议机构依据本规则第十一条第（二）项规定的职责所取得的有关材料，不得作为支持被申请人具体行政行为的证据。"},{"i":59,"n":"第五十九条","txt":"在行政复议过程中，被申请人不得自行向申请人和其他有关组织或者个人收集证据。"},{"i":60,"n":"第六十条","txt":"行政复议机构认为必要时，可以调查取证。 行政复议工作人员向有关组织和人员调查取证时，可以查阅、复制和调取有关文件和资料，向有关人员询问。调查取证时，行政复议工作人员不得少于2人，并应当向当事人和有关人员出示证件。被调查单位和人员应当配合行政复议工作人员的工作，不得拒绝、阻挠。 需要现场勘验的，现场勘验所用时间不计入行政复议审理期限。"},{"i":61,"n":"第六十一条","txt":"申请人和第三人可以查阅被申请人提出的书面答复、作出具体行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密或者个人隐私外，行政复议机关不得拒绝。"},{"i":62,"n":"第六十二条","txt":"行政复议机构应当自受理行政复议申请之日起7日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到申请书副本或者申请笔录复印件之日起10日内提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。 对国家税务总局的具体行政行为不服申请行政复议的案件，由原承办具体行政行为的相关机构向行政复议机构提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。"},{"i":63,"n":"第六十三条","txt":"行政复议机构审理行政复议案件，应当由2名以上行政复议工作人员参加。"},{"i":64,"n":"第六十四条","txt":"行政复议原则上采用书面审查的办法，但是申请人提出要求或者行政复议机构认为有必要时，应当听取申请人、被申请人和第三人的意见，并可以向有关组织和人员调查了解情况。"},{"i":65,"n":"第六十五条","txt":"对重大、复杂的案件，申请人提出要求或者行政复议机构认为必要时，可以采取听证的方式审理。"},{"i":66,"n":"第六十六条","txt":"行政复议机构决定举行听证的，应当将举行听证的时间、地点和具体要求等事项通知申请人、被申请人和第三人。 第三人不参加听证的，不影响听证的举行。"},{"i":67,"n":"第六十七条","txt":"听证应当公开举行，但是涉及国家秘密、商业秘密或者个人隐私的除外。"},{"i":68,"n":"第六十八条","txt":"行政复议听证人员不得少于2人，听证主持人由行政复议机构指定。"},{"i":69,"n":"第六十九条","txt":"听证应当制作笔录。申请人、被申请人和第三人应当确认听证笔录内容。 行政复议听证笔录应当附卷，作为行政复议机构审理案件的依据之一。"},{"i":70,"n":"第七十条","txt":"行政复议机关应当全面审查被申请人的具体行政行为所依据的事实证据、法律程序、法律依据和设定的权利义务内容的合法性、适当性。"},{"i":71,"n":"第七十一条","txt":"申请人在行政复议决定作出以前撤回行政复议申请的，经行政复议机构同意，可以撤回。 申请人撤回行政复议申请的，不得再以同一事实和理由提出行政复议申请。但是，申请人能够证明撤回行政复议申请违背其真实意思表示的除外。"},{"i":72,"n":"第七十二条","txt":"行政复议期间被申请人改变原具体行政行为的，不影响行政复议案件的审理。但是，申请人依法撤回行政复议申请的除外。"},{"i":73,"n":"第七十三条","txt":"申请人在申请行政复议时，依据本规则第十五条规定一并提出对有关规定的审查申请的，行政复议机关对该规定有权处理的，应当在30日内依法处理；无权处理的，应当在7日内按照法定程序逐级转送有权处理的行政机关依法处理，有权处理的行政机关应当在60日内依法处理。处理期间，中止对具体行政行为的审查。"},{"i":74,"n":"第七十四条","txt":"行政复议机关审查被申请人的具体行政行为时，认为其依据不合法，本机关有权处理的，应当在30日内依法处理；无权处理的，应当在7日内按照法定程序逐级转送有权处理的国家机关依法处理。处理期间，中止对具体行政行为的审查。"},{"i":75,"n":"第七十五条","txt":"行政复议机构应当对被申请人的具体行政行为提出审查意见，经行政复议机关负责人批准，按照下列规定作出行政复议决定： （一）具体行政行为认定事实清楚，证据确凿，适用依据正确，程序合法，内容适当的，决定维持。 （二）被申请人不履行法定职责的，决定其在一定期限内履行。 （三）具体行政行为有下列情形之一的，决定撤销、变更或者确认该具体行政行为违法；决定撤销或者确认该具体行政行为违法的，可以责令被申请人在一定期限内重新作出具体行政行为： 1.主要事实不清、证据不足的； 2.适用依据错误的； 3.违反法定程序的； 4.超越职权或者滥用职权的； 5.具体行政行为明显不当的。 （四）被申请人不按照本规则第六十二条的规定提出书面答复，提交当初作出具体行政行为的证据、依据和其他有关材料的，视为该具体行政行为没有证据、依据，决定撤销该具体行政行为。"},{"i":76,"n":"第七十六条","txt":"行政复议机关责令被申请人重新作出具体行政行为的，被申请人不得以同一事实和理由作出与原具体行政行为相同或者基本相同的具体行政行为；但是行政复议机关以原具体行政行为违反法定程序决定撤销的，被申请人重新作出具体行政行为的除外。 行政复议机关责令被申请人重新作出具体行政行为的，被申请人不得作出对申请人更为不利的决定；但是行政复议机关以原具体行政行为主要事实不清、证据不足或适用依据错误决定撤销的，被申请人重新作出具体行政行为的除外。"},{"i":77,"n":"第七十七条","txt":"有下列情形之一的，行政复议机关可以决定变更： （一）认定事实清楚，证据确凿，程序合法，但是明显不当或者适用依据错误的。 （二）认定事实不清，证据不足，但是经行政复议机关审理查明事实清楚，证据确凿的。"},{"i":78,"n":"第七十八条","txt":"有下列情形之一的，行政复议机关应当决定驳回行政复议申请： （一）申请人认为税务机关不履行法定职责申请行政复议，行政复议机关受理以后发现该税务机关没有相应法定职责或者在受理以前已经履行法定职责的。 （二）受理行政复议申请后，发现该行政复议申请不符合行政复议法及其实施条例和本规则规定的受理条件的。 上级税务机关认为行政复议机关驳回行政复议申请的理由不成立的，应当责令限期恢复受理。行政复议机关审理行政复议申请期限的计算应当扣除因驳回耽误的时间。"},{"i":79,"n":"第七十九条","txt":"行政复议期间，有下列情形之一的，行政复议中止： （一）作为申请人的公民死亡，其近亲属尚未确定是否参加行政复议的。 （二）作为申请人的公民丧失参加行政复议的能力，尚未确定法定代理人参加行政复议的。 （三）作为申请人的法人或者其他组织终止，尚未确定权利义务承受人的。 （四）作为申请人的公民下落不明或者被宣告失踪的。 （五）申请人、被申请人因不可抗力，不能参加行政复议的。 （六）行政复议机关因不可抗力原因暂时不能履行工作职责的。 （七）案件涉及法律适用问题，需要有权机关作出解释或者确认的。 （八）案件审理需要以其他案件的审理结果为依据，而其他案件尚未审结的。 （九）其他需要中止行政复议的情形。 行政复议中止的原因消除以后，应当及时恢复行政复议案件的审理。 行政复议机构中止、恢复行政复议案件的审理，应当告知申请人、被申请人、第三人。"},{"i":80,"n":"第八十条","txt":"行政复议期间，有下列情形之一的，行政复议终止： （一）申请人要求撤回行政复议申请，行政复议机构准予撤回的。 （二）作为申请人的公民死亡，没有近亲属，或者其近亲属放弃行政复议权利的。 （三）作为申请人的法人或者其他组织终止，其权利义务的承受人放弃行政复议权利的。 （四）申请人与被申请人依照本规则第八十七条的规定，经行政复议机构准许达成和解的。 （五）行政复议申请受理以后，发现其他行政复议机关已经先于本机关受理，或者人民法院已经受理的。 依照本规则第七十九条第一款第（一）项、第（二）项、第（三）项规定中止行政复议，满60日行政复议中止的原因未消除的，行政复议终止。"},{"i":81,"n":"第八十一条","txt":"行政复议机关责令被申请人重新作出具体行政行为的，被申请人应当在60日内重新作出具体行政行为；情况复杂，不能在规定期限内重新作出具体行政行为的，经行政复议机关批准，可以适当延期，但是延期不得超过30日。 公民、法人或者其他组织对被申请人重新作出的具体行政行为不服，可以依法申请行政复议，或者提起行政诉讼。"},{"i":82,"n":"第八十二条","txt":"申请人在申请行政复议时可以一并提出行政赔偿请求，行政复议机关对符合国家赔偿法的规定应当赔偿的，在决定撤销、变更具体行政行为或者确认具体行政行为违法时，应当同时决定被申请人依法赔偿。 申请人在申请行政复议时没有提出行政赔偿请求的，行政复议机关在依法决定撤销、变更原具体行政行为确定的税款、滞纳金、罚款和对财产的扣押、查封等强制措施时，应当同时责令被申请人退还税款、滞纳金和罚款，解除对财产的扣押、查封等强制措施，或者赔偿相应的价款。"},{"i":83,"n":"第八十三条","txt":"行政复议机关应当自受理申请之日起60日内作出行政复议决定。情况复杂，不能在规定期限内作出行政复议决定的，经行政复议机关负责人批准，可以适当延期，并告知申请人和被申请人；但是延期不得超过30日。 行政复议机关作出行政复议决定，应当制作行政复议决定书，并加盖行政复议机关印章。 行政复议决定书一经送达，即发生法律效力。"},{"i":84,"n":"第八十四条","txt":"被申请人应当履行行政复议决定。 被申请人不履行、无正当理由拖延履行行政复议决定的，行政复议机关或者有关上级税务机关应当责令其限期履行。"},{"i":85,"n":"第八十五条","txt":"申请人、第三人逾期不起诉又不履行行政复议决定的，或者不履行最终裁决的行政复议决定的，按照下列规定分别处理： （一）维持具体行政行为的行政复议决定，由作出具体行政行为的税务机关依法强制执行，或者申请人民法院强制执行。 （二）变更具体行政行为的行政复议决定，由行政复议机关依法强制执行，或者申请人民法院强制执行。"},{"i":86,"n":"第八十六条","txt":"对下列行政复议事项，按照自愿、合法的原则，申请人和被申请人在行政复议机关作出行政复议决定以前可以达成和解，行政复议机关也可以调解： （一）行使自由裁量权作出的具体行政行为，如行政处罚、核定税额、确定应税所得率等。 （二）行政赔偿。 （三）行政奖励。 （四）存在其他合理性问题的具体行政行为。 行政复议审理期限在和解、调解期间中止计算。"},{"i":87,"n":"第八十七条","txt":"申请人和被申请人达成和解的，应当向行政复议机构提交书面和解协议。和解内容不损害社会公共利益和他人合法权益的，行政复议机构应当准许。"},{"i":88,"n":"第八十八条","txt":"经行政复议机构准许和解终止行政复议的，申请人不得以同一事实和理由再次申请行政复议。"},{"i":89,"n":"第八十九条","txt":"调解应当符合下列要求： （一）尊重申请人和被申请人的意愿。 （二）在查明案件事实的基础上进行。 （三）遵循客观、公正和合理原则。 （四）不得损害社会公共利益和他人合法权益。"},{"i":90,"n":"第九十条","txt":"行政复议机关按照下列程序调解： （一）征得申请人和被申请人同意。 （二）听取申请人和被申请人的意见。 （三）提出调解方案。 （四）达成调解协议。 （五）制作行政复议调解书。"},{"i":91,"n":"第九十一条","txt":"行政复议调解书应当载明行政复议请求、事实、理由和调解结果，并加盖行政复议机关印章。行政复议调解书经双方当事人签字，即具有法律效力。 调解未达成协议，或者行政复议调解书不生效的，行政复议机关应当及时作出行政复议决定。"},{"i":92,"n":"第九十二条","txt":"申请人不履行行政复议调解书的，由被申请人依法强制执行，或者申请人民法院强制执行。"},{"i":93,"n":"第九十三条","txt":"各级税务复议机关应当加强对履行行政复议职责的监督。行政复议机构负责对行政复议工作进行系统督促、指导。"},{"i":94,"n":"第九十四条","txt":"各级税务机关应当建立健全行政复议工作责任制，将行政复议工作纳入本单位目标责任制。"},{"i":95,"n":"第九十五条","txt":"各级税务机关应当按照职责权限，通过定期组织检查、抽查等方式，检查下级税务机关的行政复议工作，并及时向有关方面反馈检查结果。"},{"i":96,"n":"第九十六条","txt":"行政复议期间行政复议机关发现被申请人和其他下级税务机关的相关行政行为违法或者需要做好善后工作的，可以制作行政复议意见书。有关机关应当自收到行政复议意见书之日起60日内将纠正相关行政违法行为或者做好善后工作的情况报告行政复议机关。 行政复议期间行政复议机构发现法律、法规和规章实施中带有普遍性的问题，可以制作行政复议建议书，向有关机关提出完善制度和改进行政执法的建议。"},{"i":97,"n":"第九十七条","txt":"省以下各级税务机关应当定期向上一级税务机关提交行政复议、应诉、赔偿统计表和分析报告，及时将重大行政复议决定报上一级行政复议机关备案。"},{"i":98,"n":"第九十八条","txt":"行政复议机构应当按照规定将行政复议案件资料立卷归档。 行政复议案卷应当按照行政复议申请分别装订立卷，一案一卷，统一编号，做到目录清晰、资料齐全、分类规范、装订整齐。"},{"i":99,"n":"第九十九条","txt":"行政复议机构应当定期组织行政复议工作人员业务培训和工作交流，提高行政复议工作人员的专业素质。"},{"i":100,"n":"第一百条","txt":"行政复议机关应当定期总结行政复议工作。对行政复议工作中做出显著成绩的单位和个人，依照有关规定表彰和奖励。"},{"i":101,"n":"第一百零一条","txt":"行政复议机关、行政复议机关工作人员和被申请人在税务行政复议活动中，违反行政复议法及其实施条例和本规则规定的，应当依法处理。"},{"i":102,"n":"第一百零二条","txt":"外国人、无国籍人、外国组织在中华人民共和国境内向税务机关申请行政复议，适用本规则。"},{"i":103,"n":"第一百零三条","txt":"行政复议机关在行政复议工作中可以使用行政复议专用章。行政复议专用章与行政复议机关印章在行政复议中具有同等效力。"},{"i":104,"n":"第一百零四条","txt":"行政复议期间的计算和行政复议文书的送达，依照民事诉讼法关于期间、送达的规定执行。 本规则关于行政复议期间有关“5日”、“7日”的规定指工作日，不包括法定节假日。"},{"i":105,"n":"第一百零五条","txt":"本规则自2010年4月1日起施行，2004年2月24日国家税务总局公布的《税务行政复议规则（暂行）》（国家税务总局令第8号）同时废止。"}],"shuiwuguifanxingwenjianzhidingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范税务规范性文件制定和管理工作，落实税收法定原则，建设规范统一的税收法律制度体系，优化税务执法方式，促进税务机关依法行政，保障税务行政相对人的合法权益，根据《中华人民共和国立法法》《规章制定程序条例》等法律法规和有关规定，结合税务机关工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称税务规范性文件，是指县以上税务机关依照法定职权和规定程序制定并发布的，影响纳税人、缴费人、扣缴义务人等税务行政相对人权利、义务，在本辖区内具有普遍约束力并在一定期限内反复适用的文件。 国家税务总局制定的税务部门规章，不属于本办法所称的税务规范性文件。"},{"i":3,"n":"第三条","txt":"税务规范性文件的起草、审查、决定、发布、备案、清理等工作，适用本办法。"},{"i":4,"n":"第四条","txt":"制定税务规范性文件，应当充分体现社会主义核心价值观的内容和要求，坚持科学、民主、公开、统一的原则，符合法律、法规、规章以及上级税务规范性文件的规定，遵循本办法规定的制定规则和制定程序。"},{"i":5,"n":"第五条","txt":"税务规范性文件不得设定税收开征、停征、减税、免税、退税、补税事项，不得设定行政许可、行政处罚、行政强制、行政事业性收费以及其他不得由税务规范性文件设定的事项。"},{"i":6,"n":"第六条","txt":"县税务机关制定税务规范性文件，应当依据法律、法规、规章或者省以上税务机关税务规范性文件的明确授权；没有授权又确需制定税务规范性文件的，应当提请上一级税务机关制定。 各级税务机关的内设机构、派出机构和临时性机构，不得以自己的名义制定税务规范性文件。"},{"i":7,"n":"第七条","txt":"税务规范性文件可以使用“办法”“规定”“规程”“规则”等名称，但是不得称“条例”“实施细则”“通知”“批复”等。 上级税务机关对下级税务机关有关特定税务行政相对人的特定事项如何适用法律、法规、规章或者税务规范性文件的请示所作的批复，需要普遍适用的，应当按照本办法规定的制定规则和制定程序另行制定税务规范性文件。"},{"i":8,"n":"第八条","txt":"税务规范性文件应当根据需要，明确制定目的和依据、适用范围和主体、权利义务、具体规范、操作程序、施行日期或者有效期限等事项。"},{"i":9,"n":"第九条","txt":"制定税务规范性文件，应当做到内容具体、明确，内在逻辑严密，语言规范、简洁、准确，避免产生歧义，具有可操作性。"},{"i":10,"n":"第十条","txt":"税务规范性文件可以采用条文式或者段落式表述。 采用条文式表述的税务规范性文件，需要分章、节、条、款、项、目的，章、节应当有标题，章、节、条的序号用中文数字依次表述；款不编序号；项的序号用中文数字加括号依次表述；目的序号用阿拉伯数字依次表述。"},{"i":11,"n":"第十一条","txt":"上级税务机关需要下级税务机关对规章和税务规范性文件细化具体操作规定的，可以授权下级税务机关制定具体的实施办法。 被授权税务机关不得将被授予的权力转授给其他机关。"},{"i":12,"n":"第十二条","txt":"税务规范性文件由制定机关负责解释。制定机关不得将税务规范性文件的解释权授予本级机关的内设机构或者下级税务机关。 税务规范性文件有下列情形之一的，制定机关应当及时作出解释： （一）税务规范性文件的规定需要进一步明确具体含义的； （二）税务规范性文件制定后出现新的情况，需要明确适用依据的。 下级税务机关在适用上级税务机关制定的税务规范性文件时认为存在本条第二款规定情形之一的，应当提请制定机关解释。"},{"i":13,"n":"第十三条","txt":"税务规范性文件不得溯及既往，但是为了更好地保护税务行政相对人权利和利益而作出的特别规定除外。"},{"i":14,"n":"第十四条","txt":"税务规范性文件应当自发布之日起30日后施行。 税务规范性文件发布后不立即施行将有碍执行的，可以自发布之日起施行。 与法律、法规、规章或者上级机关决定配套实施的税务规范性文件，其施行日期需要与前述文件保持一致的，不受本条第一款、第二款时限规定的限制。"},{"i":15,"n":"第十五条","txt":"税务规范性文件由制定机关业务主管部门负责起草。内容涉及两个或者两个以上部门的，由制定机关负责人指定牵头起草部门。"},{"i":16,"n":"第十六条","txt":"各级税务机关从事纳税服务和政策法规工作的部门或者人员（以下统称纳税服务部门、政策法规部门）负责对税务规范性文件进行审查，包括权益性审核、合法性审核、世界贸易组织规则合规性评估。其中纳税服务部门负责权益性审核；政策法规部门负责合法性审核和世界贸易组织规则合规性评估。 未经纳税服务部门和政策法规部门审查的税务规范性文件，办公厅（室）不予核稿，制定机关负责人不予签发。"},{"i":17,"n":"第十七条","txt":"起草税务规范性文件，起草部门应当深入调查研究，总结实践经验，听取基层税务机关意见。起草与税务行政相对人生产经营密切相关的税务规范性文件，起草部门应当听取税务行政相对人代表和行业协会商会的意见。起草部门可以邀请纳税服务部门和政策法规部门共同听取意见。 听取意见可以采取书面、网络征求意见，或者召开座谈会、论证会等多种形式。 除依法需要保密的外，对涉及税务行政相对人切身利益或者对其权利义务可能产生重大影响的税务规范性文件，起草部门应当向社会公开征求意见。 法律、行政法规对规范性文件公开征求意见期限有明确规定的，从其规定。"},{"i":18,"n":"第十八条","txt":"起草税务规范性文件，应当明确列举拟清理文件的名称、文号以及条款，避免与本机关已发布的税务规范性文件相矛盾。 同一事项已由多个税务规范性文件作出规定的，起草部门在起草同类文件时，应当对有关文件进行归并、整合。"},{"i":19,"n":"第十九条","txt":"税务规范性文件送审稿应当由起草部门负责人签署后，依次送交纳税服务部门和政策法规部门审查。 送审稿内容涉及征管业务及其工作流程的，应当于送交审查前会签征管科技部门；涉及其他业务主管部门工作的，应当于送交审查前会签相关业务主管部门；未按规定会签的，纳税服务部门和政策法规部门不予审查。 起草部门认定送审稿属于重要文件的，应当注明“请主要负责人会签”。"},{"i":20,"n":"第二十条","txt":"起草部门将送审稿送交审查时，应当一并提供下列材料： （一）起草说明，包括制定目的、制定依据、必要性与可行性、起草过程、征求意见以及采纳情况、对税务行政相对人权利和利益可能产生影响的评估情况、施行日期的说明、相关文件衔接处理情况以及其他需要说明的事项； （二）税务规范性文件解读稿，包括文件出台的背景、意义，文件内容的重点、理解的难点、必要的举例说明和落实的措施要求等； （三）作为制定依据的法律、法规、规章以及税务规范性文件纸质或者电子文本； （四）会签单位意见以及采纳情况； （五）其他相关材料。 按照规定应当对送审稿进行公平竞争审查的，起草部门应当提供相关审查材料。"},{"i":21,"n":"第二十一条","txt":"制定内容简单的税务规范性文件，起草部门在征求意见、提供材料等方面可以从简适用本办法第十七条、第二十条的规定。 从简适用第二十条的，不得缺少起草说明和税务规范性文件解读稿。"},{"i":22,"n":"第二十二条","txt":"纳税服务部门应当就下列事项进行权益性审核： （一）是否无法律法规依据减损税务行政相对人的合法权利和利益，或者增加其义务，主要涉及业务办理环节、报送资料、管理事项等方面； （二）是否存在泄露税务行政相对人税费保密信息风险。 对审核中发现的明显不适当的规定，纳税服务部门可以提出删除或者修改的建议。 纳税服务部门审核过程中认为有必要的，可以通过召开座谈会、论证会等形式听取相关各方意见。"},{"i":23,"n":"第二十三条","txt":"纳税服务部门进行权益性审核，根据不同情况提出审核意见： （一）认为送审稿不存在无法律法规依据减损税务行政相对人权益或者增加其负担的情形的，提出审核通过意见； （二）认为送审稿减损税务行政相对人权益或者增加其负担的理由不充分，经协商不能达成一致意见的，提出书面审核意见并退回起草部门。"},{"i":24,"n":"第二十四条","txt":"政策法规部门应当就下列事项进行合法性审核： （一）是否超越法定权限； （二）是否具有法定依据； （三）是否违反法律、法规、规章以及上级税务机关税务规范性文件的规定； （四）是否设定行政许可、行政处罚、行政强制、行政事业性收费以及其他不得由税务规范性文件设定的事项； （五）是否违法、违规减损税务行政相对人的合法权利和利益，或者违法、违规增加其义务； （六）是否违反本办法规定的制定规则或者程序； （七）是否与本机关制定的其他税务规范性文件进行衔接。 对审核中发现的明显不适当的规定，政策法规部门可以提出删除或者修改的建议。 政策法规部门审核过程中认为有必要的，可以通过召开座谈会、论证会等形式听取相关各方意见。"},{"i":25,"n":"第二十五条","txt":"政策法规部门进行合法性审核，根据不同情况提出审核意见： （一）认为送审稿没有问题或者经过协商达成一致意见的，提出审核通过意见； （二）认为起草部门应当补充征求意见，或者对重大分歧意见没有合理说明的，退回起草部门补充征求意见或者作出进一步说明； （三）认为送审稿存在问题，经协商不能达成一致意见的，提出书面审核意见后，退回起草部门。"},{"i":26,"n":"第二十六条","txt":"政策法规部门应当根据世界贸易组织规则对送审稿进行合规性评估，并提出评估意见。"},{"i":27,"n":"第二十七条","txt":"送审稿经纳税服务部门和政策法规部门审查通过的，按公文处理程序报制定机关负责人签发。"},{"i":28,"n":"第二十八条","txt":"送审稿涉及重大公共利益或者对税务行政相对人合法权益、税务管理产生重大影响的，经纳税服务部门和政策法规部门审查通过后，起草部门应当提请集体审议。纳税服务部门或者政策法规部门在审查时，认为税务规范性文件涉及重大公共利益或者对税务行政相对人合法权益、税务管理产生重大影响的，可以建议起草部门提请集体审议。"},{"i":29,"n":"第二十九条","txt":"税务机关牵头与其他机关联合制定规范性文件，省以下税务机关代地方人大及其常委会、政府起草涉及税务行政相对人权利义务的文件，业务主管部门应当将文件送审稿或者会签文本送交纳税服务部门和政策法规部门审查。 经其他机关会签后，文件内容有实质性变动的，起草部门应当重新送交纳税服务部门和政策法规部门审查。 其他机关牵头与税务机关联合制定的规范性文件，参照本条第一款规定执行。"},{"i":30,"n":"第三十条","txt":"税务规范性文件应当以公告形式发布；未以公告形式发布的，不得作为税务机关执法依据。"},{"i":31,"n":"第三十一条","txt":"制定机关应当及时在本级政府公报、税务部门公报、本辖区范围内公开发行的报纸或者在政府网站、税务机关网站上刊登税务规范性文件。 不具备本条第一款所述发布条件的税务机关，应当通过公告栏或者宣传材料等形式，在办税服务厅等公共场所及时发布税务规范性文件。"},{"i":32,"n":"第三十二条","txt":"制定机关的起草部门、纳税服务部门和政策法规部门应当及时跟踪了解税务规范性文件的施行情况。 对实施机关或者税务行政相对人反映存在问题的税务规范性文件，制定机关应当进行认真分析评估，并及时研究提出处理意见。"},{"i":33,"n":"第三十三条","txt":"税务规范性文件应当备案审查，实行有件必备、有备必审、有错必纠。"},{"i":34,"n":"第三十四条","txt":"省以下税务机关的税务规范性文件应当自发布之日起30日内向上一级税务机关报送备案。 省税务机关应当于每年3月1日前向国家税务总局报送上一年度本辖区内税务机关发布的税务规范性文件目录。"},{"i":35,"n":"第三十五条","txt":"报送税务规范性文件备案，应当提交备案报告和以下材料的电子文本： （一）税务规范性文件备案报告表； （二）税务规范性文件； （三）起草说明； （四）税务规范性文件解读稿。"},{"i":36,"n":"第三十六条","txt":"上一级税务机关的政策法规部门具体负责税务规范性文件备案登记、合法性审核和世界贸易组织规则合规性评估，会同纳税服务部门负责督促整改和考核工作；纳税服务部门负责税务规范性文件权益性审核工作；业务主管部门承担其职能范围内的税务规范性文件审查工作，并按照规定时限向政策法规部门送交审查意见。"},{"i":37,"n":"第三十七条","txt":"报送备案的税务规范性文件资料齐全的，上一级税务机关政策法规部门予以备案登记；资料不齐全的，通知制定机关限期补充报送。"},{"i":38,"n":"第三十八条","txt":"上一级税务机关对报送备案的税务规范性文件进行审查时，可以征求相关部门意见；需要了解相关情况的，可以要求制定机关提交情况说明或者补充材料。"},{"i":39,"n":"第三十九条","txt":"上一级税务机关对报送备案的税务规范性文件，应当就本办法第二十二条、第二十四条所列事项以及是否符合世界贸易组织规则进行审查。"},{"i":40,"n":"第四十条","txt":"上一级税务机关审查发现报送备案的税务规范性文件存在问题需要纠正或者补正的，应当通知制定机关在规定的时限内纠正或者补正。 制定机关应当按期纠正或者补正，并于规定时限届满之日起30日内，将处理情况报告上一级税务机关。"},{"i":41,"n":"第四十一条","txt":"对未报送备案或者不按时报送备案的，上一级税务机关应当要求制定机关限期报送；逾期仍不报送的，予以通报，并责令限期改正。"},{"i":42,"n":"第四十二条","txt":"税务行政相对人认为税务规范性文件违反法律、法规、规章或者上级税务规范性文件规定的，可以向制定机关或者其上一级税务机关书面提出审查的建议，制定机关或者其上一级税务机关应当依法及时研究处理。 有税务规范性文件制定权的税务机关应当建立书面审查建议的处理制度和工作机制。"},{"i":43,"n":"第四十三条","txt":"制定机关应当及时对税务规范性文件进行清理，形成文件清理长效机制。 清理采取日常清理和集中清理相结合的方法。"},{"i":44,"n":"第四十四条","txt":"日常清理由业务主管部门负责。 业务主管部门应当根据立法变化以及税务工作发展需要，对税务规范性文件进行及时清理。"},{"i":45,"n":"第四十五条","txt":"有下列情形之一的，制定机关应当进行集中清理： （一）上级机关部署的； （二）新的法律、法规颁布或者法律、法规进行重大修改，对税务执法产生普遍影响的。"},{"i":46,"n":"第四十六条","txt":"集中清理由政策法规部门负责牵头组织，业务主管部门分工负责。 业务主管部门应当在规定期限内列出需要清理的税务规范性文件目录，并提出清理意见；政策法规部门应当对业务主管部门提出的文件目录以及清理意见进行汇总、审查后，提请集体讨论决定。 清理过程中，业务主管部门和政策法规部门应当听取有关各方意见。"},{"i":47,"n":"第四十七条","txt":"对清理中发现存在问题的税务规范性文件，制定机关应当分类处理： （一）有下列情形之一的，宣布失效： 1.调整对象灭失； 2.不需要继续执行的。 （二）有下列情形之一的，宣布废止： 1.违反上位法规定的； 2.已被新的规定替代的； 3.明显不适应现实需要的。 （三）有下列情形之一的，予以修改： 1.与本机关税务规范性文件相矛盾的； 2.与本机关税务规范性文件相重复的； 3.存在漏洞或者难以执行的。 税务规范性文件部分内容被修改的，应当全文发布修改后的税务规范性文件。"},{"i":48,"n":"第四十八条","txt":"制定机关应当及时发布日常清理结果；在集中清理结束后，应当统一发布失效、废止的税务规范性文件目录。 上级税务机关发布清理结果后，下级税务机关应当及时对本机关制定的税务规范性文件相应进行清理。"},{"i":49,"n":"第四十九条","txt":"税务规范性文件的解释、修改或者废止，参照本办法的有关规定执行。"},{"i":50,"n":"第五十条","txt":"各级税务机关在税务规范性文件制定管理过程中，应当充分发挥公职律师的作用。 各级税务机关负有督察内审职责的部门应当加强对税务规范性文件制定管理工作的监督。"},{"i":51,"n":"第五十一条","txt":"税务规范性文件合规性评估的具体实施办法由国家税务总局另行制定。"},{"i":52,"n":"第五十二条","txt":"本办法自2017年7月1日起施行。《税收规范性文件制定管理办法》（国家税务总局令第20号公布）同时废止。"}],"shuiwubumenguizhangzhidingshishibanfa":[{"i":1,"n":"第二条","txt":"国家税务总局根据法律和国务院的行政法规、决定、命令，在权限范围内制定对税务机关和税务行政相对人具有普遍约束力的税务规章。 税务规章以国家税务总局令公布。"},{"i":2,"n":"第三条","txt":"税务规章的立项、起草、审查、决定、公布、解释、修改和废止，适用本办法。"},{"i":3,"n":"第四条","txt":"制定税务规章，应当贯彻落实党的路线方针政策和决策部署，体现全面深化改革、全面依法治国精神，符合社会主义核心价值观的要求。 制定政治方面法律的配套税务规章和制定对经济社会有重大影响的税务规章，在提交局务会议审议前应当向国家税务总局党委报告。 按照规定应当向党中央、国务院报告的重要税务规章，依照有关程序办理。"},{"i":4,"n":"第五条","txt":"制定税务规章，应当符合上位法的规定，体现职权与责任相统一的原则，切实保障税务行政相对人的合法权益。 没有法律或者国务院的行政法规、决定、命令的依据，税务规章不得设定减损税务行政相对人权利或者增加其义务的规范，不得增加本部门的权力或者减少本部门的法定职责。 税务规章不得溯及既往，但是为了更好地保护税务行政相对人权益而作出的特别规定除外。"},{"i":5,"n":"第六条","txt":"税务规章的名称一般称“办法”“规定”“规程”“规则”“决定”或者“实施细则”，不得称“条例”。"},{"i":6,"n":"第七条","txt":"税务规章应当根据需要，明确制定目的、依据、适用范围、主体、权利义务、具体规范、操作程序、法律责任、施行日期等。 税务规章用语应当准确、简洁，避免产生歧义；内容应当明确、具体，具有可操作性。"},{"i":7,"n":"第八条","txt":"税务规章应当采用条文式。 税务规章内容复杂的，可以根据需要分章、节、条、款、项、目。章、节、条的序号用中文数字依次表述，款不编序号，项的序号用中文数字加括号依次表述，目的序号用阿拉伯数字依次表述。"},{"i":8,"n":"第九条","txt":"国家税务总局各司局及其他机构（以下统称“司局”）认为需要制定税务规章的，应当于每年第一季度报请立项。 立项申请应当对制定税务规章的目的、依据、必要性、所要解决的主要问题、拟确立的主要制度等作出说明。"},{"i":9,"n":"第十条","txt":"国家税务总局可以向社会公开征集税务规章制定项目建议。 国家税务总局各省、自治区、直辖市和计划单列市税务局以及国家税务总局驻各地特派员办事处，可以向国家税务总局提出税务规章制定项目建议，项目建议应当包括制定税务规章的依据、必要性、所要解决的主要问题等说明。"},{"i":10,"n":"第十一条","txt":"国家税务总局政策法规司（以下称“政策法规司”）会同相关司局对立项申请和税务规章制定项目建议进行评估论证，拟订年度税务规章制定计划，报局务会议批准后向社会公布。 年度税务规章制定计划需要调整的，应当经局务会议批准。"},{"i":11,"n":"第十二条","txt":"税务规章由主管司局负责起草。 税务规章内容涉及两个以上司局的，由局长指定的司局负责起草。"},{"i":12,"n":"第十三条","txt":"起草税务规章，应当深入调查研究，广泛听取相关司局、基层税务机关和社会公众的意见；相关内容与其他部门关系紧密的，应当征求其他部门的意见。 除依法需要保密的外，起草司局应当将税务规章征求意见稿及其说明向社会公开征求意见，期限一般不少于30日。依法需要听证的，起草司局应当举行听证会。 起草专业性较强的税务规章，可以吸收相关领域的专家参与，或者委托有关专家、教学科研单位、社会组织起草。"},{"i":13,"n":"第十四条","txt":"起草司局形成税务规章送审稿后，应当连同下列材料，一并送政策法规司审查： （一）起草说明，包括制定税务规章的必要性、规定的主要措施、有关方面的意见及协调处理情况等； （二）作为制定依据的法律，国务院的行政法规、决定、命令； （三）其他相关材料，如听证会笔录、调研报告等。 按照规定应当对送审稿进行公平竞争审查的，起草司局应当提供相关审查材料。"},{"i":14,"n":"第十五条","txt":"政策法规司应当从以下方面对税务规章送审稿进行审查： （一）是否符合本办法第四条至第八条、第十三条的规定； （二）是否与其他税务规章协调、衔接； （三）是否正确处理各方面对税务规章送审稿主要问题的意见； （四）是否符合立法技术要求； （五）其他需要审查的内容。"},{"i":15,"n":"第十六条","txt":"政策法规司按照世界贸易组织规则，对送审稿进行合规性评估。"},{"i":16,"n":"第十七条","txt":"税务规章送审稿有下列情形之一的，政策法规司应当退回起草司局： （一）制定税务规章的基本条件尚不成熟或者发生重大变化的； （二）有关司局或者其他部门对税务规章送审稿规定的主要制度存在较大争议，起草司局未进行充分协商达成一致的； （三）未按照本办法有关规定公开征求意见的； （四）未按照本办法第十四条规定报送相关审查材料的。"},{"i":17,"n":"第十八条","txt":"政策法规司应当按照规定，对税务规章送审稿涉及的主要问题深入调查研究、广泛听取意见；涉及重大利益调整的，应当开展论证咨询。 出现较大争议的，政策法规司应当进行协调，力求达成一致。不能达成一致的，政策法规司应当将主要问题、各方意见及时报局领导决定。"},{"i":18,"n":"第十九条","txt":"政策法规司应当认真研究各方面意见，会同起草司局对税务规章送审稿进行修改，形成税务规章草案和草案说明，报局务会议审议。"},{"i":19,"n":"第二十条","txt":"税务规章草案经局务会议审议通过后，政策法规司应当根据局务会议审议意见进行修改，形成草案修改稿，报请局长签署国家税务总局令公布。"},{"i":20,"n":"第二十一条","txt":"由国家税务总局主办与国务院其他部门联合制定税务规章的，依照本办法的规定执行。 依照前款规定联合制定的税务规章，由局长和其他部门首长共同署名，并以国家税务总局令公布。"},{"i":21,"n":"第二十二条","txt":"税务规章签署公布后，应当及时在《国家税务总局公报》、国家税务总局网站以及《中国税务报》上刊载。 在《国家税务总局公报》上刊登的税务规章文本为标准文本。 《国家税务总局公报》的编纂和有关税务规章公告事宜，由办公厅和政策法规司负责实施。"},{"i":22,"n":"第二十三条","txt":"税务规章应当自公布之日起30日后施行；但是，公布后不立即施行将有碍施行的，可以自公布之日起施行。"},{"i":23,"n":"第二十四条","txt":"税务规章由国家税务总局解释。 税务规章有下列情形之一的，国家税务总局应当及时作出解释： （一）税务规章的规定需要进一步明确具体含义的； （二）税务规章制定后出现新的情况，需要明确适用规章依据的。"},{"i":24,"n":"第二十五条","txt":"税务规章解释文本由主管司局负责起草，政策法规司参照规章送审稿审查程序提出意见，报局长批准后以公告形式公布。 税务规章的解释与税务规章具有同等效力。"},{"i":25,"n":"第二十六条","txt":"税务规章应当自公布之日起30日内报国务院备案，具体工作由政策法规司实施。"},{"i":26,"n":"第二十七条","txt":"国家税务总局应当根据全面深化改革、经济社会发展需要以及上位法规定，及时组织开展税务规章清理工作。对不适应全面深化改革和经济社会发展要求、不符合上位法规定的税务规章，应当及时修改或者废止。"},{"i":27,"n":"第二十八条","txt":"国家税务总局可以根据需要，开展税务规章立法后评估，并把评估结果作为修改、废止税务规章的重要参考，具体工作由主管司局实施。"},{"i":28,"n":"第二十九条","txt":"编辑出版有关税务规章汇编，由政策法规司依照国务院《法规汇编编辑出版管理规定》的有关规定执行。"},{"i":29,"n":"第三十条","txt":"国家税务总局负责草拟法律、行政法规代拟稿的，参照本办法办理。"},{"i":30,"n":"第三十一条","txt":"本办法自2002年3月1日起施行。"}],"shuishoukuaijizhidu":[{"i":1,"n":"第一条","txt":"为了规范和加强税收会计工作，保证税收会计资料真实、准确、完整，充分发挥税收会计在加强税收管理中的作用，特制定本制度。"},{"i":2,"n":"第二条","txt":"凡是直接负责税款征收或入库业务的税务机关，都必须严格按本制度的规定，组织税收会计核算工作。"},{"i":3,"n":"第三条","txt":"税收会计的核算对象是税收资金及其运动，即税务部门组织征收的各项收入的应征、征收、减免、欠缴、上解、入库和提退等运动的全过程。"},{"i":4,"n":"第四条","txt":"税收会计核算单位，按其对税收资金管理任务的不同，分为直接管理税收资金上解的单位（简称上解单位）、直接管理税收资金入库的单位（简称入库单位）、管理税收资金上解和入库双重业务的单位（简称双重业务单位）及管理部分税款上解和部分税款入库的混合业务单位（简称混合业务单位）四种。 上解单位，指直接负责税款的征收、上解业务，而不负责与金库核对入库税款和从金库办理税款退库业务的税务机关。它是入库单位的基层核算单位，核算税收资金从应征到上解的过程，为了满足上解单位考核税收收入任务的需要，它还必须将税款的提退也纳入其核算范围，以便提供税款上解净额指标。 入库单位，指直接负责与金库核对入库税款和从金库办理税款退库业务，而不直接负责税款的征收和上解业务的税务机关。它是上解单位和混合业务单位的上级核算单位，它核算税收资金从应征到入库（提退）的全过程。 双重业务单位，指既直接负责税款的征收、上解业务，又直接负责与"},{"i":5,"n":"第五条","txt":"入库单位和双重业务单位以上各级税务机关均为会计核算汇总单位。"},{"i":6,"n":"第六条","txt":"各核算单位和汇总单位都必须在有关机构中设置税收会计人员并指定会计主管人员。 各单位配备的会计人员应当具备会计从业资格、持有会计证，担任会计机构负责人和会计主管人员必须具有国家规定的相应会计任职资格。 会计机构负责人和会计主管人员调动工作或离职，必须事先征得上级税务机关会计机构负责人的同意，并且必须与接管人员办清交接手续。"},{"i":7,"n":"第七条","txt":"本制度第三条规定的会计核算对象所涉及的税收业务，都必须在税收业务发生时填制或取得合法的会计原始凭证，并由核算单位各凭证受理部门于填制或收到凭证的次日送交会计机构或会计人员。"},{"i":8,"n":"第八条","txt":"各核算单位对所有实际发生的并引起税收资金运动的税收业务，都必须如实、及时地进行会计核算。不得伪造、变造会计凭证、会计账簿、报送虚假的会计报表。 任何部门、单位和个人不得指使、强令税收会计篡改会计资料和提供虚假的会计资料。"},{"i":9,"n":"第九条","txt":"各核算单位和汇总单位向上级税务机关或对外报送的会计核算资料，应有核算单位或汇总单位负责人、会计机构负责人、会计主管人员的签章。签章人员对会计资料的合法性、真实性承担法律责任。"},{"i":10,"n":"第十条","txt":"会计年度自公历一月一日至十二月三十一日止。"},{"i":11,"n":"第十一条","txt":"会计核算以人民币“元”为记账单位，元以下记至分。"},{"i":12,"n":"第十二条","txt":"税收会计采用“借贷记账法”。"},{"i":13,"n":"第十三条","txt":"税收会计“借贷记账法”，以税务机关为会计实体，以税收资金活动为记账主体，采用“借”、“贷”为记账符号，运用复式记账原理，反映税收资金的运动变化情况。其会计科目划分为资金来源和资金占用两大类。它的所有账户分为“借方”和“贷方”，左“借”右“贷”，“借方”记录资金占用的增加和资金来源的减少，“贷方”记录资金占用的减少和资金来源的增加。它的记账规则是，对每项税收业务，都必须按照相等的金额同时记入一个账户的借方和另一账户的贷方，或一个账户的借方（或贷方）和几个账户的贷方（或借方），即“有借必有贷，借贷必相等”。"},{"i":14,"n":"第十四条","txt":"借贷记账法的平衡公式是: 所有账户的借方余额（或发生额）合计=所有账户的贷方余额（或发生额）合计 或: 所有资金占用账户余额合计=所有资金来源账户余额合计"},{"i":15,"n":"第十五条","txt":"税收会计科目是对税收会计核算对象的具体内容，按照税收资金运动过程和税收管理需要，进行科学分类的项目。它是设置账户、组织会计核算的依据。"},{"i":16,"n":"第十六条","txt":"国家税务总局统一规定的总账科目名称、编号、核算内容及其使用方法，各地不得自行变更。如有特殊情况，需要在国家税务总局统一规定的总账科目之外增设其他总账科目，可由省级税务机关统一作出规定。 各地必须按照国家税务总局统一规定的明细科目内容进行明细核算；需要在国家税务总局统一规定的明细科目之外增设其他明细科目，及二级、三级等各层明细科目的具体名称、编号和使用方法由各省级税务机关自行制定。 省级以下各级税务机关必须严格按照国家税务总局和省级税务机关的规定设置和使用会计科目，不需要的会计科目可以不用，不得随意增减会计科目或改变科目名称、编号、核算内容和使用方法。"},{"i":17,"n":"第十七条","txt":"根据现行税收制度和税收管理需要，以及国家预算收入科目和国家金库制度，税收会计科目按四种核算单位的业务情况综合设置如下:"},{"i":18,"n":"第十八条","txt":"会计科目核算内容和使用方法如下: 1.“应征税收”、“应征其他收入”，是上解单位、入库单位、双重业务单位和混合业务单位的共用科目。 本类科目核算纳税人发生纳税义务后，税务机关应征的税金。包括:①纳税人和扣缴义务人及代征代售单位（人）向税务机关申报、预缴或由税务机关直接核定的应纳税金；②按定期定额方式征收的应纳税金；③不须缴纳，但须向税务机关申请的已发生的征前减免税金；④查补的各种税金、滞纳金和罚款；⑤税务机关征收的临时性零散税金等。当增值税纳税申报进项税额大于销项税额，应征税金为零时，不作账务处理，但以留抵税额抵顶欠税时，应作账务处理。 本类科目“贷方”记实际发生的应征税金数和申报无误缴款有误的应退多缴税金数，“借方”记应退还的多缴税金数和抵减应征税金数。即实际发生各项应征税金时，借记“待征”类科目，贷记本类科目；发生应退还的多缴税金时，借记本类科目，贷记“多缴税金”科目；若应退多缴税"},{"i":19,"n":"第十九条","txt":"税收会计凭证是说明税收业务发生情况，明确经济责任，具有法律效力，并据以登记账簿的书面证明文件。 各项税收业务的会计处理，都必须有原始凭证，并据审核无误的原始凭证归类整理填制记账凭证，然后才能根据原始凭证和记账凭证记账。税收会计凭证按其填制程序和用途分为原始凭证和记账凭证两种。"},{"i":20,"n":"第二十条","txt":"税收会计原始凭证是记录税收业务发生的最初书面证明，它是进行会计核算的原始资料，是填制记账凭证和登记明细账的依据。原始凭证必须是证明税收业务已经发生或已经完成的文件，凡是不能证明税收业务已经实际发生或完成的文件，都不能单独作为会计的原始凭证。"},{"i":21,"n":"第二十一条","txt":"税收会计原始凭证按其反映的税收业务内容的不同，分为应征凭证、减免凭证、征解凭证、入库凭证、提退凭证和其他凭证等六大类。各类凭证的具体内容如下: 1.应征凭证。是指税务机关用以确定纳税人、扣缴义务人及代征代售单位（人）应缴税金发生情况的证明，是核算应征税金的原始凭证。具体有以下几种: （1）纳税申报表（当纳税申报表中有减免税款时，该纳税申报表同时也是一种减免凭证）； （2）代扣代收税款报告； （3）预缴税款通知单； （4）企业纳税定额申请核定表或应纳税款核定书； （5）年（季度）纳税营业额申报核定表或定税清册； （6）调整定额税款通知书； （7）核准停业通知书； （8）申报（缴款）错误更正通知书； （9）税务处理决定书； （10）税务行政处罚决定书； （11）税务行政复议决定书； （12）审计决定书； （13）财政监督检查处理（处罚）决定书； （14）法院判决书； （15）海关（代征税款"},{"i":22,"n":"第二十二条","txt":"为满足入库单位会计核算需要，各上解单位和混合业务单位必须将原始凭证归类整理、按期（最长不得超过十天）编制以下各种原始凭证汇总单（其式样见附件）一式两份，一份留存；一份及时上报入库单位作为会计核算的原始凭证。 1.应征凭证汇总单。是上解单位和混合业务单位根据应征凭证等原始凭证汇总编制的，向入库单位上报应征税金等发生情况的一种原始凭证汇总单，它是入库单位核算应征税金等有关税金的原始凭证。 2.征前减免凭证汇总单。是上解单位和混合业务单位根据征前减免凭证汇总编制的，向入库单位上报征前减免税金情况的一种原始凭证汇总单。它是入库单位核算减免税金的原始凭证。 3.上解凭证汇总单。是上解单位和混合业务单位根据纳税人、扣缴义务人、代征代售单位（人）和自收现金税款的税务征收人员自行向银行缴纳税款的税收缴款书报查联及汇总专用缴款书收据联等原始凭证汇总编制的，向入库单位上报税款上解等情况的一种原始凭证汇总单"},{"i":23,"n":"第二十三条","txt":"税收会计记账凭证是根据审核无误的原始凭证或原始凭证汇总单加以归类整理编制，确定会计分录作为登记会计总账及其明细账的依据（其式样见附件）。记账凭证的编制要求如下: 1.必须以审核无误的原始凭证或原始凭证汇总单为依据，按每一项税收业务或同类税收业务汇总填制，不得把不同类型的税收业务合并填在一张记账凭证上。 2.编制要及时，要按税收业务发生日期及时填制，不得无顺序地编制。 3.总账科目和二级明细科目必须填写全称，不得只填代码不填名称或简化科目名称。 4.科目对应关系要清楚，会计分录只能一借一贷或一借多贷、一贷多借，不得编制多借多贷的会计分录。 5.记账凭证应按业务发生日期的顺序按月连续编号。 6.每份记账凭证要注明所附原始凭证的张数，并连同原始凭证及时整理，装订整齐。如果原始凭证需要另外保管或几种不同业务共用一张原始凭证的，必须在摘要栏加注说明，以备查找。"},{"i":24,"n":"第二十四条","txt":"会计凭证于记账后，应按会计档案要求及时装订，加具封面，并注明年度、月份、编号和签章，于年度终了后归档保管。"},{"i":25,"n":"第二十五条","txt":"会计账簿是以会计凭证为依据，按照会计科目，运用会计账户形式，全面、系统和连续地记录税收资金活动情况的簿籍。它是编制会计报表的主要依据。"},{"i":26,"n":"第二十六条","txt":"税收会计设置以下几种账簿: 1.总分类账。又称总账，它是按总账科目设置，考核税金活动总括情况，平衡账务，控制和核对各明细账的簿籍。 2.明细分类账。又称明细账，它是按明细科目设置，具体核算总账科目有关明细项目的簿籍。 3.日记账。它是按照税收业务发生时间的先后顺序逐笔进行登记的簿籍。 4.辅助账。又称备查账簿，它是对在总账、明细账和日记账中未能记载的事项或记载不够详细的税收业务进行补充登记的簿籍。"},{"i":27,"n":"第二十七条","txt":"税收会计账簿的设置和登记方法如下: 1.总分类账的设置和登记。税收会计各核算单位对其所用的总账科目都必须分别设置账页，开设账户。总分类账簿必须将账页固定在一起装订成册，其账页格式采用“借、贷、余”三栏式。可以按记账凭证直接登记，也可以将记账凭证按相同科目加以汇总，编制科目汇总表，然后根据科目汇总表登记（其账簿格式见附件）。 2.明细分类账的设置和登记。税收会计各核算单位都必须按照会计科目中规定的明细核算内容设置明细账。明细账必须根据记账凭证并参考原始凭证或原始凭证汇总单进行登记。它一般使用活页式账簿，其账页格式可采用三栏式和多栏式（可以是发生额分析多栏、借方发生额多栏、贷方发生额多栏）两种。三栏式明细账结构同总分类账相同。多栏式明细账是将某明细科目所属的一级明细科目或二级明细科目，作为该明细科目的发生额，合并在一张账页上进行登记的一种账页（其账簿格式见附件）。 发生额分析多栏的登记方法"},{"i":28,"n":"第二十八条","txt":"账簿的使用和登记要求如下: 1.使用账簿时，应在“账簿启用表”上将各栏内容填写清楚，经办人员更换交接时，应填明交接日期，互相签章。年度终了，必须将活页账簿装订成册归档保存。 2.各种账簿的记录，必须做到登记及时、内容完整、数字正确、摘要清楚，不得乱擦乱补、涂改或用退色药水消除字迹。 3.账簿记录发生错误，应根据错误性质和具体情况，采用划线更正法、红字冲销法和补充登记法加以更正。 4.税收会计以月为结算期，以年度为决算期。“入库”类账户应按旬小结。月份、年度终了时，各种账户必须办理结账。“提退税金”账户每月结账时，应结出本月借方发生额合计和本年借方累计发生额。每次结账时，应先进行试算平衡，总账与明细账必须核对无误，有关账户必须办理年度结转冲销工作。 第六章税收会计核算程序"},{"i":29,"n":"第二十九条","txt":"税收会计可采用记账凭证和科目汇总表两种核算程序。但一个核算单位在一个会计年度内，只能采用其中的一种程序，而不能交叉使用两种程序。 1.记账凭证核算程序如下: （1）根据原始凭证或原始凭证汇总单填制记账凭证； （2）根据记账凭证登记日记账； （3）根据原始凭证或原始凭证汇总单和记账凭证，登记明细账和有关的辅助账； （4）根据记账凭证登记总账； （5）总账和有关的明细账、日记账核对，明细账与有关的辅助账核对； （6）根据总账、明细账和有关的辅助账编制会计报表。 其程序图如下: 2.科目汇总表核算程序如下: （1）根据原始凭证或原始凭证汇总单填制记账凭证； （2）根据记账凭证登记日记账； （3）根据原始凭证或原始凭证汇总单和记账凭证，登记明细账和有关的辅助账； （4）根据记账凭证定期按科目借方和贷方发生额汇总编制科目汇总表； （5）根据科目汇总表登记总账； （6）总账和有关的明细账、日记账核"},{"i":30,"n":"第三十条","txt":"税收会计报表是用特定的表式，以会计账簿资料为主要依据，以货币为计量单位，通过一系列的税收指标，集中反映会计报告期内税收资金运动情况的书面报告。 各核算单位必须严格按照规定的时间向其上级税务机关编报各种会计报表。汇总单位应及时对下属核算单位上报的报表进行审核，并将同类报表加以汇总，编报汇总报表。"},{"i":31,"n":"第三十一条","txt":"各核算单位和汇总单位应按期向上级税务机关编报如下报表（格式见附件）: 1.税收电旬报（格式略）。它是以旬为报告期，向其上级税务机关报告本旬内税务机关组织各项税金入库情况的报表。 2.税收电月报（格式略）。它是以月为报告期，向其上级税务机关报告各税种、其他收入种类和有关重点品目税款入库和欠税情况的报表。 3.税收资金平衡表。它是以月、年为报告期，总括反映税收资金运动情况的报表。其中入库单位税收资金平衡表中的“暂收款”和“保管款”科目的余额，按各下属上解单位和混合业务单位编报的税收资金平衡表所列数据汇总填列。 4.应征税金明细报表。它是以月、年为报告期，按税种及其他收入种类反映本月和期末累计应征税金情况的报表。其中“查补税金”按“应征和入库查补税金登记簿”中的“应征查补税金”累计余额填列。 5.入库税金明细报表。它是以月、年为报告期，按预算收入科目有关类款项和预算级次详细反映本月和期末入库"},{"i":32,"n":"第三十二条","txt":"各核算单位内部管理所需要的会计报表，由各地自行制定。"},{"i":33,"n":"第三十三条","txt":"各省、自治区、直辖市、计划单列市税务局应根据本制度制定本地区的具体实施办法,并报国家税务总局备案。"},{"i":34,"n":"第三十四条","txt":"税收会计档案管理按国家有关规定执行。会计电算化管理办法另行制定。"},{"i":35,"n":"第三十五条","txt":"本制度由国家税务总局解释。"},{"i":36,"n":"第三十六条","txt":"本制度自一九九九年一月一日起施行。一九九五年八月二十一日国家税务总局颁发的《税收会计核算办法》及有关规定同时废止。 附件： 附件下载.docx"}],"shuishouzhifaduchaguize":[{"i":1,"n":"第一条","txt":"为了规范税收执法督察工作，促进税务机关依法行政，保证税收法律、行政法规和税收政策的贯彻实施，保护纳税人的合法权益，防范和化解税收执法风险，根据《中华人民共和国税收征收管理法》及其实施细则的有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"各级税务机关开展税收执法督察工作，适用本规则。"},{"i":3,"n":"第三条","txt":"本规则所称税收执法督察(以下简称执法督察)，是指县以上（含县）各级税务机关对本级税务机关内设机构、直属机构、派出机构或者下级税务机关的税收执法行为实施检查和处理的行政监督。"},{"i":4,"n":"第四条","txt":"执法督察应当服从和服务于税收中心工作，坚持依法督察，客观公正，实事求是。"},{"i":5,"n":"第五条","txt":"被督察单位及其工作人员应当自觉接受和配合执法督察。"},{"i":6,"n":"第六条","txt":"各级税务机关督察内审部门或者承担税收执法监督检查职责的部门（以下简称督察内审部门），代表本级税务机关组织开展执法督察工作，履行以下职责： （一）依据上级税务机关执法督察工作制度和计划，制定本级税务机关执法督察工作制度和计划； （二）组织实施执法督察，向本级税务机关提交税收执法督察报告，并制作《税收执法督察处理决定书》、《税收执法督察处理意见书》或者《税收执法督察结论书》； （三）组织实施税务系统税收执法责任制工作，牵头推行税收执法责任制考核信息系统，实施执法疑点信息分析监控； （四）督办执法督察所发现问题的整改和责任追究； （五）配合外部监督部门对税务机关开展监督检查工作； （六）向本级和上级税务机关报告执法督察工作情况； （七）通报执法督察工作情况和执法督察结果； （八）指导、监督和考核下级税务机关执法督察工作； （九）其他相关工作。"},{"i":7,"n":"第七条","txt":"执法督察实行统筹规划，归口管理。督察内审部门负责执法督察工作的具体组织、协调和落实。税务机关内部相关部门应当树立全局观念，积极参与、支持和配合执法督察工作。 各级税务机关根据工作需要，可以将执法督察与其他具有监督性质的工作协同开展。"},{"i":8,"n":"第八条","txt":"各级税务机关应当统一安排专门的执法督察工作经费，根据年度执法督察工作计划和具体执法督察工作的开展情况，做好经费预算，并保障经费的正确合理使用。"},{"i":9,"n":"第九条","txt":"上级税务机关对执法督察事项可以直接进行督察，也可以授权或者指定下级税务机关进行督察。"},{"i":10,"n":"第十条","txt":"上级税务机关认为下级税务机关作出的执法督察结论不适当的，可以责成下级税务机关予以变更或者撤销，必要时也可以直接作出变更或者撤销的决定。"},{"i":11,"n":"第十一条","txt":"各级税务机关可以采取复查、抽查等方式，对执法督察人员在执法督察工作中履行职责、遵守纪律、廉洁自律等情况进行监督检查。"},{"i":12,"n":"第十二条","txt":"各级税务机关应当建立税收执法督察人才库，为执法督察储备人才。根据执法督察工作需要，确定执法督察人才库人员基数，实行动态管理，定期组织业务培训。下级税务机关应当向上级税务机关执法督察人才库输送人才。"},{"i":13,"n":"第十三条","txt":"执法督察可以由督察内审部门人员独立完成，也可以抽调本级和下级税务机关税务人员实施，优先抽调执法督察人才库成员参加。相关单位和部门应当予以配合。"},{"i":14,"n":"第十四条","txt":"执法督察的内容包括： （一）税收法律、行政法规、规章和规范性文件的执行情况； （二）国务院和上级税务机关有关税收工作重要决策、部署的贯彻落实情况； （三）税务机关制定或者与其他部门联合制定的涉税文件，以及税务机关以外的单位制定的涉税文件的合法性; （四）外部监督部门依法查处或者督查、督办的税收执法事项； （五）上级机关交办、有关部门转办的税收执法事项； （六）执法督察所发现问题的整改和责任追究情况； （七）其他需要实施执法督察的税收执法事项。"},{"i":15,"n":"第十五条","txt":"执法督察可以通过全面执法督察、重点执法督察、专项执法督察和专案执法督察等形式开展。"},{"i":16,"n":"第十六条","txt":"全面执法督察是指税务机关对本级和下级税务机关的税收执法行为进行的广泛、系统的监督检查。"},{"i":17,"n":"第十七条","txt":"重点执法督察是指税务机关对本级和下级税务机关某些重点方面、重点环节、重点行业的税收执法行为所进行的监督检查。"},{"i":18,"n":"第十八条","txt":"专项执法督察是指税务机关对本级和下级税务机关某项特定内容涉及到的税收执法行为进行的监督检查。"},{"i":19,"n":"第十九条","txt":"专案执法督察是指税务机关对上级机关交办、有关部门转办的特定税收执法事项，以及通过信访、举报、媒体等途径反映的重大税收执法问题所涉及到的本级和下级税务机关的税收执法行为进行的监督检查。"},{"i":20,"n":"第二十条","txt":"各级税务机关应当积极运用信息化手段，对与税收执法活动有关的各类信息系统执法数据进行分析、筛选、监控和提示，为各种形式的执法督察提供线索。"},{"i":21,"n":"第二十一条","txt":"执法督察工作要有计划、有组织、有步骤地开展，主要包括准备、实施、处理、整改、总结等阶段，根据工作需要可以进行复查。"},{"i":22,"n":"第二十二条","txt":"督察内审部门应当科学、合理制定年度执法督察工作计划，报本级税务机关批准后统一部署实施。 未纳入年度执法督察工作计划的专案执法督察和其他特殊情况下需要启动的执法督察，应当在实施前报本级税务机关批准。"},{"i":23,"n":"第二十三条","txt":"实施执法督察前，督察内审部门应当根据执法督察的对象和内容，制定包括组织领导、工作要求和执法督察的时限、重点、方法、步骤等内容的执法督察方案。"},{"i":24,"n":"第二十四条","txt":"实施执法督察的税务机关应当成立执法督察组，负责具体实施执法督察。执法督察组人员不得少于2人，并实行组长负责制。 执法督察组组长应当对执法督察的总体质量负责。当执法督察组组长对被督察单位有关税收执法事项的意见与其他组员的意见不一致时，应当在税收执法督察报告中进行说明。"},{"i":25,"n":"第二十五条","txt":"实施执法督察的税务机关应当根据执法督察的对象和内容对执法督察组人员进行查前培训，保证执法督察效率和质量。"},{"i":26,"n":"第二十六条","txt":"实施执法督察，应当提前3个工作日向被督察单位下发税收执法督察通知，告知执法督察的时间、内容、方式，需要准备的资料，配合工作的要求等。被督察单位应当将税收执法督察通知在本单位范围内予以公布。 专案执法督察和其他特殊情况下，可以不予提前通知和公布。"},{"i":27,"n":"第二十七条","txt":"执法督察可以采取下列工作方式： （一）听取被督察单位税收执法情况汇报； （二）调阅被督察单位收发文簿、会议纪要、涉税文件、税收执法卷宗和文书，以及其他相关资料； （三）查阅、调取与税收执法活动有关的各类信息系统电子文档和数据； （四）与被督察单位有关人员谈话，了解有关情况； （五）特殊情况下需要到相关纳税人和有关单位了解情况或者取证时，应当按照法律规定的权限进行，并商请主管税务机关予以配合； （六）其他方式。"},{"i":28,"n":"第二十八条","txt":"执法督察中，被督察单位应当及时提供相关资料，以及与税收执法活动有关的各类信息系统所有数据查询权限。被督察单位主要负责人对本单位所提供的税收执法资料的真实性和完整性负责。"},{"i":29,"n":"第二十九条","txt":"实施执法督察应当制作《税收执法督察工作底稿》。 发现税收执法行为存在违法、违规问题的，应当收集相关证据材料，在工作底稿上写明行为的内容、时间、情节、证据的名称和出处，以及违法、违规的文件依据等，由被督察单位盖章或者由有关人员签字。拒不盖章或者拒不签字的，应当说明理由，记录在案。 收集证据材料时无法取得原件的，应当通过复印、照相、摄像、扫描、录音等手段提取或者复制有关资料，由原件保存单位或者个人在复制件上注明“与原件核对无误，原件存于我处”，并由有关人员签字。原件由单位保存的，还应当由该单位盖章。"},{"i":30,"n":"第三十条","txt":"执法督察组实施执法督察后，应当及时将发现的问题汇总，并向被督察单位反馈情况。 被督察单位或者个人可以对反馈的情况进行陈述和申辩，并提供陈述申辩的书面材料。"},{"i":31,"n":"第三十一条","txt":"执法督察组实施执法督察后，应当起草税收执法督察报告，内容包括： （一）执法督察的时间、内容、方法、步骤； （二）被督察单位税收执法的基本情况； （三）执法督察发现的具体问题，认定被督察单位存在违法、违规问题的基本事实和法律依据； （四）对发现问题的拟处理意见； （五）加强税收执法监督管理的建议； （六）执法督察组认为应当报告的其他事项。"},{"i":32,"n":"第三十二条","txt":"执法督察组实施执法督察后，应当将税收执法督察报告、工作底稿、证据材料、陈述申辩资料以及与执法督察情况有关的其他资料进行整理，提交督察内审部门。"},{"i":33,"n":"第三十三条","txt":"督察内审部门收到税收执法督察报告和其他证据材料后，应当对以下内容进行审理： （一）执法督察程序是否符合规定； （二）事实是否清楚，证据是否确实充分，资料是否齐全； （三）适用的法律、行政法规、规章、规范性文件和有关政策等是否正确； （四）对被督察单位的评价是否准确，拟定的意见、建议等是否适当。"},{"i":34,"n":"第三十四条","txt":"督察内审部门在审理中发现事实不清、证据不足、资料不全的，应当通知执法督察组对证据予以补正，也可以重新组织人员进行核实、检查。"},{"i":35,"n":"第三十五条","txt":"督察内审部门在审理中对适用税收法律、行政法规和税收政策有疑义的问题，以及涉嫌违规的涉税文件，应当书面征求本级税务机关法规部门和业务主管部门意见，也可以提交本级税务机关集体研究，并做好会议记录；本级税务机关无法或者无权确定的，应当请示上级税务机关或者请有权机关解释或者确定。"},{"i":36,"n":"第三十六条","txt":"督察内审部门根据审理结果修订税收执法督察报告，送被督察单位征求意见。被督察单位应当在15个工作日内提出书面反馈意见。在限期内未提出书面意见的，视同无异议。 督察内审部门应当对被督察单位提出的意见进行研究，对税收执法督察报告作必要修订，连同被督察单位的书面反馈意见一并报送本级税务机关审定。"},{"i":37,"n":"第三十七条","txt":"督察内审部门根据本级税务机关审定的税收执法督察报告制作《税收执法督察处理决定书》、《税收执法督察处理意见书》或者《税收执法督察结论书》，经本级税务机关审批后下达被督察单位。 《税收执法督察处理决定书》适用于对被督察单位违反税收法律、行政法规和税收政策的行为进行处理。 《税收执法督察处理意见书》适用于对被督察单位提出自行纠正的事项和改进工作的建议。 《税收执法督察结论书》适用于对未发现违法、违规问题的被督察单位作出评价。 受本级税务机关委托，执法督察组组长可以就执法督察结果与被督察单位主要负责人或者有关人员进行谈话。"},{"i":38,"n":"第三十八条","txt":"对违反税收法律、行政法规、规章和上级税收规范性文件的涉税文件，按下列原则作出执法督察决定： （一）对下级税务机关制定，或者下级税务机关与其他部门联合制定的，责令停止执行，并予以纠正； （二）对本级税务机关制定的，应当停止执行并提出修改建议； （三）对地方政府和其他部门制定的，同级税务机关应当停止执行，向发文单位提出修改建议，并报告上级税务机关。"},{"i":39,"n":"第三十九条","txt":"除第三十八条规定外，对其他不符合税收法律、行政法规、规章和上级税收规范性文件的税收执法行为，按下列原则作出执法督察处理决定： （一）执法主体资格不合法的，依法予以撤销； （二）未履行法定职责的，责令限期履行法定职责； （三）事实不清、证据不足的，依法予以撤销，并可以责令重新作出执法行为； （四）未正确适用法律依据的，依法予以变更或者撤销，并可以责令重新作出执法行为； （五）严重违反法定程序的，依法予以变更或者撤销，并可以责令重新作出执法行为； （六）超越职权或者滥用职权的，依法予以撤销； （七）其他不符合税收法律、行政法规、规章和上级税收规范性文件的，依法予以变更或者撤销，并可以责令重新作出执法行为。"},{"i":40,"n":"第四十条","txt":"被督察单位收到《税收执法督察处理决定书》和《税收执法督察处理意见书》后，应当在规定的期限内执行，并以书面形式向实施执法督察的税务机关报告下列执行结果： （一）对违法、违规涉税文件的清理情况和清理结果； （二）对违法、违规的税收执法行为予以变更、撤销和重新作出执法行为的情况； （三）对有关责任人的责任追究情况； （四）要求报送的其他文件和资料。"},{"i":41,"n":"第四十一条","txt":"被督察单位对执法督察处理决定有异议的，可以在规定的期限内向实施执法督察的税务机关提出复核申请。实施执法督察的税务机关应当进行复核，并作出答复。"},{"i":42,"n":"第四十二条","txt":"实施执法督察的税务机关应当在本单位范围内对执法督察结果和执法督察工作情况予以通报。 执法督察事项应当保密的，可以不予通报。"},{"i":43,"n":"第四十三条","txt":"各级税务机关应当建立执法督察结果报告制度。 督察内审部门应当对执法督察所发现的问题进行归纳和分析，提出完善制度、加强管理等工作建议，向本级税务机关专题报告，并作为有关业务部门的工作参考。 发现税收政策或者税收征管制度存在问题的，各级税务机关应当及时向上级税务机关报告。"},{"i":44,"n":"第四十四条","txt":"各级税务机关每年应当在规定时间内，向上级税务机关报送年度执法督察工作总结和报表等相关材料。"},{"i":45,"n":"第四十五条","txt":"督察内审部门应当按照有关规定做好执法督察工作资料的立卷和归档工作。 执法督察档案应当做到资料齐全、分类清楚，便于质证和查阅。"},{"i":46,"n":"第四十六条","txt":"执法督察中发现税收执法行为存在违法、违规问题的，应当按照有关规定和管理权限，对有关负责人和直接责任人予以责任追究。"},{"i":47,"n":"第四十七条","txt":"执法督察中发现纳税人的税收违法行为，实施执法督察的税务机关应当责令主管税务机关调查处理；情节严重的，移交稽查部门处理。"},{"i":48,"n":"第四十八条","txt":"执法督察中，被督察单位不如实提供相关资料和查询权限，或者无正当理由拒绝、拖延、阻挠执法督察的，由实施执法督察的税务机关责令限期改正；拒不改正的，对有关负责人和直接责任人予以责任追究。"},{"i":49,"n":"第四十九条","txt":"被督察单位未按照《税收执法督察处理决定书》和《税收执法督察处理意见书》的要求执行，由实施执法督察的税务机关责令限期改正，并对其主要负责人和有关责任人予以责任追究。"},{"i":50,"n":"第五十条","txt":"执法督察结果及其整改落实情况应当作为各级税务机关考核的重要内容。 各级税务机关应当对执法规范、成绩突出的单位和个人给予表彰和奖励，并予以通报，同时将其先进经验进行推广。存在重大执法问题的单位、部门及其主要负责人和有关责任人，不得参加先进评选。"},{"i":51,"n":"第五十一条","txt":"对执法督察人员在执法督察中滥用职权、徇私舞弊、玩忽职守或者违反廉政建设有关规定的，应当按照有关规定追究其责任。"},{"i":52,"n":"第五十二条","txt":"对在执法督察工作中业绩突出的执法督察人员，各级税务机关应当给予表扬和奖励，并将其业绩作为在优秀公务员等先进评选活动中的重要依据。"},{"i":53,"n":"第五十三条","txt":"本规则相关文书式样，由国家税务总局另行规定。"},{"i":54,"n":"第五十四条","txt":"各省、自治区、直辖市和计划单列市税务局可以依据本规则，结合本地区的具体情况制定具体实施办法。"},{"i":55,"n":"第五十五条","txt":"本规则自2013年4月1日起施行，《国家税务总局关于印发〈税收执法检查规则〉的通知》（国税发〔2004〕126号）同时废止。"}],"shuishoupiaozhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范税收票证管理工作，保证国家税收收入的安全完整，维护纳税人合法权益，适应税收信息化发展需要，根据《中华人民共和国税收征收管理法》及其实施细则等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"税务机关、税务人员、纳税人、扣缴义务人、代征代售人和税收票证印制企业在中华人民共和国境内印制、使用、管理税收票证，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称税收票证，是指税务机关、扣缴义务人依照法律法规，代征代售人按照委托协议，征收税款、基金、费、滞纳金、罚没款等各项收入（以下统称税款）的过程中，开具的收款、退款和缴库凭证。税收票证是纳税人实际缴纳税款或者收取退还税款的法定证明。 税收票证包括纸质形式和数据电文形式。数据电文税收票证是指通过横向联网电子缴税系统办理税款的征收缴库、退库时，向银行、国库发送的电子缴款、退款信息。"},{"i":4,"n":"第四条","txt":"国家积极推广以横向联网电子缴税系统为依托的数据电文税收票证的使用工作。"},{"i":5,"n":"第五条","txt":"税务机关、代征代售人征收税款时应当开具税收票证。通过横向联网电子缴税系统完成税款的缴纳或者退还后，纳税人需要纸质税收票证的，税务机关应当开具。 扣缴义务人代扣代收税款时，纳税人要求扣缴义务人开具税收票证的，扣缴义务人应当开具。"},{"i":6,"n":"第六条","txt":"税收票证的基本要素包括：税收票证号码、征收单位名称、开具日期、纳税人名称、纳税人识别号、税种（费、基金、罚没款）、金额、所属时期等。"},{"i":7,"n":"第七条","txt":"纸质税收票证的基本联次包括收据联、存根联、报查联。收据联交纳税人作完税凭证；存根联由税务机关、扣缴义务人、代征代售人留存；报查联由税务机关做会计凭证或备查。 省、自治区、直辖市和计划单列市（以下简称省）税务机关可以根据税收票证管理情况，确定除收据联以外的税收票证启用联次。"},{"i":8,"n":"第八条","txt":"国家税务总局统一负责全国的税收票证管理工作。其职责包括： （一）设计和确定税收票证的种类、适用范围、联次、内容、式样及规格； （二）设计和确定税收票证专用章戳的种类、适用范围、式样及规格； （三）印制、保管、发运需要全国统一印制的税收票证，刻制需要全国统一制发的税收票证专用章戳； （四）确定税收票证管理的机构、岗位和职责； （五）组织、指导和推广税收票证信息化工作； （六）组织全国税收票证检查工作； （七）其他全国性的税收票证管理工作。"},{"i":9,"n":"第九条","txt":"省以下税务机关应当依照本办法做好本行政区域内的税收票证管理工作。其职责包括： （一）负责本级权限范围内的税收票证印制、领发、保管、开具、作废、结报缴销、停用、交回、损失核销、移交、核算、归档、审核、检查、销毁等工作； （二）指导和监督下级税务机关、扣缴义务人、代征代售人、自行填开税收票证的纳税人税收票证管理工作； （三）组织、指导、具体实施税收票证信息化工作； （四）组织税收票证检查工作； （五）其他税收票证管理工作。"},{"i":10,"n":"第十条","txt":"扣缴义务人和代征代售人在代扣代缴、代收代缴、代征税款以及代售印花税票过程中应当做好税收票证的管理工作。其职责包括： （一）妥善保管从税务机关领取的税收票证，并按照税务机关要求建立、报送和保管税收票证账簿及有关资料； （二）为纳税人开具并交付税收票证； （三）按时解缴税款、结报缴销税收票证； （四）其他税收票证管理工作。"},{"i":11,"n":"第十一条","txt":"各级税务机关的收入规划核算部门主管税收票证管理工作。 国家税务总局收入规划核算司设立主管税收票证管理工作的机构；省、市（不含县级市，下同）、县税务机关收入规划核算部门应当设置税收票证管理岗位并配备专职税收票证管理人员；直接向税务机关税收票证开具人员、扣缴义务人、代征代售人、自行填开税收票证的纳税人发放税收票证并办理结报缴销等工作的征收分局、税务所、办税服务厅等机构（以下简称基层税务机关）应当设置税收票证管理岗位，由税收会计负责税收票证管理工作。税收票证管理岗位和税收票证开具（含印花税票销售）岗位应当分设，不得一人多岗。 扣缴义务人、代征代售人、自行填开税收票证的纳税人应当由专人负责税收票证管理工作。"},{"i":12,"n":"第十二条","txt":"税收票证包括税收缴款书、税收收入退还书、税收完税证明、出口货物劳务专用税收票证、印花税专用税收票证以及国家税务总局规定的其他税收票证。"},{"i":13,"n":"第十三条","txt":"税收缴款书是纳税人据以缴纳税款，税务机关、扣缴义务人以及代征代售人据以征收、汇总税款的税收票证。具体包括： （一）《税收缴款书（银行经收专用）》。由纳税人、税务机关、扣缴义务人、代征代售人向银行传递，通过银行划缴税款（出口货物劳务增值税、消费税除外）到国库时使用的纸质税收票证。其适用范围是： 1.纳税人自行填开或税务机关开具，纳税人据以在银行柜面办理缴税（转账或现金），由银行将税款缴入国库； 2.税务机关收取现金税款、扣缴义务人扣缴税款、代征代售人代征税款后开具，据以在银行柜面办理税款汇总缴入国库； 3.税务机关开具，据以办理\"待缴库税款\"账户款项缴入国库。 （二）《税收缴款书（税务收现专用）》。纳税人以现金、刷卡（未通过横向联网电子缴税系统）方式向税务机关缴纳税款时，由税务机关开具并交付纳税人的纸质税收票证。代征人代征税款时，也应开具本缴款书并交付纳税人。为方便流动性零散税收的征收管"},{"i":14,"n":"第十四条","txt":"税收收入退还书是税务机关依法为纳税人从国库办理退税时使用的税收票证。具体包括： （一）《税收收入退还书》。税务机关向国库传递，依法为纳税人从国库办理退税时使用的纸质税收票证。 （二）《税收收入电子退还书》。税务机关通过横向联网电子缴税系统依法为纳税人从国库办理退税时，由税收征管系统生成的数据电文形式的税收票证。 税收收入退还书应当由县以上税务机关税收会计开具并向国库传递或发送。"},{"i":15,"n":"第十五条","txt":"出口货物劳务专用税收票证是由税务机关开具，专门用于纳税人缴纳出口货物劳务增值税、消费税或者证明该纳税人再销售给其他出口企业的货物已缴纳增值税、消费税的纸质税收票证。具体包括： （一）《税收缴款书（出口货物劳务专用）》。由税务机关开具，专门用于纳税人缴纳出口货物劳务增值税、消费税时使用的纸质税收票证。纳税人以银行经收方式，税务收现方式，或者通过横向联网电子缴税系统缴纳出口货物劳务增值税、消费税时，均使用本缴款书。纳税人缴纳随出口货物劳务增值税、消费税附征的其他税款时，税务机关应当根据缴款方式，使用其他种类的缴款书，不得使用本缴款书。 （二）《出口货物完税分割单》。已经缴纳出口货物增值税、消费税的纳税人将购进货物再销售给其他出口企业时，为证明所售货物完税情况，便于其他出口企业办理出口退税，到税务机关换开的纸质税收票证。"},{"i":16,"n":"第十六条","txt":"印花税专用税收票证是税务机关或印花税票代售人在征收印花税时向纳税人交付、开具的纸质税收票证。具体包括： （一）印花税票。印有固定金额，专门用于征收印花税的有价证券。纳税人缴纳印花税，可以购买印花税票贴花缴纳，也可以开具税收缴款书缴纳。采用开具税收缴款书缴纳的，应当将纸质税收缴款书或税收完税证明粘贴在应税凭证上，或者由税务机关在应税凭证上加盖印花税收讫专用章。 （二）《印花税票销售凭证》。税务机关和印花税票代售人销售印花税票时一并开具的专供购买方报销的纸质凭证。"},{"i":17,"n":"第十七条","txt":"税收完税证明是税务机关为证明纳税人已经缴纳税款或者已经退还纳税人税款而开具的纸质税收票证。其适用范围是： （一）纳税人、扣缴义务人、代征代售人通过横向联网电子缴税系统划缴税款到国库（经收处）后或收到从国库退还的税款后，当场或事后需要取得税收票证的； （二）扣缴义务人代扣代收税款后，已经向纳税人开具税法规定或国家税务总局认可的记载完税情况的其他凭证，纳税人需要换开正式完税凭证的； （三）纳税人遗失已完税的各种税收票证（《出口货物完税分割单》、印花税票和《印花税票销售凭证》除外），需要重新开具的; （四）对纳税人特定期间完税情况出具证明的； （五）国家税务总局规定的其他需要为纳税人开具完税凭证情形。 税务机关在确保纳税人缴、退税信息全面、准确、完整的条件下，可以开展前款第四项规定的税收完税证明开具工作，具体开具办法由各省税务机关确定。"},{"i":18,"n":"第十八条","txt":"税收票证专用章戳是指税务机关印制税收票证和征、退税款时使用的各种专用章戳，具体包括： （一）税收票证监制章。套印在税收票证上，用以表明税收票证制定单位和税收票证印制合法性的一种章戳。 （二）征税专用章。税务机关办理税款征收业务，开具税收缴款书、税收完税证明、《印花税销售凭证》等征收凭证时使用的征收业务专用公章。 （三）退库专用章。税务机关办理税款退库业务，开具《税收收入退还书》等退库凭证时使用的，在国库预留印鉴的退库业务专用公章。 （四）印花税收讫专用章。以开具税收缴款书代替贴花缴纳印花税时，加盖在应税凭证上，用以证明应税凭证已完税的专用章戳。 （五）国家税务总局规定的其他税收票证专用章戳。"},{"i":19,"n":"第十九条","txt":"《税收缴款书（税务收现专用）》、《税收缴款书（代扣代收专用）》、《税收缴款书（出口货物劳务专用）》、《出口货物完税分割单》、印花税票和税收完税证明应当视同现金进行严格管理。"},{"i":20,"n":"第二十条","txt":"税收票证应当按规定的适用范围填开，不得混用。"},{"i":21,"n":"第二十一条","txt":"国家税务总局增设或简并税收票证及税收票证专用章戳种类，应当及时向社会公告。"},{"i":22,"n":"第二十二条","txt":"税收票证及税收票证专用章戳按照税收征收管理和国家预算管理的基本要求设计，具体式样另行制发。"},{"i":23,"n":"第二十三条","txt":"税收票证实行分级印制管理。 《税收缴款书（出口货物劳务专用）》、《出口货物完税分割单》、印花税票以及其他需要全国统一印制的税收票证由国家税务总局确定的企业印制；其他税收票证，按照国家税务总局规定的式样和要求，由各省税务机关确定的企业集中统一印制。 禁止私自印制、倒卖、变造、伪造税收票证。"},{"i":24,"n":"第二十四条","txt":"印制税收票证的企业应当具备下列条件： （一）取得印刷经营许可证和营业执照； （二）设备、技术水平能够满足印制税收票证的需要； （三）有健全的财务制度和严格的质量监督、安全管理、保密制度； （四）有安全、良好的保管场地和设施。 印制税收票证的企业应当按照税务机关提供的式样、数量等要求印制税收票证，建立税收票证印制管理制度。 税收票证印制合同终止后，税收票证的印制企业应当将有关资料交还委托印制的税务机关，不得保留或提供给其他单位及个人。"},{"i":25,"n":"第二十五条","txt":"税收票证应当套印税收票证监制章。 税收票证监制章由国家税务总局统一制发各省税务机关。"},{"i":26,"n":"第二十六条","txt":"除税收票证监制章外，其他税收票证专用章戳的具体刻制权限由各省税务机关确定。刻制的税收票证专用章戳应当在市以上税务机关留底归档。"},{"i":27,"n":"第二十七条","txt":"税收票证应当使用中文印制。民族自治地方的税收票证，可以加印当地一种通用的民族文字。"},{"i":28,"n":"第二十八条","txt":"负责税收票证印制的税务机关应当对印制完成的税收票证质量、数量进行查验。查验无误的，办理税收票证的印制入库手续；查验不合格的，对不合格税收票证监督销毁。"},{"i":29,"n":"第二十九条","txt":"上、下级税务机关之间，税务机关税收票证开具人员、扣缴义务人、代征代售人、自行填开税收票证的纳税人与税收票证管理人员之间，应当建立税收票证及税收票证专用章戳的领发登记制度，办理领发手续，共同清点、确认领发种类、数量和号码。 税收票证的运输应当确保安全、保密。 数据电文税收票证由税收征管系统自动生成税收票证号码，分配给税收票证开具人员，视同发放。数据电文税收票证不得重复发放、重复开具。"},{"i":30,"n":"第三十条","txt":"税收票证管理人员向税务机关税收票证开具人员、扣缴义务人和代征代售人发放视同现金管理的税收票证时，应当拆包发放，并且一般不得超过一个月的用量。 视同现金管理的税收票证未按照本办法第三十九条规定办理结报的，不得继续发放同一种类的税收票证。 其他种类的税收票证，应当根据领用人的具体使用情况，适度发放。"},{"i":31,"n":"第三十一条","txt":"税务机关、扣缴义务人、代征代售人、自行填开税收票证的纳税人应当妥善保管纸质税收票证及税收票证专用章戳。县以上税务机关应当设置具备安全条件的税收票证专用库房；基层税务机关、扣缴义务人、代征代售人和自行填开税收票证的纳税人应当配备税收票证保险专用箱柜。确有必要外出征收税款的，税收票证及税收票证专用章戳应当随身携带，严防丢失。"},{"i":32,"n":"第三十二条","txt":"税务机关对结存的税收票证应当定期进行盘点，发现结存税收票证实物与账簿记录数量不符的，应当及时查明原因并报告上级或所属税务机关。"},{"i":33,"n":"第三十三条","txt":"税收收入退还书开具人员不得同时从事退库专用章保管或《税收收入电子退还书》复核授权工作。印花税票销售人员不得同时从事印花税收讫专用章保管工作。外出征收税款的，税收票证开具人员不得同时从事现金收款工作。"},{"i":34,"n":"第三十四条","txt":"税收票证应当分纳税人开具；同一份税收票证上，税种（费、基金、罚没款）、税目、预算科目、预算级次、所属时期不同的，应当分行填列。"},{"i":35,"n":"第三十五条","txt":"税收票证栏目内容应当填写齐全、清晰、真实、规范，不得漏填、简写、省略、涂改、挖补、编造；多联式税收票证应当一次全份开具。"},{"i":36,"n":"第三十六条","txt":"因开具错误作废的纸质税收票证，应当在各联注明\"作废\"字样、作废原因和重新开具的税收票证字轨及号码。《税收缴款书（税务收现专用）》、《税收缴款书（代扣代收专用）》、税收完税证明应当全份保存；其他税收票证的纳税人所持联次或银行流转联次无法收回的，应当注明原因，并将纳税人出具的情况说明或银行文书代替相关联次一并保存。开具作废的税收票证应当按期与已填用的税收票证一起办理结报缴销手续，不得自行销毁。 税务机关开具税收票证后，纳税人向银行办理缴税前丢失的，税务机关参照前款规定处理。 数据电文税收票证作废的,应当在税收征管系统中予以标识；已经作废的数据电文税收票证号码不得再次使用。"},{"i":37,"n":"第三十七条","txt":"纸质税收票证各联次各种章戳应当加盖齐全。 章戳不得套印，国家税务总局另有规定的除外。"},{"i":38,"n":"第三十八条","txt":"税务机关税收票证开具人员、扣缴义务人、代征代售人、自行填开税收票证的纳税人与税收票证管理人员之间，基层税务机关与上级或所属税务机关之间，应当办理税收票款结报缴销手续。 税务机关税收票证开具人员、扣缴义务人、代征代售人向税收票证管理人员结报缴销视同现金管理的税收票证时，应当将已开具税收票证的存根联、报查联等联次，连同作废税收票证、需交回的税收票证及未开具的税收票证（含未销售印花税票）一并办理结报缴销手续；已开具税收票证只设一联的，税收票证管理人员应当查验其开具情况的电子记录。 其他各种税收票证结报缴销手续的具体要求，由各省税务机关确定。"},{"i":39,"n":"第三十九条","txt":"税收票款应当按照规定的时限办理结报缴销。税务机关税收票证开具人员、代征代售人开具税收票证（含销售印花税票）收取现金税款时，办理结报缴销手续的时限要求是： （一）当地设有国库经收处的，应于收取税款的当日或次日办理税收票款的结报缴销； （二）当地未设国库经收处和代征代售人收取现金税款的，由各省税务机关确定办理税收票款结报缴销的期限和额度，并以期限或额度条件先满足之日为准。 扣缴义务人代扣代收税款的，应按税法规定的税款解缴期限一并办理结报缴销。 其他各种税收票证的结报缴销时限、基层税务机关向上级或所属税务机关缴销税收票证的时限，由各省税务机关确定。"},{"i":40,"n":"第四十条","txt":"领发、开具税收票证时，发现多出、短少、污损、残破、错号、印刷字迹不清及联数不全等印制质量不合格情况的，应当查明字轨、号码、数量，清点登记，妥善保管。 全包、全本印制质量不合格的，按照本办法第五十一条规定销毁；全份印制质量不合格的，按开具作废处理。"},{"i":41,"n":"第四十一条","txt":"由于税收政策变动或式样改变等原因，国家税务总局规定停用的税收票证及税收票证专用章戳，应由县以上税务机关集中清理，核对字轨、号码和数量，造册登记，按照本办法第五十一条规定销毁。"},{"i":42,"n":"第四十二条","txt":"未开具税收票证（含未销售印花税票）发生毁损或丢失、被盗、被抢等损失的，受损单位应当及时组织清点核查，并由各级税务机关按照权限进行损失核销审批。《税收缴款书（出口货物劳务专用）》、《出口货物完税分割单》、印花税票发生损失的，由省税务机关审批核销；《税收缴款书（税务收现专用）》、《税收缴款书（代扣代收专用）》、税收完税证明发生损失的，由市税务机关审批核销；其他各种税收票证发生损失的，由县税务机关审批核销。 毁损残票和追回的税收票证按照本办法第五十一条规定销毁。"},{"i":43,"n":"第四十三条","txt":"视同现金管理的未开具税收票证（含未销售印花税票）丢失、被盗、被抢的，受损税务机关应当查明损失税收票证的字轨、号码和数量，立即向当地公安机关报案并报告上级或所属税务机关；经查不能追回的税收票证，除印花税票外，应当及时在办税场所和广播、电视、报纸、期刊、网络等新闻媒体上公告作废。 受损单位为扣缴义务人、代征代售人或税收票证印制企业的，扣缴义务人、代征代售人或税收票证印制企业应当立即报告基层税务机关或委托印制的税务机关，由税务机关按前款规定办理。 对丢失印花税票和印有固定金额的《税收缴款书（税务收现专用）》负有责任的相关人员，税务机关应当要求其按照面额赔偿；对丢失其他视同现金管理的税收票证负有责任的相关人员，税务机关应当要求其适当赔偿。"},{"i":44,"n":"第四十四条","txt":"税收票证专用章戳丢失、被盗、被抢的，受损税务机关应当立即向当地公安机关报案并逐级报告刻制税收票证专用章戳的税务机关；退库专用章丢失、被盗、被抢的，应当同时通知国库部门。重新刻制的税收票证专用章戳应当及时办理留底归档或预留印鉴手续。 毁损和损失追回的税收票证专用章戳按照本办法第五十一条规定销毁。"},{"i":45,"n":"第四十五条","txt":"由于印制质量不合格、停用、毁损、损失追回、领发错误，或者扣缴义务人和代征代售人终止税款征收业务、纳税人停止自行填开税收票证等原因，税收票证及税收票证专用章戳需要交回的，税收票证管理人员应当清点、核对字轨、号码和数量，及时上交至发放或有权销毁税收票证及税收票证专用章戳的税务机关。"},{"i":46,"n":"第四十六条","txt":"纳税人遗失已完税税收票证需要税务机关另行提供的，如税款经核实确已缴纳入库或从国库退还，税务机关应当开具税收完税证明或提供原完税税收票证复印件。"},{"i":47,"n":"第四十七条","txt":"税务机关税收票证开具人员、税收票证管理人员工作变动离岗前，应当办理税收票证、税收票证专用章戳、账簿以及其他税收票证资料的移交。移交时应当有专人监交，监交人、移交人、接管人三方共同签章，票清离岗。"},{"i":48,"n":"第四十八条","txt":"税务机关应当按税收票证种类、领用单位设置税收票证账簿，对各种税收票证的印制、领发、用存、作废、结报缴销、停用、损失、销毁的数量、号码进行及时登记和核算，定期结账。"},{"i":49,"n":"第四十九条","txt":"基层税务机关的税收票证管理人员应当按日对已结报缴销税收票证的完整性、准确性和税收票证管理的规范性进行审核；基层税务机关的上级或所属税务机关税收票证管理人员对基层税务机关缴销的税收票证，应当定期进行复审。"},{"i":50,"n":"第五十条","txt":"税务机关应当及时对已经开具、作废的税收票证、账簿以及其他税收票证资料进行归档保存。 纸质税收票证、账簿以及其他税收票证资料，应当整理装订成册，保存期限五年；作为会计凭证的纸质税收票证保存期限十五年。 数据电文税收票证、账簿以及其他税收票证资料，应当通过光盘等介质进行存储，确保数据电文税收票证信息的安全、完整，保存时间和具体办法另行制定。"},{"i":51,"n":"第五十一条","txt":"未填用的《税收缴款书（出口货物劳务专用）》、《出口货物完税分割单》、印花税票需要销毁的，应当由两人以上共同清点，编制销毁清册，逐级上缴省税务机关销毁；未填用的《税收缴款书（税务收现专用）》、《税收缴款书（代扣代收专用）》、税收完税证明需要销毁的，应当由两人以上共同清点，编制销毁清册，报经市税务机关批准，指派专人到县税务机关复核并监督销毁；其他各种税收票证、账簿和税收票证资料需要销毁的，由税收票证主管人员清点并编制销毁清册，报经县或市税务机关批准，由两人以上监督销毁；税收票证专用章戳需要销毁的，由刻制税收票证专用章戳的税务机关销毁。"},{"i":52,"n":"第五十二条","txt":"税务机关应当定期对本级及下级税务机关、税收票证印制企业、扣缴义务人、代征代售人、自行填开税收票证的纳税人税收票证及税收票证专用章戳管理工作进行检查。"},{"i":53,"n":"第五十三条","txt":"税务机关工作人员违反本办法的，应当根据情节轻重，给予批评教育、责令做出检查、诫勉谈话或调整工作岗位处理；构成违纪的，依照《中华人民共和国公务员法》、《行政机关公务员处分条例》等法律法规给予处分；涉嫌犯罪的，移送司法机关。"},{"i":54,"n":"第五十四条","txt":"扣缴义务人未按照本办法及有关规定保管、报送代扣代缴、代收代缴税收票证及有关资料的，按照《中华人民共和国税收征收管理法》及相关规定进行处理。 扣缴义务人未按照本办法开具税收票证的，可以根据情节轻重，处以一千元以下的罚款。"},{"i":55,"n":"第五十五条","txt":"税务机关与代征代售人、税收票证印制企业签订代征代售合同、税收票证印制合同时，应当就违反本办法及相关规定的责任进行约定，并按约定及其他有关规定追究责任；涉嫌犯罪的，移送司法机关。"},{"i":56,"n":"第五十六条","txt":"自行填开税收票证的纳税人违反本办法及相关规定的，税务机关应当停止其税收票证的领用和自行填开，并限期缴销全部税收票证；情节严重的，可以处以一千元以下的罚款。"},{"i":57,"n":"第五十七条","txt":"非法印制、转借、倒卖、变造或者伪造税收票证的，依照《中华人民共和国税收征收管理法实施细则》的规定进行处理；伪造、变造、买卖、盗窃、抢夺、毁灭税收票证专用章戳的，移送司法机关。"},{"i":58,"n":"第五十八条","txt":"各级政府部门委托税务机关征收的各种基金、费可以使用税收票证。"},{"i":59,"n":"第五十九条","txt":"本办法第六条、第七条、第二十五条、第三十六条、第三十七条、第四十六条所称税收票证，不包括印花税票。"},{"i":60,"n":"第六十条","txt":"本办法所称银行，是指经收预算收入的银行、信用社。"},{"i":61,"n":"第六十一条","txt":"各省税务机关应当根据本办法制定具体规定，并报国家税务总局备案。"},{"i":62,"n":"第六十二条","txt":"本办法自2014年1月1日起施行。1998年3月10日国家税务总局发布的《税收票证管理办法》（国税发〔1998〕32号）同时废止。"}],"shuishouweifaxingweijianjuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保障单位、个人依法检举纳税人、扣缴义务人违反税收法律、行政法规行为的权利，规范检举秩序，根据《中华人民共和国税收征收管理法》及其实施细则的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称检举，是指单位、个人采用书信、电话、传真、网络、来访等形式，向税务机关提供纳税人、扣缴义务人税收违法行为线索的行为。 采用前款所述的形式，检举税收违法行为的单位、个人称检举人；被检举的纳税人、扣缴义务人称被检举人。 检举人可以实名检举,也可以匿名检举。"},{"i":3,"n":"第三条","txt":"本办法所称税收违法行为，是指涉嫌偷税（逃避缴纳税款）,逃避追缴欠税，骗税，虚开、伪造、变造发票，以及其他与逃避缴纳税款相关的税收违法行为。"},{"i":4,"n":"第四条","txt":"检举管理工作坚持依法依规、分级分类、属地管理、严格保密的原则。"},{"i":5,"n":"第五条","txt":"市（地、州、盟）以上税务局稽查局设立税收违法案件举报中心。国家税务总局稽查局税收违法案件举报中心负责接收税收违法行为检举，督促、指导、协调处理重要检举事项；省、自治区、直辖市、计划单列市和市（地、州、盟）税务局稽查局税收违法案件举报中心负责税收违法行为检举的接收、受理、处理和管理；各级跨区域稽查局和县税务局应当指定行使税收违法案件举报中心职能的部门，负责税收违法行为检举的接收，并按规定职责处理。 本办法所称举报中心是指前款所称的税收违法案件举报中心和指定行使税收违法案件举报中心职能的部门。举报中心应当对外挂标识牌。"},{"i":6,"n":"第六条","txt":"税务机关应当向社会公布举报中心的电话（传真）号码、通讯地址、邮政编码、网络检举途径，设立检举接待场所和检举箱。 税务机关同时通过12366纳税服务热线接收税收违法行为检举。"},{"i":7,"n":"第七条","txt":"税务机关应当与公安、司法、纪检监察和信访等单位加强联系和合作，做好检举管理工作。"},{"i":8,"n":"第八条","txt":"检举税收违法行为是检举人的自愿行为，检举人因检举而产生的支出应当由其自行承担。"},{"i":9,"n":"第九条","txt":"检举人在检举过程中应当遵守法律、行政法规等规定；应当对其所提供检举材料的真实性负责，不得捏造、歪曲事实，不得诬告、陷害他人；不得损害国家、社会、集体的利益和其他公民的合法权益。"},{"i":10,"n":"第十条","txt":"检举人检举税收违法行为应当提供被检举人的名称（姓名）、地址（住所）和税收违法行为线索；尽可能提供被检举人统一社会信用代码（身份证件号码），法定代表人、实际控制人信息和其他相关证明资料。 鼓励检举人提供书面检举材料。"},{"i":11,"n":"第十一条","txt":"举报中心接收实名检举，应当准确登记实名检举人信息。 检举人以个人名义实名检举应当由其本人提出；以单位名义实名检举应当委托本单位工作人员提出。 多人联名进行实名检举的，应当确定第一联系人；未确定的，以检举材料的第一署名人为第一联系人。"},{"i":12,"n":"第十二条","txt":"12366纳税服务热线接收电话检举后，应当按照以下分类转交相关部门： （一）符合本办法第三条规定的检举事项，应当及时转交举报中心； （二）对应开具而未开具发票、未申报办理税务登记及其他轻微税收违法行为的检举事项，按照有关规定直接转交被检举人主管税务机关相关业务部门处理； （三）其他检举事项转交有处理权的单位或者部门。 税务机关的其他单位或者部门接到符合本办法第三条规定的检举材料后，应当及时转交举报中心。"},{"i":13,"n":"第十三条","txt":"以来访形式实名检举的，检举人应当提供营业执照、居民身份证等有效身份证件的原件和复印件。 以来信、网络、传真形式实名检举的，检举人应当提供营业执照、居民身份证等有效身份证件的复印件。 以电话形式要求实名检举的，税务机关应当告知检举人采取本条第一款、第二款的形式进行检举。 检举人未采取本条第一款、第二款的形式进行检举的，视同匿名检举。 举报中心可以应来访的实名检举人要求出具接收回执；对多人联名进行实名来访检举的，向其确定的第一联系人或者第一署名人出具接收回执。"},{"i":14,"n":"第十四条","txt":"来访检举应当到税务机关设立的检举接待场所；多人来访提出相同检举事项的，应当推选代表，代表人数应当在3人以内。"},{"i":15,"n":"第十五条","txt":"接收来访口头检举，应当准确记录检举事项，交检举人阅读或者向检举人宣读确认。实名检举的，由检举人签名或者盖章；匿名检举的，应当记录在案。 接收电话检举，应当细心接听、询问清楚、准确记录。 接收电话、来访检举，经告知检举人后可以录音、录像。 接收书信、传真等书面形式检举，应当保持检举材料的完整，及时登记处理。"},{"i":16,"n":"第十六条","txt":"税务机关应当合理设置检举接待场所。检举接待场所应当与办公区域适当分开，配备使用必要的录音、录像等监控设施，保证监控设施对接待场所全覆盖并正常运行。"},{"i":17,"n":"第十七条","txt":"举报中心对接收的检举事项，应当及时审查，有下列情形之一的，不予受理： （一）无法确定被检举对象，或者不能提供税收违法行为线索的； （二）检举事项已经或者依法应当通过诉讼、仲裁、行政复议以及其他法定途径解决的； （三）对已经查结的同一检举事项再次检举，没有提供新的有效线索的。 除前款规定外，举报中心自接收检举事项之日起即为受理。 举报中心可以应实名检举人要求，视情况采取口头或者书面方式解释不予受理原因。 国家税务总局稽查局举报中心对本级收到的检举事项应当进行甄别。对本办法第三条规定以外的检举事项，转送有处理权的单位或者部门；对本办法第三条规定范围内的检举事项，按属地管理原则转送相关举报中心，由该举报中心审查并决定是否受理。国家税务总局稽查局举报中心应当定期向相关举报中心了解所转送检举事项的受理情况，对应受理未受理的应予以督办。"},{"i":18,"n":"第十八条","txt":"未设立稽查局的县税务局受理的检举事项，符合本办法第三条规定的，提交上一级税务局稽查局举报中心统一处理。 各级跨区域稽查局受理的检举事项，符合本办法第三条规定的，提交同级税务局稽查局备案后处理。"},{"i":19,"n":"第十九条","txt":"检举事项管辖有争议的，由争议各方本着有利于案件查处的原则协商解决；不能协商一致的，报请共同的上一级税务机关协调或者决定。"},{"i":20,"n":"第二十条","txt":"检举事项受理后，应当分级分类，按照以下方式处理: （一）检举内容详细、税收违法行为线索清楚、证明资料充分的，由稽查局立案检查。 （二）检举内容与线索较明确但缺少必要证明资料，有可能存在税收违法行为的，由稽查局调查核实。发现存在税收违法行为的，立案检查；未发现的，作查结处理。 （三）检举对象明确，但其他检举事项不完整或者内容不清、线索不明的，可以暂存待查，待检举人将情况补充完整以后，再进行处理。 （四）已经受理尚未查结的检举事项，再次检举的，可以合并处理。 （五）本办法第三条规定以外的检举事项，转交有处理权的单位或者部门。"},{"i":21,"n":"第二十一条","txt":"举报中心可以税务机关或者以自己的名义向下级税务机关督办、交办检举事项。"},{"i":22,"n":"第二十二条","txt":"举报中心应当在检举事项受理之日起十五个工作日内完成分级分类处理，特殊情况除外。 查处部门应当在收到举报中心转来的检举材料之日起三个月内办理完毕；案情复杂无法在期限内办理完毕的，可以延期。"},{"i":23,"n":"第二十三条","txt":"税务局稽查局对督办案件的处理结果应当认真审查。对于事实不清、处理不当的，应当通知承办机关补充调查或者重新调查，依法处理。"},{"i":24,"n":"第二十四条","txt":"举报中心应当严格管理检举材料，逐件登记已受理检举事项的主要内容、办理情况和检举人、被检举人的基本情况。"},{"i":25,"n":"第二十五条","txt":"已接收的检举材料原则上不予退还。不予受理的检举材料，登记检举事项的基本信息和不予受理原因后，经本级稽查局负责人批准可以销毁。"},{"i":26,"n":"第二十六条","txt":"暂存待查的检举材料，若在受理之日起两年内未收到有价值的补充材料，可以销毁。"},{"i":27,"n":"第二十七条","txt":"督办案件的检举材料应当专门管理，并按照规定办理督办案件材料的转送、报告等具体事项。"},{"i":28,"n":"第二十八条","txt":"检举材料的保管和整理，应当按照档案管理的有关规定办理。"},{"i":29,"n":"第二十九条","txt":"举报中心每年度对检举案件和有关事项的数量、类别及办理情况等进行汇总分析，形成年度分析报告，并按规定报送。"},{"i":30,"n":"第三十条","txt":"实名检举人可以要求答复检举事项的处理情况与查处结果。 实名检举人要求答复处理情况时，应当配合核对身份；要求答复查处结果时，应当出示检举时所提供的有效身份证件。 举报中心可以视具体情况采取口头或者书面方式答复实名检举人。"},{"i":31,"n":"第三十一条","txt":"实名检举事项的处理情况，由作出处理行为的税务机关的举报中心答复。 将检举事项督办、交办、提交或者转交的，应当告知去向；暂存待查的，应当建议检举人补充资料。"},{"i":32,"n":"第三十二条","txt":"实名检举事项的查处结果，由负责查处的税务机关的举报中心答复。 实名检举人要求答复检举事项查处结果的，检举事项查结以后，举报中心可以将与检举线索有关的查处结果简要告知检举人，但不得告知其检举线索以外的税收违法行为的查处情况，不得提供执法文书及有关案情资料。"},{"i":33,"n":"第三十三条","txt":"12366纳税服务热线接收检举事项并转交举报中心或者相关业务部门后，可以应检举人要求将举报中心或者相关业务部门反馈的受理情况告知检举人。"},{"i":34,"n":"第三十四条","txt":"检举事项经查证属实，为国家挽回或者减少损失的，按照财政部和国家税务总局的有关规定对实名检举人给予相应奖励。"},{"i":35,"n":"第三十五条","txt":"检举人不愿提供个人信息或者不愿公开检举行为的，税务机关应当予以尊重和保密。"},{"i":36,"n":"第三十六条","txt":"税务机关应当在职责范围内依法保护检举人、被检举人的合法权益。"},{"i":37,"n":"第三十七条","txt":"税务机关工作人员与检举事项或者检举人、被检举人有直接利害关系的，应当回避。 检举人有正当理由并且有证据证明税务机关工作人员应当回避的，经本级税务机关负责人或者稽查局负责人批准以后，予以回避。"},{"i":38,"n":"第三十八条","txt":"税务机关工作人员必须严格遵守以下保密规定： （一）检举事项的受理、登记、处理及查处，应当依照国家有关法律、行政法规等规定严格保密，并建立健全工作责任制，不得私自摘抄、复制、扣压、销毁检举材料； （二）严禁泄露检举人的姓名、身份、单位、地址、联系方式等情况，严禁将检举情况透露给被检举人及与案件查处无关的人员； （三）调查核实情况和立案检查时不得出示检举信原件或者复印件，不得暴露检举人的有关信息，对匿名的检举书信及材料，除特殊情况以外，不得鉴定笔迹； （四）宣传报道和奖励检举有功人员，未经检举人书面同意，不得公开检举人的姓名、身份、单位、地址、联系方式等情况。"},{"i":39,"n":"第三十九条","txt":"税务机关工作人员违反本办法规定，将检举人的检举材料或者有关情况提供给被检举人或者与案件查处无关人员的，依法给予行政处分。"},{"i":40,"n":"第四十条","txt":"税务机关工作人员打击报复检举人的，视情节和后果，依法给予行政处分；涉嫌犯罪的，移送司法机关依法处理。"},{"i":41,"n":"第四十一条","txt":"税务机关工作人员不履行职责、玩忽职守、徇私舞弊，给检举工作造成损失的，应当给予批评教育；情节严重的，依法给予行政处分并调离工作岗位；涉嫌犯罪的，移送司法机关依法处理。"},{"i":42,"n":"第四十二条","txt":"税收违法检举案件中涉及税务机关或者税务人员违纪违法问题的，应当按照规定移送有关部门依纪依法处理。"},{"i":43,"n":"第四十三条","txt":"检举人违反本办法第九条规定的，税务机关工作人员应当对检举人进行劝阻、批评和教育；经劝阻、批评和教育无效的，可以联系有关部门依法处理。"},{"i":44,"n":"第四十四条","txt":"本办法所称的检举事项查结，是指检举案件的结论性文书生效，或者检举事项经调查核实后未发现税收违法行为。"},{"i":45,"n":"第四十五条","txt":"国家税务总局各省、自治区、直辖市和计划单列市税务局可以根据本办法制定具体的实施办法。"},{"i":46,"n":"第四十六条","txt":"本办法自2020年1月1日起施行。《税收违法行为检举管理办法》（国家税务总局令第24号公布）同时废止。"}],"shuikuanjiaokutuikugongzuoguicheng":[{"i":1,"n":"第一条","txt":"为规范税款缴库及退库管理，保障国家税收收入的安全完整，维护纳税人合法权益，适应税收信息化发展需要，根据《中华人民共和国税收征收管理法》《中华人民共和国预算法》《中华人民共和国国家金库条例》等法律法规，制定本规程。"},{"i":2,"n":"第二条","txt":"税务机关、纳税人、扣缴义务人、代征代售人办理税款缴库和退库业务，适用本规程。"},{"i":3,"n":"第三条","txt":"本规程所称税款缴库是指税务机关、扣缴义务人、代征代售人依照法律法规或者委托代征税款协议，开具法定税收票证，将征收的税款、滞纳金、罚没款等各项收入（以下统称税款）缴入国家金库（以下简称国库），以及纳税人直接通过银行将应缴纳的税款缴入国库；税款退库是指税务机关对经财政部门授权办理的税收收入退库业务，依照法律法规，开具法定税收票证，通过国库向纳税人退还应退税款。 税务机关按照国家政策规定和预算管理要求，对税款预算科目、预算级次、收款国库等事项，通过国库进行调整的税款调库业务，适用本规程。"},{"i":4,"n":"第四条","txt":"税款缴库、退库应当遵循依法、规范、安全、效率、简便的原则。"},{"i":5,"n":"第五条","txt":"税款缴库、退库按照办理凭证的不同分为手工缴库、退库和电子缴库、退库。"},{"i":6,"n":"第六条","txt":"国家积极推广以横向联网电子缴税系统为依托的税款电子缴库、退库工作。 税务机关应当加强与国库、银行等部门间的协作，保持税收征管系统与横向联网电子缴税系统稳定，确保电子缴库、退库信息安全、完整和不可篡改，保证电子缴库、退库税款准确。"},{"i":7,"n":"第七条","txt":"税务机关应当按照国家规定的税收征收管理范围和税款预算科目、预算级次办理税款缴库、退库。"},{"i":8,"n":"第八条","txt":"税务机关应当将征收的税款按照国家规定直接缴入国库，不得缴入在国库以外或者国家规定的税款账户以外的任何账户。 任何税务机关不得占压、挪用和截留税款。"},{"i":9,"n":"第九条","txt":"税务机关应当加强税款缴库、退库管理，建立部门、岗位配合和制约机制。"},{"i":10,"n":"第十条","txt":"各级税务机关收入规划核算部门根据本级职责范围，负责制定税款缴库、退库管理制度，办理税款缴库、退库相关业务，反映税款缴库、退库结果，监督税款缴库、退库的规范性、准确性和及时性。"},{"i":11,"n":"第十一条","txt":"《税收缴款书（银行经收专用）》、《税收缴款书（出口货物劳务专用）》和《税收电子缴款书》是税款缴库的法定凭证。"},{"i":12,"n":"第十二条","txt":"税务机关、扣缴义务人、代征代售人、自行填开税收票证的纳税人开具税款缴库凭证，应当对开具内容与开具依据进行核对。 核对内容包括登记注册类型、缴款单位（人）识别号、缴款单位（人）名称、开户银行、账号、税务机关、收款国库、预算科目编码、预算科目名称、预算级次、品目名称、税款限缴日期、实缴金额等。 开具依据包括纳税申报表、代扣代收税款报告表、延期缴纳税款申请审批表、税务事项通知书、税务处理决定书、税务行政处罚决定书、税务行政复议决定书、生效的法院判决书以及其他记载税款缴库凭证内容的纸质资料或电子信息。"},{"i":13,"n":"第十三条","txt":"税务机关、纳税人、扣缴义务人、代征代售人等向银行传递《税收缴款书（银行经收专用）》《税收缴款书（出口货物劳务专用）》，由银行据以收纳报解税款后缴入国库的缴库方式为手工缴库。 税务机关将记录纳税人、扣缴义务人、代征代售人应缴税款信息的《税收电子缴款书》通过横向联网电子缴税系统发送给国库，国库转发给银行，银行据以收纳报解税款后缴入国库的缴库方式为电子缴库。"},{"i":14,"n":"第十四条","txt":"手工缴库包括直接缴库和汇总缴库两种形式。 直接缴库的，由纳税人持《税收缴款书（银行经收专用）》或《税收缴款书（出口货物劳务专用）》，直接到银行缴纳税款，银行据以收纳报解税款后缴入国库。 汇总缴库分为税务机关汇总缴库和扣缴义务人、代征代售人汇总缴库： （一）税务机关汇总缴库的，由纳税人、扣缴义务人、代征代售人向税务机关缴纳或者解缴税款，税务机关根据所收税款，汇总开具《税收缴款书（银行经收专用）》，向银行解缴，银行据以收纳报解税款后缴入国库，应予缴库的税务代保管资金和待缴库税款，按纳税人分别开具《税收缴款书（银行经收专用）》； （二）扣缴义务人、代征代售人汇总缴库的，由纳税人向扣缴义务人、代征代售人缴纳税款，扣缴义务人、代征代售人根据所扣、所收税款，汇总开具《税收缴款书（银行经收专用）》，向银行解缴，银行据以收纳报解税款后缴入国库。"},{"i":15,"n":"第十五条","txt":"直接缴库时，纳税人应当在税款缴库凭证载明的税款限缴日期内，到银行办理税款的缴纳；超过税款限缴日期的，由税务机关计算纳税人应缴滞纳金，开具税款缴库凭证，纳税人到银行办理税款和滞纳金的缴纳。 税务机关汇总缴库时，应当于收取税款的当日或次日向银行办理税款解缴；地区偏远无法及时办理的，应当按照限期限额的规定向银行办理税款解缴。扣缴义务人、代征代售人汇总缴库时，应当在到税务机关办理税收票款结报缴销前向银行办理税款解缴；解缴迟延的，参照上款规定，办理滞纳金、违约金的缴纳。"},{"i":16,"n":"第十六条","txt":"电子缴库包括划缴入库和自缴入库两种形式。 划缴入库的，由税务机关将纳税人、扣缴义务人、代征代售人应缴库税款的信息，通过横向联网电子缴税系统发送给国库，国库转发给纳税人、扣缴义务人、代征代售人签订授权（委托）划缴协议的开户银行，开户银行从签约指定账户将款项划至国库。 自缴入库的，由纳税人、扣缴义务人、代征代售人通过银行或POS机布设机构，经横向联网电子缴税系统向税务机关查询其应缴税款信息并予以确认，银行或POS机布设机构办理税款实时入库。 条件具备时，税务机关可以通过电子缴库方式，办理税务代保管资金和待缴库税款的缴库。"},{"i":17,"n":"第十七条","txt":"用划缴入库形式缴库时，税务机关可以将应缴税款信息分户发送至横向联网电子缴税系统办理税款实时划缴入库，也可以将多户应缴税款信息批量发送横向联网电子缴税系统办理税款定时划缴入库。"},{"i":18,"n":"第十八条","txt":"授权（委托）划缴协议是纳税人、扣缴义务人、代征代售人等缴款人准予其指定账户的开户银行根据税务机关发送的应缴税信息，从该指定账户中扣划税款缴库的书面约定。协议的基本要素应当包括协议编号、签约各方名称、签约方地址、缴款人税务登记号、划缴税款账户名称及账号、缴款人开户银行行号、清算行行号及名称、签约日期，签约各方的权利和义务等。"},{"i":19,"n":"第十九条","txt":"由于横向联网电子缴税系统故障等非纳税人、扣缴义务人原因造成税款缴库不成功的，对纳税人、扣缴义务人不加征滞纳金。"},{"i":20,"n":"第二十条","txt":"纳税人从异地或第三方账户缴纳的不能直接缴库的非现金税款，由直接负责税款征收的县以上税务机关通过国库“待缴库税款”专户收缴，并在收到国库发送的收账回单的当日或次日，核对收账回单、纳税申报表、税务处理决定书等凭证，分纳税人填开缴库凭证，将税款解缴入库。 “待缴库税款”专户收缴税款时，应当区分以下情况办理： （一）通过国内汇款方式缴纳税款的，税务机关应当通知纳税人或其他汇款人将税款直接汇入国库“待缴库税款”专户。 （二）通过国外汇款方式缴纳税款的，税务机关应当通知纳税人或其他汇款人将税款汇入国库商税务、财政部门选定的具备结汇资格的银行，指定银行按照当日外汇买入价办理结汇并将税款划转“待缴库税款”专户。"},{"i":21,"n":"第二十一条","txt":"《税收收入退还书》《税收收入电子退还书》是税款退库的法定凭证。 税务机关向国库传递《税收收入退还书》，由国库据以办理税款退还的方式为手工退库。 税务机关通过横向联网电子缴税系统将记录应退税款信息的《税收收入电子退还书》发送给国库，国库据以办理税款退还的方式为电子退库。"},{"i":22,"n":"第二十二条","txt":"税务机关办理税款退库应当直接退还纳税人。 纳税人经由扣缴义务人代扣代收的税款发生多缴的，经纳税人同意，税务机关可以将税款退还扣缴义务人，由扣缴义务人转退纳税人。 国家政策明确规定税款退给非原纳税人的，税务机关应当向非原纳税人退还，退库办理程序参照本章规定执行。"},{"i":23,"n":"第二十三条","txt":"税务机关直接向纳税人退还税款的，应当由纳税人填写退税申请。税务机关通过扣缴义务人向纳税人退还税款的，可以由扣缴义务人填写退税申请。"},{"i":24,"n":"第二十四条","txt":"税务机关应当在法定期限内办理税款退库。 税务机关发现纳税人多缴税款的，应当立即核实应退税额、账户等相关情况，通知纳税人或扣缴义务人提交退税申请，自接到纳税人或扣缴义务人退税申请之日起10日内办理退库手续。 纳税人发现多缴税款要求退还的，税务机关应当自接到纳税人或扣缴义务人退税申请之日起30日内查实并办理退库手续。"},{"i":25,"n":"第二十五条","txt":"除出口退税以外，纳税人既有应退税款又有欠缴税款的，税务机关可以将纳税人的应退税款和利息先抵扣欠缴的税款；抵扣后有余额的，办理应退余额的退库。"},{"i":26,"n":"第二十六条","txt":"县以上税务机关收入规划核算部门具体办理税款退库工作，根据退税申请相关资料和纳税人欠税情况，复核退税依据、原完税情况、退税金额、退税收款账户等退库凭证项目内容，复核无误的，正确适用预算科目、预算级次，开具税款退库凭证。退税申请相关资料不齐全、相关项目内容不准确的，不得开具退库凭证办理退库；应予抵扣欠税的，办理税款抵扣手续。 退税申请相关资料包括：签有退税核实部门意见的退税申请书、原完税凭证、出口退（免）税汇总申报表、减免税审批文书、纳税申报表、税务稽查结论、税务处理决定书、纳税评估文书、税务行政复议决定书、生效的法院判决书、税务机关认可的其他记载应退税款内容的资料或电子信息。 税收征管系统中可以查询到纳税申报表、税款缴库等电子信息的，可以不再通过书面资料复核。"},{"i":27,"n":"第二十七条","txt":"手工退库的，《税收收入退还书》应当经税务机关主要负责人签发并加盖在国库预留的退税专用印鉴，连同退税申请书，由税务机关送国库办理退库手续；电子退库的，《税收收入电子退还书》应当经税务机关复核人员复核授权，连同相关电子文件，由税务机关向国库发送办理退库手续。"},{"i":28,"n":"第二十八条","txt":"税务机关直接向纳税人退还税款时，应当将税款退至纳税人原缴款账户。税务机关通过扣缴义务人向纳税人退还税款的，应当将税款退至扣缴义务人原缴款账户。 由于特殊情况不能退至纳税人、扣缴义务人原缴款账户的，纳税人、扣缴义务人在申请退税时应当书面说明理由，提交相关证明资料，并指定接受退税的其他账户及接受退税单位（人）名称。"},{"i":29,"n":"第二十九条","txt":"税务机关对未开设银行账户的纳税人确需以现金方式退税的，应当在《税收收入退还书》备注栏注明“退付现金”和原完税凭证号码、纳税人身份证号码，送当地国库办理退库手续，同时通知纳税人到指定银行领取退还税款。"},{"i":30,"n":"第三十条","txt":"境外纳税人以外币兑换人民币缴纳的税款需要退库的，税务机关应当在《税收收入退还书》上加盖\"可退付外币\"戳记，并根据纳税人缴纳的外汇税款币种注明退付的外币币种，送交国库通过指定银行退至境外纳税人账户。"},{"i":31,"n":"第三十一条","txt":"根据《中华人民共和国税收征收管理法》及其实施细则规定应当向纳税人退付利息的，按照税务机关办理退税手续当天中国人民银行规定的活期存款利率计算利息。 办理退税手续当天是指开具《税收收入退还书》或《税收收入电子退还书》、办理应退税款抵扣欠缴税款的当天。"},{"i":32,"n":"第三十二条","txt":"退付给纳税人的利息，用冲减应退税款原入库预算科目的办法，从入库收入中退付。"},{"i":33,"n":"第三十三条","txt":"退库税款预算科目和预算级次应当与原入库税款一致，但是，退库税款有专用退库预算科目，原预算科目、预算级次已修订或国家另有规定的除外。"},{"i":34,"n":"第三十四条","txt":"除出口退税以外，应退税款超过一定额度标准的，应当事先向市（不含县级市，下同）或省（自治区、直辖市和计划单列市，以下简称省）税务机关报告，具体标准和报告程序由各省税务机关确定。"},{"i":35,"n":"第三十五条","txt":"税务机关办理税款调库时，应当开具《更正（调库）通知书》等凭证，送国库进行业务处理。 税款调库可以用传递纸质调库凭证的手工调库方式办理，也可以采用通过横向联网电子缴税系统发送电子调库凭证的电子调库方式办理。"},{"i":36,"n":"第三十六条","txt":"税款调库包括出口免抵调、应退税款跨预算科目抵扣欠税、税款更正等业务。"},{"i":37,"n":"第三十七条","txt":"退库办理部门根据免抵调政策办理税款调库时，应当根据免抵税数额和免抵调库指标，开具《更正（调库）通知书》，并于开具当日或次日连同开具依据一起送当地国库办理税款调库手续。"},{"i":38,"n":"第三十八条","txt":"税务机关办理应退税款抵扣欠缴税款业务，并且应退税款与欠缴税款属于不同预算科目的，退库办理部门应当根据《应退税款抵扣欠缴税款通知书》填开《更正（调库）通知书》，送国库办理调库手续。"},{"i":39,"n":"第三十九条","txt":"税款缴库、退库业务办理完成后，税务机关或国库发现双方入库或退库税款预算科目、预算级次、收款国库等要素不一致需要调整的，应当根据\"谁差错、谁更正\"的原则，按以下程序办理税款更正调库手续： （一）国库数据发生差错、税务机关数据正确的，税务机关应当及时将差错数据情况告知国库，由国库填写《更正（调库）通知书》办理更正调库； （二）国库和税务机关数据同时发生差错的，由税务机关进行数据红字更正处理，同时填写《更正（调库）通知书》，送国库办理更正调库。"},{"i":40,"n":"第四十条","txt":"由于政策性原因需要对入库税款预算科目和预算级次等进行调整的，税务机关应当填写《更正（调库）通知书》，送国库办理更正调库。"},{"i":41,"n":"第四十一条","txt":"银行和国库返回缴库、退库和调库凭证后，税务机关应当与留存凭证的相关项目核对，进行凭证销号和税款对账，确认税款缴库、退库和调库业务的完成，并且完成相关业务税收会计核算原始凭证的收集。 根据税款缴库、退库和调库业务的处理方式，销号和对账可以由税务机关根据国库返回的纸质凭证或电子凭证信息，手工进行销号、对账或者由税收征管系统自动进行电子销号、对账。"},{"i":42,"n":"第四十二条","txt":"手工缴库、退库、调库的，税务机关应当在收到银行、国库返回的纸质缴库、退库、调库凭证相关联次的当日或次日，根据银行收讫章日期、国库收讫章日期、国库退库转讫章日期、国库调库业务章日期进行税款上解、入库、退库和调库销号。 电子缴库、退库、调库的，税务机关应当在横向联网电子缴税系统返回电子缴库、退库、调库凭证信息的当日，根据电子缴库凭证的扣款成功日期、电子缴库凭证的入库日期、电子退库凭证的退还日期、电子调库更正凭证的办理日期进行税款上解、入库、退库和调库销号。 电子信息未能及时、准确返回的，应当在与国库确认业务办理成功后，手工进行销号。"},{"i":43,"n":"第四十三条","txt":"每日、每月、每年业务终了后，县税务机关应当将税款缴库、退库、调库数据与国库预算收入日报表（月报表、年报表）数据进行对账，对账项目包括预算科目、预算级次和税款金额。 省、市税务机关与国库对账周期由各省税务机关商当地国库自行确定，但每年业务终了后，必须与同级国库进行对账。"},{"i":44,"n":"第四十四条","txt":"对账不一致时，税务机关数据发生差错而国库数据正确的，税务机关应当通过数据红字更正方式或补充更正方式处理。 国库和税务机关数据同时发生差错，或者国库数据发生差错而税务机关数据正确的，通过税款更正调库办理。"},{"i":45,"n":"第四十五条","txt":"年终对账无误后，税务机关应当在加盖国家金库章的国库预算收入年报表上加盖单位公章，按规定及时反馈国库。"},{"i":46,"n":"第四十六条","txt":"税务机关应当强化内部制约机制，严格按照各项法律法规和财经纪律办理税款缴库、退库、调库及销号对账等手续，确保国家税款的安全、完整、准确。"},{"i":47,"n":"第四十七条","txt":"税务机关应当定期对下级税务机关、扣缴义务人、代征代售人的税款缴库、退库的及时性、准确性等情况进行检查。"},{"i":48,"n":"第四十八条","txt":"税务机关应当及时对税款缴库、退库、调库凭证及相关资料进行归档，保存期限按国家有关规定执行。"},{"i":49,"n":"第四十九条","txt":"税务机关工作人员违反本规程的，应当根据情节轻重，给予批评教育、责令做出检查、诫勉谈话或调整工作岗位处理；构成违纪的，按照《中华人民共和国税收征收管理法》《中华人民共和国公务员法》《行政机关公务员处分条例》《财政违法行为处罚处分条例》《税收违法违纪行为处分规定》及有关规定给予处分；涉嫌犯罪的，移送司法机关。"},{"i":50,"n":"第五十条","txt":"纳税人、扣缴义务人违反本规程的，按照《中华人民共和国税收征收管理法》及相关规定进行处理；涉嫌犯罪的，移送司法机关。"},{"i":51,"n":"第五十一条","txt":"税务机关与代征代售人签订代征代售合同时，应当就违反本规程及相关规定的责任进行约定，并按约定及其他有关规定追究责任；涉嫌犯罪的，移送司法机关。"},{"i":52,"n":"第五十二条","txt":"税务机关依照法律法规征收的各种基金、费办理缴库、退库，参照本规程执行。 各级政府部门委托税务机关征收的各种基金、费办理缴库、退库，可以参照本规程执行。"},{"i":53,"n":"第五十三条","txt":"本规程所称银行，是指经收预算收入的银行、信用社等银行业金融机构。"},{"i":54,"n":"第五十四条","txt":"本规程所称应予缴库的税务代保管资金是指按照《税务代保管资金账户管理办法》规定缴入税务代保管资金账户的款项中经确认属于税款的资金；待缴库税款是指按照《待缴库税款收缴管理办法》规定缴入“待缴库税款”专户的税款。"},{"i":55,"n":"第五十五条","txt":"各省税务机关应当根据本规程制定本地区的具体实施办法。"},{"i":56,"n":"第五十六条","txt":"本规程自2014年9月1日起施行。"}],"nashuidanbaoshixingbanfa":[{"i":1,"n":"第一条","txt":"为规范纳税担保行为，保障国家税收收入，保护纳税人和其他当事人的合法权益，根据《中华人民共和国税收征收管理法》（以下简称《税收征管法》）及其实施细则和其他法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称纳税担保，是指经税务机关同意或确认，纳税人或其他自然人、法人、经济组织以保证、抵押、质押的方式，为纳税人应当缴纳的税款及滞纳金提供担保的行为。 纳税担保人包括以保证方式为纳税人提供纳税担保的纳税保证人和其他以未设置或者未全部设置担保物权的财产为纳税人提供纳税担保的第三人。"},{"i":3,"n":"第三条","txt":"纳税人有下列情况之一的，适用纳税担保： （一）税务机关有根据认为从事生产、经营的纳税人有逃避纳税义务行为，在规定的纳税期之前经责令其限期缴纳应纳税款，在限期内发现纳税人有明显的转移、隐匿其应纳税的商品、货物以及其他财产或者应纳税收入的迹象，责成纳税人提供纳税担保的； （二）欠缴税款、滞纳金的纳税人或者其法定代表人需要出境的； （三）纳税人同税务机关在纳税上发生争议而未缴清税款，需要申请行政复议的； （四）税收法律、行政法规规定可以提供纳税担保的其他情形。"},{"i":4,"n":"第四条","txt":"扣缴义务人按照《税收征管法》第八十八条规定需要提供纳税担保的，适用本办法的规定。 纳税担保人按照《税收征管法》第八十八条规定需要提供纳税担保的，应当按照本办法规定的抵押、质押方式，以其财产提供纳税担保；纳税担保人已经以其财产为纳税人向税务机关提供担保的，不再需要提供新的担保。"},{"i":5,"n":"第五条","txt":"纳税担保范围包括税款、滞纳金和实现税款、滞纳金的费用。费用包括抵押、质押登记费用，质押保管费用，以及保管、拍卖、变卖担保财产等相关费用支出。 用于纳税担保的财产、权利的价值不得低于应当缴纳的税款、滞纳金，并考虑相关的费用。纳税担保的财产价值不足以抵缴税款、滞纳金的，税务机关应当向提供担保的纳税人或纳税担保人继续追缴。"},{"i":6,"n":"第六条","txt":"用于纳税担保的财产、权利的价格估算，除法律、行政法规另有规定外，由税务机关按照税收征管法实施细则第六十四条规定的方式，参照同类商品的市场价、出厂价或者评估价估算。"},{"i":7,"n":"第七条","txt":"纳税保证，是指纳税保证人向税务机关保证，当纳税人未按照税收法律、行政法规规定或者税务机关确定的期限缴清税款、滞纳金时，由纳税保证人按照约定履行缴纳税款及滞纳金的行为。税务机关认可的，保证成立；税务机关不认可的，保证不成立。 本办法所称纳税保证为连带责任保证，纳税人和纳税保证人对所担保的税款及滞纳金承担连带责任。当纳税人在税收法律、行政法规或税务机关确定的期限届满未缴清税款及滞纳金的，税务机关即可要求纳税保证人在其担保范围内承担保证责任，缴纳担保的税款及滞纳金。"},{"i":8,"n":"第八条","txt":"纳税保证人，是指在中国境内具有纳税担保能力的自然人、法人或者其他经济组织。法人或其他经济组织财务报表资产净值超过需要担保的税额及滞纳金2倍以上的，自然人、法人或其他经济组织所拥有或者依法可以处分的未设置担保的财产的价值超过需要担保的税额及滞纳金的，为具有纳税担保能力。"},{"i":9,"n":"第九条","txt":"国家机关，学校、幼儿园、医院等事业单位，社会团体不得作为纳税保证人。 企业法人的职能部门不得为纳税保证人。企业法人的分支机构有法人书面授权的，可以在授权范围内提供纳税担保。 有以下情形之一的，不得作为纳税保证人： （一）有偷税、抗税、骗税、逃避追缴欠税行为被税务机关、司法机关追究过法律责任未满2年的； （二）因有税收违法行为正在被税务机关立案处理或涉嫌刑事犯罪被司法机关立案侦查的； （三）纳税信誉等级被评为C级以下的； （四）在主管税务机关所在地的市（地、州）没有住所的自然人或税务登记不在本市（地、州）的企业； （五）无民事行为能力或限制民事行为能力的自然人； （六）与纳税人存在担保关联关系的； （七）有欠税行为的。"},{"i":10,"n":"第十条","txt":"纳税保证人同意为纳税人提供纳税担保的，应当填写纳税担保书。纳税担保书应当包括以下内容： （一）纳税人应缴纳的税款及滞纳金数额、所属期间、税种、税目名称； （二）纳税人应当履行缴纳税款及滞纳金的期限； （三）保证担保范围及担保责任； （四）保证期间和履行保证责任的期限； （五）保证人的存款账号或者开户银行及其账号； （六）税务机关认为需要说明的其他事项。"},{"i":11,"n":"第十一条","txt":"纳税担保书须经纳税人、纳税保证人签字盖章并经税务机关签字盖章同意方为有效。 纳税担保从税务机关在纳税担保书签字盖章之日起生效。"},{"i":12,"n":"第十二条","txt":"保证期间为纳税人应缴纳税款期限届满之日起60日，即税务机关自纳税人应缴纳税款的期限届满之日起60日内有权要求纳税保证人承担保证责任，缴纳税款、滞纳金。 履行保证责任的期限为15日，即纳税保证人应当自收到税务机关的纳税通知书之日起15日内履行保证责任，缴纳税款及滞纳金。 纳税保证期间内税务机关未通知纳税保证人缴纳税款及滞纳金以承担担保责任的，纳税保证人免除担保责任。"},{"i":13,"n":"第十三条","txt":"纳税人在规定的期限届满未缴清税款及滞纳金，税务机关在保证期限内书面通知纳税保证人的，纳税保证人应按照纳税担保书约定的范围，自收到纳税通知书之日起15日内缴纳税款及滞纳金，履行担保责任。 纳税保证人未按照规定的履行保证责任的期限缴纳税款及滞纳金的，由税务机关发出责令限期缴纳通知书，责令纳税保证人在限期15日内缴纳；逾期仍未缴纳的，经县以上税务局（分局）局长批准，对纳税保证人采取强制执行措施，通知其开户银行或其他金融机构从其存款中扣缴所担保的纳税人应缴纳的税款、滞纳金，或扣押、查封、拍卖、变卖其价值相当于所担保的纳税人应缴纳的税款、滞纳金的商品、货物或者其他财产，以拍卖、变卖所得抵缴担保的税款、滞纳金。"},{"i":14,"n":"第十四条","txt":"纳税抵押，是指纳税人或纳税担保人不转移对本办法第十五条 所列财产的占有，将该财产作为税款及滞纳金的担保。纳税人逾期未缴清税款及滞纳金的，税务机关有权依法处置该财产以抵缴税款及滞纳金。 前款规定的纳税人或者纳税担保人为抵押人，税务机关为抵押权人，提供担保的财产为抵押物。"},{"i":15,"n":"第十五条","txt":"下列财产可以抵押： （一）抵押人所有的房屋和其他地上定着物； （二）抵押人所有的机器、交通运输工具和其他财产； （三）抵押人依法有权处分的国有的房屋和其他地上定着物； （四）抵押人依法有权处分的国有的机器、交通运输工具和其他财产； （五）经设区的市、自治州以上税务机关确认的其他可以抵押的合法财产。"},{"i":16,"n":"第十六条","txt":"以依法取得的国有土地上的房屋抵押的，该房屋占用范围内的国有土地使用权同时抵押。 以乡（镇）、村企业的厂房等建筑物抵押的，其占用范围内的土地使用权同时抵押。"},{"i":17,"n":"第十七条","txt":"下列财产不得抵押： （一）土地所有权； （二）土地使用权，但本办法第十六条规定的除外； （三）学校、幼儿园、医院等以公益为目的的事业单位、社会团体、民办非企业单位的教育设施、医疗卫生设施和其他社会公益设施； （四）所有权、使用权不明或者有争议的财产； （五）依法被查封、扣押、监管的财产； （六）依法定程序确认为违法、违章的建筑物； （七）法律、行政法规规定禁止流通的财产或者不可转让的财产； （八）经设区的市、自治州以上税务机关确认的其他不予抵押的财产。"},{"i":18,"n":"第十八条","txt":"学校、幼儿园、医院等以公益为目的的事业单位、社会团体，可以其教育设施、医疗卫生设施和其他社会公益设施以外的财产为其应缴纳的税款及滞纳金提供抵押。"},{"i":19,"n":"第十九条","txt":"纳税人提供抵押担保的，应当填写纳税担保书和纳税担保财产清单。纳税担保书应当包括以下内容： （一）担保的纳税人应缴纳的税款及滞纳金数额、所属期间、税种名称、税目； （二）纳税人履行应缴纳税款及滞纳金的期限； （三）抵押物的名称、数量、质量、状况、所在地、所有权权属或者使用权权属； （四）抵押担保的范围及担保责任； （五）税务机关认为需要说明的其他事项。 纳税担保财产清单应当写明财产价值以及相关事项。纳税担保书和纳税担保财产清单须经纳税人签字盖章并经税务机关确认。"},{"i":20,"n":"第二十条","txt":"纳税抵押财产应当办理抵押物登记。纳税抵押自抵押物登记之日起生效。纳税人应向税务机关提供由以下部门出具的抵押登记的证明及其复印件（以下简称证明材料）： （一）以城市房地产或者乡（镇）、村企业的厂房等建筑物抵押的，提供县级以上地方人民政府规定部门出具的证明材料； （二）以船舶、车辆抵押的，提供运输工具的登记部门出具的证明材料； （三）以企业的设备和其他动产抵押的，提供财产所在地的工商行政管理部门出具的证明材料或者纳税人所在地的公证部门出具的证明材料。"},{"i":21,"n":"第二十一条","txt":"抵押期间，经税务机关同意，纳税人可以转让已办理登记的抵押物，并告知受让人转让物已经抵押的情况。 纳税人转让抵押物所得的价款，应当向税务机关提前缴纳所担保的税款、滞纳金。超过部分，归纳税人所有，不足部分由纳税人缴纳或提供相应的担保。"},{"i":22,"n":"第二十二条","txt":"在抵押物灭失、毁损或者被征用的情况下，税务机关应该就该抵押物的保险金、赔偿金或者补偿金要求优先受偿，抵缴税款、滞纳金。 抵押物灭失、毁损或者被征用的情况下，抵押权所担保的纳税义务履行期未满的，税务机关可以要求将保险金、赔偿金或补偿金等作为担保财产。"},{"i":23,"n":"第二十三条","txt":"纳税人在规定的期限内未缴清税款、滞纳金的，税务机关应当依法拍卖、变卖抵押物，变价抵缴税款、滞纳金。"},{"i":24,"n":"第二十四条","txt":"纳税担保人以其财产为纳税人提供纳税抵押担保的，按照纳税人提供抵押担保的规定执行；纳税担保书和纳税担保财产清单须经纳税人、纳税担保人签字盖章并经税务机关确认。 纳税人在规定的期限届满未缴清税款、滞纳金的，税务机关应当在期限届满之日起15日内书面通知纳税担保人自收到纳税通知书之日起15日内缴纳担保的税款、滞纳金。 纳税担保人未按照前款规定的期限缴纳所担保的税款、滞纳金的，由税务机关责令限期在15日内缴纳；逾期仍未缴纳的，经县以上税务局（分局）局长批准，税务机关依法拍卖、变卖抵押物，抵缴税款、滞纳金。"},{"i":25,"n":"第二十五条","txt":"纳税质押，是指经税务机关同意，纳税人或纳税担保人将其动产或权利凭证移交税务机关占有，将该动产或权利凭证作为税款及滞纳金的担保。纳税人逾期未缴清税款及滞纳金的，税务机关有权依法处置该动产或权利凭证以抵缴税款及滞纳金。纳税质押分为动产质押和权利质押。 动产质押包括现金以及其他除不动产以外的财产提供的质押。 汇票、支票、本票、债券、存款单等权利凭证可以质押。 对于实际价值波动很大的动产或权利凭证，经设区的市、自治州以上税务机关确认，税务机关可以不接受其作为纳税质押。"},{"i":26,"n":"第二十六条","txt":"纳税人提供质押担保的，应当填写纳税担保书和纳税担保财产清单并签字盖章。纳税担保书应当包括以下内容： （一）担保的税款及滞纳金数额、所属期间、税种名称、税目； （二）纳税人履行应缴纳税款、滞纳金的期限； （三）质物的名称、数量、质量、价值、状况、移交前所在地、所有权权属或者使用权权属； （四）质押担保的范围及担保责任； （五）纳税担保财产价值； （六）税务机关认为需要说明的其他事项。 纳税担保财产清单应当写明财产价值及相关事项。 纳税质押自纳税担保书和纳税担保财产清单经税务机关确认和质物移交之日起生效。"},{"i":27,"n":"第二十七条","txt":"以汇票、支票、本票、公司债券出质的，税务机关应当与纳税人背书清单记载“质押”字样。以存款单出质的，应由签发的金融机构核押。"},{"i":28,"n":"第二十八条","txt":"以载明兑现或者提货日期的汇票、支票、本票、债券、存款单出质的，汇票、支票、本票、债券、存款单兑现日期先于纳税义务履行期或者担保期的，税务机关与纳税人约定将兑现的价款用于缴纳或者抵缴所担保的税款及滞纳金。"},{"i":29,"n":"第二十九条","txt":"纳税人在规定的期限内缴清税款及滞纳金的，税务机关应当自纳税人缴清税款及滞纳金之日起3个工作日内返还质物，解除质押关系。 纳税人在规定的期限内未缴清税款、滞纳金的，税务机关应当依法拍卖、变卖质物，抵缴税款、滞纳金。"},{"i":30,"n":"第三十条","txt":"纳税担保人以其动产或财产权利为纳税人提供纳税质押担保的，按照纳税人提供质押担保的规定执行；纳税担保书和纳税担保财产清单须经纳税人、纳税担保人签字盖章并经税务机关确认。 纳税人在规定的期限内缴清税款、滞纳金的，税务机关应当在3个工作日内将质物返还给纳税担保人，解除质押关系。 纳税人在规定的期限内未缴清税款、滞纳金的，税务机关应当在期限届满之日起15日内书面通知纳税担保人自收到纳税通知书之日起15日内缴纳担保的税款、滞纳金。 纳税担保人未按照前款规定的期限缴纳所担保的税款、滞纳金，由税务机关责令限期在15日内缴纳；缴清税款、滞纳金的，税务机关自纳税担保人缴清税款及滞纳金之日起3个工作日内返还质物、解除质押关系；逾期仍未缴纳的，经县以上税务局（分局）局长批准，税务机关依法拍卖、变卖质物，抵缴税款、滞纳金。"},{"i":31,"n":"第三十一条","txt":"纳税人、纳税担保人采取欺骗、隐瞒等手段提供担保的，由税务机关处以1000元以下的罚款；属于经营行为的，处以10000元以下的罚款。 非法为纳税人、纳税担保人实施虚假纳税担保提供方便的，由税务机关处以1000元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"纳税人采取欺骗、隐瞒等手段提供担保，造成应缴税款损失的，由税务机关按照《税收征管法》第六十八条规定处以未缴、少缴税款50%以上5倍以下的罚款。"},{"i":33,"n":"第三十三条","txt":"税务机关负有妥善保管质物的义务。因保管不善致使质物灭失或者毁损，或未经纳税人同意擅自使用、出租、处分质物而给纳税人造成损失的，税务机关应当对直接损失承担赔偿责任。 纳税义务期限届满或担保期间，纳税人或者纳税担保人请求税务机关及时行使权利，而税务机关怠于行使权利致使质物价格下跌造成损失的，税务机关应当对直接损失承担赔偿责任。"},{"i":34,"n":"第三十四条","txt":"税务机关工作人员有下列情形之一的，根据情节轻重给予行政处分： （一）违反本办法规定，对符合担保条件的纳税担保，不予同意或故意刁难的； （二）违反本办法规定，对不符合担保条件的纳税担保，予以批准，致使国家税款及滞纳金遭受损失的； （三）私分、挪用、占用、擅自处分担保财物的； （四）其他违法情形。"},{"i":35,"n":"第三十五条","txt":"纳税担保文书由国家税务总局统一制定。"},{"i":36,"n":"第三十六条","txt":"本办法自2005年7月1日起施行。 附件：1.责成提供纳税担保通知书 　　　2.纳税担保财产清单 　　　3.纳税担保书 　　　4.解除纳税担保通知书"}],"wangluofapiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强普通发票管理，保障国家税收收入，规范网络发票的开具和使用，根据《中华人民共和国发票管理办法》规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内使用网络发票管理系统开具发票的单位和个人办理网络发票管理系统的开户登记、网上领取发票手续、在线开具、传输、查验和缴销等事项，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称网络发票是指符合国家税务总局统一标准并通过国家税务总局及省、自治区、直辖市税务局公布的网络发票管理系统开具的发票。 国家积极推广使用网络发票管理系统开具发票。"},{"i":4,"n":"第四条","txt":"税务机关应加强网络发票的管理，确保网络发票的安全、唯一、便利，并提供便捷的网络发票信息查询渠道；应通过应用网络发票数据分析，提高信息管税水平。"},{"i":5,"n":"第五条","txt":"税务机关应根据开具发票的单位和个人的经营情况，核定其在线开具网络发票的种类、行业类别、开票限额等内容。 开具发票的单位和个人需要变更网络发票核定内容的，可向税务机关提出书面申请，经税务机关确认，予以变更。"},{"i":6,"n":"第六条","txt":"开具发票的单位和个人开具网络发票应登录网络发票管理系统，如实完整填写发票的相关内容及数据，确认保存后打印发票。 开具发票的单位和个人在线开具的网络发票，经系统自动保存数据后即完成开票信息的确认、查验。"},{"i":7,"n":"第七条","txt":"单位和个人取得网络发票时，应及时查询验证网络发票信息的真实性、完整性，对不符合规定的发票，不得作为财务报销凭证，任何单位和个人有权拒收。"},{"i":8,"n":"第八条","txt":"开具发票的单位和个人需要开具红字发票的，必须收回原网络发票全部联次或取得受票方出具的有效证明，通过网络发票管理系统开具金额为负数的红字网络发票。"},{"i":9,"n":"第九条","txt":"开具发票的单位和个人作废开具的网络发票，应收回原网络发票全部联次，注明“作废”， 并在网络发票管理系统中进行发票作废处理。"},{"i":10,"n":"第十条","txt":"开具发票的单位和个人应当在办理变更或者注销税务登记的同时，办理网络发票管理系统的用户变更、注销手续并缴销空白发票。"},{"i":11,"n":"第十一条","txt":"税务机关根据发票管理的需要，可以按照国家税务总局的规定委托其他单位通过网络发票管理系统代开网络发票。 税务机关应当与受托代开发票的单位签订协议，明确代开网络发票的种类、对象、内容和相关责任等内容。"},{"i":12,"n":"第十二条","txt":"开具发票的单位和个人必须如实在线开具网络发票，不得利用网络发票进行转借、转让、虚开发票及其他违法活动。"},{"i":13,"n":"第十三条","txt":"开具发票的单位和个人在网络出现故障，无法在线开具发票时，可离线开具发票。 开具发票后，不得改动开票信息，并于48小时内上传开票信息。"},{"i":14,"n":"第十四条","txt":"开具发票的单位和个人违反本办法规定的，按照《中华人民共和国发票管理办法》有关规定处理。"},{"i":15,"n":"第十五条","txt":"省以上税务机关在确保网络发票电子信息正确生成、可靠存储、查询验证、安全唯一等条件的情况下，可以试行电子发票。"},{"i":16,"n":"第十六条","txt":"本办法自2013年4月1日起施行。"}],"gufenzhishidianqiyeyouguanshuishouwentidezanxinggue72b33":[],"huowuqihuozhengshouzengzhishuijutibanfa":[],"youjinashuishenbaobanfa":[],"zhongdashuiwuanjianshenlibanfa":[{"i":1,"n":"第一条","txt":"为贯彻落实中共中央办公厅、国务院办公厅印发的《关于进一步深化税收征管改革的意见》，推进税务机关科学民主决策，强化内部权力制约，优化税务执法方式，严格规范执法行为，推进科学精确执法，保护纳税人缴费人等税务行政相对人合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国税收征收管理法》，制定本办法。"},{"i":2,"n":"第二条","txt":"省以下各级税务局开展重大税务案件审理工作适用本办法。"},{"i":3,"n":"第三条","txt":"重大税务案件审理应当以事实为根据、以法律为准绳，遵循合法、合理、公平、公正、效率的原则，注重法律效果和社会效果相统一。"},{"i":4,"n":"第四条","txt":"参与重大税务案件审理的人员应当严格遵守国家保密规定和工作纪律，依法为纳税人缴费人等税务行政相对人的商业秘密、个人隐私和个人信息保密。"},{"i":5,"n":"第五条","txt":"省以下各级税务局设立重大税务案件审理委员会（以下简称审理委员会）。 审理委员会由主任、副主任和成员单位组成，实行主任负责制。 审理委员会主任由税务局局长担任，副主任由税务局其他领导担任。审理委员会成员单位包括政策法规、税政业务、纳税服务、征管科技、大企业税收管理、税务稽查、督察内审部门。各级税务局可以根据实际需要，增加其他与案件审理有关的部门作为成员单位。"},{"i":6,"n":"第六条","txt":"审理委员会履行下列职责： （一）拟定本机关审理委员会工作规程、议事规则等制度； （二）审理重大税务案件； （三）指导监督下级税务局重大税务案件审理工作。"},{"i":7,"n":"第七条","txt":"审理委员会下设办公室，办公室设在政策法规部门，办公室主任由政策法规部门负责人兼任。 第八条审理委员会办公室履行下列职责： （一）组织实施重大税务案件审理工作； （二）提出初审意见； （三）制作审理会议纪要和审理意见书； （四）办理重大税务案件审理工作的统计、报告、案卷归档； （五）承担审理委员会交办的其他工作。"},{"i":8,"n":"第九条","txt":"审理委员会成员单位根据部门职责参加案件审理，提出审理意见。 稽查局负责提交重大税务案件证据材料、拟作税务处理处罚意见、举行听证。 稽查局对其提交的案件材料的真实性、合法性、准确性负责。"},{"i":9,"n":"第十条","txt":"参与重大税务案件审理的人员有法律法规规定的回避情形的，应当回避。 重大税务案件审理参与人员的回避，由其所在部门的负责人决定；审理委员会成员单位负责人的回避，由审理委员会主任或其授权的副主任决定。"},{"i":10,"n":"第十一条","txt":"本办法所称重大税务案件包括： （一）重大税务行政处罚案件，具体标准由各省、自治区、直辖市和计划单列市税务局根据本地情况自行制定，报国家税务总局备案； （二）根据《重大税收违法案件督办管理暂行办法》督办的案件； （三）应监察、司法机关要求出具认定意见的案件； （四）拟移送公安机关处理的案件； （五）审理委员会成员单位认为案情重大、复杂，需要审理的案件； （六）其他需要审理委员会审理的案件。 有下列情形之一的案件，不属于重大税务案件审理范围： （一）公安机关已就税收违法行为立案的； （二）公安机关尚未就税收违法行为立案，但被查对象为走逃（失联）企业，并且涉嫌犯罪的； （三）国家税务总局规定的其他情形。"},{"i":11,"n":"第十二条","txt":"本办法第十一条第一款第三项规定的案件经审理委员会审理后，应当将拟处理意见报上一级税务局审理委员会备案。备案5日后可以作出决定。"},{"i":12,"n":"第十三条","txt":"稽查局应当在每季度终了后5日内将稽查案件审理情况备案表送审理委员会办公室备案。"},{"i":13,"n":"第十四条","txt":"稽查局应当在内部审理程序终结后5日内，将重大税务案件提请审理委员会审理。 当事人按照法律、法规、规章有关规定要求听证的，由稽查局组织听证。"},{"i":14,"n":"第十五条","txt":"稽查局提请审理委员会审理案件，应当提交以下案件材料： （一）重大税务案件审理案卷交接单； （二）重大税务案件审理提请书； （三）税务稽查报告； （四）税务稽查审理报告； （五）听证材料； （六）相关证据材料。 重大税务案件审理提请书应当写明拟处理意见，所认定的案件事实应当标明证据指向。 证据材料应当制作证据目录。 稽查局应当完整移交证据目录所列全部证据材料，不能当场移交的应当注明存放地点。"},{"i":15,"n":"第十六条","txt":"审理委员会办公室收到稽查局提请审理的案件材料后，应当在重大税务案件审理案卷交接单上注明接收部门和收到日期，并由接收人签名。 对于证据目录中列举的不能当场移交的证据材料，必要时，接收人在签收前可以到证据存放地点现场查验。"},{"i":16,"n":"第十七条","txt":"审理委员会办公室收到稽查局提请审理的案件材料后，应当在5日内进行审核。 根据审核结果，审理委员会办公室提出处理意见，报审理委员会主任或其授权的副主任批准： （一）提请审理的案件属于本办法规定的审理范围，提交了本办法第十五条规定的材料的，建议受理； （二）提请审理的案件属于本办法规定的审理范围，但未按照本办法第十五条的规定提交相关材料的，建议补正材料； （三）提请审理的案件不属于本办法规定的审理范围的，建议不予受理。"},{"i":17,"n":"第十八条","txt":"重大税务案件应当自批准受理之日起30日内作出审理决定，不能在规定期限内作出审理决定的，经审理委员会主任或其授权的副主任批准，可以适当延长，但延长期限最多不超过15日。 补充调查、请示上级机关或征求有权机关意见、拟处理意见报上一级税务局审理委员会备案的时间不计入审理期限。"},{"i":18,"n":"第十九条","txt":"审理委员会审理重大税务案件，应当重点审查： （一）案件事实是否清楚； （二）证据是否充分、确凿； （三）执法程序是否合法； （四）适用法律是否正确； （五）案件定性是否准确； （六）拟处理意见是否合法适当。"},{"i":19,"n":"第二十条","txt":"审理委员会成员单位应当认真履行职责，根据本办法第十九条的规定提出审理意见，所出具的审理意见应当详细阐述理由、列明法律依据。 审理委员会成员单位审理案件，可以到审理委员会办公室或证据存放地查阅案卷材料，向稽查局了解案件有关情况。"},{"i":20,"n":"第二十一条","txt":"重大税务案件审理采取书面审理和会议审理相结合的方式。"},{"i":21,"n":"第二十二条","txt":"审理委员会办公室自批准受理重大税务案件之日起5日内，将重大税务案件审理提请书及必要的案件材料分送审理委员会成员单位。"},{"i":22,"n":"第二十三条","txt":"审理委员会成员单位自收到审理委员会办公室分送的案件材料之日起10日内，提出书面审理意见送审理委员会办公室。"},{"i":23,"n":"第二十四条","txt":"审理委员会成员单位认为案件事实不清、证据不足，需要补充调查的，应当在书面审理意见中列明需要补充调查的问题并说明理由。 审理委员会办公室应当召集提请补充调查的成员单位和稽查局进行协调，确需补充调查的，由审理委员会办公室报审理委员会主任或其授权的副主任批准，将案件材料退回稽查局补充调查。"},{"i":24,"n":"第二十五条","txt":"稽查局补充调查不应超过30日，有特殊情况的，经稽查局局长批准可以适当延长，但延长期限最多不超过30日。 稽查局完成补充调查后，应当按照本办法第十五条、第十六条的规定重新提交案件材料、办理交接手续。 稽查局不能在规定期限内完成补充调查的，或者补充调查后仍然事实不清、证据不足的，由审理委员会办公室报请审理委员会主任或其授权的副主任批准，终止审理。"},{"i":25,"n":"第二十六条","txt":"审理过程中，稽查局发现本办法第十一条第二款规定情形的，书面告知审理委员会办公室。审理委员会办公室报请审理委员会主任或其授权的副主任批准，可以终止审理。"},{"i":26,"n":"第二十七条","txt":"审理委员会成员单位认为案件事实清楚、证据确凿，但法律依据不明确或者需要处理的相关事项超出本机关权限的，按规定程序请示上级税务机关或者征求有权机关意见。"},{"i":27,"n":"第二十八条","txt":"审理委员会成员单位书面审理意见一致，或者经审理委员会办公室协调后达成一致意见的，由审理委员会办公室起草审理意见书，报审理委员会主任批准。"},{"i":28,"n":"第二十九条","txt":"审理委员会成员单位书面审理意见存在较大分歧，经审理委员会办公室协调仍不能达成一致意见的，由审理委员会办公室向审理委员会主任或其授权的副主任报告，提请审理委员会会议审理。"},{"i":29,"n":"第三十条","txt":"审理委员会办公室提请会议审理的报告，应当说明成员单位意见分歧、审理委员会办公室协调情况和初审意见。 审理委员会办公室应当将会议审理时间和地点提前通知审理委员会主任、副主任和成员单位，并分送案件材料。"},{"i":30,"n":"第三十一条","txt":"成员单位应当派员参加会议，三分之二以上成员单位到会方可开会。审理委员会办公室以及其他与案件相关的成员单位应当出席会议。 案件调查人员、审理委员会办公室承办人员应当列席会议。必要时，审理委员会可要求调查对象所在地主管税务机关参加会议。"},{"i":31,"n":"第三十二条","txt":"审理委员会会议由审理委员会主任或其授权的副主任主持。首先由稽查局汇报案情及拟处理意见。审理委员会办公室汇报初审意见后，各成员单位发表意见并陈述理由。 审理委员会办公室应当做好会议记录。"},{"i":32,"n":"第三十三条","txt":"经审理委员会会议审理，根据不同情况，作出以下处理： （一）案件事实清楚、证据确凿、程序合法、法律依据明确的，依法确定审理意见； （二）案件事实不清、证据不足的，由稽查局对案件重新调查； （三）案件执法程序违法的，由稽查局对案件重新处理； （四）案件适用法律依据不明确，或者需要处理的有关事项超出本机关权限的，按规定程序请示上级机关或征求有权机关的意见。"},{"i":33,"n":"第三十四条","txt":"审理委员会办公室根据会议审理情况制作审理纪要和审理意见书。 审理纪要由审理委员会主任或其授权的副主任签发。会议参加人员有保留意见或者特殊声明的，应当在审理纪要中载明。 审理意见书由审理委员会主任签发。"},{"i":34,"n":"第三十五条","txt":"稽查局应当按照重大税务案件审理意见书制作税务处理处罚决定等相关文书，加盖稽查局印章后送达执行。 文书送达后5日内，由稽查局送审理委员会办公室备案。"},{"i":35,"n":"第三十六条","txt":"重大税务案件审理程序终结后，审理委员会办公室应当将相关证据材料退回稽查局。"},{"i":36,"n":"第三十七条","txt":"各级税务局督察内审部门应当加强对重大税务案件审理工作的监督。"},{"i":37,"n":"第三十八条","txt":"审理委员会办公室应当加强重大税务案件审理案卷的归档管理，按照受理案件的顺序统一编号，做到一案一卷、资料齐全、卷面整洁、装订整齐。 需要归档的重大税务案件审理案卷包括税务稽查报告、税务稽查审理报告以及有关文书。"},{"i":38,"n":"第三十九条","txt":"各省、自治区、直辖市和计划单列市税务局应当于每年1月31日之前，将本辖区上年度重大税务案件审理工作开展情况和重大税务案件审理统计表报送国家税务总局。"},{"i":39,"n":"第四十条","txt":"各级税务局办理的其他案件，需要移送审理委员会审理的，参照本办法执行。特别纳税调整案件按照有关规定执行。"},{"i":40,"n":"第四十一条","txt":"各级税务局在重大税务案件审理工作中可以使用重大税务案件审理专用章。"},{"i":41,"n":"第四十二条","txt":"本办法规定期限的最后一日为法定休假日的，以休假日期满的次日为期限的最后一日；在期限内有连续３日以上法定休假日的，按休假日天数顺延。 本办法有关“5日”的规定指工作日，不包括法定休假日。"},{"i":42,"n":"第四十三条","txt":"各级税务局应当按照国家税务总局的规划和要求，积极推动重大税务案件审理信息化建设。"},{"i":43,"n":"第四十四条","txt":"各级税务局应当加大对重大税务案件审理工作的基础投入，保障审理人员和经费，配备办案所需的录音录像、文字处理、通讯等设备，推进重大税务案件审理规范化建设。"},{"i":44,"n":"第四十五条","txt":"各省、自治区、直辖市和计划单列市税务局可以依照本办法制定具体实施办法。"},{"i":45,"n":"第四十六条","txt":"本办法自2015年2月1日起施行。《国家税务总局关于印发〈重大税务案件审理办法（试行）〉的通知》（国税发〔2001〕21号）同时废止。"}],"zhongdashuishouweifashixinzhutixinxigongbuguanliba64d507":[{"i":1,"n":"第一条","txt":"为了贯彻落实中共中央办公厅、国务院办公厅印发的《关于进一步深化税收征管改革的意见》，维护正常税收征收管理秩序，惩戒重大税收违法失信行为，保障税务行政相对人合法权益，促进依法诚信纳税，推进社会信用体系建设，根据《中华人民共和国税收征收管理法》《优化营商环境条例》等相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"税务机关依照本办法的规定，确定重大税收违法失信主体，向社会公布失信信息，并将信息通报相关部门实施监管和联合惩戒。"},{"i":3,"n":"第三条","txt":"重大税收违法失信主体信息公布管理应当遵循依法行政、公平公正、统一规范、审慎适当的原则。"},{"i":4,"n":"第四条","txt":"各级税务机关应当依法保护税务行政相对人合法权益，对重大税收违法失信主体信息公布管理工作中知悉的国家秘密、商业秘密或者个人隐私、个人信息，应当依法予以保密。"},{"i":5,"n":"第五条","txt":"税务机关工作人员在重大税收违法失信主体信息公布管理工作中，滥用职权、玩忽职守、徇私舞弊的，依照有关规定严肃处理；涉嫌犯罪的，依法移送司法机关。"},{"i":6,"n":"第六条","txt":"本办法所称“重大税收违法失信主体”（以下简称失信主体）是指有下列情形之一的纳税人、扣缴义务人或者其他涉税当事人（以下简称当事人）： （一）伪造、变造、隐匿、擅自销毁账簿、记账凭证，或者在账簿上多列支出或者不列、少列收入，或者经税务机关通知申报而拒不申报或者进行虚假的纳税申报，不缴或者少缴应纳税款100万元以上，且任一年度不缴或者少缴应纳税款占当年各税种应纳税总额10%以上的，或者采取前述手段，不缴或者少缴已扣、已收税款，数额在100万元以上的； （二）欠缴应纳税款，采取转移或者隐匿财产的手段，妨碍税务机关追缴欠缴的税款，欠缴税款金额100万元以上的； （三）骗取国家出口退税款的； （四）以暴力、威胁方法拒不缴纳税款的； （五）虚开增值税专用发票或者虚开用于骗取出口退税、抵扣税款的其他发票的； （六）虚开增值税普通发票100份以上或者金额400万元以上的； （七）私自印制、伪造、变造发票"},{"i":7,"n":"第七条","txt":"税务机关对当事人依法作出《税务行政处罚决定书》，当事人在法定期限内未申请行政复议、未提起行政诉讼，或者申请行政复议，行政复议机关作出行政复议决定后，在法定期限内未提起行政诉讼，或者人民法院对税务行政处罚决定或行政复议决定作出生效判决、裁定后，有本办法第六条规定情形之一的，税务机关确定其为失信主体。 对移送公安机关的当事人，税务机关在移送时已依法作出《税务处理决定书》，未作出《税务行政处罚决定书》的，当事人在法定期限内未申请行政复议、未提起行政诉讼，或者申请行政复议，行政复议机关作出行政复议决定后，在法定期限内未提起行政诉讼，或者人民法院对税务处理决定或行政复议决定作出生效判决、裁定后，有本办法第六条规定情形之一的，税务机关确定其为失信主体。"},{"i":8,"n":"第八条","txt":"税务机关应当在作出确定失信主体决定前向当事人送达告知文书，告知其依法享有陈述、申辩的权利。告知文书应当包括以下内容： （一）当事人姓名或者名称、有效身份证件号码或者统一社会信用代码、地址。没有统一社会信用代码的，以税务机关赋予的纳税人识别号代替； （二）拟确定为失信主体的事由、依据； （三）拟向社会公布的失信信息； （四）拟通知相关部门采取失信惩戒措施提示； （五）当事人依法享有的相关权利； （六）其他相关事项。 对纳入纳税信用评价范围的当事人，还应当告知其拟适用D级纳税人管理措施。"},{"i":9,"n":"第九条","txt":"当事人在税务机关告知后5日内，可以书面或者口头提出陈述、申辩意见。当事人口头提出陈述、申辩意见的，税务机关应当制作陈述申辩笔录，并由当事人签章。 税务机关应当充分听取当事人陈述、申辩意见，对当事人提出的事实、理由和证据进行复核。当事人提出的事实、理由或者证据成立的，应当采纳。"},{"i":10,"n":"第十条","txt":"经设区的市、自治州以上税务局局长或者其授权的税务局领导批准，税务机关在本办法第七条规定的申请行政复议或提起行政诉讼期限届满，或者行政复议决定、人民法院判决或裁定生效后，于30日内制作失信主体确定文书，并依法送达当事人。失信主体确定文书应当包括以下内容： （一）当事人姓名或者名称、有效身份证件号码或者统一社会信用代码、地址。没有统一社会信用代码的，以税务机关赋予的纳税人识别号代替； （二）确定为失信主体的事由、依据； （三）向社会公布的失信信息提示； （四）相关部门采取失信惩戒措施提示； （五）当事人依法享有的相关权利； （六）其他相关事项。 对纳入纳税信用评价范围的当事人，还应当包括适用D级纳税人管理措施提示。 本条第一款规定的时限不包括因其他方式无法送达，公告送达告知文书和确定文书的时间。"},{"i":11,"n":"第十一条","txt":"税务机关应当在失信主体确定文书送达后的次月15日内，向社会公布下列信息： （一）失信主体基本情况； （二）失信主体的主要税收违法事实； （三）税务处理、税务行政处罚决定及法律依据； （四）确定失信主体的税务机关; （五）法律、行政法规规定应当公布的其他信息。 对依法确定为国家秘密的信息，法律、行政法规禁止公开的信息，以及公开后可能危及国家安全、公共安全、经济安全、社会稳定的信息，税务机关不予公开。"},{"i":12,"n":"第十二条","txt":"税务机关按照本办法第十一条第一款第一项规定向社会公布失信主体基本情况。失信主体为法人或者其他组织的，公布其名称、统一社会信用代码（纳税人识别号）、注册地址以及违法行为发生时的法定代表人、负责人或者经人民法院生效裁判确定的实际责任人的姓名、性别及身份证件号码（隐去出生年、月、日号码段）；失信主体为自然人的，公布其姓名、性别、身份证件号码（隐去出生年、月、日号码段）。 经人民法院生效裁判确定的实际责任人，与违法行为发生时的法定代表人或者负责人不一致的，除有证据证明法定代表人或者负责人有涉案行为外，税务机关只向社会公布实际责任人信息。"},{"i":13,"n":"第十三条","txt":"税务机关应当通过国家税务总局各省、自治区、直辖市、计划单列市税务局网站向社会公布失信主体信息，根据本地区实际情况，也可以通过税务机关公告栏、报纸、广播、电视、网络媒体等途径以及新闻发布会等形式向社会公布。 国家税务总局归集各地税务机关确定的失信主体信息，并提供至“信用中国”网站进行公开。"},{"i":14,"n":"第十四条","txt":"属于本办法第六条第一项、第二项规定情形的失信主体，在失信信息公布前按照《税务处理决定书》《税务行政处罚决定书》缴清税款、滞纳金和罚款的，经税务机关确认，不向社会公布其相关信息。 属于本办法第六条第八项规定情形的失信主体，具有偷税、逃避追缴欠税行为的，按照前款规定处理。"},{"i":15,"n":"第十五条","txt":"税务机关对按本办法规定确定的失信主体，纳入纳税信用评价范围的，按照纳税信用管理规定，将其纳税信用级别判为D级，适用相应的D级纳税人管理措施。"},{"i":16,"n":"第十六条","txt":"对按本办法第十一条第一款规定向社会公布信息的失信主体，税务机关将失信信息提供给相关部门，由相关部门依法依规采取失信惩戒措施。"},{"i":17,"n":"第十七条","txt":"失信主体信息自公布之日起满3年的，税务机关在5日内停止信息公布。"},{"i":18,"n":"第十八条","txt":"失信信息公布期间，符合下列条件之一的，失信主体或者其破产管理人可以向作出确定失信主体决定的税务机关申请提前停止公布失信信息： （一）按照《税务处理决定书》《税务行政处罚决定书》缴清（退）税款、滞纳金、罚款，且失信主体失信信息公布满六个月的； （二）失信主体破产，人民法院出具批准重整计划或认可和解协议的裁定书，税务机关依法受偿的； （三）在发生重大自然灾害、公共卫生、社会安全等突发事件期间，因参与应急抢险救灾、疫情防控、重大项目建设或者履行社会责任作出突出贡献的。"},{"i":19,"n":"第十九条","txt":"按本办法第十八条第一项规定申请提前停止公布的，申请人应当提交停止公布失信信息申请表、诚信纳税承诺书。 按本办法第十八条第二项规定申请提前停止公布的，申请人应当提交停止公布失信信息申请表，人民法院出具的批准重整计划或认可和解协议的裁定书。 按本办法第十八条第三项规定申请提前停止公布的，申请人应当提交停止公布失信信息申请表、诚信纳税承诺书以及省、自治区、直辖市、计划单列市人民政府出具的有关材料。"},{"i":20,"n":"第二十条","txt":"税务机关应当自收到申请之日起2日内作出是否受理的决定。申请材料齐全、符合法定形式的，应当予以受理，并告知申请人。不予受理的，应当告知申请人，并说明理由。"},{"i":21,"n":"第二十一条","txt":"受理申请后，税务机关应当及时审核。符合本办法第十八条第一项规定条件的，经设区的市、自治州以上税务局局长或者其授权的税务局领导批准，准予提前停止公布；符合本办法第十八条第二项、第三项规定条件的，经省、自治区、直辖市、计划单列市税务局局长或者其授权的税务局领导批准，准予提前停止公布。 税务机关应当自受理之日起15日内作出是否予以提前停止公布的决定，并告知申请人。对不予提前停止公布的，应当说明理由。"},{"i":22,"n":"第二十二条","txt":"失信主体有下列情形之一的，不予提前停止公布： （一）被确定为失信主体后，因发生偷税、逃避追缴欠税、骗取出口退税、抗税、虚开发票等税收违法行为受到税务处理或者行政处罚的； （二）五年内被确定为失信主体两次以上的。 申请人按本办法第十八条第二项规定申请提前停止公布的，不受前款规定限制。"},{"i":23,"n":"第二十三条","txt":"税务机关作出准予提前停止公布决定的，应当在5日内停止信息公布。"},{"i":24,"n":"第二十四条","txt":"税务机关可以组织申请提前停止公布的失信主体法定代表人、财务负责人等参加信用培训，开展依法诚信纳税教育。信用培训不得收取任何费用。"},{"i":25,"n":"第二十五条","txt":"本办法规定的期间以日计算的，是指工作日，不含法定休假日;期间以年、月计算的，到期月的对应日为期间的最后一日；没有对应日的，月末日为期间的最后一日。期间开始的当日不计算在期间内。 本办法所称“以上、日内”，包含本数（级）。"},{"i":26,"n":"第二十六条","txt":"国家税务总局各省、自治区、直辖市、计划单列市税务局可以依照本办法制定具体实施办法。"},{"i":27,"n":"第二十七条","txt":"本办法自2022年2月1日起施行。《国家税务总局关于发布〈重大税收违法失信案件信息公布办法〉的公告》（2018年第54号）同时废止。"}],"jinyinshoushixiaofeishuizhengshouguanlibanfa":[],"feijuminchengbaogongchengzuoyehetigonglaowushuisho390bdb":[{"i":1,"n":"第一条","txt":"为规范对非居民在中国境内承包工程作业和提供劳务的税收征收管理，根据《中华人民共和国税收征收管理法》（以下简称税收征管法）及其实施细则、《中华人民共和国企业所得税法》（以下简称企业所得税法）及其实施条例、《中华人民共和国营业税暂行条例》及其实施细则、《中华人民共和国增值税暂行条例》及其实施细则、中国政府对外签署的避免双重征税协定（含与香港、澳门特别行政区签署的税收安排，以下统称税收协定）等相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称非居民，包括非居民企业和非居民个人。非居民企业是指依照外国（地区）法律成立且实际管理机构不在中国境内，但在中国境内设立机构、场所的，或者在中国境内未设立机构、场所，但有来源于中国境内所得的企业。非居民个人是指在中国境内无住所又不居住或者无住所而在境内居住不满一年的个人。"},{"i":3,"n":"第三条","txt":"本办法所称承包工程作业，是指在中国境内承包建筑、安装、装配、修缮、装饰、勘探及其他工程作业。 本办法所称提供劳务是指在中国境内从事加工、修理修配、交通运输、仓储租赁、咨询经纪、设计、文化体育、技术服务、教育培训、旅游、娱乐及其他劳务活动。"},{"i":4,"n":"第四条","txt":"本办法所称非居民在中国境内承包工程作业和提供劳务税收管理，是指对非居民营业税、增值税和企业所得税的纳税事项管理。涉及个人所得税、印花税等税收的管理，应依照有关规定执行。"},{"i":5,"n":"第五条","txt":"非居民企业在中国境内承包工程作业或提供劳务的，应当自项目合同或协议（以下简称合同）签订之日起30日内，向项目所在地主管税务机关办理税务登记手续。 依照法律、行政法规规定负有税款扣缴义务的境内机构和个人，应当自扣缴义务发生之日起30日内，向所在地主管税务机关办理扣缴税款登记手续。 境内机构和个人向非居民发包工程作业或劳务项目的，应当自项目合同签订之日起30日内，向主管税务机关报送《境内机构和个人发包工程作业或劳务项目报告表》（见附件1），并附送非居民的税务登记证、合同、税务代理委托书复印件或非居民对有关事项的书面说明等资料。"},{"i":6,"n":"第六条","txt":"非居民企业在中国境内承包工程作业或提供劳务的，应当在项目完工后15日内，向项目所在地主管税务机关报送项目完工证明、验收证明等相关文件复印件，并依据《税务登记管理办法》的有关规定申报办理注销税务登记。"},{"i":7,"n":"第七条","txt":"境内机构和个人向非居民发包工程作业或劳务项目合同发生变更的，发包方或劳务受让方应自变更之日起10日内向所在地主管税务机关报送《非居民项目合同变更情况报告表》（见附件2）。"},{"i":8,"n":"第八条","txt":"境内机构和个人向非居民发包工程作业或劳务项目，从境外取得的与项目款项支付有关的发票和其他付款凭证，应在自取得之日起30日内向所在地主管税务机关报送《非居民项目合同款项支付情况报告表》（见附件3）及付款凭证复印件。 境内机构和个人不向非居民支付工程价款或劳务费的，应当在项目完工开具验收证明前，向其主管税务机关报告非居民在项目所在地的项目执行进度、支付人名称及其支付款项金额、支付日期等相关情况。"},{"i":9,"n":"第九条","txt":"境内机构和个人向非居民发包工程作业或劳务项目，与非居民的主管税务机关不一致的，应当自非居民申报期限届满之日起15日内向境内机构和个人的主管税务机关报送非居民申报纳税证明资料复印件。"},{"i":10,"n":"第十条","txt":"税务机关应当建立税源监控机制，获取并利用发改委、建设、外汇管理、商务、教育、文化、体育等部门关于非居民在中国境内承包工程作业和提供劳务的相关信息，并可根据工作需要，将信息使用情况反馈给有关部门。"},{"i":11,"n":"第十一条","txt":"非居民或境内机构和个人的同一涉税事项同时涉及国家税务局和地方税务局的，各主管税务机关办理涉税事项后应当制作《非居民承包工程作业和提供劳务项目信息传递表》（见附件4），并按月传递给对方纳入非居民税收管理档案。"},{"i":12,"n":"第十二条","txt":"非居民企业在中国境内承包工程作业或提供劳务项目的，企业所得税按纳税年度计算、分季预缴，年终汇算清缴，并在工程项目完工或劳务合同履行完毕后结清税款。"},{"i":13,"n":"第十三条","txt":"非居民企业进行企业所得税纳税申报时，应当如实报送纳税申报表，并附送下列资料： （一）工程作业（劳务）决算（结算）报告或其他说明材料； （二）参与工程作业或劳务项目外籍人员姓名、国籍、出入境时间、在华工作时间、地点、内容、报酬标准、支付方式、相关费用等情况的书面报告； （三） 财务会计报告或财务情况说明； （四）非居民企业依据税收协定在中国境内未构成常设机构，需要享受税收协定待遇的，应提交《非居民企业承包工程作业和提供劳务享受税收协定待遇报告表》（以下简称报告表）（见附件5）,并附送居民身份证明及税务机关要求提交的其他证明资料。 非居民企业未按上述规定提交报告表及有关证明资料，或因项目执行发生变更等情形不符合享受税收协定待遇条件的，不得享受税收协定待遇,应依照企业所得税法规定缴纳税款。"},{"i":14,"n":"第十四条","txt":"工程价款或劳务费的支付人所在地县（区）以上主管税务机关根据附件1及非居民企业申报纳税证明资料或其他信息，确定符合企业所得税法实施条例第一百零六条所列指定扣缴的三种情形之一的，可指定工程价款或劳务费的支付人为扣缴义务人，并将《非居民企业承包工程作业和提供劳务企业所得税扣缴义务通知书》（见附件6）送达被指定方。"},{"i":15,"n":"第十五条","txt":"指定扣缴义务人应当在申报期限内向主管税务机关报送扣缴企业所得税报告表及其他有关资料。"},{"i":16,"n":"第十六条","txt":"扣缴义务人未依法履行扣缴义务或无法履行扣缴义务的，由非居民企业在项目所在地申报缴纳。主管税务机关应自确定未履行扣缴义务之日起15日内通知非居民企业在项目所在地申报纳税。"},{"i":17,"n":"第十七条","txt":"非居民企业逾期仍未缴纳税款的，项目所在地主管税务机关应自逾期之日起15日内，收集该非居民企业从中国境内取得其他收入项目的信息，包括收入类型，支付人的名称、地址，支付金额、方式和日期等，并向其他收入项目支付人（以下简称其他支付人）发出《非居民企业欠税追缴告知书》（见附件7），并依法追缴税款和滞纳金。 非居民企业从中国境内取得其他收入项目，包括非居民企业从事其他工程作业或劳务项目所得，以及企业所得税法第三条第二、三款规定的其他收入项目。非居民企业有多个其他支付人的，项目所在地主管税务机关应根据信息准确性、收入金额、追缴成本等因素确定追缴顺序。"},{"i":18,"n":"第十八条","txt":"其他支付人主管税务机关应当提供必要的信息，协助项目所在地主管税务机关执行追缴事宜。"},{"i":19,"n":"第十九条","txt":"非居民在中国境内发生营业税或增值税应税行为，在中国境内设立经营机构的，应自行申报缴纳营业税或增值税。"},{"i":20,"n":"第二十条","txt":"非居民在中国境内发生营业税或增值税应税行为而在境内未设立经营机构的，以代理人为营业税或增值税的扣缴义务人；没有代理人的，以发包方、劳务受让方或购买方为扣缴义务人。 工程作业发包方、劳务受让方或购买方，在项目合同签订之日起30日内，未能向其所在地主管税务机关提供下列证明资料的，应履行营业税或增值税扣缴义务： (一)非居民纳税人境内机构和个人的工商登记和税务登记证明复印件及其从事经营活动的证明资料； (二)非居民委托境内机构和个人代理事项委托书及受托方的认可证明。"},{"i":21,"n":"第二十一条","txt":"非居民进行营业税或增值税纳税申报，应当如实填写报送纳税申报表，并附送下列资料： （一）工程（劳务）决算（结算）报告或其他说明材料； （二）参与工程或劳务作业或提供加工、修理修配的外籍人员的姓名、国籍、出入境时间、在华工作时间、地点、内容、报酬标准、支付方式、相关费用等情况； （三）主管税务机关依法要求报送的其他有关资料。"},{"i":22,"n":"第二十二条","txt":"主管税务机关应当按项目建档、分项管理的原则，建立非居民承包工程作业和提供劳务项目的管理台账和纳税档案，及时准确掌握工程和劳务项目的合同执行、施工进度、价款支付、对外付汇、税款缴纳等情况。"},{"i":23,"n":"第二十三条","txt":"境内机构和个人从境外取得的付款凭证，主管税务机关对其真实性有疑义的，可要求其提供境外公证机构或者注册会计师的确认证明，经税务机关审核认可后，方可作为计账核算的凭证。"},{"i":24,"n":"第二十四条","txt":"主管税务机关应对非居民享受协定待遇进行事后管理，审核其提交的报告表和证明资料的真实性和准确性，对其不构成常设机构的情形进行认定。对于不符合享受协定待遇条件且未履行纳税义务的情形，税务机关应该依法追缴其应纳税款、滞纳金及罚款。"},{"i":25,"n":"第二十五条","txt":"税务机关应当利用售付汇信息，包括境内机构和个人向非居民支付服务贸易款项的历史记录，以及当年新增发包项目付款计划等信息，对承包工程作业和提供劳务项目实施监控。对于付汇前有欠税情形的，应当及时通知纳税人或扣缴义务人缴纳，必要时可以告知有关外汇管理部门或指定外汇支付银行依法暂停付汇。"},{"i":26,"n":"第二十六条","txt":"主管税务机关应对非居民参与国家、省、地市级重点建设项目，包括城市基础设施建设、能源建设、企业技术设备引进等项目中涉及的承包工程作业或提供劳务，以及其他有非居民参与的合同金额超过5000万元人民币的，实施重点税源监控管理；对承包方和发包方是否存在关联关系、合同实际执行情况、常设机构判定、境内外劳务收入划分等事项进行重点跟踪核查，对发现的问题，可以实施情报交换、反避税调查或税务稽查。"},{"i":27,"n":"第二十七条","txt":"省（自治区、直辖市和计划单列市）税务机关应当于年度终了后45日内，将《非居民承包工程作业和提供劳务重点建设项目统计表》（见附件8），以及项目涉及的企业所得税、增值税、营业税、印花税、个人所得税等税收收入和税源变动情况的分析报告报送国家税务总局（国际税务司）。"},{"i":28,"n":"第二十八条","txt":"主管税务机关可根据需要对非居民承包工程作业和提供劳务的纳税情况实施税务审计，必要时应将审计结果及时传递给同级国家税务局或地方税务局。税务审计可以采取国家税务局、地方税务局联合审计的方式进行。"},{"i":29,"n":"第二十九条","txt":"主管税务机关在境内难以获取涉税信息时，可以制作专项情报，由国家税务总局（国际税务司）向税收协定缔约国对方提出专项情报请求；非居民在中国境内未依法履行纳税义务的，主管税务机关可制作自动或自发情报，提交国家税务总局依照有关规定将非居民在中国境内的税收违法行为告知协定缔约国对方主管税务当局；对非居民承包工程作业和提供劳务有必要进行境外审计的，可根据税收情报交换有关规定，经国家税务总局批准后组织实施。"},{"i":30,"n":"第三十条","txt":"欠缴税款的非居民企业法定代表人或非居民个人在出境前未按照规定结清应纳税款、滞纳金又不提供纳税担保的，税务机关可以通知出入境管理机关阻止其出境。"},{"i":31,"n":"第三十一条","txt":"对于非居民工程或劳务项目完毕，未按期结清税款并已离境的，主管税务机关可制作《税务事项告知书》（见附件9），通过信函、电子邮件、传真等方式，告知该非居民限期履行纳税义务，同时通知境内发包方或劳务受让者协助追缴税款。"},{"i":32,"n":"第三十二条","txt":"非居民、扣缴义务人或代理人实施承包工程作业和提供劳务有关事项存在税收违法行为的，税务机关应按照税收征管法及其实施细则的有关规定处理。"},{"i":33,"n":"第三十三条","txt":"境内机构或个人发包工程作业或劳务项目，未按本办法第五条、第七条、第八条、第九条规定向主管税务机关报告有关事项的，由税务机关责令限期改正，可以处2000元以下的罚款；情节严重的，处2000元以上10000元以下的罚款。"},{"i":34,"n":"第三十四条","txt":"各省、自治区、直辖市和计划单列市国家税务局、地方税务局可根据本办法制定具体实施办法。 附件： 1.境内机构和个人发包工程作业或劳务项目报告表 2.非居民项目合同变更情况报告表 3.非居民项目合同款项支付情况报告表 4.非居民承包工程作业和提供劳务项目信息传递表 5.非居民企业承包工程作业和提供劳务享受税收协定待遇报告表 6.非居民企业承包工程作业和提供劳务企业所得税扣缴义务通知书 7.非居民企业欠税追缴告知书 8.非居民承包工程作业和提供劳务重点建设项目统计表 9.税务事项告知书"}]};
